def _config_file():
    """Where the settings file lives: next to the app, but not loose in a game folder. A new
    version put next to the launcher's shortcut (an update) has none of its own: it uses the one
    where the app lives, which the shortcut passes along (W3MM_HOME), and moves in there."""
    if APP_DIR.name.lower() != MANAGER_DIRNAME.lower() and _looks_like_game(APP_DIR):
        return APP_DIR / MANAGER_DIRNAME / CONFIG_NAME
    lived = os.environ.get("W3MM_HOME")
    if lived and not (APP_DIR / CONFIG_NAME).exists() and (Path(lived) / CONFIG_NAME).is_file():
        return Path(lived) / CONFIG_NAME
    return APP_DIR / CONFIG_NAME


def _looks_like_game(folder):
    folder = Path(folder)
    return any((folder / "bin" / d / "witcher3.exe").is_file() for d in ("x64", "x64_dx12"))


CONFIG_FILE = _config_file()


def set_home(folder):
    """Make `folder` the home: every file the app keeps besides its settings file goes there."""
    global CONFIG_DIR, WINDOW_FILE, PERF_LOG, ERROR_LOG, HOME_GAME
    CONFIG_DIR = Path(folder)
    WINDOW_FILE = CONFIG_DIR / "windows.json"
    PERF_LOG = CONFIG_DIR / "perf.log"
    ERROR_LOG = CONFIG_DIR / "errors.log"
    HOME_GAME = CONFIG_DIR.parent if CONFIG_DIR.name.lower() == MANAGER_DIRNAME.lower() else None


def home_for(cfg):
    """The _ModManager folder these settings mean, or None while no game folder is set."""
    if cfg.get("manager_dir"):
        return Path(cfg["manager_dir"]).expanduser()
    game = cfg.get("game_dir")
    return Path(game).expanduser() / MANAGER_DIRNAME if game and _looks_like_game(Path(game).expanduser()) else None


def _runtime_dir():
    """Scratch space the system empties at logout: for things rebuilt at every start (the
    checkbox and arrow icons), so they never leave a trace."""
    base = os.environ.get("XDG_RUNTIME_DIR") or tempfile.gettempdir()
    return Path(base) / f"w3modmanager-{os.getuid()}"


