_VANILLA_MISSES = set()


def fetch_vanilla(cache_dir, kind, version, rel, kept_only=False):
    """The game's own copy of a file as it was in `version`, or None. rel: its path as the game
    has it (scripts: under content/scripts; XML: inside the bundles). kept_only: only a copy
    downloaded before, never the network."""
    src = VANILLA_SOURCES.get(kind, {}).get(version)
    if not src:
        return None
    key = (kind, version, rel.lower())
    safe = re.sub(r"[^A-Za-z0-9._-]", "_", version)
    path = Path(cache_dir) / kind / safe / rel
    gone = path.with_name(path.name + ".none")       # that version has no such file: never asked again
    if path.is_file():
        return path.read_bytes()                     # downloaded once, kept for every later merge
    if kept_only or gone.exists() or not VANILLA_FETCH or key in _VANILLA_MISSES:
        return None
    url_t, commit = src
    folder = "scripts" if kind == "script" else "XML"
    url = url_t.format(c=commit, folder=folder, rel=urllib.parse.quote(rel))
    try:
        req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
        with urllib.request.urlopen(req, timeout=15) as r:
            data = r.read()
    except urllib.error.HTTPError as e:
        _VANILLA_MISSES.add(key)
        if e.code == 404:
            try:
                gone.parent.mkdir(parents=True, exist_ok=True)
                gone.touch()
            except OSError:
                pass
        return None
    except (OSError, ValueError):
        _VANILLA_MISSES.add(key)                     # no connection: tried again next time the app starts
        return None
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(path.name + ".tmp")
        tmp.write_bytes(data)
        os.replace(tmp, path)
    except OSError:
        pass
    return data


def _opcodes(a, b):
    """difflib-style opcodes from the merge's own (faster) line matcher."""
    out, pa, pb = [], 0, 0
    for i, j, k in _matching_blocks(a, b) + [(len(a), len(b), 0)]:
        if i > pa or j > pb:
            out.append(("replace" if i > pa and j > pb else "delete" if i > pa else "insert", pa, i, pb, j))
        if k:
            out.append(("equal", i, i + k, j, j + k))
        pa, pb = i + k, j + k
    return out


def rebase_on(origin, game, mod):
    """A mod's copy brought onto your game's copy, using the file it was made from (origin): its
    own changes (origin -> mod) are put where the same lines sit in your copy, and everything the
    game changed since is kept. A change of the mod's that falls on lines the game changed too
    replaces your copy's lines there (as the mod's whole file would): -> (lines, how many such)."""
    hunks = line_hunks(origin, mod)
    if not hunks:
        return list(game), 0
    at = {}
    for tag, i1, i2, j1, j2 in _opcodes(_norm(origin), _norm(game)):
        if tag == "equal":
            for k in range(i2 - i1):
                at[i1 + k] = j1 + k

    def before(i):                     # your copy's line right after the last unchanged one up to origin line i
        while i >= 0 and at.get(i) is None:
            i -= 1
        return at[i] + 1 if i >= 0 else 0

    def after(i):                      # your copy's first unchanged line from origin line i on
        while i < len(origin) and at.get(i) is None:
            i += 1
        return at[i] if i < len(origin) else len(game)

    moved, clashed = [], 0
    for start, end, new in hunks:
        spots = [at.get(k) for k in range(start, end)]
        if end > start and None not in spots and spots == list(range(spots[0], spots[0] + len(spots))):
            moved.append((spots[0], spots[-1] + 1, new))
        elif end == start and (start == 0 or at.get(start - 1) is not None):
            p = at[start - 1] + 1 if start else 0      # lines added: right after the one they followed
            moved.append((p, p, new))
        else:
            # the game changed these lines too: the mod's version of the stretch counts
            lo, hi = before(start - 1), after(end)
            if moved and lo < moved[-1][1]:
                return None
            moved.append((lo, max(lo, hi), new))
            clashed += 1
    return apply_hunks(game, moved), clashed


