# .w3strings, from WolvenKit's reader (WolvenKit.W3Strings) and a 5.00 file: 'RTSW', a version
# (162 up to 4.x, 164 since 5.00), a language key split between bytes 8-9 and the file's last
# two bytes, then three tables — (string ID, offset, length) per string, (key hash, string ID)
# per named key, and the strings' total size — then the strings, each character XOR-ed with a
# key from the language. Up to 4.x a character is 2 bytes (UTF-16); since 5.00 it's 1 (UTF-8
# bytes), with the same keys. 5.00 reads only its own layout.
_W3S_LANG_MAGIC = {
    0x00000000: 0x00000000, 0x83496237: 0x73946816, 0x43975139: 0x79321793, 0x75886138: 0x42791159,
    0x45931894: 0x12375973, 0x23863176: 0x75921975, 0x24987354: 0x21793217, 0x18796651: 0x42387566,
    0x18632176: 0x16875467, 0x63481486: 0x42386347, 0x42378932: 0x67823218, 0x54834893: 0x59825646,
}
_W3S_VERSIONS = {162: ("4.x", 2), 164: ("5.x", 1)}


def _w3s_count(data, pos):
    """The tables' variable-length counts: 6 bits in the first byte, 7 in each one after."""
    b = data[pos]
    pos += 1
    value = b & 0x3F
    if b & 0x40:
        shift = 6
        while True:
            n = data[pos]
            pos += 1
            value |= (n & 0x7F) << shift
            shift += 7
            if not n & 0x80 or shift >= 27:
                break
    return value, pos


def w3strings_read(data, texts=False):
    """A .w3strings file -> {'format': '4.x' | '5.x', 'ids': {string ID}, 'keys': {key hash},
    'texts': {string ID: text} (with texts=True)}, or {'format': 'other'} for a version this
    doesn't know, or None when it isn't one that checks out (every table has to add up to the
    file's size, and the strings have to read as text)."""
    if len(data) < 14 or data[:4] != b"RTSW":
        return None
    version = struct.unpack_from("<I", data, 4)[0]
    if version not in _W3S_VERSIONS:
        return {"format": "other"}
    name, unit = _W3S_VERSIONS[version]
    key = struct.unpack_from("<H", data, 8)[0] << 16 | struct.unpack_from("<H", data, len(data) - 2)[0]
    magic = _W3S_LANG_MAGIC.get(key)
    if magic is None:
        return None
    try:
        n1, pos = _w3s_count(data, 10)
        entries = [struct.unpack_from("<III", data, pos + 12 * k) for k in range(n1)]
        pos += 12 * n1
        n2, pos = _w3s_count(data, pos)
        keys = {struct.unpack_from("<I", data, pos + 8 * k)[0] for k in range(n2)}
        pos += 8 * n2
        n3, pos = _w3s_count(data, pos)
    except (IndexError, struct.error):
        return None
    if pos + unit * n3 + 2 != len(data):              # the tables must account for every byte
        return None

    def text(offset, length):
        at = pos + unit * offset
        if length > 1 << 16 or at + unit * length > len(data) - 2:
            return None
        string_key = (magic >> 8) & 0xFFFF
        out = bytearray()
        for i in range(length):
            char_key = ((length + 1) * string_key) & 0xFFFF
            if unit == 2:
                out += bytes([data[at + 2 * i] ^ (char_key & 0xFF), data[at + 2 * i + 1] ^ (char_key >> 8)])
            else:
                out.append(data[at + i] ^ (char_key & 0xFF))
            string_key = ((string_key << 1) | (string_key >> 15)) & 0xFFFF
        try:
            return out.decode("utf-16-le" if unit == 2 else "utf-8")
        except UnicodeDecodeError:
            return None

    good = total = 0
    for _id, offset, length in entries[:40]:
        t = text(offset, length)
        if t is None:
            return None
        total += len(t)
        good += sum(1 for c in t if c.isprintable() or c in "\n\r\t")
    if total and good / total < 0.95:
        return None
    out = {"format": name, "ids": {e[0] ^ magic for e in entries}, "keys": keys}
    if texts:
        out["texts"] = {e[0] ^ magic: (text(e[1], e[2]) or "") for e in entries}
    return out


def w3strings_format(data):
    """'4.x' (UTF-16 strings: 5.00 can't read it), '5.x', 'other' (a version this doesn't know),
    or None: can't tell — then its date decides."""
    got = w3strings_read(data)
    return got["format"] if got else None


def collision_cache_format(path):
    """'1.x', '4.x', '5.x' or None (can't tell) for a collision.cache, from its header: 'CC3W' and a
    version. The classic game's (1.32 and before) is 1 (2 past 4 GB), with the date and the tables
    at 0x10 (WolvenKit's reader, WolvenKit.Cache/CollisionCache). Next-gen 4.x's is 9: the same
    tables, 72-byte entries (seen in next-gen mods' files). 5.00's is 11, laid out anew (seen in
    5.00 files, and in a mod's file rebuilt from its 4.x one). For the older ones the tables must
    also point inside the file and hold names."""
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            head = f.read(0x30)
            if len(head) < 0x30 or head[:4] != b"CC3W":
                return None
            version = struct.unpack_from("<I", head, 4)[0]
            if version >= 11:
                return "5.x"
            if version not in (1, 2, 9):
                return None
            if version == 2:
                _info, count, names_at = struct.unpack_from("<QQQ", head, 0x10)
                names_size = struct.unpack_from("<I", head, 0x28)[0]
            else:
                info, count, names_at, names_size = struct.unpack_from("<IIII", head, 0x10)
                if version == 9 and info + 72 * count != size:
                    return None                       # its table doesn't end the file: not that layout
            if not count or not names_size or names_at + names_size > size or names_size > 64 << 20:
                return None
            f.seek(names_at)
            names = _cache_strings(f.read(names_size))
            if not names:
                return None
            return "4.x" if version == 9 else "1.x"
    except (OSError, struct.error):
        return None


REM_SCAN_REV = 2    # what remaster_scan looks for changed: each mod is looked at again once (2: 4.x's collision.cache)
REDKIT_5_BUILD = 1042178      # REDkit 5.0.1042178, released with the Remastered (29 Sep 2026)


def rsblob_build(path):
    """The REDkit build that compiled a precompiled.rsblob, from its header (a version, then
    length-prefixed strings: platform 'x64', build '1042178', … — seen in 5.00 files), or None."""
    try:
        with open(path, "rb") as f:
            head = f.read(64)
    except OSError:
        return None
    if len(head) < 8 or struct.unpack_from("<I", head, 0)[0] != 1:
        return None
    pos, texts = 4, []
    for _ in range(2):
        if pos >= len(head) or not head[pos] & 0x80:
            return None
        n = head[pos] & 0x7F
        texts.append(head[pos + 1:pos + 1 + n])
        pos += 1 + n
    return int(texts[1]) if texts[1].isdigit() else None


def _rsb_int(d, p):
    """One number in a precompiled.rsblob: 6 bits in the first byte (with a sign bit and a
    'more' bit), then 7 bits per byte, REDengine's packed int. -> (value, next position)."""
    b = d[p]
    p += 1
    v = b & 0x3F
    if b & 0x40:
        shift = 6
        while True:
            b = d[p]
            p += 1
            v |= (b & 0x7F) << shift
            shift += 7
            if not b & 0x80:
                break
    return v, p


def rsblob_read(data):
    """What a precompiled.rsblob (REDkit 5's compiled scripts) declares, read from its tables:
    {'enums', 'types' (classes, structs, enums), 'states': [(machine, name)], 'functions',
    'replace_method', 'add_method', 'wrap_method', 'add_field': [(class, name)]}, names as
    written. Raises ValueError for anything that doesn't read cleanly.
    Layout (worked out on ten mods' files, REDkit builds 1042178, 1044630 and 1048625, checked
    against one's published source): a version (1), platform, build, 8 bytes, configuration;
    then enums, structs, classes and states, global functions, a list that was empty in every
    file seen, @replaceMethod, @addMethod, @wrapMethod, @addField; the name table at the offset
    in the file's last 4 bytes. A function: name, class, flags, return/parameters/locals, code.
    Flags tell the annotations apart: 0x40000 replace, 0x80000 add, 0x100000 wrap."""
    d = data
    try:
        if len(d) < 16 or struct.unpack_from("<I", d, 0)[0] != 1:
            raise ValueError("not a precompiled script file")
        at = struct.unpack_from("<I", d, len(d) - 4)[0]
        if not 16 <= at < len(d) - 8:
            raise ValueError("no name table")
        count = struct.unpack_from("<I", d, at)[0]
        names, q = [], at + 4
        for _ in range(count):
            n, q = _rsb_int(d, q)
            names.append(d[q:q + n].decode("latin-1"))
            q += n
        if q != len(d) - 4:
            raise ValueError("name table doesn't end the file")

        def num(p):
            v, p = _rsb_int(d, p)
            if p > at:
                raise ValueError("runs into the name table")
            return v, p

        def name(p):
            v, p = num(p)
            if v >= len(names):
                raise ValueError("name out of range")
            return names[v], p

        def text(p):                                 # a string written in place: length, then bytes
            n, p = num(p)
            if p + n > at:
                raise ValueError("text runs into the name table")
            return d[p:p + n], p + n

        def prop(p):                                 # name, hint, flags, type, class, (unused)
            nm, p = name(p)
            _h, p = text(p)
            _f, p = num(p)
            _t, p = name(p)
            owner, p = name(p)
            _x, p = name(p)
            return (owner, nm), p

        def props(p):
            n, p = num(p)
            out = []
            for _ in range(n):
                x, p = prop(p)
                out.append(x)
            return out, p

        def funcs(p, want=None):
            n, p = num(p)
            out = []
            for _ in range(n):
                nm, p = name(p)
                owner, p = name(p)
                flags, p = num(p)
                if want is not None and not flags & want:
                    raise ValueError("a function where another kind was expected")
                for _k in range(3):                  # return, parameters, locals
                    _l, p = props(p)
                size, p = num(p)
                p += size
                if p > at:
                    raise ValueError("code runs into the name table")
                out.append((owner, nm))
            return out, p

        def node(p, depth=0):                        # a default value: key, text, its parts
            if depth > 32:
                raise ValueError("default value nested too deep")
            _k, p = num(p)
            _v, p = text(p)
            n, p = num(p)
            for _ in range(n):
                p = node(p, depth + 1)
            return p

        def defaults(p):
            n, p = num(p)
            for _ in range(n):
                _nm, p = name(p)
                p = node(p)
            return p

        p = 4
        for _ in range(2):                           # platform, build
            _t, p = text(p)
        p += 8
        _t, p = text(p)                              # configuration ("Release")
        out = {"enums": [], "types": [], "states": [], "functions": [], "replace_method": [],
               "add_method": [], "wrap_method": [], "add_field": []}
        n, p = num(p)
        for _ in range(n):                           # enums: name, then (value name, value)
            nm, p = name(p)
            k, p = num(p)
            for _k in range(k):
                _v, p = name(p)
                _v, p = num(p)
            out["enums"].append(nm)
            out["types"].append(nm)
        n, p = num(p)
        for _ in range(n):                           # structs
            nm, p = name(p)
            _h, p = text(p)
            _f, p = props(p)
            p = defaults(p)
            out["types"].append(nm)
        n, p = num(p)
        for _ in range(n):                           # classes, and states (in their state machine)
            nm, p = name(p)
            _parent, p = name(p)
            machine, p = name(p)
            for _k in range(2):
                _v, p = num(p)
            _f, p = props(p)
            _m, p = funcs(p)
            p = defaults(p)
            if machine:
                out["states"].append((machine, nm))
            else:
                out["types"].append(nm)
        glob, p = funcs(p)
        out["functions"] = [nm for _o, nm in glob]
        _u, p = funcs(p)                             # empty in every file seen
        out["replace_method"], p = funcs(p, 0x40000)
        out["add_method"], p = funcs(p, 0x80000)
        out["wrap_method"], p = funcs(p, 0x100000)
        out["add_field"], p = props(p)
        return out
    except (IndexError, struct.error, UnicodeError) as e:
        raise ValueError(f"unreadable: {e}") from None


_RSB_CACHE = {}
_CHANGED_CACHE = {}    # ModManager._changed_game_functions, by both files' size and time
RSB_KEPT = "rsb2"      # what rsblob_symbols keeps in scans.json (2: @replaceMethod, enums)


def rsblob_symbols(path):
    """{(kind, class, name): 'Class.Name' as written} for what a precompiled.rsblob declares
    that only one mod may: @replaceMethod / @addMethod / @addField on a class ('@replacemethod',
    '@addmethod', '@addfield'), classes, structs and enums ('type'), states ('state') and global functions ('function'). The
    same keys as _annotated_symbols, so loose scripts and precompiled ones are checked
    together. {} when it can't be read. Remembered like _annotated_symbols."""
    try:
        st = os.stat(path)
    except OSError:
        return {}
    sig = (str(path), st.st_mtime_ns, st.st_size)
    hit = _RSB_CACHE.get(sig)
    if hit is not None:
        return hit
    kept = KEPT.get(RSB_KEPT, str(path), st)
    if isinstance(kept, list):
        try:
            out = {tuple(k): shown for k, shown in kept}
            _RSB_CACHE[sig] = out
            return out
        except (TypeError, ValueError):
            pass
    out = {}
    try:
        got = rsblob_read(Path(path).read_bytes())
        for cls, nm in got["replace_method"]:
            out[("@replacemethod", cls.lower(), nm.lower())] = f"{cls}.{nm}"
        for cls, nm in got["add_method"]:
            out[("@addmethod", cls.lower(), nm.lower())] = f"{cls}.{nm}"
        for cls, nm in got["add_field"]:
            out[("@addfield", cls.lower(), nm.lower())] = f"{cls}.{nm}"
        for nm in got["types"]:
            out[("type", "", nm.lower())] = nm
        for machine, nm in got["states"]:
            out[("state", machine.lower(), nm.lower())] = f"{machine}.{nm}"
        for nm in got["functions"]:
            out[("function", "", nm.lower())] = nm
    except (OSError, ValueError):
        out = {}
    _RSB_CACHE[sig] = out
    KEPT.put(RSB_KEPT, str(path), st, [[list(k), shown] for k, shown in out.items()])
    return out


class KeptScans:
    """What was read out of a mod's files (the text IDs in a .w3strings, what a script adds with
    @addMethod…), kept between starts in _ModManager/scans.json so the first redraw doesn't
    read them all again. Used only while the file's size, modified time and change time are
    exactly what they were; anything else (or a missing or damaged scans.json) means the file is
    read again. Entries for files that are gone are dropped when it's next written."""
    REV = 1
    MISSING = object()

    def __init__(self):
        self.path, self.data, self.dirty, self.checked = None, None, False, False
        self.lock = threading.Lock()

    def bind(self, path):
        with self.lock:
            if path != self.path:
                self.path, self.data, self.dirty, self.checked = path, None, False, False

    def _files(self):
        if self.data is None:
            data = None
            if self.path is not None:
                try:
                    data = json.loads(Path(self.path).read_text(encoding="utf-8"))
                except (OSError, ValueError):
                    data = None
            if not (isinstance(data, dict) and data.get("rev") == self.REV and isinstance(data.get("files"), dict)):
                data = {"rev": self.REV, "files": {}}
            self.data = data
        return self.data["files"]

    def get(self, kind, path, st):
        with self.lock:
            e = self._files().get(f"{kind}:{path}")
        if isinstance(e, list) and len(e) == 4 and e[:3] == [st.st_size, st.st_mtime_ns, st.st_ctime_ns]:
            return e[3]
        return self.MISSING

    def put(self, kind, path, st, value):
        with self.lock:
            self._files()[f"{kind}:{path}"] = [st.st_size, st.st_mtime_ns, st.st_ctime_ns, value]
            self.dirty = True

    def save(self):
        with self.lock:
            if self.path is None or self.data is None:
                return
            if self.dirty or not self.checked:
                # files that are gone (their mod was removed or moved) are forgotten: looked for
                # whenever something new is written, and once per start
                files = self.data["files"]
                gone = [k for k in files if not os.path.exists(k.split(":", 1)[1])]
                for key in gone:
                    del files[key]
                self.checked, self.dirty = True, self.dirty or bool(gone)
            if not self.dirty:
                return
            text = json.dumps(self.data, separators=(",", ":"))
            self.dirty = False
        path = Path(self.path)
        tmp = path.with_name(path.name + ".tmp")
        try:
            tmp.write_text(text, encoding="utf-8")
            os.replace(tmp, path)
        except OSError:
            tmp.unlink(missing_ok=True)


KEPT = KeptScans()
SCANS_FILE = "scans.json"


def _text_mark(text):
    """A short fingerprint of a text: two mods' texts are compared by it (the same words or not)."""
    return hashlib.blake2b(text.encode("utf-8", "surrogatepass"), digest_size=12).hexdigest()


_W3S_SEEN = {}
W3S_TEXT = {}           # (mod folder, lower-case; string ID) -> its English text's fingerprint: the same words aren't a clash
TEXT_ID = "Text ID "    # how a string ID is named among the files a mod clashes on


def w3strings_file(path):
    """w3strings_read for a file, read once per size and time (and kept between starts, see
    KeptScans). An en.w3strings' texts are kept in W3S_TEXT, as fingerprints, under the mod
    folder it's in (…/mods/<folder>/content/en.w3strings)."""
    try:
        st = os.stat(path)
        key = (str(path), st.st_size, st.st_mtime_ns)
        if key not in _W3S_SEEN:
            if st.st_size > 64 << 20:
                return None
            got = marks = None
            kept = KEPT.get("w3s", str(path), st)
            try:
                if kept is not None:
                    got = {"format": kept["format"], "ids": {int(i) for i in kept["ids"]}}
                    marks = {int(i): str(m) for i, m in kept["texts"].items()}
            except (KeyError, TypeError, ValueError, AttributeError):
                kept = KeptScans.MISSING                     # not from here, or damaged: read it
            if kept is KeptScans.MISSING:
                with open(path, "rb") as f:
                    english = Path(path).name.lower() == "en.w3strings"
                    got = w3strings_read(f.read(), texts=english)
                marks = {i: _text_mark(t) for i, t in (got or {}).pop("texts", {}).items()} if got else {}
                KEPT.put("w3s", str(path), st, None if got is None else {
                    "format": got["format"], "ids": sorted(got.get("ids", ())),
                    "texts": {str(i): m for i, m in marks.items()}})
            if marks:
                parts = [x.lower() for x in Path(path).parts]
                at = len(parts) - 1 - parts[::-1].index("content") if "content" in parts[1:] else 0
                folder = parts[at - 1] if at else ""          # the last "content": the mod's own
                W3S_TEXT.update({(folder, i): m for i, m in marks.items()})
            _W3S_SEEN[key] = got
        return _W3S_SEEN[key]
    except OSError:
        return None


def w3strings_file_format(path):
    """w3strings_format for a file."""
    got = w3strings_file(path)
    return got["format"] if got else None


def version_generation(v):
    """1, 4 or 5: the game generation a version name belongs to ('4.04a' -> 4)."""
    m = re.match(r"\d+", v or "")
    return int(m.group()) if m else 0


def built_in_mod(mod, page_name="", remastered=False):
    """The entry for a mod the next-gen update (or, with remastered=True, the Remastered) made
    unneeded, or None: (name, since which version, [(ID, name) to use instead] or a note).
    Matched by Nexus ID, and only when a word of the name agrees too (the page's name, or the
    mod's own)."""
    nid = str(mod.get("nexus") or "")
    entry = NG_BUILT_IN.get(nid)
    if remastered and nid in REM_BUILT_IN:
        entry = REM_BUILT_IN[nid]
    if not entry:
        return None
    words = lambda t: {w for w in re.findall(r"[a-z0-9]+", (t or "").lower()) if len(w) >= 4}
    listed = words(entry[0])
    if listed & (words(page_name) | words(mod.get("name"))):
        return entry
    return None


def compare_made_for(files, game_versions):
    """files: [(kind, path, versions)] -> the report made_for() describes. game_versions(kind, path)
    gives your game's side."""
    out, older, newer, classic = [], [], [], False
    for kind, rel, mine in files:
        order = SCRIPT_GAME_VERSIONS
        game = game_versions(kind, rel)
        verdict = None
        if game:
            if set(mine) & set(game):
                verdict = "same"
            elif max(order.index(v) for v in mine) < min(order.index(v) for v in game):
                verdict = "older"
                older.append(mine)
                # from an earlier generation of the game (1.x on 4.x, 4.x on 5.x)
                classic = classic or max(map(version_generation, mine)) < min(map(version_generation, game))
            else:
                verdict = "newer"
                newer.append(mine)
        out.append((kind, rel, mine, game, verdict))
    # the versions it was made for: what all its copies agree on, else those of its oldest
    sets = [set(m) for _k, _r, m, _g, _v in out]
    common = set.intersection(*sets) if sets else set()
    if not common and sets:
        oldest = min(out, key=lambda f: SCRIPT_GAME_VERSIONS.index(f[2][0]))
        common = set(oldest[2])
    made = [v for v in SCRIPT_GAME_VERSIONS if v in common]
    status = "classic" if classic else "older" if older else "newer" if newer else ""
    # the chip names the newest version it could be for: "1.32" for a 1.21–1.32 copy
    return {"files": out, "label": version_range(made), "short": made[-1] if made else "", "status": status}


def _short_list(items):
    """Every item, never cut short: the tooltip scrolls when it's long."""
    return [file_html(x) for x in items]


def remaster_rows(rem):
    """Tooltip lines for what in a mod was made for 4.x (made_for()'s 'rem' report)."""
    if not rem:
        return []
    ash = C["ash"]
    rows = []
    # the note above already says why they won't work: a kind of file gets a short name only
    # when there are several kinds to tell apart
    groups = [(head, rem[key]) for key, head in (("packed16", "Packed XML/CSV (UTF-16):"),
                                                  ("strings16", "Strings (.w3strings):"),
                                                  ("srt", "SpeedTree (.srt):"),
                                                  ("cache16", "Collision cache:"),
                                                  ("rebuild", "Caches:" if all(f.lower().endswith(".cache")
                                                                               for f in rem.get("rebuild") or [])
                                                   else "Other files:"),
                                                  ("ui", "UI files:")) if rem.get(key)]
    for head, files in groups:
        rows.append("<br>".join(([f"<span style='color:{ash}'>{html.escape(head)}</span>"] if len(groups) > 1 else [])
                                + _short_list(files)))
    if rem.get("dx11"):
        n = len(rem["dx11"])
        rows.append(f"<span style='color:{ash}'>{n} file{'s' if n != 1 else ''} for the DX11 build (bin/x64), which "
                    f"5.00 doesn't have: not placed</span>")
    return rows


# a collision.cache in an older layout (1.32's or 4.x's; 5.00's is 11, see collision_cache_format): what
# that means for you, said no stronger than what's known. The game can't use the old layout, but
# what it does with one isn't documented: most likely it's skipped
COLLISION_NOTE = ("Its collision.cache is in {fmt}, so the game likely skips it: collision and physics "
                  "shapes may be missing.")


def collision_note(rem):
    """COLLISION_NOTE with the format its collision.cache is actually in."""
    kinds = set((rem.get("cache16_from") or {}).values())
    fmt = ("the classic game's format (1.32 and before)" if kinds == {"1.x"} else
           "next-gen 4.x's format" if kinds == {"4.x"} else "an older format than 5.00's")
    return COLLISION_NOTE.format(fmt=fmt)
COLLISION_FIX = "The rest of the mod works. A Remastered version would fix it."


def remaster_note(made, rem_game=True):
    """The explanation under 'Made for game version …' when the usual one (copies of game files
    from another patch) doesn't fit: on 5.x, or when only the mod's info file says its version."""
    rem = made.get("rem") or {}
    status = made["status"]
    if rem_game and status == "classic":
        parts = []
        if any(f[4] == "older" for f in made["files"]):
            parts.append("Its copies of game files undo what 5.00 changed in them.")
        if rem.get("packed16") or rem.get("srt") or rem.get("strings16") or rem.get("rebuild"):
            parts.append("Some files use an old format the Remastered can't read.")
        if rem.get("cache16"):
            parts.append(collision_note(rem))
        if rem.get("ui"):
            parts.append("UI files from 4.x don't fit 5.00's menus.")
        if not parts and rem.get("dx11"):
            parts.append("It's all for the DX11 build (bin/x64), which 5.00 doesn't have, so nothing is placed.")
        if parts == [collision_note(rem)]:
            return parts[0] + " " + COLLISION_FIX           # only that: the rest of the mod works
        return " ".join(parts + ["Look for a Remastered version of the mod."])
    if made["files"]:
        return None
    if rem_game and rem.get("dx11") and not made.get("declared"):
        return ("It's all for the DX11 build (bin/x64), which 5.00 doesn't have, so nothing is placed. "
                "Look for a Remastered version of the mod.")
    if made.get("declared"):
        said = ", ".join(made["declared"])
        if status == "newer":
            return f"Made for game version {said}, by its info file. Update the game, or find a version for yours."
        return f"Made for game version {said}, by its info file. Find a version for yours."
    return None


def version_range(found):
    """['4.02', '4.03'] -> '4.02–4.03'; a run of versions shown by its ends."""
    if not found:
        return ""
    order = SCRIPT_GAME_VERSIONS                     # every kind's versions are among these
    idx = sorted(order.index(v) for v in found if v in order)
    runs, start = [], idx[0]
    for a, b in zip(idx, idx[1:] + [None]):
        if b != a + 1:
            runs.append(order[start] if start == a else f"{order[start]}–{order[a]}")
            start = b
    return ", ".join(runs)


_FP_DATA = ""   # filled in below the app's code: see the end of this file
MERGE_ENGINE = 10                    # bump to force every merged script to rebuild


def _sha(data):
    if isinstance(data, str):
        data = data.encode("utf-8")
    return hashlib.sha1(data).hexdigest()


# --- text in, text out --------------------------------------------------------
def decode_script(data):
    """bytes -> (lines, format). Format is whatever the file used, so output can match."""
    if data.startswith(codecs.BOM_UTF16_LE):
        enc, bom = "utf-16-le", codecs.BOM_UTF16_LE
    elif data.startswith(codecs.BOM_UTF16_BE):
        enc, bom = "utf-16-be", codecs.BOM_UTF16_BE
    elif data.startswith(codecs.BOM_UTF8):
        enc, bom = "utf-8", codecs.BOM_UTF8
    else:
        bom = b""
        if len(data) > 3 and data[1:2] == b"\x00" and data.count(b"\x00") > len(data) // 4:
            enc = "utf-16-le"
        else:
            enc = None
            for candidate in ("utf-8", "cp1252"):
                try:
                    data.decode(candidate)
                    enc = candidate
                    break
                except UnicodeDecodeError:
                    pass
            enc = enc or "latin-1"
    body = data[len(bom):]
    if enc.startswith("utf-16"):
        body = _unmangle_utf16(body, enc)
    text = body.decode(enc, errors="strict" if enc != "latin-1" else "replace")
    crlf = text.count("\r\n")
    newline = "\r\n" if crlf and crlf >= text.count("\n") - crlf else "\n"
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    final = text.endswith("\n")
    lines = (text[:-1] if final else text).split("\n") if text else []
    return lines, {"encoding": enc, "bom": bom, "newline": newline, "final": final}


def _unmangle_utf16(body, enc):
    """Undo git's line-ending conversion run over a UTF-16 LE file: it slips a stray CR byte in
    front of every line-feed byte, shifting everything after it by one byte, so the file won't
    decode or decodes as nonsense. Each stray byte lands where a character starts, and reads
    as U+0A0D — a character no real text contains — so each such spot loses its first byte.
    An undamaged file is returned as it was; an odd last byte is dropped."""
    if enc != "utf-16-le":
        return body[:len(body) - len(body) % 2]
    damaged = len(body) % 2 or any(body[i] == 0x0D and body[i + 1] == 0x0A for i in range(0, len(body) - 1, 2))
    if not damaged:
        return body
    out, i = bytearray(), 0
    while i + 1 < len(body):
        if body[i] == 0x0D and body[i + 1] == 0x0A:
            i += 1                                   # the stray byte: skip it, read on in step
            continue
        out += body[i:i + 2]
        i += 2
    return bytes(out)


def encode_script(lines, fmt):
    nl = fmt["newline"]
    text = nl.join(lines) + (nl if lines and fmt["final"] else "")
    return fmt["bom"] + text.encode(fmt["encoding"])


def output_formats(lines, base_fmt, decoded):
    """Formats to try for a merged script, best first. Vanilla's own format, unless the merge
    carries non-English text and vanilla's format was only a guess (plain ASCII, no BOM):
    then a format with a BOM, or the one the mod that wrote that text used, so the game
    reads the text the way that mod intended."""
    mods = [fmt for _l, fmt in decoded]
    if base_fmt["encoding"] == "utf-8":
        # the game's own copy is UTF-8 (all of 5.00's text is, and the game reads nothing else):
        # so is the merge, whatever the mods' copies were saved as
        return [base_fmt]
    if base_fmt["bom"] or all(line.isascii() for line in lines):
        return [base_fmt] + mods
    with_bom = [f for f in mods if f["bom"]]
    writers = [fmt for mod_lines, fmt in decoded if not all(l.isascii() for l in mod_lines)]
    return with_bom + writers + [base_fmt] + mods


def encode_script_safely(lines, formats):
    """Encode in the first format that can hold the text, and prove it reads back."""
    for fmt in formats:
        try:
            data = encode_script(lines, fmt)
        except UnicodeEncodeError:
            continue
        if decode_script(data)[0] == lines:
            return data
    fallback = {"encoding": "utf-16-le", "bom": codecs.BOM_UTF16_LE,
                "newline": formats[0]["newline"] if formats else "\r\n", "final": True}
    return encode_script(lines, fallback)


def encode_xml_safely(lines, formats):
    """encode_script_safely for an XML file: its declaration says the encoding it's written in."""
    for fmt in formats:
        name = "UTF-16" if fmt["encoding"].startswith("utf-16") else fmt["encoding"].upper()
        fixed = list(lines)
        if fixed:
            fixed[0] = re.sub(r'(<\?xml[^>]*encoding\s*=\s*["\'])[^"\']*(["\'])', lambda m: m.group(1) + name + m.group(2),
                              fixed[0], count=1)
        try:
            data = encode_script(fixed, fmt)
        except UnicodeEncodeError:
            continue
        if decode_script(data)[0] == fixed:
            return data
    return encode_script_safely(lines, formats)


# --- diff -------------------------------------------------------------------------
# Histogram diff, the algorithm git recommends for code, written out here so merging needs
# nothing installed. It anchors on the rarest line two versions share, so a change isn't
# matched against a lookalike line elsewhere in the file. Correctness doesn't rest on the
# diff being perfect: every mod's changes must rebuild that mod's file exactly, or the
# merge is refused.
_MAX_CHAIN = 64          # lines more common than this aren't used as anchors (as in git)


def _anchor(a, b, a0, a1, b0, b1):
    """The best matching run inside a[a0:a1] and b[b0:b1], grown out from the rarest shared
    line: (a_start, a_end, b_start, b_end). None when nothing is shared, "dense" when every
    shared line is too common to anchor on."""
    occ = {}
    for i in range(a0, a1):
        occ.setdefault(a[i], []).append(i)
    best, best_cnt, shared = None, _MAX_CHAIN + 1, False
    j = b0
    while j < b1:
        nxt = j + 1
        where = occ.get(b[j])
        if where:
            shared = True
            if len(where) <= best_cnt:
                for i in where:
                    as_, bs, ae, be, rc = i, j, i + 1, j + 1, len(where)
                    while as_ > a0 and bs > b0 and a[as_ - 1] == b[bs - 1]:
                        as_ -= 1
                        bs -= 1
                        if rc > 1:
                            rc = min(rc, len(occ[a[as_]]))
                    while ae < a1 and be < b1 and a[ae] == b[be]:
                        if rc > 1:
                            rc = min(rc, len(occ[a[ae]]))
                        ae += 1
                        be += 1
                    nxt = max(nxt, be)
                    if best is None or ae - as_ > best[1] - best[0] or rc < best_cnt:
                        best, best_cnt = (as_, ae, bs, be), rc
        j = nxt
    if best is None:
        return "dense" if shared else None
    return best


def _matching_blocks(a, b):
    """[(a index, b index, length)] of lines the two versions share, in order."""
    n, m = len(a), len(b)
    lo = 0
    while lo < n and lo < m and a[lo] == b[lo]:
        lo += 1
    ea, eb = n, m
    while ea > lo and eb > lo and a[ea - 1] == b[eb - 1]:
        ea -= 1
        eb -= 1
    blocks = [(0, 0, lo)] if lo else []
    stack = [(lo, ea, lo, eb)]
    while stack:
        a0, a1, b0, b1 = stack.pop()
        if a0 >= a1 or b0 >= b1:
            continue
        found = _anchor(a, b, a0, a1, b0, b1)
        if found is None:
            continue
        if isinstance(found, str):          # only very common lines left: plain LCS here
            sm = difflib.SequenceMatcher(None, a[a0:a1], b[b0:b1], autojunk=False)
            blocks += [(a0 + i, b0 + j, k) for i, j, k in sm.get_matching_blocks() if k]
            continue
        as_, ae, bs, be = found
        blocks.append((as_, bs, ae - as_))
        stack.append((a0, as_, b0, bs))
        stack.append((ae, a1, be, b1))
    if ea < n:
        blocks.append((ea, eb, n - ea))
    return sorted(blocks)


def diff_hunks(a, b):
    """[(start, end, new_lines)]: a[start:end] becomes new_lines. Pure additions and
    removals are slid down as far as identical lines allow (as git does), so a new
    function lands after the closing brace of the one before it rather than inside it."""
    if a == b:
        return []
    return [(s0, e0, b[s1:e1]) for s0, e0, s1, e1 in _raw_hunks(a, b)]


def _norm_line(line):
    s = line.rstrip()
    body = s.lstrip()
    if not body:
        return ""
    return " " * len(s[:len(s) - len(body)].expandtabs(4)) + body


def key_clash_lines(d, mgr):
    """A mod's keybind clashes for its tooltip, one line per key, saying which mod kept it:
    "IK_F5 in Exploration · kept by Brothers In Arms", or "IK_F5 in Exploration · kept, also
    wanted by Friendly HUD". Clashes noted by an older version (keys only): the keys."""
    detail = d.get("key_clash_detail") or []
    if not detail:
        return [html.escape(", ".join(d["key_clash"]))]
    name = lambda mid: (mgr.get(mid) or {}).get("name") or "another mod"
    keys = {}
    for section, key, other, kept in detail:
        k = keys.setdefault((section.lower(), key.lower()), {"section": section, "key": key, "by": None, "also": []})
        if kept:
            k["also"].append(name(other))
        else:
            k["by"] = name(other)
    out = []
    for k in keys.values():
        where = f"{k['key']} in {k['section']}"
        if k["by"]:
            out.append(html.escape(f"{where} · kept by {k['by']}"))
        else:
            out.append(html.escape(f"{where} · kept, also wanted by {', '.join(dict.fromkeys(k['also']))}"))
    return out


def bundle_outliers(counts):
    """Which of these bundle counts stand out: ({indices}, what most have, as "1" or "1 to 3").
    Measured against the middle of the list (the median), so one big mod doesn't shift what
    counts as usual: at least three times that, and at least 5. Needs five mods or more to say."""
    if len(counts) < 5:
        return set(), ""
    ordered = sorted(counts)
    mid = ordered[len(ordered) // 2] if len(ordered) % 2 else (ordered[len(ordered) // 2 - 1] + ordered[len(ordered) // 2]) / 2
    limit = max(5, 3 * mid)
    odd = {k for k, n in enumerate(counts) if n >= limit}
    rest = sorted(n for k, n in enumerate(counts) if k not in odd)
    lo, hi = (rest[len(rest) // 4], rest[(3 * len(rest)) // 4]) if rest else (0, 0)
    usual = f"{lo}" if lo == hi else f"{lo} to {hi}"
    return odd, usual


def merge_contributors(rec):
    """(label, owner) of the copies that went into a merge with changes of their own: a mod's copy
    identical to the game's file (a mod that ships the whole scripts folder, say) adds nothing,
    so it isn't named as merged with the others."""
    same = set(rec.get("unchanged") or ())
    return [(label, owner) for i, (label, owner) in enumerate(zip(rec.get("labels", []), rec.get("owners", [])))
            if i not in same]


def _same_as_game(lines, base_lines):
    """Is a mod's copy the game's own file, apart from trailing spaces, tabs vs spaces and blank
    lines at the end?"""
    def trim(x):
        x = _norm(x)
        while x and not x[-1]:
            x.pop()
        return x
    return trim(lines) == trim(base_lines)


def _norm(lines):
    """Lines as the merge compares them: trailing spaces don't count, and indentation counts by
    depth only (a tab is four spaces) — so a mod saved with spaces for tabs, or trailing spaces
    stripped, doesn't look changed where it isn't. Depth still counts: a function's closing
    brace never passes for an inner block's, which would line the versions up wrongly."""
    return [_norm_line(l) for l in lines]


def line_hunks(base, lines):
    """A version's changes to `base`, one changed line at a time where lines pair up (trailing
    spaces and tab/space indentation don't count). A block rewritten into more lines is its
    lines changed in order plus the extra ones added after; into fewer, the leftover ones
    removed. New text is always the version's own.
    Code a version puts inside a /* */ comment (or takes out of one) is gone for the compiler
    (or new), however untouched its lines look, so the whole stretch counts as one change —
    another mod's edit inside it is then a clash, never quietly commented out."""
    nb, nl = _norm(base), _norm(lines)
    if nb == nl:
        return []
    raw = _raw_hunks(nb, nl)
    spans = _comment_spans_changed(base, lines, raw)
    if not spans:
        return _split_hunks(nb, nl, lines, raw)
    inside = lambda h: any(bs <= h[0] and h[1] <= be and as_ <= h[2] and h[3] <= ae
                           for bs, be, as_, ae in spans)
    out = _split_hunks(nb, nl, lines, [h for h in raw if not inside(h)])
    out = sorted(out + [(bs, be, list(lines[as_:ae])) for bs, be, as_, ae in spans],
                 key=lambda h: (h[0], h[1]))
    if _norm(apply_hunks(base, out)) != nl:              # never at the cost of rebuilding it exactly
        return _split_hunks(nb, nl, lines, raw)
    return out


def _split_hunks(nb, nl, lines, raw):
    out = []
    for s0, e0, s1, e1 in raw:
        m, n = e0 - s0, e1 - s1
        k = min(m, n)
        for j in range(k):
            if nb[s0 + j] != nl[s1 + j]:
                out.append((s0 + j, s0 + j + 1, [lines[s1 + j]]))
        if n > k:
            out.append((s0 + k, s0 + k, list(lines[s1 + k:e1])))
        elif m > k:
            out.append((s0 + k, e0, []))
    return out


_COMMENT_CACHE = {}


def _comment_spans(lines):
    """(first, last) line of every /* */ comment that runs over more than one line."""
    text = "\n".join(lines)
    hit = _COMMENT_CACHE.get(text)
    if hit is not None:
        return hit
    out, line = [], 0
    for m in _TOKEN_RE.finditer(text):
        kind = m.lastgroup
        if kind == "nl":
            line += 1
        elif kind == "bc":
            n = m.group().count("\n")
            if n:
                out.append((line, line + n))
            line += n
    if len(_COMMENT_CACHE) > 32:
        _COMMENT_CACHE.clear()
    _COMMENT_CACHE[text] = out
    return out


def _comment_spans_changed(base, lines, raw):
    """[bs, be, as, ae]: base[bs:be] that a version turned into lines[as:ae] by opening or
    closing a /* */ comment around code — its /* or */ line is one of the version's changes."""
    def where(p, side):
        """Line p of the version (side 1) or of vanilla (side 0): the change it's part of,
        or where the same line sits on the other side."""
        pa = pb = 0
        for h in raw:
            s, e = (h[2], h[3]) if side else (h[0], h[1])
            if p < s:
                break
            if p < e:
                return h, None
            pa, pb = h[1], h[3]
        return None, (pa + (p - pb)) if side else (pb + (p - pa))

    spans = []
    for side, comments in ((1, _comment_spans(lines)), (0, _comment_spans(base))):
        for p, q in comments:
            hp, op = where(p, side)
            hq, oq = where(q, side)
            if (hp is None and hq is None) or (hp is not None and hp is hq):
                continue                       # left as it was, or wholly new text
            if side:
                bs, as_ = (hp[0], hp[2]) if hp else (op, p)
                be, ae = (hq[1], hq[3]) if hq else (oq + 1, q + 1)
            else:
                bs, as_ = (hp[0], hp[2]) if hp else (p, op)
                be, ae = (hq[1], hq[3]) if hq else (q + 1, oq + 1)
            spans.append([bs, be, as_, ae])
    spans.sort()
    merged = []
    for s in spans:
        if merged and s[0] <= merged[-1][1] and s[2] <= merged[-1][3]:
            m = merged[-1]
            m[1], m[3] = max(m[1], s[1]), max(m[3], s[3])
        else:
            merged.append(s)
    return merged


def _raw_hunks(a, b):
    """[[a_start, a_end, b_start, b_end]] of every differing stretch."""
    raw, pa, pb = [], 0, 0
    for i, j, k in _matching_blocks(a, b) + [(len(a), len(b), 0)]:
        if i > pa or j > pb:
            raw.append([pa, i, pb, j])                  # a[pa:i] -> b[pb:j]
        pa, pb = i + k, j + k
    for n, h in enumerate(raw):
        limit = raw[n + 1][0] if n + 1 < len(raw) else len(a)
        s0, e0, s1, e1 = h
        if s0 == e0 and s1 < e1:                         # pure addition
            while e0 + 1 < limit and e1 < len(b) and b[s1] == b[e1] == a[e0]:
                s0 += 1; e0 += 1; s1 += 1; e1 += 1
        elif s1 == e1 and s0 < e0:                       # pure removal
            while e0 + 1 < limit and a[s0] == a[e0]:
                s0 += 1; e0 += 1; s1 += 1; e1 += 1
        h[:] = [s0, e0, s1, e1]
    return raw


def apply_hunks(base, hunks, lo=0, hi=None):
    """base[lo:hi] with every hunk that falls inside it applied."""
    hi = len(base) if hi is None else hi
    out, pos = [], lo
    for start, end, new in sorted(hunks, key=lambda h: (h[0], h[1])):
        if start < lo or end > hi:
            continue
        out += base[pos:start]
        out += new
        pos = end
    return out + base[pos:hi]


# --- understanding WitcherScript well enough to check it ----------------------
_TOKEN_RE = re.compile(r"""
    (?P<nl>\n)
  | (?P<bc>/\*.*?\*/)
  | (?P<bcopen>/\*)
  | (?P<lc>//[^\n]*)
  | (?P<str>"(?:\\.|[^"\\\n])*")
  | (?P<strbad>")
  | (?P<cname>'(?:\\.|[^'\\\n])*')
  | (?P<cnamebad>')
  | (?P<id>[A-Za-z_]\w*)
  | (?P<open>[{(\[])
  | (?P<close>[})\]])
  | (?P<bcend>\*/(?!\*))
  | (?P<ws>[^\n/"'A-Za-z_{}()\[\];@*]+)
  | (?P<other>.)
""", re.S | re.X)
_PAIRS = {"}": "{", ")": "(", "]": "["}
_FUNC_WORDS = {"function", "event"}
_SCOPE_WORDS = {"class", "state", "struct", "enum"}


_SCAN_CACHE = {}


def scan_script(lines):
    """-> (functions, problems).
    functions: [(first_line, last_line, name, owner)] for every function with a body.
    problems:  [(line, text)] for anything unbalanced or unterminated.
    A merge checks the same texts several times, so recent results are remembered."""
    hit = _scan_cached(lines)
    return list(hit[0]), list(hit[1])


def scan_decls(lines):
    """Declarations that must be unique: types (class/struct/enum), states, class fields,
    and @addMethod / @addField / @replaceMethod additions — as (kind, owner, name) keys."""
    return list(_scan_cached(lines)[2])


def _scan_cached(lines):
    text = "\n".join(lines)
    hit = _SCAN_CACHE.get(text)
    if hit is None:
        if len(_SCAN_CACHE) > 32:
            _SCAN_CACHE.clear()
        hit = _SCAN_CACHE[text] = _scan(text)
    return hit


_UNIQUE_ANNOTATIONS = {"addmethod", "addfield", "replacemethod"}
_VAR_WORDS = {"var", "autobind"}


def _scan(text):
    stack, functions, problems, decls = [], [], [], []
    line = 0
    paren = 0
    pending_fn = None          # {"name", "line", "ready", "annotated"}
    pending_scope = None       # name of a class/state/struct/enum awaiting its "{"
    scope_kind = None
    scope_parent = None        # "state X in Y": Y
    expect_scope_name = False
    expect_parent = False
    annotated = False
    ann = []                   # words of the annotation being read: @addMethod(CR4Player)
    var_mode = None            # reading field names after "var": the annotation key, or ""

    def owner_now():
        return ".".join(s[1] for s in stack if s[0] == "scope")

    def ann_key():
        return ann[0] if ann else ""

    for m in _TOKEN_RE.finditer(text):
        kind, tok = m.lastgroup, m.group()
        if kind == "nl":
            line += 1
            continue
        if kind in ("bc", "lc", "ws"):
            line += tok.count("\n")
            if var_mode is not None and kind == "ws" and ":" in tok:
                var_mode = None                    # the type follows, not another name
            continue
        if kind == "bcopen":
            problems.append((line, "comment that never ends"))
            break
        if kind == "bcend":
            problems.append((line, "“*/” with no comment to end"))
            continue
        if kind in ("strbad", "cnamebad"):
            problems.append((line, "text in quotes that never ends"))
            continue
        if kind == "other" and tok == "@":
            annotated, ann = True, []
            continue
        if kind == "id":
            if expect_scope_name:
                pending_scope, expect_scope_name = tok, False
                expect_parent = scope_kind == "state"
            elif expect_parent and tok == "in":
                pass
            elif expect_parent:
                scope_parent, expect_parent = tok, False
            elif var_mode is not None:
                how, arg = var_mode
                if how in _UNIQUE_ANNOTATIONS:
                    decls.append(("@" + how, arg, tok.lower()))
                elif not how and (not stack or stack[-1][0] == "scope"):
                    decls.append(("var", owner_now().lower(), tok.lower()))
            elif tok in _FUNC_WORDS and paren == 0:
                pending_fn = {"name": None, "line": line, "ready": False, "annotated": annotated,
                              "ann": ann_key() if annotated else "", "ann_arg": " ".join(ann[1:])}
                annotated, ann = False, []
            elif tok in _VAR_WORDS and paren == 0 and pending_fn is None:
                var_mode = (ann_key(), " ".join(ann[1:])) if annotated else ("", "")
                annotated, ann = False, []
            elif tok in _SCOPE_WORDS and paren == 0 and pending_fn is None:
                expect_scope_name, scope_kind, scope_parent = True, tok, None
            elif pending_fn is not None and pending_fn["name"] is None:
                pending_fn["name"] = tok
            elif annotated and pending_fn is None:
                ann.append(tok.lower())
            continue
        if kind == "open":
            if tok == "(":
                paren += 1
            if tok in "([":
                stack.append(("pair", tok, line))
                continue
            if pending_fn is not None and pending_fn["ready"]:
                stack.append(("func", pending_fn, line))
                pending_fn = None
            elif pending_scope is not None:
                if scope_kind == "state":
                    decls.append(("state", (scope_parent or "").lower(), pending_scope.lower()))
                else:
                    decls.append(("type", owner_now().lower(), pending_scope.lower()))
                stack.append(("scope", pending_scope, line))
                pending_scope = None
            else:
                stack.append(("block", None, line))
            annotated = False
            continue
        if kind == "close":
            if tok == ")":
                paren = max(0, paren - 1)
                if pending_fn is not None and pending_fn["name"] and paren == 0:
                    pending_fn["ready"] = True
            want = _PAIRS[tok]
            if tok == "}":
                # close the innermost brace, reporting anything left open inside it
                while stack and stack[-1][0] == "pair":
                    problems.append((stack[-1][2], f"“{stack[-1][1]}” is never closed"))
                    stack.pop()
                if not stack:
                    problems.append((line, "“}” with nothing to close"))
                    continue
                what, info, start = stack.pop()
                if what == "func":
                    owner = ".".join(s[1] for s in stack if s[0] == "scope")
                    functions.append((info["line"], line, info["name"], owner, info["annotated"]))
                    if info["ann"] in _UNIQUE_ANNOTATIONS and info["name"]:
                        decls.append(("@" + info["ann"], info["ann_arg"], info["name"].lower()))
            else:
                if stack and stack[-1][0] == "pair" and stack[-1][1] == want:
                    stack.pop()
                else:
                    problems.append((line, f"“{tok}” with nothing to close"))
            continue
        if kind == "other" and tok == ";" and paren == 0:
            pending_fn = None          # a declaration without a body
            pending_scope = None
            expect_scope_name = expect_parent = False
            annotated, ann, var_mode = False, [], None
    for what, info, start in stack:
        label = "{" if what != "pair" else info
        problems.append((start, f"“{label}” is never closed"))
    return tuple(functions), tuple(problems), tuple(decls)


def duplicate_functions(functions):
    """{(owner, name)} defined more than once — WitcherScript has no overloading."""
    seen, dups = {}, set()
    for _first, _last, name, owner, annotated in functions:
        if annotated or not name:
            continue
        key = (owner.lower(), name.lower())
        if key in seen:
            dups.add(seen[key])
        else:
            seen[key] = (owner, name)
    return dups


_ANN_CACHE = {}
_ANN_WORDS = (b"@addmethod", b"@addfield", b"@replacemethod")


def _annotated_symbols(path):
    """{(annotation, class, name): 'Class.Name' as written} for what a script file adds or
    replaces through @addMethod, @addField or @replaceMethod. Remembered by size and time,
    so the mod list stays quick."""
    try:
        st = os.stat(path)
    except OSError:
        return {}
    sig = (str(path), st.st_mtime_ns, st.st_size)
    hit = _ANN_CACHE.get(sig)
    if hit is not None:
        return hit
    kept = KEPT.get("ann", str(path), st)               # from an earlier start (see KeptScans)
    if isinstance(kept, list):
        try:
            out = {tuple(k): shown for k, shown in kept}
            _ANN_CACHE[sig] = out
            return out
        except (TypeError, ValueError):
            pass
    out = {}
    try:
        data = Path(path).read_bytes()
        wide = data[:2] in (b"\xff\xfe", b"\xfe\xff") or b"\x00" in data[:400]
        if wide or any(w in data.lower() for w in _ANN_WORDS):
            lines = decode_script(data)[0]
            spelt = {}
            for word in _ID_RE.findall(_strip_code("\n".join(lines))):
                spelt.setdefault(word.lower(), word)
            for d in scan_decls(lines):
                if d[0].startswith("@"):
                    out[d] = ".".join(spelt.get(p, p) for p in d[1:] if p)
    except (OSError, UnicodeError, ValueError):
        pass
    if len(_ANN_CACHE) > 20000:
        _ANN_CACHE.clear()
    _ANN_CACHE[sig] = out
    KEPT.put("ann", str(path), st, [[list(k), shown] for k, shown in out.items()])
    return out


def duplicate_decls(decls):
    seen, dups = set(), set()
    for d in decls:
        (dups if d in seen else seen).add(d)
    return dups


def removed_but_used(base, versions, merged):
    """(name, mod) when a mod deletes a function but the merge still calls it — another mod
    added the call. That would fail to compile, so it isn't merged. None if all is well."""
    defined = {(n or "").lower() for _f, _l, n, _o, _a in scan_script(merged)[0]}
    base_names = {(n or "").lower(): n for _f, _l, n, _o, _a in scan_script(base)[0] if n}
    words = lambda lines: set(re.findall(r"[A-Za-z_]\w*", "\n".join(lines).lower()))
    merged_words = None
    for label, lines in versions:
        mine = {(n or "").lower() for _f, _l, n, _o, _a in scan_script(lines)[0]}
        removed = [k for k in base_names if k not in mine and k not in defined]
        if not removed:
            continue
        merged_words = merged_words if merged_words is not None else words(merged)
        own = words(lines)
        for k in removed:
            if k in merged_words and k not in own:
                return base_names[k], label
    return None


_STRIP_RE = re.compile(r"""/\*.*?\*/|//[^\n]*|"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'""", re.S)
_LOCAL_VAR_RE = re.compile(r"\bvar\s+([A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*)\s*:")
_PARAM_RE = re.compile(r"(?:^|[(,])\s*(?:(?:optional|out)\s+)*([A-Za-z_]\w*)\s*:")
_USE_RE = re.compile(r"(?<![\w.])([A-Za-z_]\w*)")


def _own_body(text):
    """(head, body) of one function's text: everything before its first "{", and from there to
    the matching "}" — so a function sharing a line with the next one (`}function G() {`) ends
    where it really ends. text is already stripped of comments and quotes."""
    brace = text.find("{")
    if brace < 0:
        return text, ""
    depth = 0
    for k in range(brace, len(text)):
        if text[k] == "{":
            depth += 1
        elif text[k] == "}":
            depth -= 1
            if depth == 0:
                return text[:brace], text[brace:k + 1]
    return text[:brace], text[brace:]


def _strip_code(text):
    """Comments and quoted text blanked out (same length, same lines), so names in them never count."""
    return _STRIP_RE.sub(lambda m: re.sub(r"[^\n]", " ", m.group()), text)


def _function_locals(lines, first, last):
    """For one function: ({local name: [lines it's declared on]}, {parameter names},
    {name: first line it's used on}) — lines counted from the function's first line."""
    text = _strip_code("\n".join(lines[first:last + 1]))
    head, body = _own_body(text)
    if not body:
        return {}, set(), {}
    a, b = head.find("("), head.rfind(")")
    params = {m.group(1).lower() for m in _PARAM_RE.finditer(head[a:b + 1])} if 0 <= a < b else set()
    declared, spans = {}, []
    for m in _LOCAL_VAR_RE.finditer(body):
        spans.append((m.start(), m.end()))
        at = head.count("\n") + body.count("\n", 0, m.start())
        for name in re.split(r"\s*,\s*", m.group(1)):
            declared.setdefault(name.lower(), []).append(at)
    used = {}
    for m in _USE_RE.finditer(body):
        if any(s0 <= m.start() < e0 for s0, e0 in spans):
            continue                                   # the declaration itself isn't a use
        name = m.group(1).lower()
        if name not in used:
            used[name] = head.count("\n") + body.count("\n", 0, m.start())
    return declared, params, used


_TOK_RE = re.compile(r"[A-Za-z_]\w*|\S")


def _structure_faults(lines, first, last):
    """Rules the game's script compiler enforces that a merge can break by putting two mods'
    lines together, for one function: [(line counted from `first`, what)].
      - every `var` comes before the function's first statement (invalid-local-var-placement)
      - an `else` follows the block of an `if`, never another `else` or a loop's block"""
    text = _strip_code("\n".join(lines[first:last + 1]))
    head, body = _own_body(text)
    if not body:
        return []
    start = len(head)
    text = text[:start + len(body)]
    toks = [(m.group(), text.count("\n", 0, m.start())) for m in _TOK_RE.finditer(text, start + 1)]
    out = []
    i = 0
    while i < len(toks) and toks[i][0] == "var":                  # the declarations up front
        while i < len(toks) and toks[i][0] != ";":
            i += 1
        i += 1
    for word, line in toks[i:]:
        if word == "var":
            out.append((line, "has a var line after other code (the game requires them first)"))
            break
    # else: the block before it must belong to an if( … )
    pair = {}
    stack = []
    for k, (t, _l) in enumerate(toks):
        if t in "({":
            stack.append(k)
        elif t in ")}" and stack:
            pair[k] = stack.pop()
    for k, (t, line) in enumerate(toks):
        if t != "else" or k == 0 or toks[k - 1][0] != "}":
            continue
        opener = pair.get(k - 1)
        if opener is None or opener == 0:
            continue
        before = toks[opener - 1][0]
        if before == "else":
            out.append((line, "has an else after another else"))
        elif before == ")":
            paren = pair.get(opener - 1)
            head = toks[paren - 1][0] if paren else ""
            if head in ("for", "while", "switch"):
                out.append((line, f"has an else after a {head} block"))
    return out


def structure_problems(base, versions, merged):
    """[(owner, name, line in merged, what)] for functions where the merge broke one of the
    rules in _structure_faults — only where no input already had that fault in that function."""
    def faults(lines):
        out = {}
        for first, last, name, owner, _a in scan_script(lines)[0]:
            if name:
                got = _structure_faults(lines, first, last)
                out[(owner.lower(), name.lower())] = ({w for _l, w in got}, first, got)
        return out
    before = [faults(v) for v in [base] + [v for _l, v in versions]]
    out = []
    for first, last, name, owner, _a in scan_script(merged)[0]:
        if not name:
            continue
        key = (owner.lower(), name.lower())
        for line, what in _structure_faults(merged, first, last):
            if not any(what in b.get(key, (set(),))[0] for b in before):
                out.append((owner, name, first + line, what))
    return out


def local_problems(base, versions, merged):
    """[(owner, name, line in merged, what's wrong)] for local variables the merge got wrong:
    one still used after its `var` line was dropped, or one declared twice. Only names some
    version of that very function declared count, so class fields and globals never trip it;
    and a function that's exactly as one of the inputs had it is never blamed."""
    inputs = [base] + [v for _l, v in versions]
    index = []
    for lines in inputs:
        fns = {}
        for first, last, name, owner, _a in scan_script(lines)[0]:
            if name:
                fns.setdefault((owner.lower(), name.lower()), (first, last))
        index.append((lines, fns))
    fields = {d[2] for d in scan_decls(merged) if d[0] == "var"}
    out = []
    for first, last, name, owner, _a in scan_script(merged)[0]:
        if not name:
            continue
        key = (owner.lower(), name.lower())
        text = merged[first:last + 1]
        theirs = [(lines, fns[key]) for lines, fns in index if key in fns]
        if any(lines[f:l + 1] == text for lines, (f, l) in theirs):
            continue                                   # as some input had it: not the merge's doing
        declared, params, used = _function_locals(merged, first, last)
        before = [_function_locals(lines, f, l) for lines, (f, l) in theirs]
        for local, where in declared.items():
            if len(where) > 1 and not any(len(d.get(local, ())) > 1 for d, _p, _u in before):
                out.append((owner, name, first + where[1], f"declares {local} twice"))
        known = set().union(*(set(d) | p for d, p, _u in before)) if before else set()
        for local in sorted(known - set(declared) - params - fields):
            if local in used:
                shown = next((w for w in re.findall(r"[A-Za-z_]\w*", "\n".join(text)) if w.lower() == local), local)
                out.append((owner, name, first + used[local], f"uses {shown}, but its var line is gone"))
    return out


def function_at(functions, start, end):
    """The innermost function whose body contains base lines [start, end)."""
    best = None
    for first, last, name, owner, _a in functions:
        if end > start:
            inside = first <= start and end - 1 <= last        # includes the signature line
        else:
            inside = first < start <= last                     # an insertion inside the body
        if inside and (best is None or first > best[0]):
            best = (first, last, name, owner)
    return best


def _landing(pieces, start):
    """Line in the output where base line `start` ends up, given the edits applied."""
    shift = 0
    for s, e, new in sorted(pieces, key=lambda h: (h[0], h[1])):
        if e <= start and not (s == e == start):
            shift += len(new) - (e - s)
    return start + shift


_GONE = ("<deleted>",)


def _bodies(lines, functions=None):
    """{(owner, name): body lines}. Annotated wrappers and duplicated names are left out,
    since a name alone doesn't identify them."""
    functions = scan_script(lines)[0] if functions is None else functions
    out, seen = {}, set()
    for first, last, name, owner, annotated in functions:
        if annotated or not name:
            continue
        key = (owner.lower(), name.lower())
        if key in seen:
            out.pop(key, None)
            continue
        seen.add(key)
        out[key] = tuple(lines[first:last + 1])
    return out


def _keys_touching(functions, lo, hi):
    keys = set()
    for first, last, name, owner, _a in functions:
        if (first < hi and last >= lo) if hi > lo else (first < lo <= last):
            keys.add((owner.lower(), name.lower()))
    return keys


def _combine_bodies(original, bodies):
    """Merge several mods' versions of one function on their own, by name — the independent
    second opinion on a whole-file merge, by the same rules. None if they clash."""
    if _GONE in bodies or original == _GONE:
        return None
    orig = list(original)
    clusters = _clusters(orig, [line_hunks(orig, list(b)) for b in bodies], fn_of=lambda s, e: 0)
    if any(c["kind"] != "clean" for c in clusters):
        return None
    out = apply_hunks(orig, [(c["start"], c["end"], c["text"]) for c in clusters])
    if _net(out) != _net(orig):
        return None
    if _faults(out) - set().union(*(_faults(list(b)) for b in [original] + list(bodies))):
        out = _hoist_vars(out)                         # the same move the merge makes
    return tuple(_norm(out)) if out is not None else None


def function_check(base, versions, merged, pieces, user_pieces, decided_texts=()):
    """Match functions by name, not by position: in the merged script, a function no mod
    changed must equal vanilla, one changed by a single mod must equal that mod's version
    exactly, and one changed by several must equal merging just that function on its own.
    Text merges can slip a change into a lookalike neighbouring function; this catches it
    wherever it lands. Functions you decided on in the resolver are skipped. Compares lines
    as the merge does (spacing at the ends ignored). Returns the first problem, or None."""
    base, merged = _norm(base), _norm(merged)
    versions = [(l, _norm(v)) for l, v in versions]
    base_fns, merged_fns = scan_script(base)[0], scan_script(merged)[0]
    b, m = _bodies(base, base_fns), _bodies(merged, merged_fns)
    mods = [_bodies(v) for _l, v in versions]
    yours = set()
    for s_, e_, new in user_pieces:
        at = _landing(pieces, s_)
        yours |= _keys_touching(merged_fns, at, at + len(new))
        yours |= _keys_touching(base_fns, s_, e_)
    # a function a mod added inside a spot you decided on is yours too: dropping it was the choice
    added_there = {n.lower() for vs in (decided_texts or ()) for _f, _l, n, _o, _a in scan_script(list(vs))[0] if n}
    for key in sorted(set(b) | set(m) | set().union(*mods)):
        if key in yours or (key not in b and key[1] in added_there):
            continue
        original = b.get(key, _GONE)
        changed = {mv.get(key, _GONE) for mv in mods} - {original}
        name = ".".join(x for x in key if x)
        if len(changed) > 1:
            if m.get(key, _GONE) == _combine_bodies(original, sorted(changed)):
                continue                  # merging the function alone agrees
            return f"{name} was changed by several mods without being flagged"
        expected = changed.pop() if changed else original
        if m.get(key, _GONE) != expected:
            if expected == _GONE:
                return f"{name} ended up in the merge though every mod removed it"
            if m.get(key, _GONE) == _GONE:
                return f"{name} went missing from the merge"
            who = "vanilla" if expected == original else "the mod that changed it"
            return f"{name} doesn't match {who}"
    return None


# --- the merge ----------------------------------------------------------------
def _collide(a, b):
    """Do two changes in vanilla coordinates (start, end) get in each other's way?"""
    (s1, e1), (s2, e2) = a, b
    if s1 == e1 and s2 == e2:
        return s1 == s2                          # two insertions at the same spot
    # an insertion inside, or right at either edge of, the lines another mod replaces
    if s1 == e1:
        return s2 <= s1 <= e2
    if s2 == e2:
        return s1 <= s2 <= e1
    return s1 < e2 and s2 < e1                   # both change some of the same lines


def _contains(base_r, small, big):
    """Does `big` already make every change `small` makes (normalised lines of one spot)?
    small's lines appear in big in the same order, and whatever small removed, big removed too."""
    ops = difflib.SequenceMatcher(None, small, big, autojunk=False).get_opcodes()
    if any(tag in ("replace", "delete") for tag, *_r in ops):
        return False
    cb, cs, cg = Counter(base_r), Counter(small), Counter(big)
    return all(cg[l] - cb[l] <= cs[l] - cb[l] for l in cb if cs[l] < cb[l])


def _clusters(base, per_mod, fn_of=None):
    """Every mod's changes, grouped where they meet, and what each group is:
      clean     one text — a single mod, identical edits, or one mod's edit contains the others'
      soft      they only meet at an edge, or add at the very same spot: both fit, in load order
      conflict  two mods change the same line differently
    Inside a function (fn_of(start, end) names it), one mod's changed lines meet another's
    right below them too: nothing untouched between, so neither mod wrote that stretch as it
    comes out. Unless the mod below made the change above as well — then it's its own."""
    tagged = sorted(((s, e, i, new) for i, hs in enumerate(per_mod) for s, e, new in hs),
                    key=lambda h: (h[0], h[1], h[2]))
    makers = {}
    for s, e, i, new in tagged:
        makers.setdefault((s, e, tuple(_norm(new))), set()).add(i)

    def touching(a, b):
        (s1, e1, i1, n1), (s2, e2, i2, n2) = a, b
        if fn_of is None or i1 == i2 or not (s1 < e1 == s2 < e2):
            return False
        if i1 in makers[(s2, e2, tuple(_norm(n2)))] or i2 in makers[(s1, e1, tuple(_norm(n1)))]:
            return False
        f = fn_of(s1, e2)
        return f is not None and f == fn_of(s1, e1) == fn_of(s2, e2)

    clusters = []
    for h in tagged:
        s, e, i, new = h
        # every group this change meets — not just the last one, or the result would depend on
        # which mod is listed first — becomes one group with it
        first, k = None, len(clusters)
        while k > 0 and clusters[k - 1]["end"] >= s:
            k -= 1
            if any(_collide((s, e), (o[0], o[1])) or touching(o, h) for o in clusters[k]["hunks"]):
                first = k
        if first is None:
            clusters.append({"start": s, "end": e, "mods": {i}, "hunks": [h]})
            continue
        c = clusters[first]
        for other in clusters[first + 1:]:
            c["end"] = max(c["end"], other["end"])
            c["mods"] |= other["mods"]
            c["hunks"] += other["hunks"]
        del clusters[first + 1:]
        c["end"] = max(c["end"], e)
        c["mods"].add(i)
        c["hunks"].append(h)
    for c in clusters:
        lo, hi = c["start"], c["end"]
        region = lambda i: apply_hunks(base, per_mod[i], lo, hi)
        texts = {}
        for i in sorted(c["mods"]):
            texts.setdefault(tuple(_norm(region(i))), i)
        c["pure"] = all(h[0] == h[1] for h in c["hunks"])
        if len(texts) == 1:
            c["kind"], c["text"] = "clean", region(min(c["mods"]))
            continue
        base_r = _norm(base[lo:hi])
        top = next((i for t, i in texts.items()
                    if all(_contains(base_r, list(o), list(t)) for o in texts)), None)
        if top is not None:
            c["kind"], c["text"], c["joined"] = "clean", region(top), True
            continue
        hard = False
        hs = c["hunks"]
        for x in range(len(hs)):
            for y in range(x + 1, len(hs)):
                (s1, e1, i1, n1), (s2, e2, i2, n2) = hs[x], hs[y]
                if i1 == i2 or (s1, e1, _norm(n1)) == (s2, e2, _norm(n2)):
                    continue
                if (s1 < e1 and s2 < e2 and s1 < e2 and s2 < e1) \
                        or (s1 == e1 and s2 < s1 < e2) or (s2 == e2 and s1 < s2 < e1):
                    hard = True
        if hard:
            c["kind"] = "conflict"
            continue
        seen, pieces = set(), []
        for i in sorted(c["mods"]):                          # same spot: the top mod's lines first
            for s, e, j, n in sorted((h for h in hs if h[2] == i), key=lambda h: (h[0], h[1])):
                sig = (s, e, tuple(_norm(n)))
                if sig not in seen:
                    seen.add(sig)
                    pieces.append((s, e, n))
        c["kind"], c["text"] = "soft", apply_hunks(base, pieces, lo, hi)
        # each mod's own lines still all there, in order? Not when one mod replaced a line the
        # other's addition was built around — e.g. a blank line the diff borrowed from vanilla
        # for the middle of a new function
        combined = _norm(c["text"])
        c["intact"] = all(not any(op in ("replace", "delete") for op, *_r in
                                  difflib.SequenceMatcher(None, list(t), combined, autojunk=False).get_opcodes())
                          for t in texts)
    return clusters


def _net(lines):
    """How many (, [ and { a stretch of lines leaves open (negative: closes more than it opens)."""
    text = _strip_code("\n".join(lines))
    return tuple(text.count(o) - text.count(c) for o, c in ("{}", "()", "[]"))


_PLAIN_VAR_RE = re.compile(r"^var\s+[A-Za-z_]\w*(\s*,\s*[A-Za-z_]\w*)*\s*:[^=;]+;$")


def _hoist_vars(fn_lines):
    """A function whose `var` lines don't all come first (two mods' additions put together can do
    that), with them moved up to just before its first statement — where the game requires them.
    Declarations don't depend on order, so nothing else changes. None when a misplaced `var`
    can't be moved on its own (it shares a line with other code, or sets a value)."""
    code = [_strip_code(l).strip() for l in fn_lines]
    ob = next((k for k, c in enumerate(code) if "{" in c), None)
    if ob is None:
        return None
    k = ob + 1
    while k < len(code) and (not code[k] or code[k].startswith("var ")):
        k += 1
    moved = [j for j in range(k, len(code)) if re.match(r"var\b", code[j])]
    if not moved:
        return list(fn_lines)
    if any(not _PLAIN_VAR_RE.match(code[j]) for j in moved):
        return None
    gone = set(moved)
    rest = [l for j, l in enumerate(fn_lines) if j not in gone]
    return rest[:k] + [fn_lines[j] for j in moved] + rest[k:]


def _faults(fn_lines):
    return {w for _l, w in _structure_faults(fn_lines, 0, len(fn_lines) - 1)} if fn_lines else set()


def _sound(base, fn, candidate, lo, hi, inputs):
    """A combination for base[lo:hi], checked the way the game's compiler would see it:
    (lo, hi, lines) — widened to the whole function if its `var` lines had to be moved up —
    or None when it can't work (brackets that don't pair up, an else after an else…).
    inputs: each version's own whole function, which is known to compile."""
    if _net(candidate) != _net(base[lo:hi]):
        return None
    if not fn:
        return lo, hi, candidate
    f0, f1 = fn[0], fn[1] + 1
    whole = base[f0:lo] + candidate + base[hi:f1]
    # locals: nothing used whose `var` line is gone, nothing declared twice
    if local_problems(_norm(inputs[0]), [("", _norm(x)) for x in inputs[1:]], _norm(whole)):
        return None
    known = set().union(*(_faults(x) for x in inputs))
    new = _faults(whole) - known
    if not new:
        return lo, hi, candidate
    if all("var line" in w for w in new):
        moved = _hoist_vars(whole)
        if moved is not None and not (_faults(moved) - known):
            return f0, f1, moved
    return None


_ID_RE = re.compile(r"[A-Za-z_]\w*")


def _dependencies(base, group, per_mod, chosen, versions):
    """Names a mod's kept changes still use that it only set up in lines being dropped:
    [(mod label, name)]. chosen: {cluster id: text going in} for the clashing clusters."""
    vanilla = set(_ID_RE.findall(_strip_code("\n".join(base))))
    out = []
    for i in sorted(set().union(*(c["mods"] for c in group))):
        dropped, kept = [], []
        for c in group:
            mine = [n for s, e, j, n in c["hunks"] if j == i]
            if not mine:
                continue
            if c["kind"] == "conflict":
                text = apply_hunks(base, per_mod[i], c["start"], c["end"])
                if _norm(text) != _norm(chosen.get(id(c), [])):
                    dropped += [l for n in mine for l in n]
            else:
                kept += [l for n in mine for l in n]
        ids = lambda ls: set(_ID_RE.findall(_strip_code("\n".join(ls))))
        for name in sorted((ids(dropped) & ids(kept)) - vanilla):
            out.append((versions[i][0], name))
    return out


_TRIVIAL_RE = re.compile(r"^(|[{}();]*|//.*|/\*.*|\*.*|else|break;|continue;|return;|return (true|false|0|NULL);)$")


def _repeated_additions(base, per_mod, group):
    """A line two mods each add, in different places of one function: combined it would run
    twice. The line, or None."""
    base_lines = set(_norm(base))
    seen = {}
    for c in group:
        for s, e, i, new in c["hunks"]:
            for line in _norm(new):
                if line in base_lines or _TRIVIAL_RE.match(line.strip()):
                    continue
                seen.setdefault(line.strip(), set()).add((i, s, e))
    for line, where in seen.items():
        mods = {i for i, _s, _e in where}
        spots = {(s, e) for _i, s, e in where}
        if len(mods) > 1 and len(spots) > 1:
            return line
    return None


def _twin_functions(merged, base_fns):
    """Two mods adding the very same new function (a shared helper) gives two copies; the game
    won't compile that, and one copy does the job. Later identical copies are taken out."""
    fns = [f for f in scan_script(merged)[0] if f[2] and not f[4]]
    known = {(o.lower(), n.lower()) for _f, _l, n, o, _a in base_fns if n}
    groups = {}
    for first, last, name, owner, _a in fns:
        groups.setdefault((owner.lower(), name.lower()), []).append((first, last))
    cut = []
    for key, spans in groups.items():
        if len(spans) < 2 or key in known:
            continue
        bodies = {tuple(_norm(merged[f:l + 1])) for f, l in spans}
        if len(bodies) == 1:
            cut += spans[1:]
    if not cut:
        return merged
    out = list(merged)
    for first, last in sorted(cut, reverse=True):
        if first > 0 and not out[first - 1].strip() and (last + 1 >= len(out) or not out[last + 1].strip()):
            first -= 1                                   # and the blank line that came with it
        del out[first:last + 1]
    return out


def merge_script(base, versions, resolutions, scope="", assemble_only=False):
    """versions: [(label, lines)] in priority order, top first. scope names the script, so a
    decision made for one spot is never applied to a lookalike spot or another file.

    Returns a dict:
      status   'merged' | 'pending' | 'same' | 'superset' | 'failed'
      lines    merged lines (only when status is 'merged')
      items    everything that needs or needed a decision, resolved or not
      auto     how many clean changes were combined without asking
      reason   why it failed, for 'failed'
    """
    # 1. each mod's changes against vanilla — and proof they rebuild that mod exactly
    per_mod = []
    for label, lines in versions:
        hunks = line_hunks(base, lines)
        if _norm(apply_hunks(base, hunks)) != _norm(lines):
            return {"status": "failed", "items": [], "auto": 0,
                    "reason": f"couldn't reproduce {label}'s version from its changes"}
        per_mod.append(hunks)

    distinct = {tuple(_norm(v)) for _l, v in versions}
    if len(distinct) == 1:
        return {"status": "same", "items": [], "auto": 0}

    # 2. group changes where they meet, and sort out what each group is (see _clusters)
    functions, base_problems = scan_script(base)
    clusters = _clusters(base, per_mod, fn_of=lambda s, e: function_at(functions, s, e))

    def region(i, lo, hi):
        return apply_hunks(base, per_mod[i], lo, hi)

    # 3. items: clashes, and combinations worth a look — a function at a time
    groups, order = {}, []
    for c in clusters:
        fn = function_at(functions, c["start"], c["end"])
        c["fn"] = fn
        key = fn[:2] if fn else ("top", c["start"])
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(c)

    items, covered, shared_names, group_pieces = [], set(), set(), []
    for key in order:
        group = groups[key]
        lo, hi = group[0]["start"], group[-1]["end"]
        fn = group[0]["fn"]
        mods = sorted(set().union(*(c["mods"] for c in group)))
        conflict = any(c["kind"] == "conflict" for c in group)
        f0, f1 = (fn[0], fn[1] + 1) if fn else (lo, hi)
        inputs = [base[f0:f1]] + [region(i, f0, f1) for i in mods] if fn else []

        def build(choose, lo_, hi_):
            pieces = []
            for c in group:
                t = choose(c)
                if t is None:
                    return None
                pieces.append((c["start"], c["end"], t))
            return apply_hunks(base, pieces, lo_, hi_)

        def settle(choose):
            """The combination `choose` makes, made sound — or None."""
            text = build(choose, lo, hi)
            return None if text is None else _sound(base, fn, text, lo, hi, inputs)

        why, proposed, repeated = None, None, None
        together = None if conflict else settle(lambda c: c["text"])
        if not conflict:
            soft = [c for c in group if c["kind"] == "soft"]
            repeated = _repeated_additions(base, per_mod, group) if fn and len(mods) > 1 else None
            if together is None or (not fn and any(not c.get("intact", True) for c in soft)):
                why = "structure"                      # put together, one mod's lines would break the other's
            elif fn and soft:
                why = "same_spot" if all(c["pure"] for c in soft) else "edge"
            elif repeated:
                why = "repeated"
            if why is None:
                # combined without asking: different lines, identical changes, one mod's change
                # already containing another's, or declarations added side by side
                if fn and len(mods) > 1:
                    shared_names.add(fn[2])
                group_pieces.append(together)
                covered.update(id(c) for c in group)
                continue
        # every answer offered is made sound; a `var` moved up widens the spot to the function
        clash = conflict or why == "structure"
        per_variant = {}
        if clash and why != "structure":
            for i in mods:
                per_variant[i] = settle(lambda c, i=i: c["text"] if c["kind"] != "conflict"
                                        else (apply_hunks(base, per_mod[i], c["start"], c["end"])
                                              if i in c["mods"] else None))
        base_pick = settle(lambda c: c["text"] if c["kind"] != "conflict" else base[c["start"]:c["end"]]) \
            if clash and why != "structure" else None
        wide = any(r and (r[0], r[1]) != (lo, hi) for r in [together, base_pick] + list(per_variant.values()))
        if wide:
            lo, hi = f0, f1
            def fit(r):
                if r is None or (r[0], r[1]) == (lo, hi):
                    return None if r is None else r[2]
                again = _sound(base, fn, apply_hunks(base, [(r[0], r[1], r[2])], lo, hi), lo, hi, inputs)
                return again[2] if again else None
        else:
            fit = lambda r: None if r is None else r[2]
        variants = {}                                    # normalised text -> (lines, [mods])
        for i in mods:
            real = region(i, lo, hi)
            variants.setdefault(tuple(_norm(real)), (real, []))[1].append(i)
        base_region = base[lo:hi]
        variants.pop(tuple(_norm(base_region)), None)
        ordered = sorted(variants.values(), key=lambda v: min(v[1]))
        options, depends = {}, {}
        if clash:
            for n, (real, idx) in enumerate(ordered):
                got = fit(per_variant.get(min(idx)))
                if got is not None and _norm(got) != _norm(real):
                    options[f"v{n}"] = got
                    chosen = {id(c): apply_hunks(base, per_mod[min(idx)], c["start"], c["end"])
                              for c in group if c["kind"] == "conflict"}
                    depends[f"v{n}"] = _dependencies(base, group, per_mod, chosen, versions)
            got = fit(base_pick)
            if got is not None:
                options["base"] = got
                chosen = {id(c): base[c["start"]:c["end"]] for c in group if c["kind"] == "conflict"}
                depends["base"] = _dependencies(base, group, per_mod, chosen, versions)
        else:
            proposed = fit(together)
        ident = _sha(json.dumps([scope.lower(), lo, hi, base_region, sorted(list(v[0]) for v in ordered)]))
        items.append({
            "key": ident, "kind": "conflict" if clash else "review", "why": why,
            "repeated": repeated if why == "repeated" else None,
            "start": lo, "end": hi,
            "function": {"name": fn[2], "owner": fn[3], "first": fn[0], "last": fn[1]} if fn else None,
            "base": base_region,
            "variants": [{"mods": [versions[i][0] for i in idx], "lines": list(real)} for real, idx in ordered],
            "options": options, "depends": {k: v for k, v in depends.items() if v},
            "proposed": proposed,
            "resolution": resolutions.get(ident),
        })
        covered.update(id(c) for c in group)

    # 4. assemble
    auto = sum(1 for c in clusters if id(c) not in covered)
    if any(it["resolution"] is None for it in items):
        return {"status": "pending", "items": items, "auto": auto}
    pieces = list(group_pieces)
    pieces += [(it["start"], it["end"], it["resolution"]) for it in items]
    merged = apply_hunks(base, pieces)
    merged = _twin_functions(merged, functions)
    if assemble_only:
        return {"status": "assembled", "lines": merged, "items": items, "auto": auto}

    # 5. the merged script must be at least as sound as what went in
    out_fns, out_problems = scan_script(merged)
    worst_in = max([len(base_problems)] + [len(scan_script(v)[1]) for _l, v in versions])
    if len(out_problems) > worst_in:
        line, what = out_problems[0]
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"merged script doesn't balance (line {line + 1}: {what})"}
    known = {(o.lower(), n.lower()) for o, n in set().union(
        duplicate_functions(functions), *(duplicate_functions(scan_script(v)[0]) for _l, v in versions))}
    new_dups = {d for d in duplicate_functions(out_fns) if (d[0].lower(), d[1].lower()) not in known}
    if new_dups:
        owner, name = sorted(new_dups)[0]
        where = f"{owner}.{name}" if owner else name
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"merging would define {where} twice"}
    # fields, types, states and @addMethod/@addField can't be declared twice either
    known = set().union(duplicate_decls(scan_decls(base)), *(duplicate_decls(scan_decls(v)) for _l, v in versions))
    new_dups = duplicate_decls(scan_decls(merged)) - known
    if new_dups:
        kind, owner, name = sorted(new_dups)[0]
        what = {"var": "the variable", "type": "the type", "state": "the state"}.get(kind, kind)
        where = f"{owner}.{name}" if owner else name
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"merging would declare {what} {where} twice"}
    nbase, nversions, nmerged = _norm(base), [(l, _norm(v)) for l, v in versions], _norm(merged)
    bad = local_problems(nbase, nversions, nmerged)
    if bad:
        owner, name, line, what = bad[0]
        where = f"{owner}.{name}" if owner else name
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"{where} {what} (line {line + 1}) wouldn't compile"}
    bad = structure_problems(nbase, nversions, nmerged)
    if bad:
        owner, name, line, what = bad[0]
        where = f"{owner}.{name}" if owner else name
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"{where} {what} (line {line + 1}) wouldn't compile"}
    gone = removed_but_used(nbase, nversions, nmerged)
    if gone:
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"{gone[1]} removes {gone[0]}, but another mod's change still uses it"}
    # every function must match whichever single mod changed it, or vanilla if none did
    wrong = function_check(base, versions, merged, pieces,
                           [(it["start"], it["end"], it["resolution"]) for it in items],
                           [v["lines"] for it in items for v in it["variants"]])
    if wrong:
        return {"status": "failed", "items": items, "auto": auto,
                "reason": f"{wrong}. Left unmerged to be safe"}

    shared_names = sorted(shared_names, key=str.lower)
    for idx, (label, lines) in enumerate(versions):
        if nmerged == _norm(lines):
            # one mod already contains everything — only worth a merged file if it isn't the top one
            return {"status": "superset", "lines": list(lines), "items": items, "auto": auto,
                    "winner": label, "winner_index": idx, "shared": shared_names}
    return {"status": "merged", "lines": merged, "items": items, "auto": auto, "shared": shared_names}


# --- XML merging -----------------------------------------------------------------
# Game data in XML (menus, keybinds, and later the item/ability/loot definitions inside
# bundles) is merged by its structure, three ways against the game's own copy:
#   - an element with an id / name / varId is the same element wherever it sits, so two mods
#     changing different attributes of it both count, and each change lands exactly once
#   - a container without one (VisibleVars, base_abilities…) is matched by its place
#   - everything else (a list of <a> lines, the attribute lines of an ability) is an ordered
#     list, merged with the same grouping as scripts: separate edits combine, additions at the
#     same spot go in top mod first, two mods changing the same entry differently is a clash
# Formatting is kept: an element no mod touched is written exactly as it was, a changed one as
# its mod wrote it, and only an element two mods changed is put together anew. A mod removing an
# element the game has is asked about, not done quietly: mods made for an older game version
# lack newer entries, and dropping those silently is how keybinds and items go missing.
XML_ENGINE = 2
XML_KEY = "xml:"                      # merge records for XML files are kept under "xml:<path>"
INI_KEY = "ini:"                      # and for .ini files in bin/ under "ini:<path>"
INI_ENGINE = 1                        # bumped when the .ini merge changes how it decides
INI_KEYLINE = re.compile(r"^(\s*)([^=;#\[\s][^=]*?)\s*=\s*(.*?)\s*$")


def _ini_entries(lines):
    """An .ini file read line by line: [(line index, section (lower), id, value or None)]. A key's
    id is (section, key, which one of that name in the section), all lower case; a line that
    isn't a key (a bare value in a list) is ('#', its text). Comments and blank lines: None."""
    out, section, seen = [], "", {}
    for i, line in enumerate(lines):
        st = line.strip()
        head = INI_SECTION.match(line)
        if head:
            section = head.group(1).strip().lower()
            out.append((i, section, None, None))
            continue
        if not st or st.startswith((";", "#", "//")):
            continue
        m = INI_KEYLINE.match(line)
        if m:
            k = (section, m.group(2).strip().lower())
            n = seen.get(k, 0)
            seen[k] = n + 1
            out.append((i, section, (section, k[1], n), m.group(3)))
        else:
            out.append((i, section, (section, "#", st.lower()), st))
    return out


def ini_merge(base_lines, versions, yours=None):
    """Merge .ini files key by key. base_lines: the game's own file (with what you changed in it),
    or None when the game has none. versions: [(label, lines)], top priority first. yours:
    {id: line}, keys you edited after it was merged, which win. A mod brings only what it changes:
    a key whose value differs from the game's, and keys and sections the game's file doesn't have.
    A key it leaves out stays as it is. Two mods setting one key differently: the higher one's
    value is used. The game's own lines keep their place, comments and spacing.
    Returns (lines, {label: [ids whose value it gave]}, [(id, label used, [other labels], the key
    as written, "[Section] Key")], [indices of versions that change nothing])."""
    base = list(base_lines or [])
    entries = _ini_entries(base)
    base_val = {e[2]: e[3] for e in entries if e[2] is not None}
    base_at = {e[2]: e[0] for e in entries if e[2] is not None}
    last_in_sec = {}                                      # section -> its last line with content
    for i, sec, _eid, _v in entries:
        last_in_sec[sec] = i
    setters, heads = {}, {}
    for label, lines in versions:                         # top priority first
        for i, sec, eid, value in _ini_entries(lines):
            if eid is None:
                heads.setdefault(sec, lines[i].strip())
                continue
            if eid in base_val and (eid[1] == "#" or value == base_val[eid]):
                continue                                  # the game's own value: nothing of this mod's
            setters.setdefault(eid, []).append((label, value, lines[i].strip()))
    yours = yours or {}
    final = {eid: lst[0][2] for eid, lst in setters.items()}
    for eid, line in yours.items():
        final[eid] = line.strip()
    out = list(base)
    adds = {}
    for eid, line in final.items():
        if eid in base_at:
            m = INI_KEYLINE.match(out[base_at[eid]])
            out[base_at[eid]] = (m.group(1) if m else "") + line      # changed in place
        else:
            adds.setdefault(eid[0], []).append(line)
    for at, sec in sorted(((last_in_sec[s2], s2) for s2 in adds if s2 in last_in_sec), reverse=True):
        out[at + 1:at + 1] = adds[sec]                    # at the end of its section, bottom up
    if "" in adds and "" not in last_in_sec:
        out[0:0] = adds[""]                               # keys before any section
    for sec, lines in adds.items():
        if sec in last_in_sec or sec == "":
            continue
        if out and out[-1].strip():
            out.append("")
        out += [heads.get(sec) or f"[{sec}]"] + lines     # a section the game's file doesn't have
    used, conflicts = {}, []
    for eid, lst in setters.items():
        winner = "you" if eid in yours else lst[0][0]
        if winner != "you":
            used.setdefault(winner, []).append(eid)
        if len({v for _l, v, _r in lst}) > 1 or (winner == "you" and lst):
            others = [l for l, _v, _r in lst if l != winner]
            if others:
                m = INI_KEYLINE.match(lst[0][2])
                head = INI_SECTION.match(heads.get(eid[0], "") or "")
                sec = next((INI_SECTION.match(base[i]).group(1).strip() for i, s2, e2, _v in entries
                            if e2 is None and s2 == eid[0]), head.group(1).strip() if head else eid[0])
                key = m.group(2).strip() if m else eid[1]
                conflicts.append((eid, winner, others, f"[{sec}] {key}" if sec else key))
    changed = {l for lst in setters.values() for l, _v, _r in lst}
    unchanged = [k for k, (label, _l) in enumerate(versions) if label not in changed]
    return out, used, conflicts, unchanged
XML_KEYS = ("id", "name", "varId")
_XML_TOKEN = re.compile(r"""
    (?P<comment><!--.*?-->)
  | (?P<pi><\?.*?\?>)
  | (?P<cdata><!\[CDATA\[.*?\]\]>)
  | (?P<decl><![^>]*>)
  | (?P<end></\s*(?P<etag>[^\s>]+)\s*>)
  | (?P<start><(?P<stag>[^\s/>!?]+)(?P<sattrs>(?:\s+[^\s=/>]+\s*=\s*(?:"[^"]*"|'[^']*'))*)\s*(?P<sclose>/?)>)
  | (?P<text>[^<]+)
  | (?P<bad><)
""", re.S | re.X)
_XML_ATTR = re.compile(r"""([^\s=/>]+)\s*=\s*(?:"([^"]*)"|'([^']*)')""")
_XML_START = re.compile(r"""<([A-Za-z_][\w:.-]*)((?:\s+[^\s=/>]+\s*=\s*(?:"[^"]*"|'[^']*'))*)\s*/?>""")


class XmlError(ValueError):
    pass


class XNode:
    """One element, with where it sits in its file so it can be written back unchanged."""
    __slots__ = ("tag", "attrs", "src", "start", "open_end", "close_start", "end",
                 "children", "pres", "tail", "texts", "_canon", "_flat")

    def __init__(self, tag, attrs, src, start, open_end):
        self.tag, self.attrs, self.src, self.start, self.open_end = tag, attrs, src, start, open_end
        self.close_start = self.end = open_end
        self.children, self.pres, self.tail, self.texts, self._canon = [], [], "", [], None
        self._flat = None

    def raw(self):
        return self.src[self.start:self.end]

    def self_closing(self):
        return self.close_start == self.open_end == self.end


def parse_xml(text):
    """(prolog, root, epilog). Raises XmlError for anything that isn't well-formed."""
    root, stack = None, []
    last = 0                                       # end of the previous sibling in the open element
    for m in _XML_TOKEN.finditer(text):
        kind = m.lastgroup
        if kind == "bad":
            raise XmlError(f"stray “<” at character {m.start()}")
        if kind in ("start", "end", "text", "cdata", "comment") and not stack and kind != "start":
            if kind == "text" and m.group().strip():
                raise XmlError("text outside the root element")
            if kind == "end":
                raise XmlError(f"“</{m.group('etag')}>” with nothing to close")
            continue
        if kind in ("pi", "decl"):
            if stack:
                raise XmlError("declaration inside an element")
            continue
        if kind == "start":
            attrs = [(a, v if v is not None else w) for a, v, w in _XML_ATTR.findall(m.group("sattrs"))]
            node = XNode(m.group("stag"), attrs, text, m.start(), m.end())
            if stack:
                parent = stack[-1]
                parent.pres.append(text[last:m.start()])
                parent.children.append(node)
            elif root is not None:
                raise XmlError("more than one root element")
            else:
                root = node
            if m.group("sclose"):
                node.close_start = node.end = m.end()
                last = m.end()
            else:
                stack.append(node)
                last = m.end()
            continue
        if kind == "end":
            node = stack.pop()
            if m.group("etag") != node.tag:
                raise XmlError(f"“<{node.tag}>” closed by “</{m.group('etag')}>”")
            node.tail = text[last:m.start()]
            node.close_start, node.end = m.start(), m.end()
            last = m.end()
            continue
        # text, cdata or comment inside an element
        if kind == "text":
            stack[-1].texts.append(m.group())
        elif kind == "cdata":
            stack[-1].texts.append(m.group()[9:-3])
    if stack:
        raise XmlError(f"“<{stack[-1].tag}>” is never closed")
    if root is None:
        raise XmlError("no root element")
    return text[:root.start], root, text[root.end:]


_PARSED = {}                         # text -> parse_xml(text), most recent last
_PARSED_MAX = 200_000_000            # characters of text kept
_parsed_chars = 0


def parse_xml_cached(text):
    """parse_xml, remembered: the game's copy and each mod's copy of a file are read many
    times (every merge, the safety check, the decisions window) and never change in between.
    Trees are only ever read after parsing, so sharing one is safe."""
    global _parsed_chars
    hit = _PARSED.pop(text, None)
    if hit is None:
        hit = parse_xml(text)
        _parsed_chars += len(text)
        while _parsed_chars > _PARSED_MAX and _PARSED:
            old = next(iter(_PARSED))
            _parsed_chars -= len(old)
            del _PARSED[old]
    _PARSED[text] = hit
    return hit


def _xcanon(n):
    """What an element means, ignoring comments and whitespace."""
    if n._canon is None:
        n._canon = (n.tag, tuple(sorted(n.attrs)), " ".join("".join(n.texts).split()),
                    tuple(_xcanon(c) for c in n.children))
    return n._canon


def _xidents(children, containers):
    """Who each child is: its tag and key attribute; a container by its place; anything else by
    what it says. Repeats are numbered, so every identity is unique among its siblings."""
    out, seen = [], Counter()
    for c in children:
        d = dict(c.attrs)
        key = next((k for k in XML_KEYS if k in d), None)
        if key:
            base = ("k", c.tag, key, d[key])
        elif c.tag in containers:
            base = ("p", c.tag)
        else:
            base = ("u", _xcanon(c))
        out.append(base + (seen[base],))
        seen[base] += 1
    return out


def _xdrops(b, n):
    """Attributes where n only takes something away from vanilla's b: the attribute is gone, or
    it's a list (a;b;c) and n keeps just some of it. That's what a mod made for an older game
    version looks like, so it's asked about rather than done."""
    out = []
    nd = dict(n.attrs)
    for name, bv in b.attrs:
        nv = nd.get(name)
        if nv is None:
            out.append(name)
        elif nv != bv:
            bi = {x.strip() for x in re.split(r"[;,]", bv) if x.strip()}
            ni = {x.strip() for x in re.split(r"[;,]", nv) if x.strip()}
            if len(bi) > 1 and ni < bi:
                out.append(name)
    return out


def _xloses(b, n):
    """Does n leave out anything of vanilla's b that's asked about — an attribute (see _xdrops),
    or an element with a key or a container — anywhere inside it?"""
    if _xcanon(b) == _xcanon(n):
        return False
    if _xdrops(b, n):
        return True
    containers = {c.tag for c in b.children + n.children if c.children}
    theirs = dict(zip(_xidents(n.children, containers), n.children))
    for ident, c in zip(_xidents(b.children, containers), b.children):
        if ident[0] == "u":
            continue
        if ident not in theirs or _xloses(c, theirs[ident]):
            return True
    return False


def _xtok(ident):
    return hashlib.sha1(repr(ident).encode("utf-8")).hexdigest()[:20]


def _xlabel(ident):
    if ident[0] == "k":
        return f"{ident[1]} “{ident[3]}”"
    return ident[1] if ident[0] == "p" else "…"


def _lead(node):
    """The indentation before an element on its line (nothing if other text shares the line)."""
    line_start = node.src.rfind("\n", 0, node.start) + 1
    lead = node.src[line_start:node.start]
    return lead if not lead.strip() else ""


def _open_tag(node, attrs):
    """node's start tag with these attributes, keeping its own spacing and quoting."""
    raw = node.src[node.start:node.open_end]
    if list(node.attrs) == list(attrs):
        return raw
    new = dict(attrs)
    head = len(node.tag) + 1
    out, pos = [raw[:head]], head
    for m in _XML_ATTR.finditer(raw, head):
        name = m.group(1)
        lead = raw[pos:m.start()]
        if name in new:
            val = new[name]
            q = '"' if '"' not in val else "'"
            out.append(lead + f"{name}={q}{val}{q}")
        pos = m.end()
    rest = raw[pos:]
    have = {m.group(1) for m in _XML_ATTR.finditer(raw, head)}
    extra = "".join(f' {n}="{v}"' for n, v in attrs if n not in have)
    close = "/>" if rest.rstrip().endswith("/>") else ">"
    body = rest.rstrip()[:-len(close)]
    out.append(extra + body + close)
    return "".join(out)


def _xrender(res):
    kind, node = res[0], res[1]
    if kind == "src":
        return node.raw()
    m = res[1]
    src = m["open_src"]
    body = "".join(pre + _xrender(k) for pre, k in m["kids"]) + m["tail"]
    opening = _open_tag(src, m["attrs"])
    if src.self_closing():
        if not m["kids"] and not m["tail"]:
            return opening
        opening = opening[:-2].rstrip() + ">"
        return opening + body + f"</{src.tag}>"
    return opening + body + src.src[src.close_start:src.end]


def _xflatten(root):
    """{path: {field: value}} — every attribute, the text and the order of the plain entries of
    every element reached through keyed or container children. Plus sibling-key counts.
    Worked out once per tree (trees aren't changed after parsing)."""
    if root._flat is None:
        root._flat = _xflatten_now(root)
    return root._flat


def _xflatten_now(root):
    out, dups = {}, {}

    def walk(node, path):
        fields = {"@" + a: v for a, v in node.attrs}
        fields["#text"] = " ".join("".join(node.texts).split())
        containers = {c.tag for c in node.children if c.children}
        ids = _xidents(node.children, containers)
        fields["#seq"] = tuple(i for i in ids if i[0] == "u")
        out[path] = fields
        keys = Counter(i[:4] for i in ids if i[0] == "k")
        dups[path] = {k for k, n in keys.items() if n > 1}
        for ident, c in zip(ids, node.children):
            if ident[0] != "u":
                walk(c, path + (ident,))
    walk(root, ((("root", root.tag)),))
    return out, dups


_GONE = ("<not there>",)


class _XmlMerge:
    def __init__(self, base, docs, labels, resolutions, scope, elsewhere=None):
        self.base, self.docs, self.labels = base, docs, labels
        self.res, self.scope = resolutions, scope
        self.elsewhere = elsewhere                     # label -> keyed elements in its other files
        self.moved = 0                                 # game entries a mod moved to its own file
        self.items, self.auto = [], 0
        self.skip_trees, self.skip_fields = set(), set()
        self._resolved = {}                            # your answers' elements, by stand-in token
        text = base[1].src if base else ""
        self.line_starts = [0] + [i + 1 for i, ch in enumerate(text) if ch == "\n"]

    # --- places in vanilla, as line numbers the decisions window can show
    def line_of(self, offset):
        return bisect.bisect_right(self.line_starts, offset) - 1

    @staticmethod
    def node_lines(nodes):
        """Lines of these elements, one after the other, each at its own indentation."""
        out = []
        for n in nodes:
            line_start = n.src.rfind("\n", 0, n.start) + 1
            lead = n.src[line_start:n.start]
            out += ((lead if not lead.strip() else "") + n.raw()).split("\n")
        return out

    @staticmethod
    def fragment(kids, lo, hi):
        """Lines of kids[lo:hi] as their file has them, starting at the first one's indentation."""
        if lo >= hi:
            return []
        first, last = kids[lo], kids[hi - 1]
        src = first.src
        line_start = src.rfind("\n", 0, first.start) + 1
        lead = src[line_start:first.start]
        lead = lead if not lead.strip() else ""
        return (lead + src[first.start:last.end]).split("\n")

    def item(self, kind, why, path, base_lines, variants, options, proposed, start, end, where):
        ident = _sha(json.dumps([self.scope.lower(), repr(path), why or kind, base_lines,
                                 sorted(v["lines"] for v in variants)]))
        it = {"key": ident, "kind": kind, "why": why, "repeated": None, "start": start, "end": end,
              "function": None, "where": where, "base": base_lines, "variants": variants,
              "options": options, "depends": {}, "proposed": proposed,
              "resolution": self.res.get(ident)}
        self.items.append(it)
        return it

    def where(self, path):
        return " › ".join(_xlabel(p) for p in path[1:]) or path[0][1]

    # --- merging
    def merge_node(self, path, b, vs):
        """b: vanilla's element or None; vs: [(version index, element)] top first."""
        cb = _xcanon(b) if b is not None else None
        changed = [(i, n) for i, n in vs if _xcanon(n) != cb]
        if not changed:
            return ("src", b)
        drops = {} if b is None else {i: d for i, n in changed for d in [_xdrops(b, n)] if d}
        if len({_xcanon(n) for _i, n in changed}) == 1 and (b is None or not _xloses(b, changed[0][1])):
            return ("src", changed[0][1])
        # attributes, one by one
        bd = dict(b.attrs) if b is not None else {}
        vds = [(i, dict(n.attrs)) for i, n in vs]
        names = list(bd)
        for _i, n in vs:
            names += [a for a, _v in n.attrs if a not in names]
        final, clash = [], {}
        for name in names:
            bv = bd.get(name)
            vals = {i: d.get(name) for i, d in vds}
            ch = {v for v in vals.values() if v != bv}
            if len(ch) > 1:
                clash[name] = vals
                val = bv
            else:
                val = ch.pop() if ch else bv
            if val is not None:
                final.append((name, val))
        texts = {" ".join("".join(n.texts).split()) for _i, n in vs}
        btext = " ".join("".join(b.texts).split()) if b is not None else None
        if len(texts - {btext}) > 1:
            raise XmlError(f"{self.where(path)}: two mods change the text inside it differently")
        top = vs[0][1]
        if clash:
            final = self.tag_item(path, b, vs, final, clash, top)
        elif drops:
            final = self.drop_item(path, b, vs, final, drops)
        kids, tail = self.merge_children(path, b, vs)
        return ("m", {"attrs": final, "open_src": b if b is not None else top, "kids": kids, "tail": tail})

    def tag_item(self, path, b, vs, final, clash, top):
        src = b if b is not None else top

        def with_(pick):
            attrs = []
            for name, val in final:
                attrs.append((name, pick.get(name, val)) if name in clash else (name, val))
            for name in clash:
                if name not in dict(final) and pick.get(name) is not None:
                    attrs.append((name, pick[name]))
            return [(n, v) for n, v in attrs if v is not None]
        variants, options = [], {}
        groups = {}
        bsig = tuple(dict(b.attrs).get(name) for name in clash) if b is not None else None
        for i, n in vs:
            sig = tuple(clash[name][i] for name in clash)
            if sig != bsig:
                groups.setdefault(sig, []).append((i, n))
        order = sorted(groups.values(), key=lambda g: g[0][0])
        for k, grp in enumerate(order):
            i, n = grp[0]
            variants.append({"mods": [self.labels[j] for j, _n in grp],
                             "lines": (_lead(src) + n.src[n.start:n.open_end]).split("\n")})
            options[f"v{k}"] = (_lead(src) + _open_tag(src, with_({name: clash[name][i] for name in clash}))).split("\n")
        base_lines = (_lead(src) + src.src[src.start:src.open_end]).split("\n") if b is not None else []
        if b is not None:
            options["base"] = (_lead(src) + _open_tag(src, with_({name: dict(b.attrs).get(name) for name in clash}))).split("\n")
        start = self.line_of(b.start) if b is not None else 0
        end = self.line_of(b.open_end - 1) + 1 if b is not None else 0
        it = self.item("conflict", "attributes", path, base_lines, variants, options, None, start, end,
                       self.where(path))
        it["part"] = "tag"
        self.skip_fields.update((path, "@" + name) for name in clash)
        if it["resolution"] is None:
            return final
        m = _XML_TOKEN.match("\n".join(it["resolution"]).strip())
        if not m or m.lastgroup != "start" or m.group("stag") != src.tag:
            raise XmlError(f"{self.where(path)}: your version isn't a <{src.tag}> start tag")
        return [(a, v if v is not None else w) for a, v, w in _XML_ATTR.findall(m.group("sattrs"))]

    def drop_item(self, path, b, vs, final, drops):
        """A mod's version of this element leaves out some of the game's own attribute content."""
        names = sorted({d for ds in drops.values() for d in ds})
        restored = [(n, dict(b.attrs)[n] if n in names else v) for n, v in final]
        restored += [(n, v) for n, v in b.attrs if n in names and n not in dict(restored)]
        variants, options = [], {}
        by_tag = {}
        for i, n in vs:
            if i in drops:
                by_tag.setdefault(n.src[n.start:n.open_end], []).append(i)
        for k, (tag, who) in enumerate(sorted(by_tag.items(), key=lambda g: min(g[1]))):
            variants.append({"mods": [self.labels[i] for i in who], "lines": (_lead(b) + tag).split("\n")})
            options[f"v{k}"] = (_lead(b) + _open_tag(b, final)).split("\n")
        options["base"] = (_lead(b) + b.src[b.start:b.open_end]).split("\n")
        options["keep"] = (_lead(b) + _open_tag(b, restored)).split("\n")
        it = self.item("review", "removes", path, options["base"], variants, options, options["keep"],
                       self.line_of(b.start), self.line_of(b.open_end - 1) + 1, self.where(path))
        it["part"] = "tag"
        self.skip_fields.update((path, "@" + n) for n in names)
        if it["resolution"] is None:
            return final
        m = _XML_TOKEN.match("\n".join(it["resolution"]).strip())
        if not m or m.lastgroup != "start" or m.group("stag") != b.tag:
            raise XmlError(f"{self.where(path)}: your version isn't a <{b.tag}> start tag")
        return [(a, v if v is not None else w) for a, v, w in _XML_ATTR.findall(m.group("sattrs"))]

    def merge_children(self, path, b, vs):
        bkids = b.children if b is not None else []
        containers = {c.tag for n in ([b] if b is not None else []) + [n for _i, n in vs]
                      for c in n.children if c.children}
        bids = _xidents(bkids, containers)
        btok = [_xtok(x) for x in bids]
        ident_of = dict(zip(btok, bids))
        per, vinfo = [], []
        for i, n in vs:
            ids = _xidents(n.children, containers)
            vtok = [_xtok(x) for x in ids]
            ident_of.update(zip(vtok, ids))
            hunks = line_hunks(btok, vtok)
            if apply_hunks(btok, hunks) != vtok:
                raise XmlError(f"{self.where(path)}: couldn't line up {self.labels[i]}'s entries")
            per.append(hunks)
            vinfo.append((i, n, dict(zip(vtok, n.children)), dict(zip(vtok, n.pres))))
        bnode = dict(zip(btok, bkids))
        bpre = dict(zip(btok, b.pres)) if b is not None else {}
        self.node_of = {}
        for _i, _n, nodes, _p in reversed(vinfo):
            self.node_of.update(nodes)
        self.node_of.update(bnode)
        clusters = _clusters(btok, per)
        # what the file would say with every group combined (clashes left as vanilla for now)
        tentative = [(c["start"], c["end"], list(c["text"])) for c in clusters if c["kind"] != "conflict"]
        kept = set(apply_hunks(btok, tentative))
        # an element vanilla has (keyed or a container) that a mod drops is asked about; if another
        # mod kept it and changed it, that's a clash
        for c in clusters:
            if c["kind"] == "conflict":
                c["ask"] = "conflict"
                continue
            gone = [t for t in btok[c["start"]:c["end"]] if ident_of[t][0] != "u" and t not in kept]
            if gone:
                touched = any(t in nodes and _xcanon(nodes[t]) != _xcanon(bnode[t])
                              for t in gone for _i, _n, nodes, _pre in vinfo)
                c["ask"] = "conflict" if touched else "removes"
                if not touched and all(self.moved_by(t, c["start"], c["end"], btok, per, vs, ident_of)
                                       for t in gone):
                    c["ask"] = None                     # moved to the mod's own file: its change, done
                    self.moved += len(gone)
        pieces = []
        for c in clusters:
            lo, hi = c["start"], c["end"]
            if not c.get("ask"):
                pieces.append((lo, hi, list(c["text"])))
                self.auto += 1
                continue
            it = self.region_item(path, b, bkids, btok, per, vs, c, ident_of)
            if it["resolution"] is None:
                pieces.append((lo, hi, btok[lo:hi]))        # unanswered: nothing is written yet
                continue
            pieces.append((lo, hi, self.resolved(it, path, lo, bpre, btok)))
        merged = apply_hunks(btok, pieces)
        # each element once, merged over every version that has it
        kids, seen = [], set()
        for t in merged:
            if t in self._resolved:
                node, pre = self._resolved[t]
                kids.append((pre, ("src", node)))
                continue
            if t in seen:
                continue
            seen.add(t)
            ident = ident_of[t]
            holders = [(i, nodes[t]) for i, _n, nodes, _p in vinfo if t in nodes]
            if ident[0] == "u":
                res = ("src", bnode.get(t) or holders[0][1])
            else:
                res = self.merge_node(path + (ident,), bnode.get(t), holders)
            # the whitespace and comments before it: vanilla's, unless a mod changed them
            pres = [pre[t] for _i, _n, _nodes, pre in vinfo if t in pre]
            base_pre = bpre.get(t)
            changed = [p for p in pres if p != base_pre]
            if base_pre is None:
                pre = pres[0] if pres else "\n"
            else:
                pre = changed[0] if changed else base_pre
            kids.append((pre, res))
        tails = [n.tail for _i, n in vs]
        btail = b.tail if b is not None else None
        changed = [t for t in tails if t != btail]
        tail = changed[0] if changed else btail
        return kids, tail if tail is not None else ""

    def moved_by(self, t, lo, hi, btok, per, vs, ident_of):
        """The mods that leave the game's keyed entry t out of this stretch, if every one of them
        has it in a file of its own (moved, not removed). Otherwise []."""
        ident = ident_of[t]
        if ident[0] != "k" or not self.elsewhere:
            return []
        who = [self.labels[i] for j, (i, _n) in enumerate(vs) if t not in apply_hunks(btok, per[j], lo, hi)]
        return who if who and all(ident[1:4] in self.elsewhere(label) for label in who) else []

    def region_item(self, path, b, bkids, btok, per, vs, c, ident_of):
        lo, hi = c["start"], c["end"]
        variants, options, groups = [], {}, {}
        base_canon = [_xcanon(k) for k in bkids[lo:hi]]
        for j, (i, n) in enumerate(vs):
            # every version with its own take on this stretch: a different set of entries, or the
            # same ones changed (an edit to an entry another mod removes)
            region = apply_hunks(btok, per[j], lo, hi)
            vlo = _landing(per[j], lo)
            kids = n.children[vlo:vlo + len(region)]
            if [_xcanon(k) for k in kids] == base_canon:
                continue
            lines = self.fragment(n.children, vlo, vlo + len(region))
            groups.setdefault(tuple(_xcanon(k) for k in kids), (lines, []))[1].append(i)
        base_lines = self.fragment(bkids, lo, hi)
        for k, (lines, who) in enumerate(sorted(groups.values(), key=lambda g: min(g[1]))):
            variants.append({"mods": [self.labels[i] for i in who], "lines": lines})
            options[f"v{k}"] = lines
        options["base"] = base_lines
        if lo < hi:
            start, end = self.line_of(bkids[lo].start), self.line_of(bkids[hi - 1].end - 1) + 1
        else:
            at = bkids[lo - 1].end if lo else (b.open_end if b is not None else 0)
            start = end = self.line_of(at) + 1
        why = None if c["ask"] == "conflict" else "removes"
        proposed, moved = None, {}
        if why:
            # suggested: every mod's changes here combined, with the game's entries they leave out
            # put back where they were — unless the mods that leave one out have it in a file of
            # their own: then it was moved, and putting it back would define it twice
            text, follow = list(c["text"]), list(c["text"])
            for k, t in enumerate(btok[lo:hi]):
                if t in text or ident_of[t][0] == "u":
                    continue
                before = [x for x in btok[lo:lo + k] if x in text]
                text.insert(text.index(before[-1]) + 1 if before else 0, t)
                who = self.moved_by(t, lo, hi, btok, per, vs, ident_of)
                if who:
                    for label in who:
                        moved[label] = moved.get(label, 0) + 1
                else:
                    before = [x for x in btok[lo:lo + k] if x in follow]
                    follow.insert(follow.index(before[-1]) + 1 if before else 0, t)
            options["keep"] = self.node_lines([self.node_of[t] for t in text])
            proposed = options["keep"]
            if moved:
                proposed = options["follow"] = self.node_lines([self.node_of[t] for t in follow])
        it = self.item("conflict" if not why else "review", why, path, base_lines, variants, options,
                       proposed, start, end, self.where(path))
        it["part"] = "entries"
        if moved:
            it["moved"] = moved
        self.skip_fields.add((path, "#seq"))
        for j in range(len(vs)):                     # the elements in it are yours to decide
            for t in list(apply_hunks(btok, per[j], lo, hi)) + list(btok[lo:hi]):
                if ident_of[t][0] != "u":
                    self.skip_trees.add(path + (ident_of[t],))
        return it

    def resolved(self, it, path, lo, bpre, btok):
        """Your answer for a stretch of entries, as elements to put in its place."""
        text = "\n".join(it["resolution"])
        try:
            _p, wrap, _e = parse_xml("<__merge>" + text.lstrip() + "</__merge>")
        except XmlError as e:
            raise XmlError(f"your version at {it['where']} isn't valid XML: {e}") from None
        ref = bpre.get(btok[lo]) if lo < len(btok) else (bpre.get(btok[lo - 1]) if lo else "\n")
        toks = []
        for ident in _xidents(wrap.children, {c.tag for c in wrap.children if c.children}):
            if ident[0] != "u":
                self.skip_trees.add(path + (ident,))
        for k, node in enumerate(wrap.children):
            t = f"res:{it['key']}:{k}"
            self._resolved[t] = (node, (ref or "\n") if k == 0 else wrap.pres[k])
            toks.append(t)
        return toks


def xml_merge(base_text, versions, resolutions, scope="", elsewhere=None):
    """versions: [(label, text)] top priority first; base_text: the game's own copy, or None when
    the game has none. Returns like merge_script: status 'same' | 'merged' | 'superset' |
    'pending' | 'failed', 'text' for merged/superset, 'items', 'auto', 'reason'.
    elsewhere: label -> {(tag, key attribute, value)} in that mod's other files, which only
    changes what's suggested for an entry a mod leaves out (moved, rather than removed)."""
    fail = lambda why: {"status": "failed", "items": [], "auto": 0, "reason": why}
    try:
        base = parse_xml_cached(base_text) if base_text is not None else None
    except XmlError as e:
        return fail(f"the game's own copy isn't readable XML ({e})")
    docs = []
    for label, text in versions:
        try:
            docs.append(parse_xml_cached(text))
        except XmlError as e:
            return fail(f"{label}'s copy isn't valid XML ({e})")
    if len({_xcanon(d[1]) for d in docs}) == 1:
        return {"status": "same", "items": [], "auto": 0}
    tags = {d[1].tag for d in docs} | ({base[1].tag} if base else set())
    if len(tags) > 1:
        return fail("the copies don't share a root element")
    labels = [l for l, _t in versions]
    m = _XmlMerge(base, docs, labels, resolutions, scope, elsewhere)
    try:
        res = m.merge_node((("root", docs[0][1].tag),), base[1] if base else None,
                           [(i, d[1]) for i, d in enumerate(docs)])
    except XmlError as e:
        return fail(str(e))
    out = {"items": m.items, "auto": m.auto, "moved": m.moved}
    if any(it["resolution"] is None for it in m.items):
        return {**out, "status": "pending"}
    shell = base or docs[0]
    text = shell[0] + _xrender(res) + shell[2]
    # safety net: it must parse, and say exactly what the rules say it should
    problem, merged = _xml_check(base, docs, text, m, labels)
    if problem:
        return {**out, "status": "failed", "reason": problem + ". Left unmerged to be safe"}
    merged_canon = _xcanon(merged[1])
    for k, d in enumerate(docs):
        if _xcanon(d[1]) == merged_canon:
            return {**out, "status": "superset", "text": versions[k][1], "winner": labels[k], "winner_index": k}
    return {**out, "status": "merged", "text": text}


def _xml_check(base, docs, text, m, labels):
    """(problem or None, the merged file parsed)."""
    try:
        ET.fromstring(text)
        merged = parse_xml(text)
    except (ET.ParseError, XmlError, ValueError) as e:
        return f"the merged file isn't valid XML ({e})", None
    return _xml_check_fields(base, docs, merged, m), merged


def _xml_check_fields(base, docs, merged, m):
    B, bd = _xflatten(base[1]) if base else ({}, {})
    flats = [_xflatten(d[1]) for d in docs]
    M, md = _xflatten(merged[1])
    for path, keys in md.items():
        new = keys - bd.get(path, set()) - set().union(*(f[1].get(path, set()) for f in flats))
        if new:
            k = sorted(new)[0]
            return f"{m.where(path + (k,))} would be there twice"
    paths = set(B) | set(M) | set().union(*(set(f[0]) for f in flats))
    for path in sorted(paths, key=len):
        if any(path[:len(s)] == s for s in m.skip_trees):
            continue                                       # an element you decided on
        bf = B.get(path)
        vfs = [f[0].get(path) for f in flats]
        mf = M.get(path)
        fields = set().union(*(set(x) for x in [bf, mf, *vfs] if x))
        for field in fields:
            if (path, field) in m.skip_fields:
                continue
            val = lambda f: _GONE if f is None else f.get(field)
            bv = val(bf)
            ch = {val(v) for v in vfs if val(v) != bv}
            want = ch.pop() if len(ch) == 1 else (bv if not ch else None)
            if want is None:
                continue                                    # several mods: combined by the rules
            if val(mf) != want:
                what = field[1:] if field.startswith("@") else ("its entries" if field == "#seq" else "its text")
                who = "vanilla" if want == bv else "the mod that changed it"
                return f"{m.where(path)}: {what} doesn't match {who}"
    return None


# ------------------------------------------------------------------- core ---

def _settings_split(body):
    """A settings file's lines: split on line breaks only (str.splitlines would also split on
    characters like U+2028 inside a value, changing the line)."""
    lines = re.split(r"\r\n|\r|\n", body)
    if lines and lines[-1] == "":
        lines.pop()
    return lines


class ModManager:
    def __init__(self, game_dir, prefix):
        self.game = Path(game_dir)
        self.prefix = normalize_prefix(prefix)
        top = self.game / MANAGER_DIRNAME
        if not manager_dir_is_ours(top):
            raise RuntimeError(f"There's already a folder named {MANAGER_DIRNAME} in the game folder, and it wasn't "
                               f"made by this app:\n{top}\n\nRename or move it, then start again. Nothing was "
                               "changed in it.")
        self.root = top
        self.staging = self.root / "staging"
        self.backup = self.root / "backup"
        self.tmp = self.root / "tmp"
        self.state_file = self.root / "state.json"
        KEPT.bind(self.root / SCANS_FILE)
        for d in (self.staging, self.backup, self.tmp):
            d.mkdir(parents=True, exist_ok=True)
        for leftover in kids(self.tmp):              # from a crash / cancelled install
            shutil.rmtree(leftover, ignore_errors=True)
        self.state = self._load()
        self._files = {}
        self._settings_dir = None
        self._fix_names()
        self._groups_from_pages()
        self.pin_nexus_files()                           # from pages checked before (no web traffic)

    def _fix_names(self):
        """Mods installed before a download-name format was understood got the whole file name
        as their name, and no version or Nexus id. Fill those in from the archive's name —
        only where the name is still the raw one, never over something you typed."""
        changed = False
        for m in self.mods:
            if m.get("version") and clean_version(m["version"]) != m["version"]:
                m["version"] = clean_version(m["version"])   # 'v1.2' kept by older versions
                changed = True
        for m in self.mods:
            if m.get("nexus") or not m.get("archive"):
                continue
            name, version, mod_id = parse_archive_name(Path(m["archive"]).name)
            raw = m.get("name", "")
            if mod_id and mod_id in raw and raw.startswith(name) and raw != name:
                m["name"] = name
                m["nexus"] = mod_id
                if version and not m.get("version"):
                    m["version"] = version
                changed = True
        if changed:
            self.save()
        # names doubled by an older version for a page's other files (see undouble_name)
        for m in self.mods:
            if m.get("nexus") and (m.get("nexus_cat") or "").upper() != "MAIN":
                fixed = undouble_name(m.get("name", ""))
                if fixed != m["name"]:
                    self.rename_mod(m["id"], fixed)

    # --- state
    def _load(self):
        """state.json, or the copy kept from the save before it. If both are unreadable,
        stop: starting from an empty list would orphan every deployed file and backup."""
        state = {"mods": [], "deployed": {}, "filelist_added": {}}
        backup = self.state_file.with_suffix(".json.bak")
        for f in (self.state_file, backup):
            try:
                data = json.loads(f.read_text())
            except FileNotFoundError:
                continue
            except (OSError, ValueError):
                continue
            if isinstance(data, dict) and isinstance(data.get("mods"), list):
                state.update(data)
                for m in state["mods"]:                  # '3.1.0.lod' kept by older versions: 3.1.0
                    for k in ("version", "skip_update"):
                        if isinstance(m, dict) and isinstance(m.get(k), str) and m[k]:
                            m[k] = clean_version(m[k])
                return state
        if self.state_file.exists() or backup.exists():
            raise OSError(f"The mod list in {self.state_file} is damaged and couldn't be read. "
                          "Nothing was changed. Restore it from a backup, or move it aside to "
                          "start fresh (files already in the game would then show as unmanaged).")
        return state

    def save(self):
        self._tidy_groups()                         # every change ends here: groups stay whole
        tmp = self.state_file.with_suffix(".tmp")
        with open(tmp, "w") as f:
            # compact: Python's fast JSON writer only runs without indentation, and this file is
            # saved several times per change — pretty-printing it cost a noticeable pause each time
            f.write(json.dumps(self.state, separators=(",", ":")))
            f.flush()
            os.fsync(f.fileno())
        if self.state_file.exists():
            try:
                shutil.copyfile(self.state_file, self.state_file.with_suffix(".json.bak"))
            except OSError:
                pass
        tmp.replace(self.state_file)

    @property
    def rows(self):
        """Everything in the list, in order: mods and separators."""
        return self.state["mods"]

    @property
    def mods(self):
        """Just the mods, in order — separators never reach the game."""
        return [r for r in self.state["mods"] if not r.get("sep")]

    def get(self, mid):
        return next((r for r in self.state["mods"] if r["id"] == mid), None)

    # --- priority: who wins, kept apart from where a mod sits in the list (that's only how
    # you've arranged it). state["priority"] holds every mod's id, top priority first; the list
    # shows it as numbers on the mods that clash, and it's what mods.settings gets.
    def priority_ids(self):
        """Every mod's id, top priority first. Set up from the list's order the first time (so
        nothing changes), and kept whole: a mod missing from it goes right below the nearest mod
        above it in the list, one that's gone is dropped."""
        mods = self.mods
        ids = [m["id"] for m in mods]
        order = self.state.get("priority")
        if order is None:
            order = list(ids)
        elif len(order) != len(ids) or set(order) != set(ids):
            have = set(ids)
            order = list(dict.fromkeys(i for i in order if i in have))
            for k, mid in enumerate(ids):
                if mid in order:
                    continue
                above = next((ids[j] for j in range(k - 1, -1, -1) if ids[j] in order), None)
                order.insert(order.index(above) + 1 if above else 0, mid)
        self.state["priority"] = order
        return list(order)

    @property
    def ranked(self):
        """The mods in priority order, top (the one that wins) first."""
        by = {m["id"]: m for m in self.mods}
        return [by[i] for i in self.priority_ids()]

    def numbered_ids(self):
        """Mods that have a priority number: enabled ones with a folder that clashes."""
        self._clashes = None
        return set(self.settings_priorities())

    def place_priority(self, moved, drag=False, ignore=()):
        """Mods just put somewhere in the list get their priority from where they landed. Mods
        moved together keep the order they had among themselves.
        Installed (drag=False): right below the nearest mod above them that has a number — or,
        with none above, right above the nearest numbered one below — so a new mod doesn't take
        priority from mods already there.
        Dragged (drag=True): you put them there on purpose, so they win over every numbered mod
        listed below them; with none below, they go right after the numbered mods above them.
        Without any numbered mod around, the nearest mod at all counts. Mods in ignore (linked
        files that came along with a dragged main mod) don't count as neighbours, and keep their
        own place in the priority order."""
        prio = self.priority_ids()
        moving = set(moved) & set(prio)
        if not moving:
            return
        block = [i for i in prio if i in moving]
        rest = [i for i in prio if i not in moving]
        shown = [m["id"] for m in self.mods if m["id"] not in set(ignore) - moving]
        first = min(shown.index(i) for i in moving)
        last = max(shown.index(i) for i in moving)
        above = [i for i in reversed(shown[:first]) if i not in moving]
        below = [i for i in shown[last + 1:] if i not in moving]
        numbered = self.numbered_ids() - moving
        at = None
        if drag:
            for pool, after in (([i for i in below if i in numbered], False), ([i for i in above if i in numbered], True),
                                (below, False), (above, True)):
                if pool:
                    spots = [rest.index(i) for i in pool]
                    at = min(spots) if not after else max(spots) + 1
                    break
            self.state["priority"] = rest[:(at or 0)] + block + rest[(at or 0):]
            return
        for pool, after in (([i for i in above if i in numbered], True), ([i for i in below if i in numbered], False),
                            (above, True), (below, False)):
            if pool:
                at = rest.index(pool[0]) + (1 if after else 0)
                break
        at = 0 if at is None else at
        self.state["priority"] = rest[:at] + block + rest[at:]

    def set_priority_number(self, mid, number):
        """Give a numbered mod this priority number; the others shift to make room."""
        prio = self.priority_ids()
        numbered = self.numbered_ids()
        ranked = [i for i in prio if i in numbered]
        if mid not in ranked:
            return False
        others = [i for i in ranked if i != mid]
        number = max(1, min(int(number), len(ranked)))
        prio.remove(mid)
        if not others:
            prio.insert(0, mid)
        elif number - 1 < len(others):
            prio.insert(prio.index(others[number - 1]), mid)
        else:
            prio.insert(prio.index(others[-1]) + 1, mid)
        self.state["priority"] = prio
        self.save()
        return True

    def add_separator(self, index=0, name="New section"):
        rows = self.rows
        while 0 < index < len(rows) and rows[index].get("group") and rows[index].get("group") == rows[index - 1].get("group"):
            index -= 1                                    # never between two mods of a group: above it
        row = {"id": uuid.uuid4().hex[:12], "sep": True, "name": name, "collapsed": False}
        self.state["mods"].insert(index, row)
        self.save()
        return row

    def remove_section(self, sep_id):
        """Take a section away. Its mods stay, in the same order, moved to the part of the list
        that's outside every section (the bottom of it). Their priorities don't change."""
        rows = self.state["mods"]
        at = next((i for i, r in enumerate(rows) if r["id"] == sep_id and r.get("sep")), None)
        if at is None:
            return []
        end = at + 1
        while end < len(rows) and not rows[end].get("sep"):
            end += 1
        members = rows[at + 1:end]
        del rows[at:end]
        rows[self._section_end(None):self._section_end(None)] = members
        self.save()
        return members

    def remove_rows(self, ids, strays=()):
        for sep in [r["id"] for r in self.state["mods"] if r.get("sep") and r["id"] in ids]:
            self.remove_section(sep)
        mods = {r["id"] for r in self.state["mods"] if not r.get("sep") and r["id"] in ids}
        if mods:
            self.remove_mods(mods, strays)

    def stray_files(self, ids):
        """Files in the game that sit in the own folder of a mod being uninstalled but that the app
        didn't put there: made by the mod itself while the game ran (or its tools: a playlist
        editor's saved lists), or by you. Only a mod's own folder counts (mods/<name>, dlc/<name>),
        only one this app made, and only when no mod staying installed uses that folder. Left alone
        unless you choose otherwise: [(path relative to the game folder)]."""
        made = {d.lower() for d in self.state.get("made_dirs", [])}
        staying = {t.lower() for m in self.mods if m["id"] not in ids for t in m.get("targets", [])}
        placed = {k.lower() for k in self.state.get("deployed", {})}
        out = []
        for m in self.mods:
            if m["id"] not in ids:
                continue
            for t in m.get("targets", []):
                low = t.lower()
                if low.count("/") != 1 or not low.startswith(("mods/", "dlc/")) or low not in made or low in staying:
                    continue
                top = self.game / t
                if not top.is_dir() or top.is_symlink():
                    continue
                for dp, dn, files in os.walk(top):
                    for f in files:
                        rel = Path(dp, f).relative_to(self.game).as_posix()
                        if rel.lower() not in placed and rel not in out:
                            out.append(rel)
        return sorted(out, key=str.lower)

    def stage_dir(self, mod):
        return self.staging / mod["id"]

    def menu_files(self, mod):
        """The menus a mod adds to the game: its own XML files in the folder the game reads them
        from (user_config_matrix/pc), by name. Its copy of one of the game's own (input.xml,
        gameplay.xml…) changes a menu the game has, so it isn't one. Where a menu shows in the game
        isn't said: another mod can move menus anywhere."""
        pre = FILELIST_DIR.lower() + "/"
        deployed = getattr(self, "_deployed_low", None)
        if deployed is None or deployed[0] is not self.state["deployed"] or deployed[1] != len(self.state["deployed"]):
            deployed = (self.state["deployed"], len(self.state["deployed"]),
                        {k.lower(): v for k, v in self.state["deployed"].items() if k.lower().startswith(pre)})
            self._deployed_low = deployed
        files = self.mod_files(mod)
        cache = self.__dict__.setdefault("_menus", {})
        hit = cache.get(mod["id"])
        if hit and hit[0] is files and hit[1] is deployed:
            return hit[2]                                    # nothing changed since: the list redraws often
        out = []
        for rel in files:
            low = rel.lower()
            if not low.startswith(pre) or "/" in low[len(pre):] or not low.endswith(".xml"):
                continue
            info = deployed[2].get(low)
            if info is not None:
                if info.get("backup"):
                    continue                                 # placed over the game's own file
            elif (self.game / rel).exists() or ci_path(self.game, rel).exists():
                continue                                     # not ours there: the game's own
            out.append(rel.rpartition("/")[2])
        out = sorted(out, key=str.lower)
        cache[mod["id"]] = (files, deployed, out)
        return out

    def live_files(self, mod):
        """The files of a mod that go into the game: all of them, but its own menus when you
        switched its menu off (the "menu" kind in its snippets_off, see menu_files)."""
        files = self.mod_files(mod)
        if "menu" not in (mod.get("snippets_off") or ()):
            return files
        pre = FILELIST_DIR.lower() + "/"
        menus = {pre + n.lower() for n in self.menu_files(mod)}
        return [r for r in files if r.lower() not in menus] if menus else files

    def is_own_menu(self, rel):
        """Would a mod's file at rel (relative to the game folder) be a menu of its own, as
        menu_files tells them: an XML file straight in user_config_matrix/pc that isn't one of
        the game's own there (or that a mod put there, not over the game's)."""
        pre = FILELIST_DIR.lower() + "/"
        low = rel.lower()
        if not low.startswith(pre) or "/" in low[len(pre):] or not low.endswith(".xml"):
            return False
        info = next((v for k, v in self.state["deployed"].items() if k.lower() == low), None)
        if info is not None:
            return not info.get("backup")
        return not ((self.game / rel).exists() or ci_path(self.game, rel).exists())

    def mod_files(self, mod):
        mid = mod["id"]
        if mid not in self._files:
            # plain text, not path objects: on Python 3.12+ pathlib's relative_to is slow enough
            # that doing it per file made starting the app take seconds with big mods
            base = str(self.stage_dir(mod))
            cut = len(base) + 1
            files = []
            for dp, _, fn in os.walk(base):
                sub = dp[cut:].replace(os.sep, "/")
                lead = sub + "/" if sub else ""
                files += [lead + f for f in fn]
            self._files[mid] = sorted(files)
        return self._files[mid]

    def settings_dir(self):
        if self._settings_dir is not None or not self.prefix:
            return self._settings_dir
        docs = []
        for u in kids(self.prefix / "drive_c" / "users"):
            if u.name.lower() == "public" or not u.is_dir():
                continue
            for dn in ("Documents", "My Documents"):
                d = ci_child(u, dn)
                if d and d.is_dir():
                    docs.append(d)
                    break
        for d in docs:
            w = ci_child(d, "The Witcher 3")
            if w and w.is_dir():
                self._settings_dir = w
                return w
        docs.sort(key=lambda d: d.parent.name != "steamuser")
        self._settings_dir = (docs[0] / "The Witcher 3") if docs else None
        return self._settings_dir

    # --- install
    def prepare_install(self, archive):
        archive = Path(archive)
        tmpdir = self.tmp / uuid.uuid4().hex[:12]
        try:
            extract_archive(archive, tmpdir)
            remove_junk(tmpdir)
            plan, note = analyze(tmpdir, clean_stem(archive.name))
            keybinds = scan_keybind_files(tmpdir)
            keybinds["mod_info"] = read_mod_info(tmpdir)
        except Exception:
            shutil.rmtree(tmpdir, ignore_errors=True)
            raise
        return tmpdir, plan, note, keybinds

    def find_collisions(self, targets):
        """(managed mod ids this install replaces, unmanaged folders it would replace).
        A folder that holds the game's own files (dlc/bob, dlc/ep1…) is never either: mods
        that add files there sit side by side, and each file they overwrite is backed up."""
        shared = {t.lower() for t in targets if "/" in t and self._holds_game_files(t)}
        tl = {t.lower() for t in targets if "/" in t} - shared
        managed = [m["id"] for m in self.mods
                   if tl & {t.lower() for t in m["targets"] if "/" in t}]
        owned = {t.lower() for m in self.mods for t in m["targets"]}
        unmanaged = [t for t in targets if "/" in t and t.lower() not in owned
                     and t.lower() not in shared and ci_path(self.game, t).exists()]
        return managed, unmanaged

    def _holds_game_files(self, target):
        """Does this dlc/ folder in the game hold files this app didn't put there?"""
        if not target.lower().startswith("dlc/"):
            return False
        folder = ci_path(self.game, target)
        if not folder.is_dir():
            return False
        ours = {a.lower() for a in self.state.get("deployed", {})}
        for dp, _dn, files in os.walk(folder):
            for f in files:
                if Path(dp, f).relative_to(self.game).as_posix().lower() not in ours:
                    return True
        return False

    def sections(self):
        """[(separator id, name)] in list order."""
        return [(r["id"], r["name"]) for r in self.rows if r.get("sep")]

    @staticmethod
    def _name_key(m):
        return file_family(m.get("archive")) or re.sub(r"[^a-z0-9]+", "", m.get("name", "").lower())

    def group_main(self, nid, orphans=False):
        """The main mod among those from one Nexus page: the one you picked; else the file Nexus
        calls Main; else the one whose name the others' names start with ("Friendly HUD" for
        "Friendly HUD - Minimap Patch"); else the one installed first. Files left behind when
        their main mod was uninstalled (orphans) stand alone and don't count, unless asked."""
        page = [m for m in self.mods if str(m.get("nexus") or "") == str(nid) and (orphans or not m.get("orphan"))]
        if not page:
            return None
        keys = {m["id"]: self._name_key(m) for m in page}

        def prefix(m):
            k = keys[m["id"]]
            return bool(k) and any(o is not m and keys[o["id"]] != k and keys[o["id"]].startswith(k) for o in page)
        for test in (lambda m: m.get("group_main"), lambda m: (m.get("nexus_cat") or "").upper() == "MAIN", prefix):
            hits = [m for m in page if test(m)]
            if hits:
                return min(hits, key=lambda m: m.get("installed", 0))
        return min(page, key=lambda m: m.get("installed", 0))

    def _page_runs(self):
        """How older versions linked mods, from the list alone: mods from one Nexus page sitting
        next to each other, when the run holds that page's main mod. [(main mod, run)]. Used once,
        to turn those into groups."""
        out, rows, i = [], self.rows, 0
        while i < len(rows):
            nid = "" if rows[i].get("sep") or rows[i].get("orphan") else str(rows[i].get("nexus") or "")
            j = i + 1
            while nid and j < len(rows) and not rows[j].get("sep") and not rows[j].get("orphan") \
                    and str(rows[j].get("nexus") or "") == nid:
                j += 1
            run = rows[i:j]
            main = self.group_main(nid) if nid and len(run) > 1 else None
            if main is not None and main in run:
                out.append((main, run))
            i = j
        return out

    def _groups_from_pages(self):
        """Mods linked by their Nexus page in an older version become a group, its main mod on top."""
        if self.state.get("groups_v"):
            return
        runs = self._page_runs()
        for main, run in runs:
            gid = "g" + uuid.uuid4().hex[:8]
            for m in run:
                m["group"] = gid
            main["lead"] = True
        self.state["groups_v"] = 1
        if runs:
            self.save()

    @staticmethod
    def new_group_id():
        return "g" + uuid.uuid4().hex[:8]

    def group_rows(self, gid):
        """The mods of one group, in list order."""
        return [m for m in self.mods if gid and m.get("group") == gid]

    def group_lead(self, gid):
        return next((m for m in self.group_rows(gid) if m.get("lead")), None)

    def _tidy_groups(self):
        """Keep every group whole: at least two mods, at most one main mod, the main mod on top,
        all of them next to each other in one section (gathered where the main mod is, or the
        first of them). Only where they're listed changes, never priority."""
        rows = self.state["mods"]
        groups = {}
        for r in rows:
            if r.get("sep"):
                r.pop("group", None)
                r.pop("lead", None)
            elif r.get("group"):
                groups.setdefault(r["group"], []).append(r)
            else:
                r.pop("lead", None)
        kept = self.state.get("groups")
        if kept:
            for gid in [g for g in kept if len(groups.get(g, ())) < 2 or not kept[g]]:
                kept.pop(gid)
        for gid, members in groups.items():
            if len(members) < 2:
                for m in members:
                    m.pop("group", None)
                    m.pop("lead", None)
                continue
            leads = [m for m in members if m.get("lead")]
            for m in leads[1:]:
                m.pop("lead")
            lead = leads[0] if leads else None
            order = ([lead] if lead else []) + [m for m in members if m is not lead]
            at = [i for i, r in enumerate(rows) if r.get("group") == gid]
            if at == list(range(at[0], at[0] + len(at))) and [rows[i] for i in at] == order:
                continue
            anchor = lead or members[0]
            k = next(i for i, r in enumerate(rows) if r is anchor)
            rows[k] = None                                   # its place, kept while the others leave
            rows[:] = [r for r in rows if r is None or r.get("group") != gid]
            k = rows.index(None)
            rows[k:k + 1] = order

    def link_groups(self):
        """Groups as the list draws them: {mod id: {'main', 'head', 'prev', 'next', 'side', 'run'}}.
        main: the group's main mod (on top, the others indented under it); head: in a group without
        a main mod, which has a header row on top instead (named, foldable); prev/next: the row
        above/below is in the group too (the header counts); side: 1 under the top row; run: the
        group's id."""
        out, rows, i = {}, self.rows, 0
        while i < len(rows):
            gid = None if rows[i].get("sep") else rows[i].get("group")
            j = i + 1
            while gid and j < len(rows) and not rows[j].get("sep") and rows[j].get("group") == gid:
                j += 1
            run = rows[i:j]
            if gid and len(run) > 1:
                lead = run[0] if run[0].get("lead") else None
                for k, m in enumerate(run):
                    out[m["id"]] = {"main": m is lead, "head": lead is None, "prev": k > 0 or lead is None,
                                    "next": k < len(run) - 1, "side": 0 if m is lead else 1, "run": gid}
            i = j
        return out

    def group_info(self, gid):
        """A group's own settings (its header's name, folded or not), kept by id."""
        return self.state.setdefault("groups", {}).setdefault(gid, {})

    def group_name(self, gid):
        """The header's name: yours, or what the mods' names start with ("4K Reworked Women" for
        "4K Reworked Women - Shani", "- Triss"…), or "Group" when they have nothing in common."""
        name = (self.state.get("groups", {}).get(gid) or {}).get("name")
        if name:
            return name
        names = [m["name"] for m in self.group_rows(gid)]
        if not names:
            return "Group"
        common = os.path.commonprefix(names)
        if not all(n == common for n in names):
            if not all(len(n) == len(common) or not n[len(common)].isalnum() for n in names):
                common = common[:len(common) - len(re.split(r"[^0-9A-Za-z]", common)[-1])]   # whole words only
        common = common.rstrip(" -–_:|,.(")
        return common if len(common) >= 3 else "Group"

    def set_group_name(self, gid, name):
        info = self.group_info(gid)
        name = (name or "").strip()
        if name and name != self.group_name(gid):
            info["name"] = name
        elif not name:
            info.pop("name", None)                        # back to the one worked out from the mods
        self.save()

    def set_group_collapsed(self, gid, collapsed):
        info = self.group_info(gid)
        if collapsed:
            info["collapsed"] = True
        else:
            info.pop("collapsed", None)
        self.save()

    def make_group(self, ids):
        """One group of these mods. A mod already in a group brings its whole group along, as
        ordinary members (groups don't go inside groups); a main mod among them stays the main
        mod (the topmost one's, if several had one). They gather where the topmost of them is,
        in its section. Returns the group's id, or None for fewer than two mods."""
        chosen = [m for m in (self.get(i) for i in ids) if m and not m.get("sep")]
        gids = {m.get("group") for m in chosen if m.get("group")}
        members = [m for m in self.mods if m in chosen or (m.get("group") and m["group"] in gids)]
        if len(members) < 2:
            return None
        lead = next((m for m in members if m.get("lead")), None)
        gid = self.new_group_id()
        for m in members:
            m["group"] = gid
            m.pop("lead", None)
        if lead is not None:
            lead["lead"] = True
        rows = self.state["mods"]
        top = members[0]
        k = rows.index(top)
        rows[k] = None
        rows[:] = [r for r in rows if r is None or r not in members]
        k = rows.index(None)
        rows[k:k + 1] = ([lead] if lead else []) + [m for m in members if m is not lead]
        self._tidy_groups()
        self.save()
        return gid

    def set_lead(self, mid, on=True):
        """Make a mod its group's main mod (it goes to the top), or (on=False) leave the group
        without one. A main mod for the same Nexus page as the one before is that page's main
        file too."""
        m = self.get(mid)
        gid = (m or {}).get("group")
        if not gid:
            return
        if on:
            before = self.group_lead(gid)
            for o in self.group_rows(gid):
                o.pop("lead", None)
            m["lead"] = True
            if before is not None and m.get("nexus") and str(before.get("nexus") or "") == str(m["nexus"]):
                self.set_group_main(mid, save=False)
        else:
            m.pop("lead", None)
        self._tidy_groups()
        self.save()

    def leave_group(self, ids):
        """Take mods out of their groups: each goes right under what's left of its group."""
        rows = self.state["mods"]
        for mid in ids:
            m = self.get(mid)
            gid = (m or {}).get("group")
            if not gid:
                continue
            m.pop("group", None)
            m.pop("lead", None)
            rest = self.group_rows(gid)
            if rest:
                rows.remove(m)
                rows.insert(rows.index(rest[-1]) + 1, m)
        self._tidy_groups()
        self.save()

    def ungroup(self, gid):
        """Undo a group: its mods stay where they are, each on its own."""
        for m in self.group_rows(gid):
            m.pop("group", None)
            m.pop("lead", None)
        self.save()

    def drag_groups(self, moved, shown=None):
        """Groups after a drag in the list (the list already in its new order). A group whose main
        mod was dragged moved whole and stays as it was. Otherwise, mods dropped between two mods of
        a group join it (a whole group dropped there joins it too, as ordinary members: groups
        don't go inside groups). A mod of a group dropped right above or below it (not above its
        main mod) is still in it; dropped anywhere else, it's out of it.
        shown: the rows as the list shows them, a group's header among them as a row of its own
        ({'id', 'group', 'lead': True}): it counts like a main mod."""
        rows = shown if shown is not None else self.state["mods"]
        moving = set(moved)
        whole = set()
        for m in rows:
            if m["id"] in moving and m.get("lead") and m.get("group"):
                if all(o["id"] in moving for o in self.group_rows(m["group"])):
                    whole.add(m["group"])
        k = 0
        while k < len(rows):
            if rows[k]["id"] not in moving:
                k += 1
                continue
            j = k
            while j + 1 < len(rows) and rows[j + 1]["id"] in moving:
                j += 1
            block = rows[k:j + 1]
            above = rows[k - 1] if k > 0 else None
            below = rows[j + 1] if j + 1 < len(rows) else None
            k = j + 1
            if any(r.get("sep") for r in block):
                continue                                  # a whole section moved: its groups with it
            ga = above.get("group") if above and not above.get("sep") else None
            gb = below.get("group") if below and not below.get("sep") else None
            into = ga if ga and ga == gb else None
            for m in block:
                own = m.get("group")
                if own in whole:
                    if into and into != own:
                        m["group"] = into
                        m.pop("lead", None)
                    continue
                if into:
                    if into != own:
                        m["group"] = into
                        m.pop("lead", None)
                elif own and (own == ga or (own == gb and not below.get("lead"))):
                    continue                              # right next to its own group: still in it
                else:
                    m.pop("group", None)
                    m.pop("lead", None)
        self._tidy_groups()

    def rename_mod(self, mid, name):
        """A new name for a mod, everywhere it's shown: the list, the merges it's part of (their
        tooltips and the decisions window), and the Nexus grouping."""
        m = self.get(mid)
        old, m["name"] = m["name"], name
        for rec in self.state.get("merges", {}).values():
            if mid not in rec.get("owners", []):
                continue
            rec["labels"] = [name if label == old and owner == mid else label
                             for label, owner in zip(rec.get("labels", []), rec.get("owners", []))]
            # your answers there stay linked to it ("Clear my decisions…" finds them by name)
            if "decided" in rec:
                rec["decided"] = [[key, sorted(name if x == old else x for x in mods)]
                                  for key, mods in rec["decided"]]
        self.forget_scans()                                 # the merge inputs carry the names
        self.__dict__.pop("_details", None)                 # the decisions window: worked out again
        self.save()

    def set_enabled(self, ids, on):
        """Switch mods on or off. A main mod takes its linked files along: switched off, the ones
        that were on go off with it (and remember why); switched back on, exactly those come back.
        Files you switch yourself are yours: they lose that mark. Returns every mod id changed."""
        links = self.link_groups()
        runs = {}
        for mid, g in links.items():
            runs.setdefault(g["run"], []).append(mid)
        now, changed = int(time.time()), set()
        ids = [i for i in ids if (self.get(i) or {}).get("sep") is not True and self.get(i)]
        for mid in ids:
            m = self.get(mid)
            if on and not m["enabled"]:
                m["enabled_at"] = now                 # switching it on counts as arriving
            if m["enabled"] != on:
                changed.add(mid)
            m["enabled"] = on
            m.pop("off_with", None)
            g = links.get(mid)
            if not (g and g["main"]):
                continue
            for kid in runs[g["run"]]:
                k = self.get(kid)
                if kid == mid or kid in ids:
                    continue
                if not on and k["enabled"]:
                    k["enabled"], k["off_with"] = False, mid
                    changed.add(kid)
                elif on and k.get("off_with") == mid:
                    k["enabled"], k["enabled_at"] = True, now
                    k.pop("off_with")
                    changed.add(kid)
        self.save()
        return changed

    def edit_mod(self, mid, name, version, nexus, section, snippets_off=None, make_main=None):
        """Apply what the Edit window says. Returns True when the game's settings files need
        updating (a kind of its instructions switched on or off)."""
        m = self.get(mid)
        if name and name != m["name"]:
            self.rename_mod(mid, name)
        m["version"] = clean_version(version)
        m["nexus"] = extract_nexus_id(nexus)
        if make_main is not None and m.get("group") and bool(m.get("lead")) != make_main:
            self.set_lead(mid, make_main)
        if section != self.section_of(mid):
            # only where it's listed (priority stays); a main mod takes its group along, any
            # other mod of a group leaves it
            block = [m]
            if m.get("group") and m.get("lead"):
                block = self.group_rows(m["group"])
            elif m.get("group"):
                m.pop("group")
            rows = self.state["mods"]
            for r in block:
                rows.remove(r)
            at = self._section_end(section)
            rows[at:at] = block
        sync = False
        if snippets_off is not None:
            shown, off = set(snippets_off[1]), set(snippets_off[0])
            new = (set(m.get("snippets_off") or ()) - shown) | off
            if new != set(m.get("snippets_off") or ()):
                decided = new ^ set(m.get("snippets_off") or ())
                if "menu" in decided:
                    self._menu_switched(m, on="menu" not in new)
                m["snippets_off"] = sorted(new)
                m["snippets_auto_off"] = [k for k in m.get("snippets_auto_off", ()) if k not in decided]
                sync = True
        self.save()
        return sync

    def _menu_switched(self, m, on):
        """A mod's menu switched off: what its menu has in user.settings and dx12user.settings is
        kept (the game forgets a menu's values when it runs without that menu), so switching it
        on again brings them back, each where it was (see _menu_back)."""
        if on:
            if m.get("menu_kept"):
                m["menu_back"] = True
            return
        m.pop("menu_back", None)
        kept = self._menu_values_now(only=m)
        if kept:
            m["menu_kept"] = kept
        else:
            m.pop("menu_kept", None)

    def _menu_back(self):
        """Put back the menu values kept for a mod whose menu was switched on again, once its menu
        is in the game and the settings files can be written (not while the game runs)."""
        for m in self.mods:
            if not m.get("menu_back"):
                continue
            if not self.snippet_on(m, "menu"):
                continue                                 # off again, or the mod's off: wait
            if not self.settings_dir() or game_running():
                continue                                 # the game would write over them on exit
            self._restore_menu_values(m.pop("menu_kept", None) or {})
            m.pop("menu_back", None)

    def set_group_main(self, mid, save=True):
        """The main file of its Nexus page (what a new file from that page joins)."""
        m = self.get(mid)
        for o in self.mods:
            if str(o.get("nexus") or "") == str(m.get("nexus") or ""):
                o.pop("group_main", None)
                o.pop("orphan", None)                        # a main mod again: the page's files regroup
        m["group_main"] = True
        if save:
            self.save()

    def section_of(self, mid):
        """The separator a row sits under, or None when it's above every separator."""
        current = None
        for r in self.rows:
            if r.get("sep"):
                current = r["id"]
            elif r["id"] == mid:
                return current
        return None

    def _hand_over_settings(self, old_ids, mid):
        """An update takes over what the old version put in your settings files: the lines it added
        (so a key both versions have stays as it is, with the value you set in the mod's menu),
        the values remembered while it was off, and its keybinds. Keys the new version no longer
        has still come out on the sync that follows."""
        old_ids = set(old_ids)
        for entries in self.state.get("user_added", {}).values():
            for e in entries:
                if len(e) > 2 and e[2] in old_ids:
                    e[2] = mid
        kept = self.state.get("user_kept", {})
        for oid in old_ids:
            if oid in kept:
                kept.setdefault(mid, {}).update(kept.pop(oid))
        binds = self.state.get("keybinds", {})
        for oid in old_ids:
            if oid in binds:
                binds.setdefault(mid, []).extend(binds.pop(oid))

    def _section_end(self, sep_id):
        """Where a new mod goes: the bottom of its section (None: of the part above every
        section), so it never takes priority from mods that are already there."""
        rows = self.rows
        start = next((i + 1 for i, r in enumerate(rows) if r["id"] == sep_id), None) if sep_id else 0
        if start is None:
            start = 0
        end = start
        while end < len(rows) and not rows[end].get("sep"):
            end += 1
        return end

    def finish_install(self, tmpdir, plan, display, archive, replace_ids=(), delete_unmanaged=(),
                       version="", keybinds=None, nexus_id="", section=KEEP_PLACE, above=None, extra=None,
                       join=True):
        """section: a separator id to put the mod under, None for no section, or KEEP_PLACE —
        a replacement keeps its spot. A new mod goes to the bottom of its section.
        above: a mod id — a patch or add-on for that mod, installed into its folder: it goes right
        under it in the list, and right above it in priority, so its files win.
        join: a new file from the Nexus page of a mod you have (an optional file, a patch) goes
        right under that page's main mod, with its other files — see _join_main."""
        pos, enabled = 0, True
        prio = self.priority_ids()
        # stage the new copy first: if that fails, the old version is still fully installed
        mid = uuid.uuid4().hex[:12]
        stage = self.staging / mid
        try:
            self._save_docs(tmpdir, self.docs_dir(mid))      # before staging moves files out
            build_staging(plan, stage)
        except BaseException:
            shutil.rmtree(stage, ignore_errors=True)
            shutil.rmtree(self.docs_dir(mid), ignore_errors=True)
            raise
        finally:
            shutil.rmtree(tmpdir, ignore_errors=True)
        targets = self._scan_targets(stage)
        if not targets:
            shutil.rmtree(stage, ignore_errors=True)
            raise RuntimeError("Nothing to install: nothing was selected, or the archive is empty.")
        old_section = KEEP_PLACE
        old = []
        if replace_ids:
            # an update is one swap: the new version takes the old one's slot and a single sync
            # moves the files over — the mod's place, and with it its mods.settings entry and
            # priority, never goes missing, not even for a moment
            idxs = [i for i, r in enumerate(self.rows) if r["id"] in replace_ids]
            pos = min(idxs)
            enabled = any(self.rows[i].get("enabled") for i in idxs)
            old_section = self.section_of(self.rows[pos]["id"])
            old = [m for m in self.mods if m["id"] in replace_ids]
            self.state["mods"] = [r for r in self.rows if r["id"] not in replace_ids]
            slot = min(prio.index(i) for i in replace_ids if i in prio)       # its priority stays too
            prio = [i for i in prio if i not in replace_ids]
        for rel in delete_unmanaged:
            if rel.split("/")[0].lower() not in ("mods", "dlc"):
                continue
            p = ci_path(self.game, rel)
            if p.is_dir() and not p.is_symlink():
                shutil.rmtree(p)
            elif p.exists() or p.is_symlink():
                p.unlink()
        placed_under = None
        if not replace_ids or (section != KEEP_PLACE and section != old_section):
            pos = self._section_end(None if section == KEEP_PLACE else section)
        mod = {"id": mid, "name": display, "version": clean_version(version), "nexus": nexus_id, "enabled": enabled,
               "archive": str(archive), "installed": int(time.time()), "targets": targets}
        mod.update(keybinds or {})
        if mod.get("user_settings_own") and "snippets_off" not in (keybinds or {}):
            # the mod's own config files start off when nothing chose otherwise (the Install window does)
            mod["snippets_off"] = sorted(set(mod.get("snippets_off") or ()) | {"user_own"})
        # which file of its Nexus page it is (main or optional), and a main mod you picked: an
        # update keeps them unless the new download says otherwise
        for key in ("group_main", "nexus_cat", "orphan"):
            got = next((o[key] for o in old if o.get(key)), None)
            if got and not (extra or {}).get(key):
                mod[key] = got
        if not (extra or {}).get("nexus_file") and old:
            # a reinstall from its archive (no download link to say which file): the same upload
            # keeps its id; a different archive gets one when its Nexus name is known (pin_nexus_files)
            same = [o for o in old if o.get("nexus_file") and o.get("archive")
                    and archive_stem(Path(o["archive"]).name) == archive_stem(Path(archive).name)]
            if same:
                mod["nexus_file"] = same[0]["nexus_file"]
        if replace_ids and not (section != KEEP_PLACE and section != old_section):
            for key in ("group", "lead"):                 # an update stays in its group, in its place
                got = next((o[key] for o in old if o.get(key)), None)
                if got:
                    mod[key] = got
        mod.update({k: v for k, v in (extra or {}).items() if v})
        host = next((i for i, r in enumerate(self.rows) if r["id"] == above), None) if above else None
        if host is not None and not replace_ids:
            pos = host + 1
        elif not replace_ids:
            # a new mod that clashes goes right under the last mod in its section that has a
            # priority number, so it doesn't take priority from any of them
            placed = self._clash_place(mod, None if section == KEEP_PLACE else section)
            if placed is not None:
                pos, placed_under = placed
        if not replace_ids:
            pos, placed_under = self._past_group(pos, placed_under)
        self.rows.insert(pos, mod)
        if replace_ids:
            prio.insert(slot, mid)
            self.state["priority"] = prio
            self._hand_over_settings(replace_ids, mid)
        elif host is not None:
            prio.insert(prio.index(above), mid)
            self.state["priority"] = prio
        else:
            self.state["priority"] = prio
            rejoined = self._rejoin_orphans(mod) if nexus_id else None
            joined = self._join_main(mod) if join and nexus_id and not rejoined else None
            if rejoined:
                placed_under = None
                joined = None
            elif joined:
                placed_under = None
            else:
                self.place_priority([mid])
        self.save()
        self.sync()
        for m in old:                                      # the old version's stored copy goes last
            shutil.rmtree(self.stage_dir(m), ignore_errors=True)
            shutil.rmtree(self.docs_dir(m["id"]), ignore_errors=True)
            self._files.pop(m["id"], None)
        if not replace_ids and host is None and nexus_id and rejoined:
            return {"id": mid, "rejoined": rejoined, "name": display}
        if not replace_ids and host is None and join and nexus_id and joined:
            return {"id": mid, "joined": joined[0], "wins": joined[1], "name": display}
        if placed_under:
            where = self.section_of(mid)
            where = next((n for i, n in self.sections() if i == where), None)
            return {"id": mid, "placed_under": placed_under, "section": where, "name": display}
        return {"id": mid}

    def _past_group(self, pos, name=None):
        """A new mod put between two mods of a group goes right under the group instead: joining
        a group is your choice (or its Nexus page's). (row index, name of the row above it)."""
        rows = self.rows
        while 0 < pos < len(rows) and not rows[pos].get("sep") and rows[pos].get("group") \
                and rows[pos].get("group") == rows[pos - 1].get("group"):
            pos += 1
            name = rows[pos - 1]["name"] if name else name
        return pos, name

    def _overrides(self, a, b):
        """Does mod a have files mod b has too (loose files, scripts or packed files)?"""
        if {r.lower() for r in self.mod_files(a)} & {r.lower() for r in self.mod_files(b)}:
            return True
        self._clashes = None
        folders = self.clashes()["folders"]
        res = lambda m: set().union(*(folders.get(f, ("", None, set()))[2] for f in self._mod_folders(m)))
        return bool(res(a) & res(b))

    def _rejoin_orphans(self, mod):
        """The main file of a page whose other files were orphaned (their main mod was uninstalled)
        is installed again: it's their group's main mod again, on top (a group made for them when
        they had none left). A file that changes some of its files keeps winning over it.
        Returns how many rejoined, or None."""
        nid = str(mod.get("nexus") or "")
        orphans = [m for m in self.mods if m.get("orphan") and m is not mod and str(m.get("nexus") or "") == nid
                   and not (m.get("group") and self.group_lead(m["group"]))]
        if not orphans or self.group_main(nid, orphans=True) is not mod:
            return None
        for o in orphans:
            o.pop("orphan", None)
        gid = next((o["group"] for o in orphans if o.get("group")), None) or self.new_group_id()
        for o in orphans:
            if not o.get("group"):
                o["group"] = gid
        mod["group"], mod["lead"] = gid, True
        rows = self.state["mods"]
        rows.remove(mod)
        first = min(self.group_rows(gid), key=rows.index)
        rows.insert(rows.index(first), mod)
        self.place_priority([mod["id"]])
        winners = [o["id"] for o in orphans if self._overrides(o, mod)]
        if winners:
            prio = [i for i in self.priority_ids() if i != mod["id"]]
            prio.insert(max(prio.index(i) for i in winners) + 1, mod["id"])
            self.state["priority"] = prio
        return len(orphans)

    def _join_main(self, mod):
        """Put a new mod from the Nexus page of one you have in that page's main mod's group, at
        its end (a group made for them when the main mod has none yet). If it overrides some of the main mod's files
        it's numbered right above the main mod (a file built on a mod is meant to change it);
        otherwise its number comes from where it landed. Returns (main mod's name, whether it
        wins over it), or None when there's no other main mod to join."""
        main = self.group_main(mod.get("nexus"))
        if main is None or main["id"] == mod["id"]:
            return None
        rows = self.state["mods"]
        rows.remove(mod)
        gid = main.get("group")
        if not gid:
            gid = main["group"] = self.new_group_id()
            main["lead"] = True
        mod["group"] = gid
        mod.pop("lead", None)
        rows.insert(rows.index(self.group_rows(gid)[-1]) + 1, mod)
        self.place_priority([mod["id"]])
        wins = self._overrides(mod, main)
        if wins:
            prio = [i for i in self.priority_ids() if i != mod["id"]]
            prio.insert(prio.index(main["id"]), mod["id"])
            self.state["priority"] = prio
        return main["name"], wins

    @staticmethod
    def _mod_folders(m):
        return {t.split("/", 1)[1].lower() for t in m.get("targets", ()) if t.lower().startswith("mods/")}

    def _needs(self, extra=None):
        """Folders that get a priority number, counting a staged mod in for a moment."""
        if extra is not None:
            self.state["mods"].append(extra)
        self._clashes = None
        try:
            return self.clashes()["needs"]
        finally:
            if extra is not None:
                self.state["mods"].remove(extra)
            self._clashes = None

    def _clash_place(self, mod, section):
        """For a new mod that clashes, inside the section it's installed to (None: the part above
        every section): right under the last mod there that has a priority number, so it doesn't
        take priority from any of them. Other mods are never moved, and the mod never leaves its
        section. Returns (row index, name of the row above it), or None when it clashes with
        nothing or nothing in its section has a number (it then goes to the bottom of the section)."""
        mine = self._mod_folders(mod)
        if not mine:
            return None
        after = self._needs(mod)
        if not mine & after:
            return None
        rows = self.rows
        start = next((i + 1 for i, r in enumerate(rows) if r["id"] == section), 0) if section else 0
        end = self._section_end(section)
        numbered = [i for i in range(start, end)
                    if not rows[i].get("sep") and rows[i].get("enabled") and self._mod_folders(rows[i]) & after]
        if not numbered:
            return None
        return numbered[-1] + 1, rows[numbered[-1]]["name"]

    @staticmethod
    def _scan_targets(stage):
        out = []
        for c in kids(stage):
            n = c.name.lower()
            if n in ("mods", "dlc") and c.is_dir():
                out += [f"{n}/{s.name}" for s in kids(c)]
            else:
                out.append(c.name)
        return out

    def _forget_decisions_of(self, ids):
        """Drop every answer that involved these mods: removing a mod on purpose shouldn't
        leave its old decisions waiting to come back if it's installed again."""
        res = self.state.get("resolutions", {})
        if not res:
            return
        for mid in ids:
            for _key, item in self.decisions_of(mid):
                res.pop(item, None)

    def has_decisions(self, mid):
        """Quick check, for the menu: did you answer anything in a merge this mod is part of?"""
        return any(mid in r.get("mods", []) and (r.get("items") or 0) > (r.get("pending") or 0)
                   for r in self.state.get("merges", {}).values())

    def decisions_of(self, mid):
        """[(merge key, decision key)] for every answer you gave where this mod was involved."""
        res = self.state.get("resolutions", {})
        out = []
        for key, rec in list(self.state.get("merges", {}).items()):
            if mid not in rec.get("mods", []) or not rec.get("items"):
                continue
            if "decided" not in rec:                # merged by an older version: worked out once
                det = self.merge_details(key)
                if not det:
                    continue
                rec["decided"] = [[it["key"], sorted({m for v in it["variants"] for m in v["mods"]})]
                                  for it in det.get("items", []) if it["resolution"] is not None]
            theirs = {label for label, owner in zip(rec.get("labels", []), rec.get("owners", [])) if owner == mid}
            out += [(key, item) for item, mods in rec["decided"] if item in res and set(mods) & theirs]
        return out

    def clear_decisions(self, mid):
        """Forget your answers where this mod was involved; those spots become open questions again.
        Returns the files affected."""
        found = self.decisions_of(mid)
        res = self.state.get("resolutions", {})
        for _key, item in found:
            res.pop(item, None)
        files = sorted({key for key, _i in found})
        for key in files:
            self.state["merges"][key]["recipe"] = None          # merged again, now without them
        self.save()
        self.sync()
        return files

    def remove_mods(self, ids, strays=()):
        """strays: files the app didn't put there (see stray_files) that you chose to remove with
        the mods: they go to the Trash, so they can be got back."""
        self._forget_decisions_of(set(ids))
        gone = [m for m in self.mods if m["id"] in ids]
        # a main mod going: the rest of its group stays a group, without a main mod (none of them
        # becomes the others' parent), until that page's main file is installed again
        for m in gone:
            nid = str(m.get("nexus") or "")
            if nid and self.group_main(nid) is m:
                for o in self.mods:
                    if o["id"] not in ids and str(o.get("nexus") or "") == nid:
                        o["orphan"] = True
        for o in self.mods:
            if o.get("off_with") in ids:
                o.pop("off_with", None)                      # switched off with a mod that's gone: stays off
        self.state["mods"] = [r for r in self.rows if r["id"] not in ids]
        self.save()
        self.sync()
        placed = {k.lower() for k in self.state.get("deployed", {})}
        for rel in strays:
            path = self.game / rel
            if rel.lower() in placed or ".." in Path(rel).parts or not path.is_file() or path.is_symlink():
                continue                                   # placed by a mod meanwhile, or not a plain file
            if move_to_trash(path):
                self._prune_made(path)                    # the mod's own folders, now empty
        for m in gone:
            shutil.rmtree(self.stage_dir(m), ignore_errors=True)
            shutil.rmtree(self.docs_dir(m["id"]), ignore_errors=True)
            self._files.pop(m["id"], None)

    # --- readmes: kept apart from the mod's files, so they're never deployed into the game
    def docs_dir(self, mid):
        return self.root / "docs" / mid

    @staticmethod
    def _save_docs(src, dst):
        """Copy every readme-like file in an unpacked archive to dst, keeping its path inside the
        archive. Game data that happens to be text (filelists, anything under content/) is left out."""
        src, n = Path(src), 0
        Path(dst).mkdir(parents=True, exist_ok=True)     # made even when empty: "read, none found"
        for dp, dn, files in os.walk(src):
            dn[:] = [d for d in dn if d.lower() != "content"]
            for f in files:
                path = Path(dp, f)
                if path.suffix.lower() not in DOC_EXTS | SCRIPT_EXTS or f.lower().endswith("filelist.txt") or path.is_symlink():
                    continue
                try:
                    if path.stat().st_size > 5 * 1024 * 1024:
                        continue
                    out = Path(dst) / path.relative_to(src)
                    out.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copyfile(path, out)
                    n += 1
                except OSError:
                    pass
        return n

    def mod_docs(self, mod):
        """The mod's readmes, the one mentioning keybinds first: [(name shown, path)]."""
        out = []
        top = self.docs_dir(mod["id"])
        for dp, _dn, files in os.walk(top):
            out += [Path(dp, f) for f in files]
        if not out and not top.is_dir():           # installed before readmes were kept
            stage = self.stage_dir(mod)
            for dp, dn, files in os.walk(stage):
                dn[:] = [d for d in dn if d.lower() != "content"]
                out += [Path(dp, f) for f in files if Path(f).suffix.lower() in DOC_EXTS
                        and not f.lower().endswith("filelist.txt")]
            top = stage
        hint = (mod.get("keybinds") or "").lower()
        out.sort(key=lambda p: (p.relative_to(top).as_posix().lower() != hint, p.relative_to(top).as_posix().lower()))
        return [(p.relative_to(top).as_posix(), p) for p in out]

    def fetch_docs(self, mid):
        """Take the readmes from a mod's archive again (for mods installed before they were kept)."""
        mod = self.get(mid)
        archive = Path(mod.get("archive") or "") if mod else None
        if not archive or not archive.is_file():
            return []
        tmp = self.tmp / uuid.uuid4().hex[:12]
        try:
            extract_archive(archive, tmp)
            remove_junk(tmp)
            self.docs_dir(mid).mkdir(parents=True, exist_ok=True)     # read once: even if it has none
            self._save_docs(tmp, self.docs_dir(mid))
        finally:
            shutil.rmtree(tmp, ignore_errors=True)
        return self.mod_docs(mod)

    def loaded_bundles(self):
        """[(name, count)]: the .bundle files the game loads besides its own, per mod, in priority
        order. Read from the game folder itself (each folder in mods/, and the mods' own folders in
        dlc/), so mods the app didn't install count too, and ones switched off don't."""
        names = {t.lower(): m["name"] for m in self.ranked for t in m.get("targets", [])}
        place = {m["name"]: i for i, m in enumerate(self.ranked)}
        ours = {AUTO_MERGE_NAME.lower(): "Merged by this app", MERGED_NAME: "Script Merger's merge"}
        found = {}
        for top in ("mods", "dlc"):
            d = ci_child(self.game, top)
            if not d:
                continue
            for sub in kids(d):
                if not sub.is_dir() or (top == "dlc" and GAME_DLC.match(sub.name)):
                    continue                             # the game's own DLC
                content = ci_child(sub, "content")
                try:
                    n = sum(1 for f in content.iterdir() if f.suffix.lower() == ".bundle" and f.is_file()) \
                        if content and content.is_dir() else 0
                except OSError:
                    continue
                if n:
                    name = names.get(f"{top}/{sub.name}".lower()) or ours.get(sub.name.lower()) or sub.name
                    found[name] = found.get(name, 0) + n
        return sorted(found.items(), key=lambda kv: (place.get(kv[0], -1 if kv[0] in ours.values() else 10 ** 6), kv[0].lower()))

    def unmanaged_mods(self):
        owned = {t.lower() for m in self.mods for t in m["targets"]}
        d = ci_child(self.game, "mods")
        if not d:
            return []
        return [f"mods/{s.name}" for s in kids(d)
                if s.is_dir() and not s.is_symlink()
                and f"mods/{s.name}".lower() not in owned
                and s.name.lower() not in (MERGED_NAME, AUTO_MERGE_NAME.lower())]

    # --- script merging
    @property
    def merged_dir(self):
        return self.root / "merged"

    def merged_path(self, rel):
        return self.merged_dir / "mods" / AUTO_MERGE_NAME / "content" / "scripts" / rel

    def _managed_folders(self):
        return {t.split("/", 1)[1].lower() for m in self.mods for t in m["targets"]
                if t.lower().startswith("mods/")}

    @staticmethod
    def _unique_labels(sources):
        """Two mods can share a name (two files from one Nexus page, say). The decisions window
        tells versions apart by name, so a repeated one gets its folder (or a number) added."""
        count = Counter(s[0] for s in sources)
        if all(n == 1 for n in count.values()):
            return sources
        out, seen = [], Counter()
        for s in sources:
            label = s[0]
            if count[label] > 1:
                seen[label] += 1
                folder = s[2].split("/", 1)[1] if isinstance(s[2], str) and "/" in s[2] else ""
                label = f"{label} ({folder})" if folder else f"{label} #{seen[label]}"
            out.append((label,) + tuple(s[1:]))
        return out

    def _script_inputs(self, everything=False):
        """{key: {'rel', 'sources': [(label, path, vkey, mod id or None)]}} for every loose
        script that two or more mod folders ship, top priority first. Unmanaged folders in
        the game count too — the game loads them, so ignoring them would drop their edits."""
        return self._scanned(("scripts", everything), lambda: self._scan_scripts(everything))

    def _scan_scripts(self, everything):
        found = {}

        def add(rel_parts, label, path, vkey, mid):
            rel = "/".join(rel_parts)
            entry = found.setdefault(rel.lower(), {"rel": rel, "sources": []})
            entry["sources"].append((label, path, vkey, mid))

        for mod in self.ranked:
            if not mod["enabled"]:
                continue
            folders = set()
            for rel in self.mod_files(mod):
                parts = rel.split("/")
                if len(parts) > 4 and parts[0].lower() == "mods" and parts[2].lower() == "content" \
                        and parts[3].lower() == "scripts" and parts[-1].lower().endswith(".ws"):
                    folders.add(parts[1])
            for rel in self.mod_files(mod):
                parts = rel.split("/")
                if not (len(parts) > 4 and parts[0].lower() == "mods" and parts[2].lower() == "content"
                        and parts[3].lower() == "scripts" and parts[-1].lower().endswith(".ws")):
                    continue
                label = mod["name"] if len(folders) == 1 else module_name(parts[1], mod["name"])
                add(parts[4:], label, self.stage_dir(mod) / rel, f"{mod['id']}/{parts[1]}", mod["id"])

        mods_dir = ci_child(self.game, "mods")
        managed = self._managed_folders()
        # anything this app deployed is its own, even a mod being removed right now whose
        # files haven't been cleared yet — only folders it never touched count as unmanaged
        deployed = {a.split("/")[1].lower() for a in self.state.get("deployed", {})
                    if a.lower().startswith("mods/") and a.count("/") > 1}
        skip = managed | deployed | {MERGED_NAME, AUTO_MERGE_NAME.lower()}
        rows = self.settings_rows()
        rank = {n.lower(): i for i, (n, _e, _mid) in enumerate(rows)}
        # folders the game skips (Enabled=0 in mods.settings) have nothing to merge
        order = [n for n, en, mid in rows if mid is None and en != "0"]
        for folder in order:
            if folder.lower() in skip or not mods_dir:
                continue
            scripts = ci_path(mods_dir / folder, "content/scripts")
            if not scripts.is_dir():
                continue
            for dp, _dn, files in os.walk(scripts):
                for f in files:
                    if f.lower().endswith(".ws"):
                        path = Path(dp, f)
                        add(path.relative_to(scripts).parts, f"{folder} (not managed here)",
                            path, f"unmanaged/{folder.lower()}", None)
        out = {}
        for k, v in found.items():
            # top first, in the order mods.settings gives the game; within one folder the
            # higher mod's copy replaces the lower one on disk, so only that copy counts
            v["sources"].sort(key=lambda s: rank.get(s[2].split("/", 1)[1].lower(), len(rank)))
            seen, kept = set(), []
            for s in v["sources"]:
                folder = s[2].split("/", 1)[1].lower()
                if folder not in seen:
                    seen.add(folder)
                    kept.append(s)
            v["sources"] = self._unique_labels(kept)
            if everything or len(kept) > 1:
                out[k] = v
        return out

    def update_merges(self):
        start = time.perf_counter()
        try:
            return self._update_merges()
        finally:
            parts = getattr(self, "_merge_parts", [])
            xml = sum(d for n, d in parts if n == "merge XML")
            self._merge_parts = [("merge scripts", time.perf_counter() - start - xml)] + \
                [p for p in parts if p[0] == "merge XML"]

    def _update_merges(self):
        """Bring every merged script up to date with the current mod list. Only scripts whose
        ingredients changed are recomputed; everything else is left exactly as it is."""
        merges = self.state.setdefault("merges", {})
        resolutions = self.state.setdefault("resolutions", {})
        self.state.pop("merge_error", None)
        legacy_info = self._legacy_scan()
        inputs = self._script_inputs()
        vanilla = ci_path(self.game, VANILLA_SCRIPTS)
        legacy = ci_child(ci_child(self.game, "mods") or self.game, "mod0000_MergedFiles")

        for key, entry in inputs.items():
            rel, sources = entry["rel"], entry["sources"]
            out = self.merged_path(rel)
            base_path = ci_path(vanilla, rel)
            try:
                base_bytes = base_path.read_bytes() if base_path.is_file() else None
                blobs = [p.read_bytes() for _l, p, _v, _m in sources]
            except OSError as e:
                self._drop_output(out)
                merges[key] = {"rel": rel, "status": "failed", "reason": f"couldn't read: {e}",
                               "mods": [s[3] for s in sources if s[3]], "labels": [s[0] for s in sources],
                               "recipe": None}
                continue
            recipe = [MERGE_ENGINE, _sha(base_bytes) if base_bytes is not None else None,
                      [[s[2], _sha(b)] for s, b in zip(sources, blobs)]]
            old = merges.get(key)
            answered = any(k in resolutions for k in (old or {}).get("pending_keys", ()))
            if old and old.get("recipe") == recipe and not answered and "unchanged" in old \
                    and (old["status"] not in ("merged", "superset") or out.is_file() or old.get("topwins")):
                continue                                         # nothing it depends on changed

            record = {"rel": rel, "recipe": recipe, "mods": [s[3] for s in sources if s[3]],
                      "labels": [s[0] for s in sources], "owners": [s[3] for s in sources],
                      "reason": "", "pending": 0, "auto": 0, "unchanged": [],
                      "legacy": bool(legacy and ci_path(legacy, "content/scripts/" + rel).is_file())}
            try:
                readable = [decode_script(b) for b in blobs] + ([decode_script(base_bytes)] if base_bytes else [])
            except (UnicodeError, ValueError) as e:
                # a file that can't be read as text: that script stays unmerged, the rest go on
                self._drop_output(out)
                record.update(status="failed", reason=f"a copy of it isn't readable text ({e.__class__.__name__})")
                merges[key] = record
                continue
            if base_bytes is None:
                # a new script, not a vanilla one: nothing to merge against. Identical copies
                # (shared utility scripts) are fine; differing ones mean the top mod's wins.
                texts = {tuple(_norm(decode_script(b)[0])) for b in blobs}
                record.update(status="same" if len(texts) == 1 else "nobase")
                self._drop_output(out)
            else:
                base_lines, base_fmt = decode_script(base_bytes)
                decoded = [decode_script(b) for b in blobs]
                # copies made for another game version: only their own changes are merged (see rebase_on)
                gv = self.game_file_versions("script", rel)
                try:
                    true_rel = base_path.relative_to(vanilla).as_posix()   # the game's own spelling
                except ValueError:
                    true_rel = rel
                rebased = []
                for i, b in enumerate(blobs):
                    hit = self._bring_up("script", true_rel, base_lines, decoded[i][0], b, gv)
                    if hit:
                        decoded[i] = (hit[0], decoded[i][1])
                        rebased.append([sources[i][0], hit[1]])
                result = merge_script(base_lines, [(s[0], d[0]) for s, d in zip(sources, decoded)],
                                      resolutions, key)
                if rebased and result["status"] in ("same", "superset"):
                    # the top mod's own file still has the old version's lines: write the brought-up copy
                    result = {**result, "status": "merged",
                              "lines": result.get("lines") or list(decoded[result.get("winner_index") or 0][0])}
                record["rebased"] = rebased
                record["unchanged"] = [i for i, d in enumerate(decoded) if _same_as_game(d[0], base_lines)]
                self._keep_details(key, recipe, {**result, "rel": rel, "key": key, "base_lines": base_lines,
                                                 "versions": [(s[0], d[0]) for s, d in zip(sources, decoded)],
                                                 "labels": [s[0] for s in sources], "owners": [s[3] for s in sources]})
                status = result["status"]
                open_items = [it["key"] for it in result.get("items", []) if it["resolution"] is None]
                in_items = {m for it in result.get("items", []) for v in it["variants"] for m in v["mods"]}
                record.update(status=status, reason=result.get("reason", ""), auto=result.get("auto", 0),
                              pending=len(open_items), pending_keys=open_items,
                              involved=[s[3] for s in sources if s[3] and s[0] in in_items],
                              items=len(result.get("items", [])), winner=result.get("winner", ""),
                              shared=result.get("shared", []),
                              decided=[[it["key"], sorted({m for v in it["variants"] for m in v["mods"]})]
                                       for it in result.get("items", []) if it["resolution"] is not None])
                if status == "merged" or (status == "superset" and result.get("winner_index")):
                    data = encode_script_safely(result["lines"], output_formats(result["lines"], base_fmt, decoded))
                    self._write_output(out, data)
                else:
                    record["topwins"] = status == "superset"
                    self._drop_output(out)
            merges[key] = record

        for key in [k for k in merges if k not in inputs and not k.startswith((XML_KEY, INI_KEY))]:
            self._drop_output(self.merged_path(merges[key]["rel"]))     # no longer shared by two mods
            del merges[key]
        x = time.perf_counter()
        self._update_xml_merges(merges, resolutions)
        self._update_ini_merges(merges)
        self._merge_parts = [("merge XML", time.perf_counter() - x)]
        self._shadow_legacy(legacy_info, inputs, vanilla)
        self._prune_empty(self.merged_dir)

    # --- .ini files in bin/ (rendering.ini, a plugin's settings…): merged key by key (ini_merge)
    def _ini_inputs(self):
        """{key: {'rel', 'sources': [(label, path, mod id, mod id)]}} for every .ini in bin/ that a
        loaded mod ships and the game has too (so what you set in the game's copy is kept), or that
        two or more mods ship. Top priority first."""
        rem = self.remastered()
        found = {}
        for mod in self.ranked:
            if not mod["enabled"]:
                continue
            for rel in self.mod_files(mod):
                low = rel.lower()
                if not (low.startswith("bin/") and low.endswith(".ini")) or (rem and low.startswith("bin/x64/")):
                    continue
                entry = found.setdefault(INI_KEY + low, {"rel": rel, "sources": []})
                entry["sources"].append((mod["name"], self.stage_dir(mod) / rel, mod["id"], mod["id"]))
        out = {}
        for key, entry in found.items():
            if len(entry["sources"]) > 1 or self._vanilla_file(entry["rel"]) is not None:
                entry["sources"] = self._unique_labels(entry["sources"])
                out[key] = entry
        return out

    def _ini_yours(self, rel):
        """{id: line}: keys you edited in a merged .ini after it was placed."""
        return {(x[0], x[1], x[2]): x[3] for x in self.state.get("ini_yours", {}).get(rel.lower(), [])}

    def _update_ini_merges(self, merges):
        inputs = self._ini_inputs()
        for key, entry in inputs.items():
            rel, sources = entry["rel"], entry["sources"]
            out = self.merged_dir / rel
            head = {"rel": rel, "kind": "ini", "mods": [s[3] for s in sources if s[3]],
                    "labels": [s[0] for s in sources], "owners": [s[3] for s in sources],
                    "reason": "", "pending": 0, "auto": 0, "legacy": False}
            try:
                base_path = self._vanilla_file(rel)
                base_bytes = base_path.read_bytes() if base_path else None
                blobs = [s[1].read_bytes() for s in sources]
            except OSError as e:
                self._drop_output(out)
                merges[key] = {**head, "status": "failed", "reason": f"couldn't read: {e}", "recipe": None}
                continue
            old = merges.get(key)
            try:
                base_lines, base_fmt = decode_script(base_bytes) if base_bytes is not None else (None, None)
                decoded = [decode_script(b) for b in blobs]
            except (UnicodeError, ValueError) as e:
                self._drop_output(out)
                merges[key] = {**head, "status": "failed", "recipe": None,
                               "reason": f"a copy of it isn't readable text ({e.__class__.__name__})"}
                continue
            versions = [(s[0], d[0]) for s, d in zip(sources, decoded)]
            try:
                now = out.read_bytes() if out.is_file() else None
            except OSError:
                now = None
            if now is not None and old and old.get("out_sha") and _sha(now) != old["out_sha"]:
                # edited in the game (the placed file is ours, linked): what it was, against what it is
                was = ini_merge(base_lines, versions, self._ini_yours(rel))[0]
                self._ini_capture_lines(rel, was, decode_script(now)[0])
            yours = self._ini_yours(rel)
            recipe = [INI_ENGINE, _sha(base_bytes) if base_bytes is not None else None,
                      [[s[2], _sha(b)] for s, b in zip(sources, blobs)], _sha(repr(sorted(yours.items())))]
            if old and old.get("recipe") == recipe and now is not None and _sha(now) == old.get("out_sha"):
                continue                                         # nothing it depends on changed
            lines, used, conflicts, unchanged = ini_merge(base_lines, versions, yours)
            fmt = base_fmt or decoded[0][1]
            data = encode_script_safely(lines, output_formats(lines, fmt, decoded))
            self._write_output(out, data)
            merges[key] = {**head, "status": "merged", "recipe": recipe, "unchanged": unchanged, "out_sha": _sha(data),
                           "used": {label: len(ids) for label, ids in used.items()},
                           "conflicts": [[list(eid), winner, others, shown] for eid, winner, others, shown in conflicts]}
        for key in [k for k in merges if k.startswith(INI_KEY) and k not in inputs]:
            rec = merges.pop(key)
            self._drop_output(self.merged_dir / rec["rel"])
            # what you edited in it stays in the game's own copy once no mod is merged into it
            mine = self.state.get("ini_yours", {}).pop(rec["rel"].lower(), None)
            if mine:
                self._ini_into_original(rec["rel"], {(x[0], x[1], x[2]): x[3] for x in mine})

    def _ini_into_original(self, rel, yours):
        """Write your own edits into the game's copy of an .ini (the one set aside while a merge
        is placed, or the one in the game)."""
        path = self._vanilla_file(rel)
        if path is None:
            return
        try:
            lines, fmt = decode_script(path.read_bytes())
        except (OSError, UnicodeError, ValueError):
            return
        new, _u, _c, _n = ini_merge(lines, [], yours)
        if new != lines:
            self._write_output(path, encode_script_safely(new, [fmt]))

    def _ini_capture(self, actual, dst):
        """You edited a merged .ini in the game (saved as a new file): see _ini_capture_lines."""
        try:
            ours = decode_script((self.merged_dir / actual).read_bytes())[0]
            edited = decode_script(dst.read_bytes())[0]
        except (OSError, UnicodeError, ValueError):
            return False
        self._ini_capture_lines(actual, ours, edited)
        return True

    def _ini_capture_lines(self, rel, ours, edited):
        """The keys you changed in a merged .ini are kept as yours: they win over every mod's, and
        stay in the game's own copy when the mods go."""
        before = {e[2]: e[3] for e in _ini_entries(ours) if e[2] is not None}
        mine = self._ini_yours(rel)
        for i, _sec, eid, value in _ini_entries(edited):
            if eid is not None and (eid not in before or before[eid] != value):
                mine[eid] = edited[i].strip()
        self.state.setdefault("ini_yours", {})[rel.lower()] = [[*eid, line] for eid, line in mine.items()]

    # --- loose XML in bin/ (keybind and menu files: input.xml, hidden.xml…), and XML packed in
    # mods' bundles (item, ability, loot tables…)
    def _xml_inputs(self):
        return self._scanned("xml", self._scan_xml)

    def _scan_xml(self):
        """{key: {'rel', 'packed', 'sources': [(label, where, vkey, mod id or None)]}} for every XML
        file two or more loaded mods ship, top priority first. 'where' is a path for a loose file,
        (bundle, table row) for a packed one."""
        found = {}
        for mod in self.ranked:
            if not mod["enabled"]:
                continue
            for rel in self.live_files(mod):
                low = rel.lower()
                if low.startswith("bin/") and low.endswith(".xml"):
                    entry = found.setdefault(XML_KEY + low, {"rel": rel, "packed": False, "sources": []})
                    entry["sources"].append((mod["name"], self.stage_dir(mod) / rel, mod["id"], mod["id"]))
            if self.snippet_on(mod, "input_xml") and mod.get("input_xml"):
                rel = INPUT_XML
                entry = found.setdefault(XML_KEY + rel.lower(), {"rel": rel, "packed": False, "sources": []})
                entry["sources"].append((mod["name"], ("snippet", tuple(mod["input_xml"])),
                                         mod["id"] + ":readme", mod["id"]))
        for folder in self._packed_folders():
            label, vkey, mid = folder["label"], folder["vkey"], folder["mid"]
            for path, where in self._folder_xml(folder["path"]).items():
                entry = found.setdefault(XML_KEY + path, {"rel": path, "packed": True, "sources": [],
                                                          "folders": {}})
                entry["sources"].append((label, where, vkey, mid))
                entry["folders"][vkey] = folder["path"]
        # merged when two or more copies meet — or when a copy comes from a readme only: then no mod
        # has a file of it, and the merge is what puts it in the game
        out = {k: v for k, v in found.items() if len(v["sources"]) > 1 or any(_from_readme(s) for s in v["sources"])}
        for v in out.values():
            v["sources"] = self._unique_labels(v["sources"])
        return out

    def _packed_folders(self):
        """Every mods/ folder the game loads, top priority first: [{'path', 'label', 'vkey', 'mid'}].
        Unmanaged ones count too; Script Merger's folder and ours don't (they're merges already)."""
        rows = self.settings_rows()
        rank = {n.lower(): i for i, (n, _e, _mid) in enumerate(rows)}
        out, seen = [], set()
        for mod in self.ranked:
            if not mod["enabled"]:
                continue
            names = [t.split("/", 1)[1] for t in mod["targets"] if t.lower().startswith("mods/")]
            names = [n for n in names if (self.stage_dir(mod) / "mods" / n).is_dir()]
            for n in names:
                label = mod["name"] if len(names) == 1 else module_name(n, mod["name"])
                out.append({"path": self.stage_dir(mod) / "mods" / n, "label": label,
                            "vkey": f"{mod['id']}/{n}", "mid": mod["id"], "low": n.lower()})
                seen.add(n.lower())
        deployed = {a.split("/")[1].lower() for a in self.state.get("deployed", {})
                    if a.lower().startswith("mods/") and a.count("/") > 1}
        skip = self._managed_folders() | deployed | seen | {MERGED_NAME, AUTO_MERGE_NAME.lower()}
        mods_dir = ci_child(self.game, "mods")
        for n, en, mid in rows:
            if mid is None and en != "0" and n.lower() not in skip and mods_dir:
                d = ci_child(mods_dir, n)
                if d and d.is_dir():
                    out.append({"path": d, "label": f"{n} (not managed here)",
                                "vkey": f"unmanaged/{n.lower()}", "mid": None, "low": n.lower()})
        out.sort(key=lambda f: rank.get(f["low"], len(rank)))
        return out

    def _folder_xml(self, folder):
        """{in-game path: (bundle, table row)} for the XML packed in one mod folder's bundles."""
        return self._scanned(("folder_xml", str(folder)), lambda: self._scan_folder_xml(folder))

    @staticmethod
    def _scan_folder_xml(folder):
        out = {}
        content = ci_child(folder, "content")
        if not content or not content.is_dir():
            return out
        bundles = []
        for dp, _dn, files in os.walk(content):
            bundles += [Path(dp, f) for f in files if f.lower().endswith(".bundle")]
        for b in sorted(bundles, key=lambda p: str(p).lower()):
            for e in bundle_toc(b):
                if e[0].endswith(".xml") and e[0] not in out:
                    out[e[0]] = (b, e)
        return out

    def _game_bundles(self):
        """The game's own bundles (content/ and its DLC), as they are when no mod is deployed."""
        return self._scanned("game_bundles", self._scan_game_bundles)

    def _scan_game_bundles(self):
        out = []
        tops = [ci_child(self.game, "content")]
        dlc = ci_child(self.game, "dlc")
        tops += [d for d in kids(dlc) if d.is_dir() and GAME_DLC.match(d.name)] if dlc else []
        deployed = {a.lower(): a for a in self.state.get("deployed", {})}
        for top in tops:
            if not top or not top.is_dir():
                continue
            for dp, _dn, files in os.walk(top):
                for f in sorted(files):
                    if f.lower().endswith(".bundle"):
                        path = Path(dp, f)
                        rel = path.relative_to(self.game).as_posix()
                        if rel.lower() in deployed:          # one of ours is in its place
                            path = self.backup / deployed[rel.lower()]
                            if not path.is_file():
                                continue
                        out.append(path)
        return out

    @staticmethod
    def folder_game_copies(folder, packed_xml=None):
        """Copies of game files in one mod folder that tell a game version: [(kind, game path,
        the versions it matches)]. kind 'script' (content/scripts/…) or 'xml' (packed XML).
        packed_xml: {path: (bundle, row)} when already read, else the bundles are read here."""
        out = []
        fp = fingerprints()
        content = ci_child(Path(folder), "content")
        scripts = ci_child(content, "scripts") if content else None
        if scripts and scripts.is_dir():
            for dp, _dn, files in os.walk(scripts):
                for f in files:
                    if not f.lower().endswith(".ws"):
                        continue
                    rel = Path(dp, f).relative_to(scripts).as_posix()
                    if rel.lower() in fp["script"]:
                        try:
                            found = file_versions("script", rel, Path(dp, f).read_bytes())
                        except OSError:
                            found = None
                        if found:
                            out.append(("script", rel, found))
        packed = {}
        if content and content.is_dir():
            for dp, _dn, files in os.walk(content):
                for f in sorted(files):
                    if f.lower().endswith(".bundle"):
                        for e in bundle_toc(Path(dp, f)):
                            if e[0].endswith((".xml", ".csv")) and e[0] not in packed:
                                packed[e[0]] = (Path(dp, f), e)
        for rel, (bundle, row) in packed.items():
            kind = "xml" if rel.endswith(".xml") else "csv"
            if rel.lower() in fp[kind]:
                try:
                    found = file_versions(kind, rel, bundle_read(bundle, row))
                except (OSError, ValueError, zlib.error):
                    found = None
                if found:
                    out.append((kind, rel, found))
        return out

    @staticmethod
    def folder_ui_files(folder):
        """The UI files next-gen changed that one mod folder replaces, and the oldest date among
        the bundles holding them (archives keep their files' dates): (paths, date or None)."""
        content = ci_child(Path(folder), "content")
        found, dates = set(), []
        if content and content.is_dir():
            for dp, _dn, files in os.walk(content):
                for f in files:
                    if f.lower().endswith(".bundle"):
                        hit = bundle_entries(Path(dp, f)) & NG_CHANGED_UI
                        if hit:
                            found |= hit
                            try:
                                dates.append(Path(dp, f).stat().st_mtime)
                            except OSError:
                                pass
        return sorted(found), (min(dates) if dates else None)

    @staticmethod
    def remaster_scan(stage):
        """What in a mod's stored files was made for 4.x and needs something on 5.x:
        utf16     loose text files (.ws .xml .csv) in UTF-16 — the app places UTF-8 copies
        packed16  XML / CSV packed in its bundles in UTF-16 — the game can't read them
        srt       packed SpeedTree files without the header 5.00 added (they start "SRT ")
        strings16 .w3strings in the layout up to 4.x (see w3strings_format) — 5.00 can't read them
        cache16   collision.cache in an older layout than 5.00's (see collision_cache_format), and
                  cache16_from which one: "1.x" or "4.x"
        rebuild   collision.cache, soundspc.cache, and .w3strings whose layout can't be told —
                  formats 5.00 changed: made before 5.00 (by their dates), they don't load
        ui        packed UI files 5.00 changed
        dates     the oldest date of the files in rebuild and ui (archives keep files' dates)"""
        out = {"utf16": [], "packed16": [], "srt": [], "strings16": [], "cache16": [], "rebuild": [], "ui": [],
               "dx11": [], "files": 0, "date": None, "rsblob_build": None}
        stage = Path(stage)
        dates = []
        for dp, _dn, files in os.walk(stage):
            for f in files:
                path = Path(dp, f)
                low = f.lower()
                rel = path.relative_to(stage).as_posix()
                out["files"] += 1
                if rel.lower().startswith("bin/x64/"):
                    out["dx11"].append(rel)              # for the DX11 build: 5.00 has none
                elif low.endswith(TEXT_EXTS_UTF8):
                    try:
                        with open(path, "rb") as fh:
                            if is_utf16(fh.read(64)):
                                out["utf16"].append(rel)
                    except OSError:
                        pass
                elif low.endswith(".w3strings") and w3strings_file_format(path) is not None:
                    if w3strings_file_format(path) == "4.x":
                        out["strings16"].append(rel)  # its own layout says it: no date needed
                elif low.endswith(".rsblob"):
                    build = rsblob_build(path)        # compiled by REDkit: which one says which game
                    if build and build > (out["rsblob_build"] or 0):
                        out["rsblob_build"] = build
                elif low == "collision.cache" and collision_cache_format(path) is not None:
                    fmt = collision_cache_format(path)
                    if fmt in ("1.x", "4.x"):
                        out["cache16"].append(rel)    # its own header says it: no date needed
                        out.setdefault("cache16_from", {})[rel] = fmt
                elif low in REBUILD_NAMES or low.endswith(".w3strings"):
                    out["rebuild"].append(rel)
                    try:
                        dates.append(path.stat().st_mtime)
                    except OSError:
                        pass
                elif low.endswith(".bundle"):
                    ui_hit = False
                    for e in bundle_toc(path):
                        name = e[0]
                        try:
                            if name.endswith((".xml", ".csv")):
                                if is_utf16(bundle_peek(path, e, 64)):
                                    out["packed16"].append(name)
                            elif name.endswith(".srt"):
                                if bundle_peek(path, e, 4) == b"SRT ":
                                    out["srt"].append(name)
                        except (OSError, ValueError, zlib.error, IndexError):
                            pass
                        if name in REM_CHANGED_UI:
                            out["ui"].append(name)
                            ui_hit = True
                    if ui_hit:
                        try:
                            dates.append(path.stat().st_mtime)
                        except OSError:
                            pass
        for k in ("utf16", "packed16", "srt", "strings16", "cache16", "rebuild", "ui", "dx11"):
            out[k] = sorted(set(out[k]))
        out["date"] = min(dates) if dates else None
        return out

    def game_version(self):
        """Your game's version, from all its scripts that changed between patches together (one
        file alone often can't tell two patches apart): a list of names, usually just one.
        Worked out once per sync: the game doesn't change under the app between two."""
        return self._scanned("game_version", self._work_out_game_version)

    def _work_out_game_version(self):
        memo = self.__dict__.setdefault("_game_fp", {})
        store = self._gv_store()
        if not (isinstance(store.get("scripts"), list) and all(isinstance(r, str) for r in store["scripts"])):
            # which scripts tell versions apart, kept too: unpacking the whole table only to list
            # them took longer than looking at them all
            with _GV_LOCK:
                store["scripts"] = list(fingerprints()["script"])
                self._gv_dirty = True
        found_all = [self.game_file_versions("script", rel) for rel in store["scripts"]]
        key = hash(tuple(tuple(f) if f else () for f in found_all))
        if memo.get("__game__", (None,))[0] != key:
            common = None
            for found in found_all:
                if found:
                    common = set(found) if common is None else (common & set(found) or common)
            memo["__game__"] = (key, [v for v in SCRIPT_GAME_VERSIONS if v in (common or ())])
        self.save_game_versions()
        return memo["__game__"][1]

    # --- what each of the game's own files was found to be, kept between starts in
    # game_versions.json: a file is read again when its size, modified time or change time differ
    # (a game update rewrites it, and no tool can set the change time back), or when the
    # fingerprint table changed. The times only say "read it again", never what version a file
    # is. A missing or damaged game_versions.json just means everything is read again.
    GV_FILE_REV = 1

    def _gv_key(self):
        global _FP_TAG
        if _FP_TAG is None:
            _FP_TAG = hashlib.sha1(_FP_DATA.encode()).hexdigest()[:12]
        return f"{self.GV_FILE_REV}:{FP_REV}:{_FP_TAG}"

    def _gv_store(self):
        store = self.__dict__.get("_gv")
        if store is None:
            key = self._gv_key()
            try:
                store = json.loads((self.root / GAME_VERSIONS_FILE).read_text(encoding="utf-8"))
                if not (isinstance(store, dict) and store.get("key") == key
                        and isinstance(store.get("script"), dict) and isinstance(store.get("packed"), dict)):
                    store = None
            except (OSError, ValueError):
                store = None
            if store is None:
                store = {"key": key, "script": {}, "packed_sig": None, "packed": {}}
                self._gv_dirty = True
            self._gv = store
        return store

    def save_game_versions(self):
        """Write game_versions.json if anything new was worked out."""
        if not self.__dict__.get("_gv_dirty") or self.__dict__.get("_gv") is None:
            return
        with _GV_LOCK:
            text = json.dumps(self._gv, separators=(",", ":"))
            self._gv_dirty = False
        path = self.root / GAME_VERSIONS_FILE
        tmp = path.with_name(path.name + ".tmp")
        try:
            tmp.write_text(text, encoding="utf-8")
            os.replace(tmp, path)
        except OSError:
            tmp.unlink(missing_ok=True)

    @staticmethod
    def _gv_found(v):
        """A kept answer as the app uses it, or False when it isn't one (damaged by hand)."""
        if v is None:
            return None
        if isinstance(v, list) and all(isinstance(x, str) for x in v):
            return v
        return False

    def _game_bundle_stats(self):
        def stats():
            sig = []
            for b in self._game_bundles():
                try:
                    st = b.stat()
                    sig.append((str(b), st.st_size, st.st_mtime_ns, st.st_ctime_ns))
                except OSError:
                    pass
            return sig
        return self._scanned("game_bundle_stats", stats)

    def game_file_versions(self, kind, rel):
        """Which versions your installed game's own copy of a file matches (None: can't tell)."""
        rel = rel.lower()
        store = self._gv_store()
        if kind == "script":
            # the scripts' real spelling ("ingameMenu.ws") from listings kept for the sync: looking
            # each one up by itself listed whole folders, hundreds of times per redraw
            path = self._scanned("game_scripts_ci", lambda: CIResolver(self.game)).resolve_text(f"{VANILLA_SCRIPTS}/{rel}")
            try:
                st = os.stat(path)
            except OSError:
                return None
            stamp = [st.st_size, st.st_mtime_ns, st.st_ctime_ns]
            kept = store["script"].get(rel)
            if isinstance(kept, list) and len(kept) == 4 and kept[:3] == stamp:
                found = self._gv_found(kept[3])
                if found is not False:
                    return found
            try:
                with open(path, "rb") as f:
                    found = file_versions(kind, rel, f.read(), strict=True)
            except (OSError, ValueError, zlib.error):
                return None                       # not kept: tried again next time
            with _GV_LOCK:
                store["script"][rel] = stamp + [found]
                self._gv_dirty = True
            return found
        # packed (XML, CSV): kept for as long as none of the game's bundles changed, so the
        # bundles' tables aren't read at all when nothing did
        bsig = self._scanned("game_bundle_sig", lambda: hashlib.sha1(
            json.dumps(self._game_bundle_stats()).encode()).hexdigest()[:16])
        pkey = f"{kind}:{rel}"
        if store.get("packed_sig") != bsig:
            with _GV_LOCK:
                store["packed_sig"], store["packed"] = bsig, {}
                self._gv_dirty = True
        if pkey in store["packed"]:
            found = self._gv_found(store["packed"][pkey])
            if found is not False:
                return found
        try:
            hit = self._vanilla_packed(rel)
            found = file_versions(kind, rel, bundle_read(*hit), strict=True) if hit else None
        except (OSError, ValueError, zlib.error):
            return None
        with _GV_LOCK:
            store["packed"][pkey] = found
            self._gv_dirty = True
        return found

    def made_for(self, mod):
        """What game version a mod's copies of game files come from, next to your game's:
        {'files': [(kind, path, its versions, your game's versions, older|newer|same|None)],
         'label': the versions it was made for, 'status': 'classic' | 'older' | 'newer' | '' }.
        Worked out once per install (kept with the mod) — only your game's side is looked up."""
        stamp = [FP_REV, mod.get("installed", 0), REM_SCAN_REV]
        rec = mod.get("made_for")
        if not rec or rec.get("stamp") != stamp:
            files, ui, ui_date = [], [], None
            for t in mod["targets"]:
                if t.lower().startswith("mods/"):
                    folder = self.stage_dir(mod) / "mods" / t.split("/", 1)[1]
                    if folder.is_dir():
                        files += [[k, r, v] for k, r, v in self.folder_game_copies(folder, self._folder_xml(folder))]
                        paths, date = self.folder_ui_files(folder)
                        ui += paths
                        if date and (ui_date is None or date < ui_date):
                            ui_date = date
            rec = mod["made_for"] = {"stamp": stamp, "files": files, "ui": ui, "ui_date": ui_date,
                                     "rem": self.remaster_scan(self.stage_dir(mod))}
            self._made_for_dirty = True
        report = compare_made_for(rec["files"], self.game_file_versions)
        gen = self.generation()
        next_gen = gen in ("ng", "rem")
        # UI files next-gen changed, in a mod from before next-gen: by its Nexus file's upload date
        # only. The files' own dates in an archive are whatever the author's tools left (a mod made
        # with early tools, a repack…), too unreliable to call a mod broken by
        report["ui"] = None
        if next_gen and rec.get("ui"):
            page = self.state.get("nexus_cache", {}).get(str(mod.get("nexus") or "")) or {}
            got = self.nexus_file_of(mod, page) if page else None
            when, how = (got[0].get("at"), "uploaded to Nexus") if got and got[0].get("at") else (None, "")
            if when and when < NEXT_GEN_RELEASE:
                report["ui"] = {"files": rec["ui"], "date": when, "how": how}
                if not report["status"]:
                    report["status"] = "classic"
                if not report["label"]:
                    report["label"], report["short"] = "1.32 or earlier", "1.32"
        # on 5.x: what in it was made for 4.x (see remaster_scan)
        report["rem"] = None
        if gen == "rem":
            scan = rec.get("rem") or {}
            page = self.state.get("nexus_cache", {}).get(str(mod.get("nexus") or "")) or {}
            got = self.nexus_file_of(mod, page) if page else None
            # caches and UI files can't be told old or new by what's in them (yet): only the Nexus
            # upload date of the mod's file says they're from before 5.00, never the files' dates
            when, how = (got[0].get("at"), "uploaded to Nexus") if got and got[0].get("at") else (None, "")
            # the game version its own info file says it's for, when it has one
            declared = (mod.get("mod_info") or {}).get("game") or []
            for_rem = any(version_generation(v) >= 5 for v in declared) \
                or (scan.get("rsblob_build") or 0) >= REDKIT_5_BUILD    # compiled by REDkit 5: for 5.x
            # dates only count when nothing better says it's for 5.x
            old = bool(when and when < REMASTER_RELEASE) and not for_rem
            r = {"utf16": scan.get("utf16", []), "packed16": scan.get("packed16", []), "srt": scan.get("srt", []),
                 "strings16": scan.get("strings16", []), "cache16": scan.get("cache16", []),
                 "cache16_from": scan.get("cache16_from", {}),
                 "rebuild": scan.get("rebuild", []) if old else [], "ui": scan.get("ui", []) if old else [],
                 "dx11": scan.get("dx11", []), "date": when, "how": how}
            broken = r["packed16"] or r["srt"] or r["strings16"] or r["cache16"] or r["rebuild"] or r["ui"]
            only_dx11 = bool(r["dx11"]) and len(r["dx11"]) == scan.get("files", 0)
            # UTF-16 text needs nothing from you (the game gets UTF-8 copies), so it never
            # raises a status; only files that won't work, or a mod that is all DX11, do
            if broken or only_dx11:
                report["status"] = "classic"
                only_cache = bool(r["cache16"]) and not (r["packed16"] or r["srt"] or r["strings16"]
                                                         or r["rebuild"] or r["ui"] or only_dx11)
                if not any(f[4] == "older" for f in report["files"]):
                    only_classic = only_cache and set(r["cache16_from"].values()) == {"1.x"}
                    report["label"], report["short"] = ("1.32 or earlier", "1.32") if only_classic else ("4.x", "4.x")
                    # only an old collision.cache: the rest of the mod works and nothing breaks, so
                    # amber, not red (red is for mods that break the game or don't work)
                    report["mild"] = only_cache
            if broken or r["dx11"]:
                report["rem"] = r
            if report["status"] == "classic" and version_generation(report["short"]) == 4:
                report["short"] = "4.x"              # the chip: made for the 4.x game (details in its tooltip)
        # the game version its own info file says it's for: a mod for another generation of the game
        declared = (mod.get("mod_info") or {}).get("game") or []
        report["declared"] = declared
        game_gen = {"rem": 5, "ng": 4, "og": 1}.get(gen)
        gens = {version_generation(v) for v in declared} - {0}
        if gens and game_gen and game_gen not in gens and not report["status"]:
            report["status"] = "newer" if min(gens) > game_gen else "older"
            if not report["label"]:
                report["label"] = report["short"] = ", ".join(declared[:2])
        # a mod the game has taken in since
        report["built_in"] = None
        if next_gen:
            page_name = (self.state.get("nexus_cache", {}).get(str(mod.get("nexus") or "")) or {}).get("name", "")
            report["built_in"] = built_in_mod(mod, page_name, remastered=gen == "rem")
        report["game"] = self.game_version() if report["status"] else []    # only asked for when shown
        return report

    def _vanilla_packed(self, path):
        """(bundle, table row) of the game's own copy of a packed file, or None."""
        bundles = self._game_bundles()
        sig = self._game_bundle_stats()
        cache = getattr(self, "_vanilla_index", None)
        if not cache or cache[0] != sig:
            index = {}
            for b in bundles:
                for e in bundle_toc(b):
                    if e[0].endswith((".xml", ".csv")):
                        index.setdefault(e[0], (b, e))
            cache = self._vanilla_index = (sig, index)
        return cache[1].get(path.lower())

    def _xml_source(self, entry, src):
        """The bytes of one mod's copy."""
        where = src[1]
        if _from_readme(src):
            return self._readme_input_xml(entry, where[1])
        return bundle_read(*where) if entry["packed"] else where.read_bytes()

    def _readme_input_xml(self, entry, var_lines):
        """A mod's copy of input.xml as its readme asks for it: the game's own, with the <Var> lines
        added to the key list (after its last input entry), in the file's own format. Lines whose
        id the file already has — pasted by hand, say — aren't added twice."""
        raw = self._xml_base(entry)
        if raw is None:
            raise ValueError("the game's input.xml isn't there")
        lines, fmt = decode_script(raw)
        have = set(re.findall(r'\bid\s*=\s*"([^"]+)"', "\n".join(lines)))
        new = [l for l in var_lines if (re.search(r'\bid\s*=\s*"([^"]+)"', l) or [None, None])[1] not in have]
        if new:
            at = max((i for i, l in enumerate(lines) if INPUT_VAR.match(l) and 'builder="input"' in l.lower()), default=None)
            if at is None:
                at = next((i - 1 for i, l in enumerate(lines) if "</visiblevars>" in l.lower()), None)
            if at is None:
                raise ValueError("couldn't find where input.xml lists its keys")
            ref = lines[at] if at >= 0 else ""
            lead = ref[:len(ref) - len(ref.lstrip())] or "\t\t\t"
            lines[at + 1:at + 1] = [lead + l.strip() for l in new]
        return encode_script_safely(lines, [fmt])

    def _xml_base(self, entry):
        """The game's own copy's bytes, or None."""
        if entry["packed"]:
            hit = self._vanilla_packed(entry["rel"])
            return bundle_read(*hit) if hit else None
        base_path = self._vanilla_file(entry["rel"])
        return base_path.read_bytes() if base_path else None

    def _xml_recipe(self, entry):
        """What a merge depends on, cheaply: packed files by their bundle's table row (its CRC32 is
        of the unpacked file), so nothing is unpacked when nothing changed."""
        if not entry["packed"]:
            return None
        hit = self._vanilla_packed(entry["rel"])
        base = [hit[1][1], hit[1][4]] if hit else None
        # each mod's own new XML counts too: an entry it drops here may be one it moved there
        return [XML_ENGINE, base, [[s[2], s[1][1][1], s[1][1][4],
                                    _sha(repr(sorted((p, w[1][4]) for p, w in
                                                     self._folder_xml(entry["folders"][s[2]]).items())))]
                                   for s in entry["sources"]]]

    def packed_out(self, rel):
        """Where a merged packed file waits to go into our bundle (not deployed itself)."""
        return self.root / "merged_packed" / rel

    def bundle_dir(self):
        return self.merged_dir / "mods" / AUTO_MERGE_NAME / "content"

    def _update_bundle(self):
        """Our bundle + metadata.store, holding every merged packed file — or neither, when
        there's nothing to hold. Rewritten only when what goes in it changes."""
        top = self.root / "merged_packed"
        paths = []
        for dp, _dn, fn in os.walk(top):
            paths += [Path(dp, f) for f in fn if not f.endswith(".tmp")]
        out_b, out_s = self.bundle_dir() / "blob0.bundle", self.bundle_dir() / "metadata.store"
        self._prune_empty(top)
        if not paths:
            self._drop_output(out_b)
            self._drop_output(out_s)
            self.state.pop("bundle_sig", None)
            return
        sig = _sha(repr(sorted((p.relative_to(top).as_posix(), p.stat().st_size, p.stat().st_mtime_ns)
                               for p in paths)))
        if sig == self.state.get("bundle_sig") and out_b.is_file() and out_s.is_file():
            return                                       # nothing in it changed
        data, table = build_bundle([(p.relative_to(top).as_posix(), p.read_bytes()) for p in paths])
        self._write_output(out_b, data)
        self._write_output(out_s, build_store([("blob0.bundle", table)]))
        self.state["bundle_sig"] = sig

    def _vanilla_file(self, rel):
        """The game's own copy of a loose file, set aside while a mod's copy is in its place, or
        what's in the game folder when nothing of ours is there. None when the game has none."""
        low = rel.lower()
        actual = next((a for a in self.state.get("deployed", {}) if a.lower() == low), None)
        if actual is not None:
            b = self.backup / actual
            return b if b.is_file() else None
        path = ci_path(self.game, rel)
        return path if path.is_file() else None

    @staticmethod
    def _xml_text(data):
        """bytes -> (text, format), the way scripts are read (BOM, UTF-16, line endings)."""
        lines, fmt = decode_script(data)
        return "\n".join(lines) + ("\n" if fmt["final"] and lines else ""), fmt

    def _xml_out(self, entry_or_record):
        rel = entry_or_record["rel"]
        return self.packed_out(rel) if entry_or_record.get("packed") else self.merged_dir / rel

    def _bring_up(self, kind, rel, base_lines, mod_lines, mod_data, game_versions):
        """A mod's copy made for another game version, with only its own changes, on your game's
        copy: (lines, how many of its changes fell on lines the game changed too), or None when
        it's made for your version, or the file it was made from can't be had (no connection)."""
        if not game_versions:
            return None
        mine = file_versions(kind, rel, mod_data)
        if not mine or set(mine) & set(game_versions):
            return None
        for v in reversed(mine):                       # the newest it could be for first
            raw = fetch_vanilla(self.root / "vanilla", kind, v, rel)
            if raw is None:
                continue
            try:
                origin = decode_script(raw)[0]
            except (UnicodeError, ValueError):
                continue
            hit = rebase_on(origin, base_lines, mod_lines)
            return hit                                 # None: its changes overlap too tangled to place
        return None

    def _update_xml_merges(self, merges, resolutions):
        inputs = self._xml_inputs()
        for key, entry in inputs.items():
            rel, sources = entry["rel"], entry["sources"]
            out = self._xml_out(entry)
            head = {"rel": rel, "kind": "xml", "packed": entry["packed"],
                    "mods": [s[3] for s in sources if s[3]], "labels": [s[0] for s in sources],
                    "owners": [s[3] for s in sources]}
            old = merges.get(key)
            answered = any(k in resolutions for k in (old or {}).get("pending_keys", ()))
            recipe = self._xml_recipe(entry)            # packed: known without unpacking anything
            if recipe is not None and old and old.get("recipe") == recipe and not answered and "unchanged" in old \
                    and (old["status"] not in ("merged", "superset", "added") or out.is_file() or old.get("topwins")):
                continue
            try:
                base_bytes = self._xml_base(entry)
                blobs = [self._xml_source(entry, s) for s in sources]
            except (OSError, ValueError, zlib.error) as e:
                self._drop_output(out)
                merges[key] = {**head, "status": "failed", "reason": f"couldn't read: {e}", "recipe": None}
                continue
            if recipe is None:
                recipe = [XML_ENGINE, _sha(base_bytes) if base_bytes is not None else None,
                          [[s[2], _sha(b)] for s, b in zip(sources, blobs)]]
            if old and old.get("recipe") == recipe and not answered and "unchanged" in old \
                    and (old["status"] not in ("merged", "superset", "added") or out.is_file() or old.get("topwins")):
                continue                                         # nothing it depends on changed
            record = {**head, "recipe": recipe, "reason": "", "pending": 0, "auto": 0, "legacy": False, "unchanged": []}
            try:
                base = self._xml_text(base_bytes) if base_bytes is not None else None
                decoded = [self._xml_text(b) for b in blobs]
            except (UnicodeError, ValueError) as e:
                self._drop_output(out)
                record.update(status="failed", reason=f"a copy of it isn't readable text ({e.__class__.__name__})")
                merges[key] = record
                continue
            # packed copies made for another game version: only their own changes are merged
            rebased = []
            if base is not None and entry["packed"]:
                gv = self.game_file_versions("xml", rel)
                for i, (src, b) in enumerate(zip(sources, blobs)):
                    if _from_readme(src):
                        continue
                    hit = self._bring_up("xml", rel, base[0].split("\n"), decoded[i][0].split("\n"), b, gv)
                    if hit:
                        decoded[i] = ("\n".join(hit[0]), decoded[i][1])
                        rebased.append([src[0], hit[1]])
            record["rebased"] = rebased
            if base is not None:
                record["unchanged"] = [i for i, (src, d) in enumerate(zip(sources, decoded)) if not _from_readme(src)
                                       and _same_as_game(d[0].split("\n"), base[0].split("\n"))]
            result = xml_merge(base[0] if base else None, [(s[0], d[0]) for s, d in zip(sources, decoded)],
                               resolutions, key, elsewhere=self._moved_finder(entry))
            if rebased and result["status"] in ("same", "superset"):
                # the top copy's own file still has the old version's lines: write the brought-up one
                result = {**result, "status": "merged",
                          "text": result.get("text") or decoded[result.get("winner_index") or 0][0]}
            kept = dict(result)
            self._xml_detail_fields(kept, entry, key, base[0] if base else None,
                                    [(s[0], d[0]) for s, d in zip(sources, decoded)])
            self._keep_details(key, recipe, kept)
            status = result["status"]
            open_items = [it["key"] for it in result.get("items", []) if it["resolution"] is None]
            in_items = {m for it in result.get("items", []) for v in it["variants"] for m in v["mods"]}
            record.update(status=status, reason=result.get("reason", ""), auto=result.get("auto", 0),
                          pending=len(open_items), pending_keys=open_items,
                          involved=[s[3] for s in sources if s[0] in in_items],
                          items=len(result.get("items", [])), winner=result.get("winner", ""), shared=[],
                          moved=result.get("moved", 0),
                              decided=[[it["key"], sorted({m for v in it["variants"] for m in v["mods"]})]
                                       for it in result.get("items", []) if it["resolution"] is not None])
            readme_top = _from_readme(sources[0]) and status in ("superset", "same")
            if readme_top and not any(not _from_readme(s) for s in sources if s[0] == sources[0][0]) \
                    and (status == "same" or not result.get("winner_index")):
                result = {**result, "text": result.get("text") or decoded[0][0]}
                record["status"] = status = "added"            # no file of its own: written here
            if status in ("merged", "added") or (status == "superset" and result.get("winner_index")):
                text = result["text"]
                lines = text.split("\n")
                if lines and lines[-1] == "":
                    lines.pop()
                fmt = (base or decoded[0])[1]
                self._write_output(out, encode_xml_safely(lines, output_formats(lines, fmt, [
                    (t.split("\n"), f) for t, f in decoded])))
            else:
                record["topwins"] = status == "superset"
                self._drop_output(out)
            merges[key] = record
        for key in [k for k in merges if k.startswith(XML_KEY) and k not in inputs]:
            self._drop_output(self._xml_out(merges[key]))
            del merges[key]
        # a merged packed file that's no longer wanted (a crash between steps, an older version)
        wanted = {self._xml_out(r) for r in merges.values() if r.get("packed")}
        for dp, _dn, fn in os.walk(self.root / "merged_packed"):
            for f in fn:
                if Path(dp, f) not in wanted:
                    self._drop_output(Path(dp, f))
        self._update_bundle()

    def _own_xml_keys(self, folder):
        """{in-game path: keyed elements} for the XML files a mod folder packs that the game
        doesn't have (its own new files) — read once per sync, whatever number of merges ask."""
        def make():
            out = {}
            for path, where in self._folder_xml(folder).items():
                # only its own new files: a game file it also ships (items/ next to items_plus/, say)
                # holding the same entry isn't a move
                if self._vanilla_packed(path) is not None:
                    continue
                try:
                    text = self._xml_text(bundle_read(*where))[0]
                except (OSError, ValueError, UnicodeError, zlib.error):
                    continue
                keys = set()
                for m in _XML_START.finditer(text):
                    for name, v1, v2 in _XML_ATTR.findall(m.group(2)):
                        if name in XML_KEYS:
                            keys.add((m.group(1), name, v1 or v2))
                out[path] = keys
            return out
        return self._scanned(("own_xml", str(folder)), make)

    def _moved_finder(self, entry):
        """label -> {(tag, key attribute, value)} of every keyed element in the XML files a mod
        packs that the game doesn't have (its own new files). An entry a mod drops from a game file but has in a file of
        its own was moved there, not removed — keeping the game's copy too would define it twice."""
        if not entry["packed"]:
            return None             # menu files (bin/): the same id in two files is two settings
        folders = {s[0]: entry["folders"][s[2]] for s in entry["sources"]}
        cache = {}

        def find(label):
            if label in cache:
                return cache[label]
            found = set()
            if label in folders:
                own = self._own_xml_keys(folders[label])
                for path, keys in own.items():
                    if path != entry["rel"].lower():
                        found |= keys
            cache[label] = found
            return found
        return find

    def xml_details(self, key):
        """Everything the decisions window needs for one XML file: the sync's result when
        nothing changed since, otherwise computed fresh."""
        entry = self._xml_inputs().get(key)
        if not entry:
            return None
        recipe = self._xml_recipe(entry)
        if recipe is not None:
            kept = self._kept_details(key, recipe)
            if kept is not None:
                return kept
        raw = self._xml_base(entry)
        blobs = [self._xml_source(entry, s) for s in entry["sources"]]
        if recipe is None:
            recipe = [XML_ENGINE, _sha(raw) if raw is not None else None,
                      [[s[2], _sha(b)] for s, b in zip(entry["sources"], blobs)]]
            kept = self._kept_details(key, recipe)
            if kept is not None:
                return kept
        base = self._xml_text(raw)[0] if raw is not None else None
        versions = [(s[0], self._xml_text(b)[0]) for s, b in zip(entry["sources"], blobs)]
        result = xml_merge(base, versions, self.state.get("resolutions", {}), key,
                           elsewhere=self._moved_finder(entry))
        self._xml_detail_fields(result, entry, key, base, versions)
        self._keep_details(key, recipe, result)
        return result

    @staticmethod
    def _xml_detail_fields(result, entry, key, base, versions):
        result.update(rel=entry["rel"], key=key, lang="xml", packed=entry["packed"],
                      base_lines=base.split("\n") if base is not None else [],
                      versions=[(l, t.split("\n")) for l, t in versions],
                      labels=[s[0] for s in entry["sources"]], owners=[s[3] for s in entry["sources"]])

    # --- Script Merger's own folder (mod0000_MergedFiles)
    def _legacy_scan(self):
        """Script Merger's output folder, if there is one, and what to do about it:
          'off'      it holds nothing but scripts, which are merged here now: switched off in
                     mods.settings (never deleted), so there's one merge, not two
          'shadow'   it also holds files other than scripts, so switching it off would drop them: it stays
                     on for those — but every script in it is overridden by ours
        Without a prefix mods.settings can't be written, so switching off isn't possible there."""
        mods_dir = ci_child(self.game, "mods")
        folder = ci_child(mods_dir, "mod0000_MergedFiles") if mods_dir else None
        if not folder or not folder.is_dir():
            self.state.pop("legacy", None)
            return None
        scripts, other = {}, 0
        root = ci_path(folder, "content/scripts")
        for dp, _dn, files in os.walk(folder):
            for f in files:
                path = Path(dp, f)
                if f.lower().endswith(".ws") and root in path.parents:
                    rel = path.relative_to(root).as_posix()
                    scripts[rel.lower()] = rel
                else:
                    other += 1
        mode = "shadow" if other or self.settings_dir() is None else "off"
        info = {"folder": folder.name, "mode": mode, "scripts": scripts, "other": other}
        self.state["legacy"] = {"folder": folder.name, "mode": mode, "scripts": len(scripts), "other": other}
        return info

    def _shadow_legacy(self, info, inputs, vanilla):
        """While Script Merger's folder stays on, give each of its scripts a copy in ours —
        the merge, or else whatever the game would load without it — so an out-of-date
        merge from it can never win. Copies go again as soon as they're not needed."""
        merges = self.state.get("merges", {})

        def has_merge(key):
            rec = merges.get(key)
            return bool(rec and (rec["status"] == "merged"
                                 or (rec["status"] == "superset" and not rec.get("topwins"))))
        wanted = {}
        if info and info["mode"] == "shadow":
            shipped = None
            for key, rel in info["scripts"].items():
                if has_merge(key):
                    continue                                     # our merge is already there
                if key in inputs:
                    src = inputs[key]["sources"][0][1]           # the top mod's copy
                else:
                    if shipped is None:
                        shipped = self._script_inputs(everything=True)
                    if key in shipped:
                        src = shipped[key]["sources"][0][1]
                    else:
                        src = ci_path(vanilla, rel)
                try:
                    data = src.read_bytes() if src.is_file() else b""   # a script nobody ships now: empty
                except OSError:
                    continue
                wanted[key] = (rel, data)
        old = self.state.get("shadowed", {})
        for key, rel in old.items():
            if key not in wanted and not has_merge(key):
                self._drop_output(self.merged_path(rel))
        for key, (rel, data) in wanted.items():
            self._write_output(self.merged_path(rel), data)
        if wanted:
            self.state["shadowed"] = {k: rel for k, (rel, _d) in wanted.items()}
        else:
            self.state.pop("shadowed", None)

    def _write_output(self, path, data):
        """Atomic, and untouched when the content is already right — so an unchanged merged
        script keeps its identity and nothing downstream has to redeploy it."""
        try:
            if path.is_file() and path.read_bytes() == data:
                return
        except OSError:
            pass
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(path.name + ".tmp")
        tmp.write_bytes(data)
        os.replace(tmp, path)

    def _drop_output(self, path):
        try:
            path.unlink()
        except FileNotFoundError:
            pass

    @staticmethod
    def _prune_empty(top):
        if not Path(top).is_dir():
            return
        for dp, _dn, _fn in sorted(os.walk(top), key=lambda t: -len(t[0])):
            if Path(dp) != Path(top):
                try:
                    os.rmdir(dp)
                except OSError:
                    pass

    def _keep_details(self, key, recipe, details):
        """Remember a merge's full result, with the answers it was made with."""
        self.__dict__.setdefault("_details", {})[key] = (
            json.dumps(recipe), {it["key"]: it["resolution"] for it in details.get("items", [])}, details)

    def _kept_details(self, key, recipe):
        """A merge's result from earlier, if nothing it depends on has changed since: the same
        inputs (recipe) and the same answers for its decisions. Merging is the slow part."""
        hit = self.__dict__.get("_details", {}).get(key)
        if not hit or hit[0] != json.dumps(recipe):
            return None
        res = self.state.get("resolutions", {})
        if any(res.get(k) != v for k, v in hit[1].items()):
            return None
        return hit[2]

    def merge_details(self, key):
        """Everything the resolver needs for one script: the sync's result when nothing changed
        since, otherwise computed fresh."""
        if key.startswith(XML_KEY):
            return self.xml_details(key)
        entry = self._script_inputs().get(key)
        if not entry:
            return None
        base_path = ci_path(ci_path(self.game, VANILLA_SCRIPTS), entry["rel"])
        if not base_path.is_file():
            return None
        base_bytes = base_path.read_bytes()
        blobs = [s[1].read_bytes() for s in entry["sources"]]
        recipe = [MERGE_ENGINE, _sha(base_bytes), [[s[2], _sha(b)] for s, b in zip(entry["sources"], blobs)]]
        kept = self._kept_details(key, recipe)
        if kept is not None:
            return kept
        base_lines, _fmt = decode_script(base_bytes)
        versions = [(s[0], decode_script(b)[0]) for s, b in zip(entry["sources"], blobs)]
        result = merge_script(base_lines, versions, self.state.get("resolutions", {}), key)
        result.update(rel=entry["rel"], key=key, base_lines=base_lines, versions=versions,
                      labels=[s[0] for s in entry["sources"]], owners=[s[3] for s in entry["sources"]])
        self._keep_details(key, recipe, result)
        return result

    def save_resolutions(self, key, answers):
        """answers: {item key: [lines]}. Stored by content, so they survive removing and
        re-adding a mod, or reordering — and only come back up if those lines change."""
        res = self.state.setdefault("resolutions", {})
        res.update({k: list(v) for k, v in answers.items()})
        if key in self.state.get("merges", {}):
            self.state["merges"][key]["recipe"] = None           # rebuild it with the answers
        self.save()

    def forget_resolutions(self, key):
        details = self.merge_details(key)
        if details:
            for it in details.get("items", []):
                self.state.get("resolutions", {}).pop(it["key"], None)
        if key in self.state.get("merges", {}):
            self.state["merges"][key]["recipe"] = None
        self.save()

    def open_decisions(self):
        """{script key: set of undecided spots} — to tell new questions from ones already asked."""
        return {k: set(v.get("pending_keys", ())) for k, v in self.state.get("merges", {}).items()
                if v["status"] == "pending"}

    def pending_merges(self):
        return sorted((k for k, v in self.state.get("merges", {}).items() if v["status"] == "pending"),
                      key=lambda k: self.state["merges"][k]["rel"].lower())

    # --- deploy
    def _scanned(self, key, make):
        """Folder scans that don't change between two syncs, worked out once and reused (the
        list redrawing, merging and the decisions window all need them, often many times)."""
        cache = self.__dict__.setdefault("_scan", {})
        if key not in cache:
            cache[key] = make()
        return cache[key]

    def forget_scans(self):
        self._scan = {}

    def generation(self):
        """game_generation for this game, looked at once per sync (each mod in the list asked
        for it, and each time took a few folder lookups)."""
        return self._scanned("generation", lambda: game_generation(self.game))

    def sync(self):
        if self.state.get("mods_off"):
            # all mods are parked: nothing is placed or merged until they're on again. A switch
            # that stopped halfway (the app or the PC went down) is finished first
            self._finish_park()
            return
        t = Timing("sync")
        self._clashes = None
        self.forget_scans()
        self._track_dirs()
        t.mark("folders")
        self.update_merges()
        for name, d in getattr(self, "_merge_parts", ()):
            t.parts.append((name, d))
        t.last = time.perf_counter()
        self._clashes = None                             # merged scripts count too
        self.forget_scans()
        placed_before = len(self.state["deployed"])
        rem = self.remastered()
        filelists = {f"{FILELIST_DIR}/{fl}".lower() for fl in FILELISTS}
        desired = {}
        self._converted = {}
        for mod in reversed(self.ranked):                  # lowest priority first
            if mod["enabled"]:
                for rel in self.live_files(mod):                 # (its menu left out when switched off)
                    if rem and rel.lower() in filelists:
                        continue                         # 5.00 has none: it lists menu files by itself
                    if rem and rel.lower().startswith("bin/x64/"):
                        continue                         # the DX11 build's folder: 5.00 has none
                    desired[rel.lower()] = (mod["id"], rel)
                    if rem and rel.lower().endswith(TEXT_EXTS_UTF8):
                        conv = self._utf8_copy(mod, rel)
                        if conv is not None:
                            self._converted[(mod["id"], rel)] = conv
        t.mark("UTF-8 copies")
        for dp, _dn, files in os.walk(self.merged_dir):  # merged scripts, deployed like a mod
            for f in files:
                if f.endswith(".tmp"):
                    continue
                rel = Path(dp, f).relative_to(self.merged_dir).as_posix()
                desired[rel.lower()] = (AUTO_ID, rel)
        stage_of = {m["id"]: self.stage_dir(m) for m in self.mods}
        stage_of[AUTO_ID] = self.merged_dir
        deployed = self.state["deployed"]
        kept = set()
        new_original = False

        for actual in list(deployed):                    # remove what shouldn't be there
            info = deployed[actual]
            low = actual.lower()
            want = desired.get(low)
            dst = self.game / actual
            how = self._replaced_how(info, actual, dst, want, stage_of) \
                if self._replaced_by_someone_else(info, dst) else None
            if how in ("same", "edit"):
                # the mod's own file saved again (an editor writes a new file and swaps it in):
                # your changes go into the mod's stored copy, and it's linked in again. Nothing
                # moves to the backup: the game's original stays the one set aside there
                src = self._src(stage_of, *want)
                if how == "edit":
                    tmp = src.with_name(src.name + ".edit.tmp")
                    shutil.copyfile(dst, tmp)
                    os.replace(tmp, src)
                    self._files.pop(want[0], None)
                dst.unlink()
                _link_or_copy(src, dst)
                info["ino"] = dst.stat().st_ino
                kept.add(low)                            # ours again: it stays where it is
                continue
            elif how == "merged":
                # a merged file edited by hand: it's rebuilt from the mods, never an original. An
                # .ini keeps the keys you changed (see _ini_capture)
                if low.endswith(".ini") and INI_KEY + low in self.state.get("merges", {}) \
                        and self._ini_capture(actual, dst):
                    self._update_ini_merges(self.state["merges"])
                dst.unlink()
                del deployed[actual]
                continue
            if self._replaced_by_someone_else(info, dst):
                # a game patch, Steam's file check or you put a new file where ours was: that
                # file is the new original, so it becomes the backup instead of being deleted
                b = self.backup / actual
                b.parent.mkdir(parents=True, exist_ok=True)
                if b.exists():
                    b.unlink()
                shutil.move(str(dst), str(b))
                info["backup"] = True
                new_original = True
            elif want and want[0] == info["mod"] and want[0] in stage_of \
                    and (_same(self._src(stage_of, *want), dst) or self._edited_here(info, dst)):
                kept.add(low)
                if "ino" not in info:
                    info["ino"] = dst.stat().st_ino
                continue
            try:
                if dst.is_symlink() or dst.is_file():
                    dst.unlink()
            except FileNotFoundError:
                pass
            if info.get("backup") and rem and low in filelists:
                # 4.x's own filelist, set aside when a mod's took its place: 5.00 removed it, so
                # it isn't put back (the game is as it would be without the app)
                (self.backup / actual).unlink(missing_ok=True)
                self._prune(self.backup / actual, self.backup)
            elif info.get("backup"):
                self._restore(actual)
            del deployed[actual]
            self._prune_made(dst)
        t.mark("check placed files")
        self.save()
        t.mark("save")

        try:
            self._deploy_missing(desired, kept, stage_of, deployed)
        finally:
            self.save()                                  # never lose track of what's placed
        self._prune_converted()
        t.mark("place files")
        self._write_mods_settings()
        t.mark("mods.settings")
        self._update_filelists()
        self.scan_hints()
        self.state.pop("settings_waiting", None)
        self._write_input_settings()
        self._menu_back()
        self._write_user_settings()
        t.mark("filelists/keybinds")
        for top in list(self.state.get("created_dirs", [])):
            d = self.game / top
            try:
                if d.is_dir() and not any(d.iterdir()):
                    d.rmdir()
                if not d.exists():
                    self.state["created_dirs"].remove(top)
            except OSError:
                pass
        self.save()
        t.mark("save")
        t.done(f"({len(self.mods)} mods, {len(self.state['deployed'])} files placed, "
               f"{len(self.state['deployed']) - placed_before:+d})")
        if new_original and not getattr(self, "_resyncing", False):
            # the game updated a file a merge is built on: merge again on the new one, now
            self._resyncing = True
            try:
                self.sync()
            finally:
                self._resyncing = False

    # --- all mods off / on: the folders are moved aside, never emptied file by file
    @property
    def park_dir(self):
        return self.root / "parked"

    def all_off(self):
        return bool(self.state.get("mods_off"))

    @property
    def kept_aside_dir(self):
        """Where parked folders go that couldn't go back (one of the same name was put in the game
        while mods were off): kept, never deleted, one folder per time it happened."""
        return self.root / "kept aside"

    def _keep_aside(self, src, rel):
        """Move a parked file or folder that can't go back out of parked/, so parked/ is only ever
        what the current switch moved there. -> where it went, relative to the game folder."""
        stamp = time.strftime("%Y-%m-%d %H.%M.%S")
        dst = self.kept_aside_dir / stamp / rel
        k = 2
        while dst.exists():
            dst = self.kept_aside_dir / f"{stamp} ({k})" / rel
            k += 1
        dst.parent.mkdir(parents=True, exist_ok=True)
        os.rename(src, dst)
        return dst.relative_to(self.game).as_posix()

    def _park_targets(self):
        """The game's mods folder, and each dlc folder this app made (a mod's own): moved aside
        whole. A move on the same drive is one rename, whatever is inside."""
        out = []
        mods = ci_child(self.game, "mods")
        if mods is not None and mods.is_dir():
            out.append(mods.name)
        dlc = ci_child(self.game, "dlc")
        _made, known = self._made_dirs()
        if dlc is not None and dlc.is_dir():
            for d in sorted(dlc.iterdir(), key=lambda x: x.name.lower()):
                rel = f"{dlc.name}/{d.name}"
                if d.is_dir() and not d.is_symlink() and rel.lower() in known:
                    out.append(rel)
        return out

    def turn_all_off(self):
        """Every mod out of the game at once, for a vanilla game: the mods folder and the mods'
        own dlc folders are moved into _ModManager/parked, the game files mods replaced get their
        originals back, and the lines mods added to the settings files come out. Nothing is
        deleted or merged again: turn_all_on puts it all back as it was."""
        if self.state.get("mods_off"):
            return
        if game_running():
            raise RuntimeError("The game is running. Close it first.")
        self._track_dirs()
        if self.state.get("menu_restore"):
            self._write_user_settings()                  # values still waiting to go back go in first
        if self.park_dir.exists():
            # left over from before (a switch that couldn't put everything back): set aside, so
            # nothing of this switch lands on top of it or is skipped because of it
            for child in sorted(self.park_dir.iterdir()):
                self._keep_aside(child, child.name)
            shutil.rmtree(self.park_dir, ignore_errors=True)
        mods_ours = "mods" in {d.lower() for d in self.state.get("made_dirs", [])}
        self.state["mods_off"] = {"phase": "off", "dirs": self._park_targets(), "mods_was_yours": not mods_ours,
                                  "menu_values": self._menu_values_now()}
        self.save()                                      # recorded before anything moves
        self._finish_park()

    def turn_all_on(self):
        """Everything turn_all_off moved aside goes back, then the usual sync catches up with
        anything changed meanwhile (mods installed, removed, switched or reordered)."""
        st = self.state.get("mods_off")
        if not st:
            return []
        if game_running():
            raise RuntimeError("The game is running. Close it first.")
        st["phase"] = "on"
        self.save()
        return self._finish_park()

    def _finish_park(self):
        """Carry a switch through. Every step can be run again: a folder already moved is left
        where it is, so a switch cut short is simply finished on the next start."""
        st = self.state.get("mods_off")
        if not st:
            return []
        park = self.park_dir
        if st.get("phase") == "off":
            for rel in st["dirs"]:
                src, dst = self.game / rel, park / rel
                if src.exists() and not dst.exists():
                    dst.parent.mkdir(parents=True, exist_ok=True)
                    os.rename(src, dst)
                elif src.is_dir() and not src.is_symlink() and dst.is_dir():
                    # cut short partway (or something made it again meanwhile): what's still in the
                    # game goes in beside what's parked; a name in both is kept aside, never dropped
                    for child in sorted(src.iterdir()):
                        target = dst / child.name
                        if target.exists():
                            self._keep_aside(child, f"{rel}/{child.name}")
                        else:
                            os.rename(child, target)
            if st.get("mods_was_yours") and st["dirs"] and st["dirs"][0].lower() == "mods":
                (self.game / st["dirs"][0]).mkdir(exist_ok=True)     # yours before the app: it stays, empty
            # files placed anywhere else (bin/, the game's own dlc folders): the game's own back
            parked = tuple(r.lower() + "/" for r in st["dirs"])
            deployed = self.state["deployed"]
            for actual in list(deployed):
                if actual.lower().startswith(parked):
                    continue
                info, dst = deployed[actual], self.game / actual
                if self._replaced_by_someone_else(info, dst):
                    # the game (a patch, a file check) put its own file there: that one stays
                    (self.backup / actual).unlink(missing_ok=True)
                    self._prune(self.backup / actual, self.backup)
                else:
                    try:
                        if dst.is_symlink() or dst.is_file():
                            dst.unlink()
                    except FileNotFoundError:
                        pass
                    if info.get("backup"):
                        self._restore(actual)
                del deployed[actual]
                self._prune_made(dst)
            self.save()
            self._park_mods_settings(off=True)
            self._update_filelists()
            self._write_input_settings()                 # every mod counts as off: their lines come out
            self._write_user_settings()
            st["phase"] = "parked"
            self.save()
            return []
        if st.get("phase") == "on":
            left = []
            for rel in st["dirs"]:
                src, dst = park / rel, self.game / rel
                if not src.exists():
                    continue
                if dst.is_dir() and not dst.is_symlink() and not any(dst.iterdir()):
                    dst.rmdir()
                if not dst.exists():
                    dst.parent.mkdir(parents=True, exist_ok=True)
                    os.rename(src, dst)
                    continue
                # something new was put there meanwhile: the parked contents go back in beside it;
                # one of the same name stays out of the game, kept aside (yours wins)
                for child in sorted(src.iterdir()):
                    target = dst / child.name
                    if target.exists():
                        left.append(self._keep_aside(child, f"{rel}/{child.name}"))
                    else:
                        os.rename(child, target)
                try:
                    src.rmdir()
                except OSError:
                    pass
            self._park_mods_settings(off=False)
            if st.get("menu_values"):
                self.state["menu_restore"] = st["menu_values"]
            self._prune_empty(park)
            try:
                park.rmdir()
            except OSError:
                pass
            self.state.pop("mods_off", None)
            self.save()
            self.sync()
            return left
        return []

    def _park_mods_settings(self, off):
        """mods.settings as this app wrote it is set aside too, and yours (as it was before the
        app) is put back, or none if you had none; on again, the app's comes back."""
        sdir = self.settings_dir()
        if sdir is None:
            return
        parked = self.park_dir / "mods.settings"
        live = ci_child(sdir, "mods.settings") or sdir / "mods.settings"
        orig = self.root / "mods.settings.original"
        if off:
            if not (self.state.get("settings_ours") or self.state.get("settings_created")):
                return                                   # never written by the app: left alone
            if live.is_file() and not parked.exists():
                parked.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(live), str(parked))
            if orig.is_file() and not live.exists():
                shutil.copyfile(orig, live)
        elif parked.is_file():
            live.unlink(missing_ok=True)
            shutil.move(str(parked), str(live))

    def remastered(self):
        """Is the game The Witcher 3 Remastered (5.00 or later)?"""
        return self.generation() == "rem"

    @property
    def converted_dir(self):
        return self.root / "converted"

    def _src(self, stage_of, mid, rel):
        """The file placed in the game for a mod's file: its UTF-8 copy when one was made (5.x),
        else its stored copy."""
        return getattr(self, "_converted", {}).get((mid, rel)) or stage_of[mid] / rel

    _UTF16 = {}

    def _utf8_copy(self, mod, rel):
        """On 5.x, a mod's text file (.ws, .xml, .csv) saved as UTF-16 the way 4.x wanted, as a
        UTF-8 copy the game can read: made in _ModManager/converted, placed in the game in its
        stead. The mod's own stored file is never changed, so on a 4.x game it's used again as it
        is. None when the file is UTF-8 already (or isn't text)."""
        src = self.stage_dir(mod) / rel
        try:
            st = src.stat()
        except OSError:
            return None
        key = (str(src), st.st_size, st.st_mtime_ns)
        if key not in self._UTF16:
            try:
                with open(src, "rb") as f:
                    self._UTF16[key] = is_utf16(f.read(64))
            except OSError:
                return None
        if not self._UTF16[key]:
            return None
        out = self.converted_dir / mod["id"] / rel
        try:
            if out.is_file() and out.stat().st_mtime_ns >= st.st_mtime_ns:
                return out                               # made already (or your edit of it)
            data = to_utf8(src.read_bytes(), xml=rel.lower().endswith(".xml"))
            if data is None:
                return None
            self._write_output(out, data)
            os.utime(out, ns=(st.st_atime_ns, max(st.st_mtime_ns, out.stat().st_mtime_ns)))
        except OSError:
            return None
        return out

    def _prune_converted(self):
        """UTF-8 copies nothing uses any more (a mod removed or switched off, a 4.x game) go."""
        top = self.converted_dir
        if not top.is_dir():
            return
        keep = {str(p) for p in getattr(self, "_converted", {}).values()}
        for dp, _dn, files in os.walk(top):
            for f in files:
                if str(Path(dp, f)) not in keep:
                    Path(dp, f).unlink(missing_ok=True)
        self._prune_empty(top)
        try:
            top.rmdir()
        except OSError:
            pass

    @staticmethod
    def _edited_here(info, dst):
        """A mod's filelist that this app then added menu lines to: still that mod's file."""
        try:
            return bool(info.get("edited")) and dst.stat().st_ino == info.get("ino")
        except OSError:
            return False

    @staticmethod
    def _replaced_by_someone_else(info, dst):
        """True when the file at dst is no longer the one this app placed there."""
        if "ino" not in info:
            return False                                 # placed by an older version: can't tell
        try:
            return not dst.is_symlink() and dst.is_file() and dst.stat().st_ino != info["ino"]
        except OSError:
            return False

    TEXT_EXTS = {".xml", ".ini", ".ws", ".csv", ".txt", ".json", ".cfg", ".settings", ".yaml", ".yml"}

    def _replaced_how(self, info, actual, dst, want, stage_of):
        """A file of ours was replaced by a new one (another inode). Who did it?
        'same'   — the same bytes as the mod's copy, just written again
        'edit'   — you edited the mod's file (an editor saves to a new file and swaps it in)
        'merged' — a merged file of ours was replaced: it's rebuilt, never an original
        None     — a game patch or file check put the game's file back: it's the new original
        Inside a mod's own folder (mods/…) the game never writes, so a change there is always
        yours. Elsewhere (bin/, dlc/…) a text file counts as your edit when it's closer to the
        mod's copy than to the game's original; anything else is taken as the game's."""
        if not want or want[0] != info.get("mod") or want[0] not in stage_of:
            return None
        src = self._src(stage_of, *want)
        if want[0] == AUTO_ID and actual.lower().startswith("mods/"):
            return "merged"                               # our own folder: the game never writes there
        if not src.is_file():
            return None
        try:
            if _same(src, dst):
                return "same"
        except OSError:
            return None
        if actual.lower().startswith("mods/"):
            return "edit"
        if Path(actual).suffix.lower() not in self.TEXT_EXTS:
            return None
        def lines(path):
            try:
                if path.stat().st_size > 8 * 1024 * 1024:
                    return None
                return {l.strip() for l in decode_script(path.read_bytes())[0] if l.strip()}
            except (OSError, UnicodeError, ValueError):
                return None
        new, mod = lines(dst), lines(src)
        if not new or mod is None:
            return None
        orig_path = self.backup / actual
        orig = lines(orig_path) if orig_path.is_file() else set()
        if orig is None:
            return None
        to_mod, to_orig = len(new & mod) / len(new), len(new & orig) / len(new)
        if want[0] == AUTO_ID:
            # a merged game file (input.xml, say): hand edits are rebuilt away; anything closer
            # to the game's own is the game updating it
            return "merged" if to_mod > to_orig else None
        return "edit" if to_mod > to_orig and to_mod >= 0.5 else None

    def _deploy_missing(self, desired, kept, stage_of, deployed):
        res = CIResolver(self.game)
        game_cut = len(str(self.game)) + 1
        count = 0
        for low, (mid, rel) in desired.items():          # add what's missing
            if low in kept:
                continue
            dst = res.resolve(rel)
            actual = str(dst)[game_cut:].replace(os.sep, "/")
            src = self._src(stage_of, mid, rel)
            try:
                ours = dst.is_file() and not dst.is_symlink() and os.path.samefile(src, dst)
            except OSError:
                ours = False
            if ours:
                # already linked by a run that stopped before recording it — not an original
                prior = next((v for k, v in deployed.items() if k.lower() == low), None)
                deployed[actual] = {"mod": mid, "backup": bool(prior and prior.get("backup"))
                                    or (self.backup / actual).exists(), "ino": dst.stat().st_ino}
                continue
            # a backup with nothing recorded is an original set aside by a run that stopped early
            backup = (self.backup / actual).exists()
            if dst.exists() or dst.is_symlink():
                if dst.is_dir() and not dst.is_symlink():
                    raise RuntimeError(f"Can't place {rel}: a folder with that name is in the way.")
                b = self.backup / actual
                if b.exists():
                    dst.unlink()                         # older backup is the real original
                else:
                    b.parent.mkdir(parents=True, exist_ok=True)
                    shutil.move(str(dst), str(b))
                backup = True
            top = actual.split("/", 1)[0]
            if "/" in actual and not (self.game / top).exists():
                created = self.state.setdefault("created_dirs", [])
                if top not in created:
                    created.append(top)                  # so it can go again once empty
            self._note_new_dirs(dst.parent)
            dst.parent.mkdir(parents=True, exist_ok=True)
            deployed[actual] = {"mod": mid, "backup": backup}
            _link_or_copy(src, dst)
            deployed[actual]["ino"] = dst.stat().st_ino
            count += 1
            if count % 500 == 0:
                self.save()

    def _made_dirs(self):
        """(the list of folders this app made, the same names lower-cased as a set). The set is
        kept between calls: rebuilding it for every file placed made installs slow down with the
        square of the number of files."""
        made = self.state.setdefault("made_dirs", [])
        c = getattr(self, "_made_cache", None)
        if c is None or c[0] is not made or c[1] != len(made):
            c = self._made_cache = (made, len(made), {d.lower() for d in made})
        return made, c[2]

    def _note_new_dirs(self, folder):
        """Record every folder about to be created for a file, so removal takes away only
        folders this app made — never an (empty) folder the game or you had already."""
        made, known = self._made_dirs()
        top = str(self.game) + os.sep                 # inside the game folder: a text check, quick
        p = Path(folder)
        while str(p).startswith(top) and not p.exists():
            rel = str(p)[len(top):].replace(os.sep, "/")
            if rel.lower() not in known:
                made.append(rel)
                known.add(rel.lower())
                self._made_cache = (made, len(made), known)
            p = p.parent

    def _prune_made(self, path):
        """Remove the now-empty folders above a removed file — only ones this app created."""
        made, known = self._made_dirs()
        top = str(self.game) + os.sep
        p = Path(path).parent
        while str(p).startswith(top):
            rel = str(p)[len(top):].replace(os.sep, "/").lower()
            if rel not in known:
                break
            try:
                p.rmdir()
            except OSError:
                break
            made[:] = [d for d in made if d.lower() != rel]
            known.discard(rel)
            self._made_cache = (made, len(made), known)
            p = p.parent

    def _track_dirs(self):
        """Setups from before folders were recorded: a folder holding nothing but files this
        app placed was made by it. Top-level folders only count if they were recorded."""
        if "made_dirs" in self.state:
            return
        deployed = {a.lower() for a in self.state.get("deployed", {})}
        made, seen = [], set()
        for actual in self.state.get("deployed", {}):
            parts = actual.split("/")
            for i in range(len(parts) - 1, 0, -1):
                rel = "/".join(parts[:i])
                if rel.lower() in seen:
                    continue
                seen.add(rel.lower())
                if i == 1 and rel not in self.state.get("created_dirs", []):
                    continue
                folder = self.game / rel
                ours = folder.is_dir()
                for dp, _dn, files in os.walk(folder):
                    if any(Path(dp, f).relative_to(self.game).as_posix().lower() not in deployed
                           for f in files):
                        ours = False
                        break
                if ours:
                    made.append(rel)
        self.state["made_dirs"] = made

    def _restore(self, actual):
        b = self.backup / actual
        if b.exists():
            dst = self.game / actual
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(b), str(dst))
            self._prune(b, self.backup)

    @staticmethod
    def _prune(path, top):
        p = Path(path).parent
        while p != top and top in p.parents and p.parent != top:
            try:
                p.rmdir()
            except OSError:
                break
            p = p.parent

    def _read_settings(self):
        sdir = self.settings_dir()
        p = ci_child(sdir, "mods.settings") if sdir else None
        if p and p.is_file():
            return parse_mods_settings(p.read_text(errors="ignore"))
        return []

    def clashes(self):
        """Which loaded mod folders share a script or a packed file with another one.
        {'needs': {folder (lower)}, 'folders': {folder (lower): (name, mod id or None, resources)}}
        Worked out once per sync — reading every bundle's table isn't free."""
        if getattr(self, "_clashes", None) is not None:
            return self._clashes
        existing = self._read_settings()
        en = {e["name"].lower(): e.get("Enabled", "1") for e in existing}
        folders, managed_all = {}, set()
        for m in self.mods:
            for t in m["targets"]:
                if t.lower().startswith("mods/"):
                    managed_all.add(t.split("/", 1)[1].lower())
        for m in self.ranked:
            if not m["enabled"]:
                continue
            for t in m["targets"]:
                if not t.lower().startswith("mods/"):
                    continue
                name = t.split("/", 1)[1]
                path = self.stage_dir(m) / "mods" / name
                if path.is_dir():
                    entry = folders.setdefault(name.lower(), (name, m["id"], set()))
                    entry[2].update(folder_resources(path))
        auto = self.merged_dir / "mods" / AUTO_MERGE_NAME
        if auto.is_dir():
            folders[AUTO_MERGE_NAME.lower()] = (AUTO_MERGE_NAME, None, folder_resources(auto))
        mods_dir = ci_child(self.game, "mods")
        for d in (kids(mods_dir) if mods_dir else []):
            low = d.name.lower()
            if not d.is_dir() or low in managed_all or low in folders or low == AUTO_MERGE_NAME.lower():
                continue
            if en.get(low, "1") == "0" or (low == MERGED_NAME
                                           and (self.state.get("legacy") or {}).get("mode") == "off"):
                continue                                         # the game doesn't load it
            folders[low] = (d.name, None, folder_resources(d))
        count = {}
        for _n, _m, res in folders.values():
            for r in res:
                count[r] = count.get(r, 0) + 1
        # a script or packed file whose copies are merged isn't a clash: the merged copy, in our
        # folder (always first), is the one the game uses whichever way the mods are ordered.
        # One where the top mod's copy is used as it is (pending, failed, different new scripts,
        # or a top copy that already holds everything) still depends on priority.
        settled = set()
        for key, rec in self.state.get("merges", {}).items():
            if not (rec["status"] == "same" or (rec["status"] in ("merged", "superset") and not rec.get("topwins"))):
                continue
            if key.startswith(INI_KEY):
                continue
            if not key.startswith(XML_KEY):
                settled.add(("script", rec["rel"].lower()))
            elif rec.get("packed"):
                settled.add(("packed", rec["rel"].lower()))
        # the same text ID with the same (English) text in every mod that has it isn't a clash:
        # whichever is used, the game shows the same words
        for r, n in count.items():
            if n > 1 and r[1].startswith(TEXT_ID):
                sid = int(r[1][len(TEXT_ID):])
                texts = {W3S_TEXT.get((low, sid)) for low, (_n, _m, res) in folders.items() if r in res}
                if len(texts) == 1 and None not in texts:
                    settled.add(r)
        needs = {low for low, (_n, _m, res) in folders.items()
                 if any(count[r] > 1 and r not in settled for r in res)}
        # precompiled scripts (5.00's precompiled.rsblob) are noted, but never get a number by
        # themselves: the game orders them its own way, and what two of them can't both do
        # (add the same method, define the same class) no order fixes: annotation_clashes
        # reads them. Only a shared file gets a number
        blobs = {low for low in folders if folder_has_rsblob(self._folder_path(low))}
        self._clashes = {"needs": needs, "folders": folders, "blobs": blobs}
        return self._clashes

    def settings_rows(self):
        """The mods.settings order: [(folder, enabled, owning mod id or None)], top first."""
        return self._settings_plan()[0]

    def _settings_plan(self):
        """(rows, names this app writes, your entries). Only managed folders that clash get a
        priority — for the rest, order changes nothing. Our merged folder always comes first.
        Every entry you had that isn't ours stays, as you had it (a folder you switched off, one
        that isn't on disk right now, a mod you installed by hand); unmanaged folders that clash
        but have no entry get one, which then counts as ours."""
        existing = self._read_settings()
        prio = {e["name"].lower(): _int(e.get("Priority"), 9999) for e in existing}
        en = {e["name"].lower(): e.get("Enabled", "1") for e in existing}
        ours_before = {n.lower() for n in self._settings_ours(existing)}
        needs = self.clashes()["needs"]

        managed, managed_all = [], set()
        for m in self.ranked:
            for t in m["targets"]:
                if t.lower().startswith("mods/"):
                    name = t.split("/", 1)[1]
                    if not (self.stage_dir(m) / "mods" / name).is_dir():
                        continue                               # a loose file in mods/, not a mod
                    if m["enabled"] and name.lower() not in {n.lower() for n, _i in managed} \
                            and name.lower() in needs:
                        managed.append((name, m["id"]))     # a folder is listed once, at its highest spot
                    managed_all.add(name.lower())
        mods_dir = ci_child(self.game, "mods")
        on_disk = {d.name.lower(): d.name for d in kids(mods_dir) if d.is_dir()} if mods_dir else {}
        special = (MERGED_NAME, AUTO_MERGE_NAME.lower())
        auto = [on_disk[k] for k in on_disk if k == AUTO_MERGE_NAME.lower()]
        merged = [on_disk[k] for k in on_disk if k == MERGED_NAME]

        yours, seen = [], set()
        for e in existing:
            low = e["name"].lower()
            if low in managed_all or low in special or low in ours_before or low in seen:
                continue
            seen.add(low)
            yours.append((e["name"], en.get(low, "1")))
        added = [(on_disk[k], "1") for k in on_disk
                 if k not in managed_all and k not in special and k not in seen and k in needs]
        rest = sorted(yours + added, key=lambda r: (prio.get(r[0].lower(), 9999), r[0].lower()))

        # Script Merger's folder is switched off only while our merge stands in for it
        legacy = self.state.get("legacy") or {}
        user_legacy = self.state.get("legacy_enabled") or en.get(MERGED_NAME, "1")
        legacy_off = legacy.get("mode") == "off" and any(m["enabled"] for m in self.mods)
        legacy_en = "0" if legacy_off else user_legacy
        # numbers: 1 is always our merge folder's, even before there is one, so the mods' numbers
        # never shift when a merge appears or goes. Script Merger's folder comes right after it
        # while it's on (its merged files must win over the mods they came from); switched off,
        # its number changes nothing, so it goes last
        legacy_on = [(n, legacy_en, None) for n in merged if legacy_en != "0"]
        legacy_end = [(n, legacy_en, None) for n in merged if legacy_en == "0"]
        rows = ([(n, "1", None) for n in auto] + legacy_on
                + [(n, "1", mid) for n, mid in managed] + [(n, e, None) for n, e in rest] + legacy_end)
        numbers = ([1] * len(auto)) + list(range(2, 2 + len(rows) - len(auto)))
        ours = [n for n in auto] + [n for n, _m in managed] + [n for n, _e in added] \
            + ([n for n in merged] if legacy_off else [])
        if not ours:
            # nothing of ours in it: every entry is yours and the file is left (or given back) as you
            # had it, so its numbers are your own, and the list shows those
            given = {e["name"].lower(): _int(e.get("Priority"), None) for e in existing}
            numbers = [given.get(n.lower()) or k for (n, _e, _m), k in zip(rows, numbers)]
        return rows, ours, [n for n, _e in yours], numbers

    def _folder_path(self, low):
        """Where a loaded mod folder (lower-case name) is: a managed mod's staged copy, our merge
        folder, or the game's mods folder for one installed by hand."""
        for m in self.mods:
            for t in m["targets"]:
                if t.lower().startswith("mods/") and t.split("/", 1)[1].lower() == low:
                    return self.stage_dir(m) / "mods" / t.split("/", 1)[1]
        if low == AUTO_MERGE_NAME.lower():
            return self.merged_dir / "mods" / AUTO_MERGE_NAME
        mods_dir = ci_child(self.game, "mods")
        return ci_child(mods_dir, low) if mods_dir else None

    def precompiled(self, mod):
        """None, or every loaded mod folder with precompiled scripts when this mod's has them:
        [(folder, mod id or None)], in priority order (top first)."""
        c = self.clashes()
        mine = {t.split("/", 1)[1].lower() for t in mod["targets"] if t.lower().startswith("mods/")}
        if not mine & c["blobs"]:
            return None
        order = [(n, mid) for n, _e, mid in self.settings_rows() if n.lower() in c["blobs"]]
        listed = {n.lower() for n, _m in order}
        return order + [(c["folders"][b][0], c["folders"][b][1]) for b in sorted(c["blobs"]) if b not in listed]

    def _settings_ours(self, existing):
        """Names in mods.settings that this app put there. Setups from before this was recorded:
        entries for folders that aren't on disk were ours (yours were never dropped then)."""
        if "settings_ours" in self.state:
            return self.state["settings_ours"]
        if not (self.root / "mods.settings.original").exists():
            return []                  # older versions always kept that copy: this setup is new
        mods_dir = ci_child(self.game, "mods")
        on_disk = {d.name.lower() for d in kids(mods_dir) if d.is_dir()} if mods_dir else set()
        return [e["name"] for e in existing
                if e["name"].lower() not in on_disk or e["name"].lower() == AUTO_MERGE_NAME.lower()]

    def settings_priorities(self):
        """{mod id: [(priority number, folder), …]} in priority order — the numbers mods.settings
        gets, and the ones the list shows."""
        rows, _ours, _yours, numbers = self._settings_plan()
        out = {}
        for (name, _en, mid), n in zip(rows, numbers):
            if mid:
                out.setdefault(mid, []).append((n, name))
        return out

    def legacy_on(self):
        """Is Script Merger's folder on in mods.settings (so it holds number 2)?"""
        return any(n.lower() == MERGED_NAME and e != "0" for n, e, _m in self.settings_rows())

    def swap_priority(self, a, b):
        """Two mods trade places in priority (their numbers); every other mod keeps its own."""
        prio = self.priority_ids()
        if a not in prio or b not in prio or a == b:
            return False
        i, j = prio.index(a), prio.index(b)
        prio[i], prio[j] = prio[j], prio[i]
        self.state["priority"] = prio
        self.save()
        return True

    def set_priority_at(self, mid, number):
        """The number typed into the list for a mod: it moves to where its number comes out
        closest to that (a mod with several folders takes several numbers). Every mod is moved on
        its own, whatever Nexus page it comes from; the others keep their order."""
        pr = self.settings_priorities()
        numbered = [i for i in self.priority_ids() if i in pr]
        if mid not in numbered:
            return False
        others = [i for i in numbered if i != mid]
        base = min(p[0][0] for p in pr.values())
        now = pr[mid][0][0]
        spots, start = [], base
        for k in range(len(others) + 1):
            spots.append((k, start))
            if k < len(others):
                start += len(pr[others[k]])
        here = numbered.index(mid)
        down = number > now
        best = min(spots, key=lambda ks: (abs(ks[1] - number), (ks[0] <= here) if down else (ks[0] >= here)))[0]
        new = others[:best] + [mid] + others[best:]
        if new == numbered:
            return False
        prio = [i for i in self.priority_ids() if i != mid]
        if best < len(others):
            at = prio.index(others[best])
        elif others:
            at = prio.index(others[-1]) + 1
        else:
            at = min(self.priority_ids().index(mid), len(prio))
        self.state["priority"] = prio[:at] + [mid] + prio[at:]
        self.save()
        return True

    def _write_mods_settings(self):
        sdir = self.settings_dir()
        if sdir is None:
            return
        path = ci_child(sdir, "mods.settings") or sdir / "mods.settings"
        orig = self.root / "mods.settings.original"
        rows, ours, yours, numbers = self._settings_plan()
        legacy = self.state.get("legacy") or {}
        if any(n.lower() == MERGED_NAME for n in ours):
            if "legacy_enabled" not in self.state:       # remember yours before switching it off
                self.state["legacy_enabled"] = next((e.get("Enabled", "1") for e in self._read_settings()
                                                     if e["name"].lower() == MERGED_NAME), "1")
        else:
            self.state.pop("legacy_enabled", None)
        if not ours:
            # nothing of ours is left in it: give the file back exactly as it was, unless you've
            # added entries of your own since (older versions of this app dropped some of yours
            # from the live file — the original brings those back too)
            if orig.is_file():
                before = {e["name"].lower() for e in parse_mods_settings(orig.read_text(errors="ignore"))}
                now = {n.lower() for n, _e, _m in rows}
                if now <= before:
                    shutil.copyfile(orig, path)
                    orig.unlink()
                    self.state["settings_ours"] = []
                    return
            elif self.state.get("settings_created") and not rows:
                try:
                    path.unlink()                         # it didn't exist before this app wrote it
                except FileNotFoundError:
                    pass
                self.state.pop("settings_created", None)
                self.state["settings_ours"] = []
                return
            elif not self.state.get("settings_ours") and not self.state.get("settings_created"):
                self.state["settings_ours"] = []
                return                                    # never ours to begin with: not touched
        lines = []
        for (n, e, _mid), number in zip(rows, numbers):
            # the game documents Priority as 1-9999, and lower wins: our merge is 1
            lines += [f"[{n}]", f"Enabled={e}", f"Priority={number}", ""]
        data = "\r\n".join(lines).encode("utf-8")
        if path.is_file() and path.read_bytes() == data:
            self.state["settings_ours"] = ours
            return
        sdir.mkdir(parents=True, exist_ok=True)
        if not ours:
            # our last entries are going and the original can't come back as it was (you've
            # changed your own entries since): this is the file from now on
            orig.unlink(missing_ok=True)
            self.state.pop("settings_created", None)
        elif path.is_file():
            if not orig.exists() and not self.state.get("settings_created"):
                shutil.copy2(path, orig)                  # yours, from before this app wrote it
        elif not orig.exists():
            self.state["settings_created"] = True
        path.write_bytes(data)
        self.state["settings_ours"] = ours

    def _update_filelists(self):
        pc_dir = ci_path(self.game, FILELIST_DIR)
        prefix = FILELIST_DIR + "/"
        managed_xml = {Path(a).name for a, info in self.state["deployed"].items()
                       if a.lower().startswith(prefix) and "/" not in a[len(prefix):]
                       and a.lower().endswith(".xml") and not info.get("backup")}
        if self.remastered():
            # 5.00 has no filelists: it adds every menu file in that folder by itself. Lines this
            # app added to one still there are taken out, nothing is added, and the copies of 4.x's
            # filelists kept to give them back go — 5.00 doesn't have them to give back to
            managed_xml = set()
            added = self.state.setdefault("filelist_added", {})
            for fl in FILELISTS:
                p = ci_child(ci_path(self.game, FILELIST_DIR), fl)
                if not p or not p.is_file():
                    added.pop(fl, None)                  # the update took the file, and our lines with it
                if not added.get(fl):
                    (self.root / f"{fl}.original").unlink(missing_ok=True)
        managed_low = {x.lower() for x in managed_xml}
        added = self.state.setdefault("filelist_added", {})
        for fl in FILELISTS:
            p = ci_child(pc_dir, fl)
            if not p or not p.is_file():
                continue
            raw = p.read_bytes().decode("utf-8", errors="ignore")
            bom = "\ufeff" if raw.startswith("\ufeff") else ""
            body = raw[len(bom):]
            nl = "\r\n" if "\r\n" in body else "\n"
            final = body.endswith(("\n", "\r")) or not body
            lines = body.splitlines()
            mine = set(added.get(fl, []))
            drop = {x.lower() for x in mine if x.lower() not in managed_low}
            new = [l for l in lines if l.strip().rstrip(";").lower() not in drop]
            mine = {x for x in mine if x.lower() in managed_low}
            present = {l.strip().rstrip(";").lower() for l in new if l.strip()}
            for x in sorted(managed_xml):
                if x.lower() not in present:
                    new.append(f"{x};")
                    mine.add(x)
            if new != lines:
                bak = self.root / f"{fl}.original"
                if not bak.exists():
                    shutil.copy2(p, bak)
                # written as a new file, never through the old one: a filelist a mod shipped is
                # linked to that mod's own copy, which must stay exactly as it came
                tmp = p.with_name(p.name + ".mm-tmp")
                tmp.write_bytes((bom + nl.join(new) + (nl if final and new else "")).encode("utf-8"))
                shutil.copymode(p, tmp)
                os.replace(tmp, p)
                actual = p.relative_to(self.game).as_posix()
                info = next((v for k, v in self.state["deployed"].items() if k.lower() == actual.lower()), None)
                if info is not None:
                    info["ino"] = p.stat().st_ino
                    info["edited"] = True
            added[fl] = sorted(mine)

    # --- Nexus
    def update_check_plan(self, only=None, force=False):
        """(the mods looked at, their Nexus pages, the pages to ask about now): pages answered in the
        last hour aren't asked again unless forced. (The update check itself goes by Nexus's
        list of updated mods first, see check_updates; this is what it falls back on.)"""
        cache = self.state.get("nexus_cache", {})
        mods = [m for m in self.mods if only is None or m["id"] in only]
        all_ids = list(dict.fromkeys(str(m["nexus"]) for m in mods if m.get("nexus")))
        cutoff = time.time() - FRESH_FOR
        wanted = all_ids if force else [n for n in all_ids
                                        if cache.get(n, {}).get("checked", 0) < cutoff
                                        or "files" not in cache.get(n, {})]
        return mods, all_ids, wanted

    def pages_changed(self, pages, api_key, now=None):
        """Which of these Nexus pages to ask about, by Nexus's own list of the mods updated lately
        (one request): a page updated since it was last checked, one never checked, or one checked
        longer ago than the longest list reaches. The others haven't changed: they count as checked
        now. Returns (pages to ask, pages that haven't changed, requests made); None when the list
        can't be had (the caller falls back on update_check_plan)."""
        now = now or time.time()
        cache = self.state.setdefault("nexus_cache", {})
        longest = UPDATED_SPANS[-1][1]
        ask, maybe = [], []
        for n in pages:
            c = cache.get(n) or {}
            at = c.get("checked") or 0
            (maybe if "files" in c and at and now - at <= longest - UPDATED_SLACK else ask).append(n)
        if not maybe:
            return ask, [], 0
        back = now - min(cache[n]["checked"] for n in maybe) + UPDATED_SLACK
        period = next(name for name, span in UPDATED_SPANS if span >= back)
        try:
            listed = nexus_get(f"{NEXUS_GAME}/mods/updated.json?period={period}", api_key)
        except NexusUnreachable:
            raise
        except RuntimeError as e:
            if "rate limit" in str(e) or isinstance(e, NexusKeyRejected):
                raise
            return None
        if not isinstance(listed, list):
            return None
        when = {}
        for e in listed:
            try:
                when[str(int(e["mod_id"]))] = max(int(e.get("latest_file_update") or 0),
                                                  int(e.get("latest_mod_activity") or 0))
            except (TypeError, ValueError, KeyError):
                continue
        same = []
        for n in maybe:
            if when.get(n, 0) >= cache[n]["checked"] - UPDATED_SLACK:
                ask.append(n)                            # changed since (or just before) its last check
            else:
                same.append(n)
                cache[n]["checked"] = int(now)          # unchanged, as of now
        return ask, same, 1

    def check_updates(self, api_key, progress=None, only=None, force=False):
        """Ask Nexus about every mod that has an ID, apart from ones answered in the last
        hour, or by Nexus's list of updated mods when it can be had (see pages_changed)."""
        cache = self.state.setdefault("nexus_cache", {})
        mods, all_ids, wanted = self.update_check_plan(only, force)
        skipped = len(mods) - len(all_ids)
        calls, same = 0, []
        try:
            refresh_limits(api_key)             # free call; start from Nexus's current numbers
            if not force:
                # Nexus's list of what changed lately: only those pages are asked about (and any it
                # can't vouch for); without the list, pages answered in the last hour wait
                got = self.pages_changed(all_ids, api_key)
                if got is not None:
                    wanted, same, calls = got
        except NexusUnreachable as e:
            return {"checked": 0, "asked": 0, "skipped": skipped, "fresh": 0, "unchanged": 0,
                    "capped": False, "left": len(wanted), "offline": str(e)}
        fresh = len(all_ids) - len(wanted) - len(same)
        wanted.sort(key=lambda n: cache.get(n, {}).get("checked", 0))   # stalest first
        checked, left, offline = 0, 0, ""
        for i, nid in enumerate(wanted):
            # Nexus's own remaining count already drops with every call, so it's compared
            # against zero; only the blind budget (no numbers from Nexus yet) counts calls
            known = any(k.endswith("-remaining") for k in LAST_LIMITS)
            if (allowance() < 2) if known else (calls + 2 > BLIND_BUDGET):
                left = len(wanted) - i
                break
            try:
                data = nexus_get(f"{NEXUS_GAME}/mods/{nid}.json", api_key)
                # every file on the page, with its own version: an optional file or a patch is
                # compared with itself, never with the page's (main file's) version
                try:
                    files = nexus_files(nexus_get(f"{NEXUS_GAME}/mods/{nid}/files.json", api_key))
                except NexusUnreachable:
                    raise
                except NexusForbidden:
                    files = None                        # hidden or removed page: no files list
                except RuntimeError as e:
                    if "rate limit" in str(e) or isinstance(e, NexusKeyRejected):
                        raise
                    # a files list Nexus doesn't have: as for a hidden page. Anything else it
                    # answered with (an error on its side): the files list from the last check stays
                    old = cache.get(nid) or {}
                    files = {"files": old["files"], "updates": []} \
                        if old.get("files") and "HTTP 404" not in str(e) else None
            except NexusUnreachable as e:
                # Nexus stopped answering: the check stops here, nothing about this page changes,
                # and the pages already checked keep what they got
                offline, left = str(e), len(wanted) - i
                break
            except NexusForbidden:
                # one hidden or removed page: noted, and the check goes on with the others
                calls += 1
                cache[nid] = {**cache.get(nid, {}), "available": False, "status": "hidden",
                              "checked": int(time.time())}
                checked += 1
                if progress:
                    progress(checked, len(wanted))
                continue
            calls += 2
            before = cache.get(nid) or {}
            cache[nid] = {"version": clean_version(data.get("version", "")),
                          "name": data.get("name", ""),
                          "available": bool(data.get("available", True)),
                          "status": data.get("status", ""),
                          "files": files["files"] if files else None,
                          "updates": merged_updates((cache.get(nid) or {}).get("updates"),
                                                    files["updates"] if files else []),
                          "checked": int(time.time())}
            for key in ("changelog", "changelog_for"):   # kept until there's a newer one to fetch
                if key in before:
                    cache[nid][key] = before[key]
            for m in self.mods:                          # which file of its page each one is
                if str(m.get("nexus") or "") == nid and not m.get("nexus_cat"):
                    got = self.nexus_file_of(m, cache[nid])
                    if got and got[1]["cat"] in NEXUS_LIVE:
                        m["nexus_cat"] = got[1]["cat"]
            # the changelog: only for a page with an update waiting, and only when that update is
            # one it wasn't fetched for yet (one call; skipped when the allowance runs short)
            waiting = sorted({v for m in self.mods if str(m.get("nexus") or "") == nid
                              for v in [self.update_waiting(m)] if v})
            if waiting and cache[nid].get("changelog_for") != waiting:
                room = allowance() >= 1 if any(k.endswith("-remaining") for k in LAST_LIMITS) else calls + 1 <= BLIND_BUDGET
                if room:
                    try:
                        cache[nid]["changelog"] = nexus_changelog(
                            nexus_get(f"{NEXUS_GAME}/mods/{nid}/changelogs.json", api_key))
                        cache[nid]["changelog_for"] = waiting
                    except NexusUnreachable as e:
                        offline = str(e)                 # this page is done; the rest waits
                    except RuntimeError as e:
                        if "rate limit" in str(e) or isinstance(e, NexusKeyRejected):
                            raise
                    calls += 1
            checked += 1
            if progress:
                progress(checked, len(wanted))
            if checked % 20 == 0:
                self.save()
            if offline:
                left = len(wanted) - i - 1
                break
        if not left and not offline and only is None:
            self.state["nexus_checked"] = int(time.time())
        self.pin_nexus_files()                           # each mod's own upload, now that it's known
        self.save()
        return {"checked": checked + len(same), "asked": checked, "unchanged": len(same), "skipped": skipped,
                "fresh": fresh, "capped": bool(left) and not offline, "left": left, "offline": offline}

    @staticmethod
    def nexus_upload_of(m, page):
        """The upload on its Nexus page this mod was installed from, or None when it can't be told.
        Its archive's name as Nexus gave it (it ends in the upload time: one upload only) goes
        first, since it's the file that was installed; then the file id kept from a Nexus
        download; then the archive's size; then the file's name and version. Two uploads of the
        same name and version that nothing else tells apart: the newest, never an older one
        (which would show an update you already have). Your version no longer on the page (authors
        delete old files): your own upload as the app knows it (see _upload_gone), never the
        newest of that name, which would hide the update."""
        files = page.get("files") or []
        if not files:
            return None
        arc = Path(m["archive"]).name if m.get("archive") else ""
        if arc:
            want = archive_stem(arc)
            hit = [f for f in files if f["file_name"] and archive_stem(f["file_name"]) == want]
            if len(hit) == 1:
                return hit[0]
        if m.get("nexus_file"):
            hit = next((f for f in files if str(f["id"]) == str(m["nexus_file"])), None)
            if hit is not None:
                return hit
        key = lambda t: re.sub(r"[^a-z0-9]+", "", (t or "").lower())
        fam = file_family(m.get("archive")) or key(m.get("name"))
        same = [f for f in files if fam and fam in (file_family(f["file_name"]), key(f["name"]))]
        try:
            size = Path(m["archive"]).stat().st_size if arc else 0
        except OSError:
            size = 0
        if size:
            # the size to the byte (Nexus sends it) points at one upload, whatever the archive's called
            exact = [f for f in files if f.get("exact") and f.get("size") == size]
            if len(exact) == 1:
                return exact[0]
            near = [f for f in same if f.get("size") and not f.get("exact") and abs(f["size"] - size) < 1024]
            if len(near) == 1:
                return near[0]
        if not same:
            return None
        ver = [f for f in same if f["version"] and f["version"] == m.get("version")]
        if ver:
            return max(ver, key=lambda f: f["at"])
        return ModManager._upload_gone(m, same, size)

    @staticmethod
    def _upload_gone(m, same, size=0):
        """The upload a mod came from when it's no longer on its Nexus page (the author deleted it):
        what the app knows of it, in the shape of a file on the page. Its id is the one kept from
        the download (Nexus's record of which file replaced which still has it, so the way to the
        newest upload can be followed), its version yours, its upload time read from its archive's
        Nexus name, its title that of the uploads of the same name."""
        arc = Path(m["archive"]).name if m.get("archive") else ""
        return {"id": nexus_file_id(m.get("nexus_file")), "name": same[0]["name"] if same else "",
                "file_name": arc, "version": clean_version(m.get("version") or ""), "cat": "",
                "at": nexus_name_time(arc) if arc else 0, "size": size, "exact": False, "gone": True}

    def pin_nexus_files(self):
        """Keep the upload each mod was installed from as its file id, once it's known for sure (its
        archive's Nexus name, or its size): from then on the update check goes by that id, as for
        a Nexus download. A wrong or stale id is replaced. Returns how many changed."""
        changed = 0
        for m in self.mods:
            page = self.state.get("nexus_cache", {}).get(str(m.get("nexus") or ""))
            files = (page or {}).get("files") or []
            if not files or not m.get("archive"):
                continue
            want = archive_stem(Path(m["archive"]).name)
            hit = [f for f in files if f["file_name"] and archive_stem(f["file_name"]) == want]
            if len(hit) != 1:
                try:
                    size = Path(m["archive"]).stat().st_size
                except OSError:
                    size = 0
                hit = [f for f in files if size and f.get("exact") and f.get("size") == size]
            if len(hit) == 1 and str(m.get("nexus_file") or "") != str(hit[0]["id"]):
                m["nexus_file"] = str(hit[0]["id"])
                changed += 1
        if changed:
            self.save()
        return changed

    def nexus_file_of(self, m, page):
        """(the file on its Nexus page this mod was installed from, the newest version of that
        file), or None when it can't be told which file it is. Found by the file's id (a Nexus
        download), else its archive's name, else its file family (the name without version)."""
        mine = self.nexus_upload_of(m, page)
        files = page.get("files") or []
        if mine is None:
            return None
        # Nexus records which file replaced which: follow that to the end (past uploads deleted
        # from the page since: the last one still on it counts)…
        by_id = {str(f["id"]): f for f in files}
        after = dict(real_updates(page))
        cur, at, seen = mine, str(mine["id"]), set()
        while at in after and at not in seen:
            seen.add(at)
            at = str(after[at])
            if at in by_id:
                cur = by_id[at]
        # …and take the newest file of the same name still offered, for uploads it didn't record
        fam = file_family(cur["file_name"])
        same = [f for f in files if fam and file_family(f["file_name"]) == fam and f["cat"] in NEXUS_LIVE]
        # (by nexus_order: an author who changed how he numbers, "1.41" then "1.4.5", still gets
        # his latest upload, and a version for an older game uploaded later doesn't win)
        newest = cur
        for f in same:
            if nexus_order(f["version"], f.get("at") or 0, newest["version"], newest.get("at") or 0) > 0:
                newest = f
        return mine, newest

    def nexus_line(self, nid, file_id=None, file_name=None):
        """Every file id on a Nexus page that is a version of one file, by what Nexus itself records
        as replacing what ("Main files (5.0)" 1.1.0 -> 1.2.0 -> "Main files (5.01)" 1.2.1: one
        line, whatever the author renamed). The file is given by its id, or else by its archive's
        name. An empty set when the page or the file isn't known."""
        page = self.state.get("nexus_cache", {}).get(str(nid or ""))
        files = (page or {}).get("files") or []
        if not files:
            return set()
        fid = nexus_file_id(file_id)
        if not fid and file_name:
            want = archive_stem(file_name)
            fid = next((str(f["id"]) for f in files if f.get("file_name") and archive_stem(f["file_name"]) == want), "")
        if not fid:
            return set()
        links = {}
        for old, new in real_updates(page):
            links.setdefault(str(old), set()).add(str(new))
            links.setdefault(str(new), set()).add(str(old))
        line, todo = {fid}, [fid]
        while todo:
            for other in links.get(todo.pop(), ()):
                if other not in line:
                    line.add(other)
                    todo.append(other)
        return line

    def upload_time(self, nid, file_id=None, file_name=None):
        """When Nexus says this file was uploaded: from the page's file list (by its id, or its
        archive's name), else from the archive's own Nexus name. 0 when unknown."""
        page = self.state.get("nexus_cache", {}).get(str(nid or "")) or {}
        files = page.get("files") or []
        hit = None
        if file_id:
            hit = next((f for f in files if str(f["id"]) == str(file_id)), None)
        if hit is None and file_name:
            want = archive_stem(Path(file_name).name)
            hit = next((f for f in files if f.get("file_name") and archive_stem(f["file_name"]) == want), None)
        if hit is not None and hit.get("at"):
            return int(hit["at"])
        return nexus_name_time(Path(file_name).name) if file_name else 0

    def compare_to(self, m, version, nid=None, file_id=None, file_name=None):
        """How a file coming in compares with installed mod m: 'newer', 'same', 'older' or ''.
        Two files from the same Nexus page go by nexus_order: their upload times when Nexus
        records one replacing the other, or when they're numbered differently ("1.41" then
        "1.4.5"); otherwise, and for anything else, by the version numbers."""
        file_id = nexus_file_id(file_id)
        if nid and str(m.get("nexus") or "") == str(nid):
            mine = self.my_upload_id(m)
            if file_id and mine and str(file_id) == mine:
                return "same"
            mine_name = Path(m["archive"]).name if m.get("archive") else None
            if file_name and mine_name and archive_stem(file_name) == archive_stem(mine_name):
                return "same"
            new_t = self.upload_time(nid, file_id, file_name)
            old_t = self.upload_time(nid, mine, mine_name)
            if new_t and old_t:
                line = self.nexus_line(nid, file_id, file_name)
                linked = len(line) > 1 and bool(mine) and mine in line
                order = nexus_order(version, new_t, m.get("version"), old_t, linked)
                if order:
                    return "newer" if order > 0 else "older"
        return version_verdict(version, m.get("version"))

    def my_upload_id(self, m):
        """The Nexus file id of the upload mod m was installed from (see nexus_upload_of), '' when
        it can't be told."""
        page = self.state.get("nexus_cache", {}).get(str(m.get("nexus") or ""))
        got = self.nexus_upload_of(m, page) if page else None
        return str(got["id"]) if got else nexus_file_id(m.get("nexus_file"))

    def same_file_line(self, m, nid, file_id=None, file_name=None):
        """Is this download (a file id, or an archive's name) another version of the file installed
        mod m came from, by Nexus's own record of which file replaced which?"""
        if not nid or str(m.get("nexus") or "") != str(nid):
            return False
        line = self.nexus_line(nid, file_id, file_name)
        if len(line) < 2:
            return False                            # nothing recorded: only its name can tell
        mine = self.my_upload_id(m)
        if not mine and m.get("archive"):
            mine = next(iter(self.nexus_line(nid, file_name=Path(m["archive"]).name) & line), "")
        return mine in line

    def remote_for(self, m):
        """What Nexus says about this mod: {'available', 'status', 'version' (its own file's newest,
        when known), 'file' (that file's title)}. {} when its page hasn't been checked."""
        page = self.state.get("nexus_cache", {}).get(str(m.get("nexus") or ""))
        if not page:
            return {}
        out = {"available": page.get("available", True), "status": page.get("status", "")}
        got = self.nexus_file_of(m, page)
        if got:
            out["version"], out["file"] = got[1]["version"], got[1]["name"]
            mine, newest = got
            if mine.get("at") and newest.get("at"):
                # Nexus's own record decides, as for downloads (nexus_order)
                line = self.nexus_line(m.get("nexus"), mine["id"])
                out["newer"] = str(newest["id"]) != str(mine["id"]) and nexus_order(
                    newest["version"], newest["at"], mine["version"], mine["at"], str(newest["id"]) in line) > 0
                if out["newer"] and newest["version"] == mine["version"] and mine.get("size") \
                        and mine.get("size") == newest.get("size"):
                    out["newer"] = False                 # uploaded again, the same size: the same file
        elif page.get("files") is None and self.group_main(m.get("nexus")) is m:
            out["version"] = page.get("version", "")    # no files list yet: the page's own
                                                        # version, for its main mod only
        return out

    def update_waiting(self, m):
        """Nexus has a newer version of this mod's file than the one installed, and it isn't one
        you chose to ignore: what the ↑ chip shows. The newer version, or None."""
        rem = self.remote_for(m)
        if not rem or not rem.get("available", True) or not rem.get("version"):
            return None
        newer = rem["newer"] if "newer" in rem else version_is_newer(rem["version"], m.get("version"))
        if not newer or clean_version(rem["version"]) == clean_version(m.get("skip_update")):
            return None
        return rem["version"]

    # --- info
    def scan_hints(self):
        """Find keybind instructions in a mod: the readme that mentions them, and any
        [Section]/IK_Key=(...) lines we can apply to input.settings ourselves."""
        changed = False
        for m in self.mods:
            if "keybinds" in m and m.get("snippet_scan", 0) >= SNIPPET_SCAN:
                continue
            docs = self.docs_dir(m["id"])
            found = scan_keybind_files(docs if docs.is_dir() else self.stage_dir(m))
            if "keybinds" not in m:
                m.update({k: found[k] for k in ("keybinds", "keybind_lines", "keybind_source")})
            # which readme has keybind lines to add by hand: read again by the newer reader
            m["keybinds"] = found["keybinds"]
            if m.get("snippet_scan", 0) < SNIPPET_SCAN:
                # read with an older reader (or none): what's newly found is recorded, but left off
                # — nothing in your settings files changes by surprise; switch it on from the mod's
                # right-click menu
                had = {"user": m.get("user_settings"), "input_xml": m.get("input_xml")}
                m.update({k: found[k] for k in ("user_settings", "input_xml", "snippet_filelist",
                                                "snippet_optional", "snippet_source")})
                had_own = m.get("user_settings_own")
                own, own_src = scan_own_configs(self.stage_dir(m))
                m["user_settings_own"], m["own_source"] = own, own_src
                off = set(m.get("snippets_off", []))
                auto = set(m.get("snippets_auto_off", []))
                if own and not had_own:
                    off.add("user_own")                  # the mod's own files: off unless you switch them on
                for kind, key in (("user", "user_settings"), ("input_xml", "input_xml")):
                    if found[key] and not had[kind] and kind not in off:
                        off.add(kind)
                        auto.add(kind)
                m["snippets_off"], m["snippets_auto_off"] = sorted(off), sorted(auto)
                m["snippet_scan"] = SNIPPET_SCAN
            changed = True
        if changed:
            self.save()

    @staticmethod
    def _snippet_on(mod, kind):
        """Is this kind of snippet (user / input / input_xml) switched on for the mod?"""
        return mod.get("enabled") and kind not in mod.get("snippets_off", ())

    def snippet_on(self, mod, kind):
        """The same, and never while all mods are off."""
        return not self.state.get("mods_off") and self._snippet_on(mod, kind)

    # --- input.settings
    def _write_input_settings(self):
        """Add each enabled mod's keybind lines, and take back out exactly what we added."""
        tracked = self.state.setdefault("keybinds", {})
        # sections this app created: [name, whether it also added the blank line above]
        # (older setups stored just the name, and always added the blank line)
        created = self.state.setdefault("keybind_sections", [])
        created[:] = [c if isinstance(c, list) else [c, True] for c in created]
        clashes = self.state["keybind_clashes"] = {}
        # who kept which key: mod id -> [[section, key, the other mod's id, this mod kept it]]
        clash_detail = self.state["keybind_clash_detail"] = {}
        game_keys = self.state["keybind_game_clashes"] = {}     # mod id -> ["IK_F5 (QuickSave) in Exploration"]
        # highest mod in the list wins a key; lower ones are left out and flagged
        claimed, desired = {}, {}
        for m in self.ranked:
            if not (self.snippet_on(m, "input") and m.get("keybind_lines")):
                continue
            for section, keys in m["keybind_lines"].items():
                for line in keys:
                    key = IK_LINE.match(line).group(1)
                    owner = claimed.get((section.lower(), key.lower()))
                    if owner and owner != m["id"]:
                        clashes.setdefault(m["id"], []).append(key)
                        clashes.setdefault(owner, []).append(key)
                        clash_detail.setdefault(m["id"], []).append([section, key, owner, False])
                        clash_detail.setdefault(owner, []).append([section, key, m["id"], True])
                        continue
                    claimed[(section.lower(), key.lower())] = m["id"]
                    desired.setdefault(m["id"], {}).setdefault(section, []).append(line)
        sdir = self.settings_dir()
        path = ci_child(sdir, "input.settings") if sdir else None
        if path and path.is_file() and game_running():
            self.state["settings_waiting"] = True     # the game would overwrite it on exit
            return
        if not path or not path.is_file():
            # the game hasn't written its settings yet, or the prefix can't be reached right
            # now: keep what we know we added, so it can still be taken out later
            self.state["input_settings_found"] = False
            return
        self.state["input_settings_found"] = True
        raw, bom, nl, final = self._read_settings_text(path)
        lines = _settings_split(raw[len(bom):])

        def section_end(name):
            """Index just after the last non-empty line of a section, creating it if needed."""
            start = None
            for i, line in enumerate(lines):
                m = INI_SECTION.match(line)
                if m and m.group(1).strip().lower() == name.lower():
                    start = i
                    break
            if start is None:
                blank = bool(lines and lines[-1].strip())
                if blank:
                    lines.append("")
                lines.append(f"[{name}]")
                if not any(c[0].lower() == name.lower() for c in created):
                    created.append([name, blank])
                return len(lines)
            end = len(lines)
            for i in range(start + 1, len(lines)):
                if INI_SECTION.match(lines[i]):
                    end = i
                    break
            while end - 1 > start and not lines[end - 1].strip():
                end -= 1
            return end

        def in_section(name):
            out, inside = [], False
            for line in lines:
                m = INI_SECTION.match(line)
                if m:
                    inside = m.group(1).strip().lower() == name.lower()
                    continue
                if inside and line.strip():
                    out.append(line.strip())
            return out

        def remove_line(name, text):
            current = None
            for i, line in enumerate(lines):
                m = INI_SECTION.match(line)
                if m:
                    current = m.group(1).strip().lower()
                elif current == name.lower() and line.strip() == text:
                    del lines[i]
                    return True
            return False

        def action(line):
            m = re.search(r"Action\s*=\s*([^,\)\s]+)", line)
            return m.group(1).lower() if m else None

        # each line we added: [section, line as it is now, its action was new there, line as the
        # mod gave it]. Older setups kept just [section, line]
        for mid, entries in tracked.items():
            entries[:] = [e if len(e) == 4 else [e[0], e[1], False, e[1]] for e in entries]
        # a key you rebound in the game's menu: the game wrote its line with another key. Follow
        # it (only for an action that the mod brought itself), so it's neither added a second time
        # nor left behind when the mod goes
        for mid, entries in tracked.items():
            for e in entries:
                section, now, solo, _orig = e
                have = in_section(section)
                if now in have or not solo or not action(now):
                    continue
                moved = [l for l in have if action(l) == action(now)]
                if len(moved) == 1:
                    e[1] = moved[0]

        # take out lines we added for mods that are gone, off, or no longer bring them
        for mid, entries in list(tracked.items()):
            keep = []
            for e in entries:
                if e[3] in (desired.get(mid, {}).get(e[0]) or []):
                    keep.append(e)
                else:
                    remove_line(e[0], e[1])
            if keep:
                tracked[mid] = keep
            else:
                tracked.pop(mid)

        # add what's missing
        for mid, sections in desired.items():
            entries = tracked.setdefault(mid, [])
            for section, keys in sections.items():
                present = in_section(section)
                for line in keys:
                    mine = next((e for e in entries if e[0].lower() == section.lower() and e[3] == line), None)
                    if mine is not None and mine[1] in present:
                        continue                  # ours, maybe on the key you rebound it to
                    if mine is None and line in present:
                        continue                  # already there — yours or the game's, not ours
                    # the same key already does something else here (the game's own binding, or
                    # yours): both would fire. Still added — mods sometimes mean it — but flagged
                    solo = not any(action(l) == action(line) for l in present)
                    lines.insert(section_end(section), line)
                    present.append(line)
                    if mine is None:
                        entries.append([section, line, solo, line])
                    else:
                        mine[1] = line
            if not entries:
                tracked.pop(mid)

        # drop sections we created ourselves once they're empty again
        for entry in list(created):
            name, blank = entry
            if in_section(name):
                continue
            for i, line in enumerate(lines):
                m = INI_SECTION.match(line)
                if m and m.group(1).strip().lower() == name.lower():
                    del lines[i]
                    if blank and i and not lines[i - 1].strip():
                        del lines[i - 1]
                    break
            created.remove(entry)

        # a key the game (or you) already uses for something else in that context: both fire.
        # Still added — mods sometimes mean it — but flagged, with what the key already does
        ours = {e[1] for es in tracked.values() for e in es}
        for mid, entries in tracked.items():
            for section, now, _solo, _orig in entries:
                m = IK_LINE.match(now)
                if not m:
                    continue
                for l in in_section(section):
                    k = IK_LINE.match(l)
                    if k and k.group(1).lower() == m.group(1).lower() and l not in ours and action(l) != action(now):
                        note = f"{m.group(1)} ({IK_ACTION(l)}) in {section}"
                        if note not in game_keys.setdefault(mid, []):
                            game_keys[mid].append(note)
        new_raw = bom + nl.join(lines) + (nl if final and lines else "")
        self._write_settings_text(path, raw, new_raw)

    USER_FILES = ("user.settings", "dx12user.settings")

    def _menu_xml_groups(self, data):
        """{group id (lower): set of keys (lower)} a menu XML file writes to user.settings: each
        <Group id="…"> is a section, its <Var id="…"> the keys; a preset's <Entry overrideGroup="…"
        varId="…"> writes a key into another section. {} when it isn't XML (nothing guessed)."""
        import xml.etree.ElementTree as ET
        if len(data) > 4_000_000:
            return {}
        try:
            text = "\n".join(decode_script(data)[0])
            root = ET.fromstring(re.sub(r"^\s*<\?xml[^>]*\?>", "", text, count=1))
        except (ValueError, ET.ParseError):
            return {}
        out = {}
        for g in root.iter("Group"):
            gid = (g.get("id") or "").strip()
            keys = {(v.get("id") or "").strip().lower() for v in g.iter("Var")} - {""}
            if gid and keys:
                out.setdefault(gid.lower(), set()).update(keys)
        for e in root.iter("Entry"):
            gid, var = (e.get("overrideGroup") or "").strip(), (e.get("varId") or "").strip()
            if gid and var:
                out.setdefault(gid.lower(), set()).add(var.lower())
        return out

    def _menu_owned(self, mods=None):
        """({section (lower): keys (lower)} the installed mods' own menus write to user.settings,
        the sections the game's own menus have). A section of the game's own is shared: only the
        mods' keys in it are theirs. mods: only these mods' menus (all installed mods without)."""
        pre = FILELIST_DIR.lower() + "/"
        owned = {}
        for m in (self.mods if mods is None else mods):
            names = {n.lower() for n in self.menu_files(m)}
            if not names:
                continue
            for rel in self.mod_files(m):
                low = rel.lower()
                if not low.startswith(pre) or "/" in low[len(pre):] or low[len(pre):] not in names:
                    continue
                try:
                    data = (self.stage_dir(m) / rel).read_bytes()
                except OSError:
                    continue
                for gid, keys in self._menu_xml_groups(data).items():
                    owned.setdefault(gid, set()).update(keys)
        game_groups = set()
        pc = ci_path(self.game, FILELIST_DIR)
        deployed = {k.lower(): v for k, v in self.state["deployed"].items()}
        for f in (sorted(pc.iterdir()) if pc.is_dir() else []):
            if not f.is_file() or f.suffix.lower() != ".xml":
                continue
            info = deployed.get(f"{pre}{f.name.lower()}")
            src = f
            if info is not None:
                if not info.get("backup"):
                    continue                             # a mod's own menu
                src = self.backup / f"{FILELIST_DIR}/{f.name}"     # the game's own, set aside
            try:
                game_groups.update(self._menu_xml_groups(src.read_bytes()))
            except OSError:
                pass
        return owned, game_groups

    def _menu_values_now(self, only=None):
        """What the mods' menus have in user.settings and dx12user.settings right now, line for
        line, with where each line sits: kept while all mods are off, so whatever the game drops
        from them meanwhile (it runs without their menus then) goes back exactly as it was.

        A mod's own section is kept whole: its settings, any other line in it, blank lines and
        comments inside it. In a section the game has too, only the mods' own keys. Lines this
        app put in from a mod's instructions are left out (they come and go with the mod, see
        _write_user_settings); only where they sat is kept, so they go back there."""
        sdir = self.settings_dir()
        owned, game_groups = self._menu_owned([only] if only is not None else None)   # only: one mod's menus
        if not sdir or not owned:
            return {}
        out = {}
        for fname in self.USER_FILES:
            path = ci_child(sdir, fname)
            if not path or not path.is_file():
                continue
            ours = {(sec.lower(), key.lower()) for sec, key, _mid in self.state.get("user_added", {}).get(fname, [])}
            raw, bom, _nl, final = self._read_settings_text(path)
            lines = _settings_split(raw[len(bom):])
            sections, readme, cur, seen, last_key = [], [], None, [], None
            for i, line in enumerate(lines):
                head = INI_SECTION.match(line)
                if head:
                    name = head.group(1).strip()
                    nth = sum(1 for n, _k in seen if n.lower() == name.lower())
                    cur = {"name": name, "nth": nth, "header": line, "prevs": [list(x) for x in reversed(seen)],
                           "blank_before": i > 0 and not lines[i - 1].strip(), "blank_after": False,
                           "shared": name.lower() in game_groups, "body": [], "tail": 0}
                    sections.append(cur)
                    seen.append((name, nth))
                    last_key = None
                    continue
                if cur is None:
                    continue
                low = cur["name"].lower()
                kv = SETTING_LINE.match(line)
                if kv:
                    key = kv.group(1)
                    if (low, key.lower()) in ours:
                        readme.append([low, key.lower(), last_key])
                    elif low in owned and (not cur["shared"] or key.lower() in owned[low]):
                        cur["body"].append([key, line, last_key, key.lower() in owned[low]])
                        cur["tail"] = len(cur["body"])
                    last_key = key
                elif low in owned and not cur["shared"]:
                    cur["body"].append([None, line, last_key, False])         # a blank line or a comment
                    if line.strip():
                        cur["tail"] = len(cur["body"])
                    else:
                        nxt = next((l for l in lines[i + 1:] if l.strip()), None)
                        if nxt is not None and INI_SECTION.match(nxt) and cur["tail"] == len(cur["body"]) - 1:
                            cur["blank_after"] = True
            kept = []
            for sec in sections:
                body = sec["body"][:sec["tail"]]                 # blank lines after it: the gap to the next section
                if any(e[0] for e in body):
                    kept.append({k: sec[k] for k in ("name", "nth", "header", "prevs", "blank_before",
                                                     "blank_after", "shared")} | {"body": body})
            if kept or readme:
                out[fname] = {"sections": kept, "readme": readme, "final": final}
        return out

    def _restore_menu_values(self, saved):
        """Put back the mods' menu values the game dropped while all mods were off, each where it
        was. Only missing lines are added: one that's there (the game kept it, you changed it by
        hand) stays as it is, and nothing is moved or taken out. Only sections of a menu a mod
        still installed has come back (a mod removed meanwhile leaves nothing behind), without
        the settings its new version's menu dropped. Returns where the app's own lines from
        mods' instructions sat, for _write_user_settings to put them back there."""
        hints = {}
        sdir = self.settings_dir()
        if not sdir or not saved:
            return hints
        owned, _game_groups = self._menu_owned()
        for fname, rec in saved.items():
            for sec_low, key_low, prev in rec.get("readme", []):
                hints[(fname.lower(), sec_low, key_low)] = prev
            path = ci_child(sdir, fname)
            if not path or not path.is_file():
                continue
            raw, bom, nl, final = self._read_settings_text(path)
            lines = _settings_split(raw[len(bom):])

            def find(name, nth=0):
                """(header index, end index) of the nth section of that name, or None."""
                start, k = None, -1
                for i, line in enumerate(lines):
                    head = INI_SECTION.match(line)
                    if not head:
                        continue
                    if start is not None:
                        return start, i
                    if head.group(1).strip().lower() == name.lower():
                        k += 1
                        if k == nth:
                            start = i
                return (start, len(lines)) if start is not None else None

            def body_end(where):
                end = where[1]
                while end - 1 > where[0] and not lines[end - 1].strip():
                    end -= 1
                return end

            def key_line(where, key):
                for i in range(where[0] + 1, where[1]):
                    kv = SETTING_LINE.match(lines[i])
                    if kv and kv.group(1).lower() == key.lower():
                        return i
                return None
            to_end = False
            for sec in rec.get("sections", []):
                allowed = owned.get(sec["name"].lower())
                if allowed is None:
                    continue                             # no menu of a mod you have uses it now
                body = [e for e in sec["body"] if e[0] is None or not e[3] or e[0].lower() in allowed]
                if not any(e[0] for e in body):
                    continue
                where = find(sec["name"], sec["nth"])
                if where is None:
                    # the whole section went: back right after the nearest section it followed that's
                    # still there (before all of them if none is), with the blank lines it had around it
                    after = next((w for w in (find(n, k) for n, k in sec["prevs"]) if w), None)
                    if after:
                        at = body_end(after)
                    else:
                        at = next((i for i, l in enumerate(lines) if INI_SECTION.match(l)), len(lines))
                    block = [sec["header"]] + [e[1] for e in body]
                    if sec["blank_before"] and at > 0 and lines[at - 1].strip():
                        block.insert(0, "")
                    if sec["blank_after"] and at < len(lines) and lines[at].strip():
                        block.append("")
                    to_end = to_end or at == len(lines)
                    lines[at:at] = block
                    continue
                for key, line, prev_key, _menu in body:
                    if key is None or key_line(where, key) is not None:
                        continue                         # still there: left exactly as it is
                    before = key_line(where, prev_key) if prev_key else None
                    at = before + 1 if before is not None else (where[0] + 1 if prev_key is None else body_end(where))
                    to_end = to_end or at == len(lines)
                    lines.insert(at, line)
                    where = (where[0], where[1] + 1)
            if to_end and rec.get("final"):
                final = True                             # it ended with a line break: so it does again
            new_raw = bom + nl.join(lines) + (nl if final and lines else "")
            self._write_settings_text(path, raw, new_raw)
        return hints

    @staticmethod
    def _read_settings_text(path):
        """(text, bom, newline, ends with a newline). Bytes that aren't UTF-8 (an accented
        letter saved by an old editor, say) are carried through untouched, not dropped."""
        raw = path.read_bytes().decode("utf-8", errors="surrogateescape")
        bom = "\ufeff" if raw.startswith("\ufeff") else ""
        body = raw[len(bom):]
        return raw, bom, ("\r\n" if "\r\n" in body else "\n"), (body.endswith(("\n", "\r")) or not body)

    def _write_settings_text(self, path, raw, new_raw):
        """Write a settings file only when it changed: a copy of your first version is kept once,
        and the new one replaces it in one step, so a crash never leaves half a file."""
        if new_raw == raw:
            return
        backup = self.root / f"{path.name}.original"
        if not backup.exists():
            shutil.copy2(path, backup)
        tmp = path.with_name(path.name + ".w3mm-tmp")
        tmp.write_bytes(new_raw.encode("utf-8", errors="surrogateescape"))
        os.replace(tmp, path)

    def _write_user_settings(self):
        """Add each enabled mod's user.settings lines (from its readme) to user.settings and
        dx12user.settings, and take back out exactly what was added. Only keys you don't have are
        added: a value you (or the mod's menu) set is never overwritten. The top mod wins a key
        two mods both bring."""
        tracked = self.state.setdefault("user_added", {})        # file -> [[section, key, mod id]]
        created = self.state.setdefault("user_sections", {})     # file -> [[section, blank line added]]
        desired = {}                                             # (section, key) lower -> (section, line, mod id)
        for m in self.ranked:
            # from its readmes, and from its own config files when you switched those on
            for kind, field in (("user", "user_settings"), ("user_own", "user_settings_own")):
                if not (self.snippet_on(m, kind) and m.get(field)):
                    continue
                for section, lines in m[field].items():
                    for line in lines:
                        key = line.split("=", 1)[0].strip()
                        desired.setdefault((section.lower(), key.lower()), (section, line, m["id"]))
        sdir = self.settings_dir()
        files = [ci_child(sdir, n) for n in self.USER_FILES] if sdir else []
        files = [f for f in files if f and f.is_file()]
        self.state["user_settings_found"] = bool(files)
        if not files:
            return                                  # the game hasn't made them yet: kept for later
        if game_running():
            self.state["settings_waiting"] = True
            return
        hints = {}                                  # where lines below sat before all mods went off
        if self.state.get("menu_restore"):
            hints = self._restore_menu_values(self.state["menu_restore"])
            self.state.pop("menu_restore", None)
        # a value with ':' or ';' in it is never added: the game cuts a value at ':', and with such a
        # value followed by more lines it threw the whole file away and reset every setting
        # (Remos's tests, 18 Oct: Upgrade Kits Hardcore's "UKHC_ReportStatus=NOT_STARTED: …; …"
        # first, then 101 more lines: reset; the same line alone, or the 101 alone: fine)
        blocked = self.state["user_blocked"] = {}           # mod id -> ["[Section] key"] left out
        for key, (section, line, mid) in list(desired.items()):
            name, _eq, value = line.partition("=")
            if ";" in value:                                # a note after ';': not part of the value
                value = value.split(";", 1)[0].strip()
                desired[key] = (section, f"{name.strip()}={value}", mid)
            if ":" in value:
                del desired[key]
                blocked.setdefault(mid, []).append(f"[{section}] {name.strip()}")
        # values you changed from a mod's own (in its menu, say) while it was switched off are
        # remembered, and come back when it's switched on again; forgotten once it's uninstalled.
        # Each file's own: user.settings and dx12user.settings can hold different values
        kept = self.state.setdefault("user_kept", {})
        for mid in list(kept):
            if self.get(mid) is None:
                kept.pop(mid)
        mem_key = lambda fname, sl, kl: f"{sl}\n{kl}" if fname == "user.settings" else f"{fname}\n{sl}\n{kl}"
        wanted = desired
        for path in files:
            name = path.name.lower()
            desired = {}
            for key, (section, line, mid) in wanted.items():
                mem = (kept.get(mid) or {}).get(mem_key(name, *key))
                desired[key] = (section, mem or line, mid)
            raw, bom, nl, final = self._read_settings_text(path)
            lines = _settings_split(raw[len(bom):])
            mine = tracked.setdefault(name, [])
            made = created.setdefault(name, [])

            def find(section):
                """(header index, end index) of a section, or None."""
                start = None
                for i, line in enumerate(lines):
                    m = INI_SECTION.match(line)
                    if m and start is None and m.group(1).strip().lower() == section.lower():
                        start = i
                    elif m and start is not None:
                        return start, i
                return (start, len(lines)) if start is not None else None

            def key_at(section, key):
                where = find(section)
                if not where:
                    return None
                for i in range(where[0] + 1, where[1]):
                    kv = SETTING_LINE.match(lines[i])
                    if kv and kv.group(1).lower() == key.lower():
                        return i
                return None
            # take out what was added for mods that are gone, off, or no longer bring it
            keep = []
            for section, key, mid in mine:
                want = desired.get((section.lower(), key.lower()))
                if want and want[2] == mid:
                    keep.append([section, key, mid])
                    continue
                at = key_at(section, key)
                if at is not None:
                    theirs = next((mm for mm in self.mods if mm["id"] == mid), None)
                    orig = next((l for l in ((theirs or {}).get("user_settings") or {}).get(section, [])
                                 if l.split("=", 1)[0].strip().lower() == key.lower()), None)
                    if theirs is not None and orig is not None and lines[at].strip() != orig.strip():
                        kept.setdefault(mid, {})[mem_key(name, section.lower(), key.lower())] = lines[at].strip()
                    del lines[at]
            mine[:] = keep
            # add what's missing
            for (sl, kl), (section, line, mid) in desired.items():
                if key_at(section, line.split("=", 1)[0].strip()) is not None:
                    if not any(t[0].lower() == sl and t[1].lower() == kl for t in mine):
                        continue                    # yours (or the game's) already: left as it is
                    continue
                where = find(section)
                if where is None:
                    blank = bool(lines and lines[-1].strip())
                    if blank:
                        lines.append("")
                    lines.append(f"[{section}]")
                    made.append([section, blank])
                    where = find(section)
                end = where[1]
                while end - 1 > where[0] and not lines[end - 1].strip():
                    end -= 1
                if (name, sl, kl) in hints:
                    # back where it was before all mods went off: after the line it followed
                    prev = hints[(name, sl, kl)]
                    at = key_at(section, prev) if prev else None
                    end = at + 1 if at is not None else (where[0] + 1 if prev is None else end)
                lines.insert(end, line)
                if not any(t[0].lower() == sl and t[1].lower() == kl and t[2] == mid for t in mine):
                    mine.append([section, line.split("=", 1)[0].strip(), mid])
            # sections this app created, empty again: gone, with the blank line it put before them
            for entry in list(made):
                section, blank = entry
                where = find(section)
                if where is None:
                    made.remove(entry)
                    continue
                if any(lines[i].strip() for i in range(where[0] + 1, where[1])):
                    continue
                del lines[where[0]:where[1]]
                if blank and where[0] and not lines[where[0] - 1].strip():
                    del lines[where[0] - 1]
                made.remove(entry)
            new_raw = bom + nl.join(lines) + (nl if final and lines else "")
            self._write_settings_text(path, raw, new_raw)
            if not mine:
                tracked.pop(name, None)
            if not made:
                created.pop(name, None)

    def _settings_info(self, info):
        """What each mod's readme settings did: settings_added (values in user.settings),
        xml_added (entries in input.xml), settings_pending (why they're not in yet, or ""),
        settings_off (kinds it has that are switched off)."""
        waiting = self.state.get("settings_waiting")
        user_found = self.state.get("user_settings_found", True)
        added = {}
        for entries in self.state.get("user_added", {}).values():
            for section, key, mid in entries:
                added.setdefault(mid, set()).add((section.lower(), key.lower()))
        rec = self.state.get("merges", {}).get(XML_KEY + INPUT_XML.lower())
        for m in self.mods:
            d = info[m["id"]]
            d["settings_added"] = len(added.get(m["id"], ()))
            xml_in = bool(rec and m["id"] in rec.get("mods", ()) and rec["status"] in ("added", "merged", "superset", "same")
                          and self.snippet_on(m, "input_xml") and m.get("input_xml"))
            d["xml_added"] = len(m["input_xml"]) if xml_in else 0
            pending = ""
            if self.snippet_on(m, "user") and m.get("user_settings") and not d["settings_added"]:
                if not user_found:
                    pending = "No user.settings yet. Start the game once and they go in."
                elif waiting:
                    pending = "The game is running. They go in once it's closed."
            d["settings_pending"] = pending
            if waiting and self.snippet_on(m, "input") and m.get("keybind_lines") and not d["keys_added"]:
                d["keys_pending"] = True
            data = {"user": m.get("user_settings"), "input_xml": m.get("input_xml"), "input": m.get("keybind_lines")}
            d["settings_off"] = [k for k in ("user", "input", "input_xml")
                                 if m["enabled"] and data[k] and k in m.get("snippets_off", ())]
            d["settings_source"] = list(dict.fromkeys(m.get("snippet_source") or []))
            d["settings_blocked"] = (self.state.get("user_blocked") or {}).get(m["id"], []) \
                if self.snippet_on(m, "user") else []
            # the lines themselves, for its tooltip: {file label: [(section, line)]}
            lines = {}
            for e in (self.state.get("keybinds", {}).get(m["id"], []) if d.get("keys_added") else []):
                lines.setdefault("input.settings", []).append((e[0], e[1]))
            mine = added.get(m["id"], set())
            for section, entries in (m.get("user_settings") or {}).items():
                for line in entries:
                    if (section.lower(), line.split("=", 1)[0].strip().lower()) in mine:
                        lines.setdefault("user.settings · dx12user.settings", []).append((section, line.strip()))
            if xml_in:
                for line in m["input_xml"]:
                    got = re.search(r'\bid\s*=\s*"([^"]+)"', line)
                    lines.setdefault("input.xml", []).append(("", got.group(1) if got else line.strip()))
            d["added_lines"] = lines

    def analysis(self):
        """Per mod: {scripts, xmls} = {file: [other mods]}, lost = files beaten by higher mods."""
        names = {m["id"]: m["name"] for m in self.mods}
        shared = {"scripts": {}, "xmls": {}}
        winner = {}
        for m in reversed(self.ranked):
            if not m["enabled"]:
                continue
            for rel in self.live_files(m):
                low = rel.lower()
                winner[low] = m["id"]
                parts = low.split("/")
                if parts[0] == "bin" and low.endswith(".xml"):
                    shared["xmls"].setdefault(low, set()).add(m["id"])
        cache = self.state.get("nexus_cache", {})
        found = self.state.get("input_settings_found", True)
        info = {m["id"]: {"scripts": {}, "xmls": {}, "lost": 0,
                          "remote": self.remote_for(m),
                          # a readme mentioning keybinds only needs you if nothing could be read from it
                          "keybinds": m.get("keybinds", ""),
                          "key_source": m.get("keybind_source") or [],
                          "keys_added": len(self.state.get("keybinds", {}).get(m["id"], [])) if found else 0,
                          "key_clash": sorted(set(self.state.get("keybind_clashes", {}).get(m["id"], []))),
                          "key_clash_detail": list(self.state.get("keybind_clash_detail", {}).get(m["id"], [])),
                          "key_game": list(self.state.get("keybind_game_clashes", {}).get(m["id"], [])),
                          "keys_pending": bool(m["enabled"] and m.get("keybind_lines") and not found)}
                for m in self.mods}
        self._settings_info(info)
        place = {m["id"]: i for i, m in enumerate(self.ranked)}
        merged_xml = {k[len(XML_KEY):] for k in self.state.get("merges", {}) if k.startswith(XML_KEY)}
        for kind, groups in shared.items():
            for key, ids in groups.items():
                if kind == "xmls" and key in merged_xml:
                    continue                          # merged: shown with the other merges
                if len(ids) > 1:
                    order = [names[j] for j in sorted(ids, key=place.get)]   # top of the list wins
                    for i in ids:
                        info[i][kind][key] = order
        for d in info.values():
            d["merge"] = {"merged": [], "pending": [], "failed": [], "nobase": []}
        arrived = {m["id"]: max(m.get("installed", 0), m.get("enabled_at", 0)) for m in self.mods}
        for key, rec in self.state.get("merges", {}).items():
            status = rec["status"]
            bucket = {"superset": "merged", "same": None, "added": None}.get(status, status)
            ids = [mid for mid in set(rec.get("mods", [])) if mid in info]
            if bucket == "merged":
                # only copies with changes of their own count: one identical to the game's file
                # merged nothing, and a merge left with a single mod's changes isn't one between mods
                changed = {owner for _label, owner in merge_contributors(rec) if owner}
                ids = [mid for mid in ids if mid in changed] if len(changed) > 1 else []
            if bucket == "pending" and rec.get("involved"):
                ids = [mid for mid in ids if mid in rec["involved"]] or ids   # only mods with a say in it
            if bucket == "pending" and ids:
                # a question waiting for you is flagged on the mod that brought it — the one
                # installed, updated or switched on last — not on the mods it clashes with,
                # which were fine until it arrived
                ids = [max(ids, key=lambda i: (arrived.get(i, 0), place.get(i, 0)))]
            for mid in ids:
                if mid in info and bucket in info[mid]["merge"]:
                    others = [label for label, owner in merge_contributors(rec) if owner != mid]
                    info[mid]["merge"][bucket].append({**rec, "key": key, "others": others})
        # a file that's merged isn't lost to the mod above — every copy of it went into the merge
        combined = {k.split(":", 1)[1] for k, r in self.state.get("merges", {}).items()
                    if k.startswith((XML_KEY, INI_KEY)) and r["status"] in ("merged", "superset", "same", "added")}
        for m in self.mods:
            if m["enabled"]:
                info[m["id"]]["lost"] = sum(1 for rel in self.live_files(m)
                                            if winner.get(rel.lower()) != m["id"] and rel.lower() not in combined)
        # files packed in bundles that another loaded folder packs too: the higher one wins
        for d in info.values():
            d["packed"] = {}
        cl = self.clashes()
        order = {n.lower(): i for i, (n, _e, _m) in enumerate(self.settings_rows())}
        holders = {}
        # packed XML that's merged (or waits on a decision) is shown with the other merges
        settled = {k[len(XML_KEY):] for k, r in self.state.get("merges", {}).items()
                   if k.startswith(XML_KEY) and r.get("packed")
                   and r["status"] in ("merged", "superset", "same", "pending")}
        for low, (name, mid, res) in cl["folders"].items():
            if low == AUTO_MERGE_NAME.lower():
                continue
            for r in res:
                if r[0] == "packed" and r[1] not in settled:
                    holders.setdefault(r[1], []).append((order.get(low, len(order)), name, mid, low))
        # how many files of each kind (extension) each mod packs, for "Textures 3/10" in its tooltip
        for d in info.values():
            d["packed_totals"] = {}
        own = {}
        for low, (name, mid, res) in cl["folders"].items():
            if mid in info:
                own.setdefault(mid, set()).update(r[1] for r in res if r[0] == "packed" and not r[1].startswith(TEXT_ID))
        for mid, paths in own.items():
            totals = info[mid]["packed_totals"]
            for path in paths:
                ext = Path(path).suffix.lower()
                totals[ext] = totals.get(ext, 0) + 1
        for path, who in holders.items():
            if len(who) < 2:
                continue
            who.sort()
            top = who[0]
            order = list(dict.fromkeys(names.get(o_mid) or o_name for _r, o_name, o_mid, _l in who))
            for rank, name, mid, low in who:
                if mid in info:
                    info[mid]["packed"][path] = {"order": order, "wins": (rank, name, mid, low) == top,
                                                 "top_folder": top[3]}
        # the same symbol added (or taken over) through annotations in two mods' own files:
        # flagged on the mod that arrived last, like a script decision
        for d in info.values():
            d["annot"] = []
        for key, owners in self.annotation_clashes().items():
            ids = [mid for _label, mid in owners if mid in info]
            if not ids:
                continue
            last = max(ids, key=lambda i: (arrived.get(i, 0), place.get(i, 0)))
            others = [names.get(mid) or label.replace(" (not managed here)", "")
                      for label, mid in owners if mid != last]
            info[last]["annot"].append((key, others))
        return info

    def _changed_game_functions(self, rel, path, wanted):
        """Of the (class, function) pairs in `wanted` (lower case), those a mod's copy of a game
        script changes or adds compared with the game's own copy of that script, as made for
        the game version the copy is for (only what was downloaded before is used; no copy to
        compare with, nothing counted). Quick when the file doesn't mention them."""
        base_path = ci_path(ci_path(self.game, VANILLA_SCRIPTS), rel)
        try:
            st, bst = os.stat(path), os.stat(base_path)
        except OSError:
            return []
        sig = (str(path), st.st_size, st.st_mtime_ns, str(base_path), bst.st_size, bst.st_mtime_ns,
               frozenset(wanted))
        hit = _CHANGED_CACHE.get(sig)
        if hit is not None:
            return hit
        # kept between starts too (scans.json), for this game copy and these functions: reading a
        # big script and the game's copy of it again on every start costs a noticeable moment
        what = hashlib.sha1(repr((str(base_path), bst.st_size, bst.st_mtime_ns,
                                  sorted(wanted))).encode()).hexdigest()[:16]
        kept = KEPT.get("chg", str(path), st)          # one entry per file: [what it was asked, answer]
        if isinstance(kept, list) and len(kept) == 2 and kept[0] == what:
            try:
                hit = [tuple(k) for k in kept[1]]
            except TypeError:
                hit = None
        if hit is None:
            hit = self._work_out_changed(rel, path, base_path, wanted)
            KEPT.put("chg", str(path), st, [what, [list(k) for k in hit]])
        if len(_CHANGED_CACHE) > 2000:
            _CHANGED_CACHE.clear()
        _CHANGED_CACHE[sig] = hit
        return hit

    def _work_out_changed(self, rel, path, base_path, wanted):
        try:
            data = Path(path).read_bytes()
            raw = data.lower()
            # a file that doesn't mention any of them (in UTF-8 or UTF-16) isn't read at all
            if not any(name.encode() in raw or name.encode("utf-16-le") in raw for _c, name in wanted):
                return []
            low = decode_script(data)[0]
            base = base_path.read_bytes()
            mine = file_versions("script", rel, data)
            game = file_versions("script", rel, base)
            if mine and game and not set(mine) & set(game):
                base = next((b for b in (fetch_vanilla(self.root / "vanilla", "script", v, rel, kept_only=True)
                                         for v in reversed(mine)) if b is not None), None)
                if base is None:
                    return []
            theirs = _bodies(decode_script(base)[0])
            ours = _bodies(low)
        except (OSError, UnicodeError, ValueError):
            return []
        return [k for k in wanted if k in ours and _norm(list(ours[k])) != _norm(list(theirs.get(k, ())))]

    def annotation_clashes(self):
        """{(annotation, 'Class.Name'): [(label, mod id or None)]} for every method or field that
        two mods' scripts both add (@addMethod, @addField), or both replace (@replaceMethod),
        from different files. The game compiles every script together: a class can't have two
        members with one name, and a method can only be replaced once. A file two mods both ship
        is loaded once (merged, or the top copy), so the same symbol there isn't a clash."""
        found, spelt = {}, {}                        # key -> {rel: [(label, mid)]}
        for low, entry in self._script_inputs(everything=True).items():
            for label, path, _vkey, mid in entry["sources"]:
                for key, shown in _annotated_symbols(path).items():
                    found.setdefault(key, {}).setdefault(low, []).append((label, mid))
                    spelt.setdefault(key, shown)
        # precompiled scripts (precompiled.rsblob) are loaded alongside: what they add or
        # replace counts the same. A class two of them both define doesn't count: Brothers in
        # Arms carries the same menu classes as Quest Tweaks and Events (which it took in), and
        # the game starts fine with both, in either order (tried in game)
        c = self.clashes()
        targets = {}
        for low in sorted(c["blobs"]):
            label, mid = c["folders"][low][0], c["folders"][low][1]
            content = ci_child(self._folder_path(low), "content")
            for dp, _dn, files in os.walk(content) if content else ():
                for f in files:
                    if f.lower().endswith(".rsblob"):
                        for key, shown in rsblob_symbols(Path(dp, f)).items():
                            if not key[0].startswith("@"):
                                continue
                            found.setdefault(key, {}).setdefault(f"rsblob:{low}/{f.lower()}", []).append((label, mid))
                            spelt.setdefault(key, shown)
                            if key[0] in ("@replacemethod", "@addmethod"):
                                targets[key[1:]] = key[0]
        # a game function a precompiled mod replaces (or a method it adds) that another mod's
        # copy of that game script changes (or has): only one of them is used. A copy that
        # leaves it as the game has it doesn't count
        if targets:
            for low, entry in self._script_inputs(everything=True).items():
                for label, path, _vkey, mid in entry["sources"]:
                    for fn in self._changed_game_functions(entry["rel"], path, targets):
                        key = (targets[fn],) + fn
                        found.setdefault(key, {}).setdefault(f"edit:{low}", []).append((label, mid))
        out = {}
        for key, rels in found.items():
            if len(rels) > 1:
                owners = list(dict.fromkeys(o for who in rels.values() for o in who))
                if len({mid or label for label, mid in owners}) > 1:
                    out[(key[0], spelt[key])] = owners
        return out


