# Dark steel with a bronze accent, borrowed from the game's own menus.

C = {
    "stone": "#191d25",    # window
    "slate": "#21272e",    # lists, inputs
    "well": "#13171b",     # code panels, set into the window
    "raised": "#2b323a",   # buttons, menus
    "tip": "#2f3740",      # tooltips: a step lighter than anything under them
    "tip_edge": "#5d6773",
    "ridge": "#363e48",    # borders
    "ridge_hi": "#4a535e",
    "silver": "#d9dee4",   # text
    "ash": "#8c96a1",      # secondary text
    "dim": "#5f6873",      # disabled
    "bronze": "#c9a45c",   # accent
    "bronze_hi": "#dbb977",
    "bronze_muted": "#a89a7d",  # the accent, desaturated: an action that doesn't need to call out
    "bronze_muted_hi": "#baae97",
    "blood": "#e3735f",    # needs attention
    "brick": "#c4806a",    # stands out, for information only (a mod with far more bundles than most)
    "moss": "#7fbf8a",     # handled automatically
    "sky": "#8ec5f0",      # a newer version (on Nexus, or downloaded): news, not a problem
    "steel": "#86b0cf",    # folder names in tooltips
    "tip_rule": "#535d69", # thin line between groups in a tooltip
}


def _over_tip(colour, alpha):
    """A colour at `alpha` opacity over the tooltip's background, as a solid colour (Qt's rich
    text has no transparency)."""
    a, b = QColor(colour), QColor(C["tip"])
    return QColor(*(round(alpha * x + (1 - alpha) * y) for x, y in
                    zip((a.red(), a.green(), a.blue()), (b.red(), b.green(), b.blue())))).name()


C["file_name"] = C["ash"]                       # a file in a tooltip: grey like a mod whose copy isn't used,
C["file_ext"] = _over_tip(C["ash"], 0.6)        # its type a little darker
C["file_note"] = _over_tip(C["ash"], 0.75)      # a note about one file, under it: dimmer than the files
_over = lambda colour, alpha, under: (lambda a, b: QColor(*(round(alpha * x + (1 - alpha) * y) for x, y in zip(
    (a.red(), a.green(), a.blue()), (b.red(), b.green(), b.blue())))).name())(QColor(colour), QColor(under))
C["menu_sign"] = _over(C["ash"], 0.7, C["slate"])        # a mod's game menu, in the list: there, but quiet
C["menu_sign_off"] = _over(C["ash"], 0.4, C["slate"])    # the same for a mod switched off
C["kind_light"] = _over_tip(C["steel"], 0.75)   # a kind of file's line over them: what it is, in blue,
C["kind_deep"] = (lambda q: QColor.fromHsv(q.hsvHue(), min(255, int(q.hsvSaturation() * 1.6)), q.value()).name())(
    QColor(C["kind_light"]))                    # and how many, the same blue, deeper


_FILE_EXT = re.compile(r"(\.[A-Za-z0-9_]+(?:\.\d+\.buffer)?)$")
_LABEL_EXT = re.compile(r"(\(\.[^)]+\))$")


def file_html(name):
    """A file name for a tooltip: the name in the quiet file colour, its extension (".w2mesh",
    ".w2mesh.1.buffer", or "(.w3strings)" after a label) a little brighter."""
    m = _FILE_EXT.search(name) or _LABEL_EXT.search(name)
    stem, ext = (name[:m.start()], m.group(1)) if m and m.start() > 0 else (name, "")
    out = f"<span style='color:{C['file_name']}'>{html.escape(stem)}</span>"
    return out + (f"<span style='color:{C['file_ext']}'>{html.escape(ext)}</span>" if ext else "")
UI_DIR = _runtime_dir() / "ui"


def _write_ui_icons():
    svg = '<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{body}</svg>'
    box = '<rect x="1.5" y="1.5" width="15" height="15" rx="4" fill="{fill}" stroke="{stroke}" stroke-width="1.5"/>'
    tick = '<path d="M5.2 9.3l2.5 2.5 5.1-5.3" fill="none" stroke="{c}" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"/>'
    icons = {
        "checked": svg.format(w=18, h=18, body=box.format(fill=C["bronze"], stroke=C["bronze"]) + tick.format(c=C["stone"])),
        "checked_off": svg.format(w=18, h=18, body=box.format(fill=C["dim"], stroke=C["dim"]) + tick.format(c=C["stone"])),
        "unchecked": svg.format(w=18, h=18, body=box.format(fill="none", stroke=C["ridge_hi"])),
        "unchecked_hover": svg.format(w=18, h=18, body=box.format(fill="none", stroke=C["bronze"])),
        # some on, some off (a group header): the outline and a dash, in the tick's colour
        "partial": svg.format(w=18, h=18, body=box.format(fill="none", stroke=C["bronze"])
                              + f'<path d="M5.5 9h7" stroke="{C["bronze"]}" stroke-width="2.1" stroke-linecap="round"/>'),
        "chevron": svg.format(w=12, h=12, body=f'<path d="M3 4.5l3 3 3-3" fill="none" stroke="{C["ash"]}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>'),
    }
    UI_DIR.mkdir(parents=True, exist_ok=True)
    for name, data in icons.items():
        f = UI_DIR / f"{name}.svg"
        if not f.exists() or f.read_text() != data:
            f.write_text(data)


