class _FocusGuard(QObject):
    """Two Qt habits that pull the rug out from under you while typing:
    - a dropdown or spin box changes value when the wheel turns over it, even when you were
      only scrolling past — so the wheel only works on one you've clicked into; otherwise
      it scrolls whatever it sits in
    - in a table with fields inside it, merely moving the pointer over a row makes it the
      current row, and Qt then hands keyboard focus to the field in it"""

    # it sees every event in the app, so anything that isn't a dropdown, spin box or menu is let
    # through before even asking what the event is (that question alone cost noticeable time)
    GUARDED = (QComboBox, QAbstractSpinBox, QMenu, QLabel)     # QLabel: Qt's own tooltips are one

    def eventFilter(self, obj, e):
        if not isinstance(obj, self.GUARDED):
            return False
        t = e.type()
        if isinstance(obj, QLabel):
            if t in (QEvent.Type.Show, QEvent.Type.Resize) and obj.objectName() == "qtooltip_label":
                fit_tooltip(obj)
            return False
        if t == QEvent.Type.Wheel and isinstance(obj, (QComboBox, QAbstractSpinBox)) and not obj.hasFocus():
            area = obj.parentWidget()
            while area is not None and not isinstance(area, QAbstractScrollArea):
                area = area.parentWidget()
            if area is not None:
                QApplication.sendEvent(area.viewport(), e)
            return True
        if isinstance(obj, QMenu):
            if t == QEvent.Type.Polish and not obj.property("roundMenu"):
                # every menu (right-click, submenus, text fields' own) gets see-through corners
                # and room around it for a soft shadow, like the tooltips
                obj.setProperty("roundMenu", True)
                obj.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
                obj.setWindowFlags(obj.windowFlags() | Qt.WindowType.FramelessWindowHint
                                   | Qt.WindowType.NoDropShadowWindowHint)
            elif t == QEvent.Type.ActionAdded:
                # every menu entry gets its line icon from its text, wherever the menu is built
                kind = menu_icon_kind(e.action().text())
                if kind:
                    e.action().setIcon(menu_icon(*kind))
                    if not obj.property("icons"):
                        obj.setProperty("icons", True)
                        obj.style().unpolish(obj)
                        obj.style().polish(obj)
            elif t == QEvent.Type.Show and obj.property("roundMenu"):
                # the shadow's room is part of the menu: move it back so the menu itself still
                # opens right at the pointer (or beside its parent item)
                obj.move(obj.pos() - QPoint(MENU_SHADOW[0], MENU_SHADOW[1]))
            elif t == QEvent.Type.Paint and obj.property("roundMenu"):
                paint_menu_shadow(obj)          # under the menu; Qt then paints the menu itself
        return False


TIP_MAX_W = 640           # a tooltip wider than this wraps its lines (narrower on a small screen)


def fit_tooltip(label):
    """Qt wraps a formatted tooltip at a width of its own guessing, so a line can break with a
    word or two left over that would have fitted. Here: every line stays whole when the widest
    fits within TIP_MAX_W; otherwise the lines fill that width before they wrap."""
    if label.property("fitting") or not label.text():
        return
    label.setProperty("fitting", True)
    try:
        screen = label.screen().availableGeometry() if label.screen() else QRect(0, 0, 1920, 1080)
        cap = max(320, min(TIP_MAX_W, int(screen.width() * 0.45)))
        label.setWordWrap(False)
        size = label.sizeHint()
        if size.width() > cap:
            label.setWordWrap(True)
            size = QSize(cap, label.heightForWidth(cap))
        if label.size() != size:
            label.resize(size)
        g = label.geometry()                             # still on the screen after growing
        if g.right() > screen.right():
            label.move(max(screen.left(), screen.right() - g.width()), g.top())
        if g.bottom() > screen.bottom():
            label.move(label.x(), max(screen.top(), screen.bottom() - g.height()))
    finally:
        label.setProperty("fitting", False)


# menu entries -> their icon: (text pattern, icon, red). Matched on the entry's text, so a
# menu built anywhere in the app gets them. Red is only for the ones that throw something away.
MENU_ICONS = [
    (r"edit|rename", "edit", False), (r"open readme", "readme", False),
    (r"open nexus page", "nexus", False), (r"open( downloads)? folder|game folder|settings folder|open$", "folder", False),
    (r"mods\.settings|input\.settings", "readme", False),
    (r"script decisions", "decisions", False), (r"clear my decisions", "clear", False),
    (r"run script merger", "decisions", False),
    (r"check( nexus)?( for| \d+ for)? updates?", "update", False), (r"reinstall", "reinstall", False),
    (r"import existing", "reinstall", False),
    (r"uninstall|move .*trash", "uninstall", True), (r"remove( all \d+)? from list", "remove", False),
    (r"new section", "plus", False), (r"remove section", "minus", False),
    (r"group \d+ mods", "group", False), (r"set as main mod", "main", False),
    (r"remove .*groups?$", "minus", False), (r"ungroup", "ungroup", False),
    (r"unfold", "unfold", False), (r"fold", "fold", False), (r"settings…", "gear", False),
]
_MENU_ICON_CACHE = {}


def menu_icon_kind(text):
    t = (text or "").replace("&", "").strip().lower()
    for pattern, kind, red in MENU_ICONS:
        if re.match(pattern, t):
            return kind, red
    return None


def menu_icon(kind, red=False):
    """A thin line icon for a menu entry, drawn in code (sharp at any scaling): grey, or red
    for the entries that throw something away."""
    key = (kind, red)
    if key in _MENU_ICON_CACHE:
        return _MENU_ICON_CACHE[key]
    scale = 3
    pm = QPixmap(16 * scale, 16 * scale)
    pm.setDevicePixelRatio(scale)
    pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pen = QPen(QColor(C["blood"] if red else C["ash"]), 1.35)
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
    p.setPen(pen)
    path = QPainterPath()

    def line(*pts, close=False):
        path.moveTo(*pts[0])
        for q in pts[1:]:
            path.lineTo(*q)
        if close:
            path.closeSubpath()

    if kind == "edit":
        line((3, 13), (3.3, 10.4), (10.6, 3.1), (12.9, 5.4), (5.6, 12.7), close=True)
        line((9.2, 4.5), (11.5, 6.8))
    elif kind == "readme":
        line((4, 2.5), (9.5, 2.5), (12.5, 5.5), (12.5, 13.5), (4, 13.5), close=True)
        line((9.5, 2.5), (9.5, 5.5), (12.5, 5.5))
        line((6, 8.3), (10.5, 8.3))
        line((6, 10.8), (10.5, 10.8))
    elif kind == "nexus":
        line((9, 3), (13, 3), (13, 7))
        line((13, 3), (7.5, 8.5))
        line((11.5, 9.5), (11.5, 13), (3, 13), (3, 4.5), (6.5, 4.5))
    elif kind == "folder":
        line((2.5, 4), (6.5, 4), (8, 5.7), (13.5, 5.7), (13.5, 12.5), (2.5, 12.5), close=True)
    elif kind == "update":
        path.arcMoveTo(QRectF(3, 3, 10, 10), 60)
        path.arcTo(QRectF(3, 3, 10, 10), 60, 280)
        line((12.6, 2.2), (12.6, 5.4), (9.4, 5.4))
    elif kind == "reinstall":
        line((2.5, 4), (13.5, 4), (13.5, 6.5), (2.5, 6.5), close=True)
        line((3.5, 6.5), (3.5, 13), (12.5, 13), (12.5, 6.5))
        line((8, 8), (8, 11.3))
        line((6.5, 9.8), (8, 11.3), (9.5, 9.8))
    elif kind == "uninstall":
        line((2.8, 4.5), (13.2, 4.5))
        line((6, 4.5), (6.4, 2.8), (9.6, 2.8), (10, 4.5))
        line((4.3, 4.5), (5, 13.3), (11, 13.3), (11.7, 4.5))
        line((6.8, 7), (6.8, 11))
        line((9.2, 7), (9.2, 11))
    elif kind == "decisions":                      # a list with ticks
        for y in (4.5, 8, 11.5):
            line((2.8, y), (3.6, y + 0.8), (5, y - 0.8))
            line((7, y), (13, y))
    elif kind == "clear":                          # an eraser
        line((2.8, 10), (8.8, 4), (13, 8.2), (8.2, 13), (5.8, 13), close=True)
        line((5.8, 7), (10, 11.2))
        line((8.2, 13), (13.2, 13))
    elif kind == "remove":
        line((4.5, 4.5), (11.5, 11.5))
        line((11.5, 4.5), (4.5, 11.5))
    elif kind == "plus":
        line((8, 3.5), (8, 12.5))
        line((3.5, 8), (12.5, 8))
    elif kind == "minus":
        line((3.5, 8), (12.5, 8))
    elif kind == "group":                          # three rows, linked as in the list
        line((2.5, 2.5), (7.5, 2.5), (7.5, 5.5), (2.5, 5.5), close=True)
        line((5, 5.5), (5, 12))
        line((5, 8.5), (8.5, 8.5))
        line((5, 12), (8.5, 12))
        line((8.5, 7), (13.5, 7), (13.5, 10), (8.5, 10), close=True)
        line((8.5, 10.5), (13.5, 10.5), (13.5, 13.5), (8.5, 13.5), close=True)
    elif kind == "ungroup":                        # the same rows, each on its own
        for y in (2.5, 7, 11.5):
            line((4.5, y), (11.5, y), (11.5, y + 2), (4.5, y + 2), close=True)
    elif kind == "main":                           # to the top
        line((3, 3), (13, 3))
        line((8, 13), (8, 6))
        line((5, 9), (8, 6), (11, 9))
    elif kind == "fold":
        line((4, 9.8), (8, 5.8), (12, 9.8))
    elif kind == "unfold":
        line((4, 6.2), (8, 10.2), (12, 6.2))
    elif kind == "gear":
        path.addEllipse(QPointF(8, 8), 2.1, 2.1)
        for k in range(8):
            a = k * math.pi / 4
            line((8 + 3.6 * math.cos(a), 8 + 3.6 * math.sin(a)), (8 + 5.4 * math.cos(a), 8 + 5.4 * math.sin(a)))
        path.addEllipse(QPointF(8, 8), 3.6, 3.6)
    p.drawPath(path)
    p.end()
    _MENU_ICON_CACHE[key] = QIcon(pm)
    return _MENU_ICON_CACHE[key]


# room around a menu for its shadow: sides, top, bottom. Kept equal: Qt gives a menu the same
# space at its top and bottom, so a deeper bottom margin would eat the padding under the last item
MENU_SHADOW = (10, 10, 10)


def paint_menu_shadow(menu):
    side, top, bottom = MENU_SHADOW
    p = QPainter(menu)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    box = QRectF(side, top, menu.width() - 2 * side, menu.height() - top - bottom)
    reach, drop = bottom - 3, 3                   # the shadow falls a little lower than the menu
    for i in range(reach, 0, -1):
        path = QPainterPath()
        path.addRoundedRect(box.adjusted(-i, -i + drop, i, i + drop), 8 + i, 8 + i)
        p.fillPath(path, QColor(0, 0, 0, int(64 * (1 - i / reach) ** 2 + 2)))
    p.end()


_FOCUS_GUARD = None


class _HoverGuard(QObject):
    """On a table that holds fields (see no_hover_focus): moving the pointer over a row never
    makes it the current row, so keyboard focus stays where it is."""

    def eventFilter(self, obj, e):
        if e.type() == QEvent.Type.MouseMove and e.buttons() == Qt.MouseButton.NoButton:
            return True
        return False


_HOVER_GUARD = None


def no_hover_focus(view):
    """For a table that holds fields: hovering a row must not move keyboard focus into it."""
    global _HOVER_GUARD
    if _HOVER_GUARD is None:
        _HOVER_GUARD = _HoverGuard(QApplication.instance())
    for w in (view, view.viewport()):
        w.setProperty("noHoverFocus", True)
        w.installEventFilter(_HOVER_GUARD)


def apply_theme(app):
    global _FOCUS_GUARD
    if _FOCUS_GUARD is None:
        _FOCUS_GUARD = _FocusGuard(app)             # owned by the app, so it goes when the app does
        app.installEventFilter(_FOCUS_GUARD)
    _write_ui_icons()
    app.setStyle("Fusion")
    # Inter for the interface when it's installed (code keeps its monospaced font);
    # otherwise the desktop's own font, same size either way
    if "Inter" in QFontDatabase.families():
        font = QFont(app.font())
        font.setFamily("Inter")
        app.setFont(font)
    pal = QPalette()
    R = QPalette.ColorRole
    for role, col in ((R.Window, "stone"), (R.WindowText, "silver"), (R.Base, "slate"),
                      (R.AlternateBase, "slate"), (R.Text, "silver"), (R.Button, "raised"),
                      (R.ButtonText, "silver"), (R.Highlight, "bronze"), (R.HighlightedText, "stone"),
                      (R.ToolTipBase, "raised"), (R.ToolTipText, "silver"), (R.PlaceholderText, "ash"),
                      (R.Link, "bronze"), (R.Mid, "ridge"), (R.Dark, "stone"), (R.Light, "ridge_hi")):
        pal.setColor(role, QColor(C[col]))
    for role in (R.Text, R.ButtonText, R.WindowText):
        pal.setColor(QPalette.ColorGroup.Disabled, role, QColor(C["dim"]))
    app.setPalette(pal)
    app.setStyleSheet(_qss())


# --- Script Merger ------------------------------------------------------------
# Forks store their settings differently — the original and SM-FAE use .NET appSettings
# (WitcherScriptMerger.exe.config / .dll.config), others use a settings XML section or
# JSON. So nothing here assumes a file shape or a key name: the settings are read, the
# ones holding a Windows path are found by what they're called, and only those that
# don't resolve in this prefix are touched.
WIN_PATH_RE = re.compile(r"^[A-Za-z]:[\\/]")
ROLE_WORDS = ("dir", "path", "folder", "location")


def wine_drives(prefix):
    """{'c': Path('/…/drive_c'), 'z': Path('/'), …} from the prefix's own dosdevices links."""
    drives = {}
    try:
        entries = list((Path(prefix) / "dosdevices").iterdir())
    except OSError:
        return drives
    for entry in entries:
        name = entry.name.lower()
        if len(name) == 2 and name[1] == ":" and name[0].isalpha():
            try:
                drives[name[0]] = Path(os.path.realpath(entry))
            except OSError:
                pass
    return drives


def to_windows_path(prefix, linux_path):
    """Convert using this prefix's real mappings, preferring the most specific drive."""
    try:
        target = Path(os.path.realpath(Path(linux_path)))
    except OSError:
        return None
    best = None
    for letter, root in wine_drives(prefix).items():
        if target == root or root in target.parents:
            depth = len(root.parts)
            if best is None or depth > best[0]:
                best = (depth, letter, root)
    if best is None:
        return None
    _d, letter, root = best
    rest = target.relative_to(root).as_posix().replace("/", "\\")
    return f"{letter.upper()}:\\{rest}" if rest else f"{letter.upper()}:\\"


def from_windows_path(prefix, win_path):
    """The reverse — so a stored path can be checked against the real filesystem."""
    if not win_path or len(win_path) < 2 or win_path[1] != ":":
        return None
    root = wine_drives(prefix).get(win_path[0].lower())
    if root is None:
        return None
    rest = win_path[2:].replace("\\", "/").lstrip("/")
    return root / rest if rest else root



def setting_role(key):
    """'game', 'mods', 'scripts' — or None for a setting we can't work out a value for."""
    k = key.rsplit(".", 1)[-1].lower()
    if not any(word in k for word in ROLE_WORDS):
        return None
    if "vanilla" in k or ("script" in k and "mod" not in k):
        return "scripts"
    if "mod" in k:
        return "mods"
    if "game" in k or "witcher" in k or "install" in k:
        return "game"
    return None


class MergerSettings:
    """A Script Merger config, whatever shape it is. Keys are read and written in place
    so every other setting in the file survives untouched."""

    def __init__(self, path):
        self.path = Path(path)
        self.kind = None
        self._tree = self._nodes = self._data = None
        self._load()

    # --- loading
    def _load(self):
        if self.path.suffix.lower() == ".json":
            self._load_json()
        else:
            self._load_xml()

    def _load_xml(self):
        try:
            self._tree = ET.parse(self.path)
        except (OSError, ET.ParseError):
            return
        self._nodes = {}
        for el in self._tree.getroot().iter():
            if el.tag == "add" and el.get("key") is not None:          # appSettings
                self._nodes[el.get("key")] = ("attr", el)
            elif el.tag == "setting" and el.get("name") is not None:   # userSettings
                child = el.find("value")
                if child is not None:
                    self._nodes[el.get("name")] = ("text", child)
        self.kind = "xml"

    def _load_json(self):
        try:
            self._data = json.loads(self.path.read_text(encoding="utf-8-sig"))
        except (OSError, ValueError):
            return
        if not isinstance(self._data, dict):
            self._data = None
            return
        self._nodes = {}

        def walk(node, prefix=""):
            for key, value in node.items():
                full = f"{prefix}{key}"
                if isinstance(value, str):
                    self._nodes[full] = ("json", (node, key))
                elif isinstance(value, dict) and not prefix:
                    walk(value, f"{key}.")

        walk(self._data)
        self.kind = "json"

    # --- access
    def ok(self):
        return self._nodes is not None

    def items(self):
        out = {}
        for key, (how, target) in (self._nodes or {}).items():
            if how == "attr":
                out[key] = target.get("value") or ""
            elif how == "text":
                out[key] = target.text or ""
            else:
                node, name = target
                out[key] = node.get(name) or ""
        return out

    def path_settings(self):
        """Settings whose value looks like a Windows path."""
        return {k: v for k, v in self.items().items() if WIN_PATH_RE.match(v.strip())}

    def set(self, key, value):
        entry = (self._nodes or {}).get(key)
        if entry is None:
            return self._add(key, value)
        how, target = entry
        if how == "attr":
            if (target.get("value") or "") == value:
                return False
            target.set("value", value)
        elif how == "text":
            if (target.text or "") == value:
                return False
            target.text = value
        else:
            node, name = target
            if node.get(name) == value:
                return False
            node[name] = value
        return True

    def _add(self, key, value):
        if self.kind == "json":
            self._data[key] = value
            self._nodes[key] = ("json", (self._data, key))
            return True
        root = self._tree.getroot()
        section = root.find("appSettings")
        if section is None:
            section = ET.SubElement(root, "appSettings")
        el = ET.SubElement(section, "add", {"key": key, "value": value})
        self._nodes[key] = ("attr", el)
        return True

    def save(self):
        backup = self.path.with_suffix(self.path.suffix + ".original")
        try:
            if not backup.exists():
                shutil.copy2(self.path, backup)
            if self.kind == "json":
                self.path.write_text(json.dumps(self._data, indent=2), encoding="utf-8")
            else:
                ET.indent(self._tree, space="  ")
                self._tree.write(self.path, encoding="utf-8", xml_declaration=True)
        except OSError:
            return False
        return True


def merger_config(exe_path):
    """The settings file beside the exe. A .NET config named after the exe wins, then any
    file that already holds a path setting, then anything readable."""
    exe = Path(exe_path)
    named = {f"{exe.name}.config".lower(), f"{exe.stem}.dll.config".lower(),
             f"{exe.stem}.config".lower()}
    best = None
    candidates = list(exe.parent.glob("*.config")) + list(exe.parent.glob("*.json"))
    for f in sorted(candidates):
        if f.name.lower().endswith(".original"):
            continue
        settings = MergerSettings(f)
        if not settings.ok():
            continue
        has_role = any(setting_role(k) for k in settings.path_settings())
        rank = (f.name.lower() in named, has_role, bool(settings.items()))
        if not any(rank):
            continue
        if best is None or rank > best[0]:
            best = (rank, settings)
    return best[1] if best else None


def merger_path_check(prefix, game_dir, exe_path):
    """Compare the stored paths with what this prefix needs.

    Returns (settings, {key: new value}, [(key, stored, wanted)], [(key, stored)]),
    the last being broken paths we have no way to work out a value for.
    """
    settings = merger_config(exe_path)
    if settings is None:
        return None, {}, [], []
    game_dir = Path(game_dir)
    targets = {"game": game_dir,
               "mods": ci_child(game_dir, "mods"),
               "scripts": ci_path(game_dir, "content/content0/scripts")}
    windows = {role: (to_windows_path(prefix, p) if p and Path(p).is_dir() else None)
               for role, p in targets.items()}
    if not windows["game"]:
        return settings, {}, [], []

    def resolves(value):
        real = from_windows_path(prefix, value)
        return real is not None and real.exists()

    def same_as(value, other):
        real = from_windows_path(prefix, value)
        try:
            return real is not None and Path(os.path.realpath(real)) == Path(os.path.realpath(other))
        except OSError:
            return False

    wanted, wrong, unfixable = {}, [], []
    stored_paths = settings.path_settings()
    seen_roles = set()
    for key, value in stored_paths.items():
        role = setting_role(key)
        if role is None:
            if not resolves(value):
                unfixable.append((key, value))
            continue
        seen_roles.add(role)
        if role == "game":
            if resolves(value) and same_as(value, game_dir):
                continue
        elif resolves(value):
            continue                      # an override that works is the user's business
        want = windows.get(role)
        if not want:
            unfixable.append((key, value))
            continue
        wanted[key] = want
        wrong.append((key, value, want))

    if "game" not in seen_roles:          # never configured, or the key is missing entirely
        key = next((k for k in settings.items() if setting_role(k) == "game"), "GameDirectory")
        wanted[key] = windows["game"]
        wrong.append((key, settings.items().get(key, ""), windows["game"]))
    return settings, wanted, wrong, unfixable


def steam_roots():
    """Where Steam keeps its files: native, Flatpak and Snap installs."""
    home = Path.home()
    return [home / ".local/share/Steam", home / ".steam/steam",
            home / ".var/app/com.valvesoftware.Steam/.local/share/Steam",
            home / "snap/steam/common/.local/share/Steam", home / "snap/steam/common/.steam/steam"]


def theme_icon(*names):
    for n in names:
        ic = QIcon.fromTheme(n)
        if not ic.isNull():
            return ic
    return QIcon()


PRIORITY_COL, NAME_COL, VERSION_COL, CONFLICT_COL, DATE_COL = range(5)
COLUMNS = 5
CHIPS_ROLE = Qt.ItemDataRole.UserRole + 1
SEP_ROLE = Qt.ItemDataRole.UserRole + 3
COLLAPSED_ROLE = Qt.ItemDataRole.UserRole + 4
GRID_ALPHA = 0.55                                # how strongly the mod list's grid lines show
COUNT_ROLE = Qt.ItemDataRole.UserRole + 5      # a section's (mods switched on, mods in it)


def section_count(on, n):
    """What a section's row says about its mods: how many are switched on, of how many ("4/6")."""
    return f"{on}/{n}"
OFF_ROLE = Qt.ItemDataRole.UserRole + 2
GROUP_ROLE = Qt.ItemDataRole.UserRole + 6
MENU_ROLE = Qt.ItemDataRole.UserRole + 7       # a mod's own game menus: the tooltip of its sign in the list
GHEAD_ROLE = Qt.ItemDataRole.UserRole + 8      # a group's header row (a group without a main mod): its id
GHEAD_PREFIX = "group:"                        # a header row's id in the list (never a mod's)
HEAD_LOOK = "bronze"                           # a group header: "plain" (like a mod row), "bronze" (its name in
                                               # the group lines' colour) or "tint" (a faint bronze shade)


class RowDelegate(QStyledItemDelegate):
    """Taller rows, grid lines, a pill for the priority number, tags for conflicts."""
    ROW_H = 40
    INDENT = 22                         # how far a linked sub-mod sits in from its main mod
    priorityChosen = pyqtSignal(str, int)
    prio_min, prio_max = 2, 2           # the numbers the priority editor offers

    def createEditor(self, parent, opt, idx):
        if idx.column() != PRIORITY_COL:
            return super().createEditor(parent, opt, idx)
        box = QSpinBox(parent, objectName="PrioEdit")
        box.setRange(0, 999999999)          # type anything: it's fitted to the nearest place on Enter
        box.setAlignment(Qt.AlignmentFlag.AlignCenter)
        box.setButtonSymbols(QAbstractSpinBox.ButtonSymbols.NoButtons)
        box.setFrame(False)
        return box

    def setEditorData(self, editor, idx):
        if idx.column() == PRIORITY_COL:
            editor.setValue(prio_start(idx.data()))
            editor.selectAll()
            return
        super().setEditorData(editor, idx)

    def setModelData(self, editor, model, idx):
        if idx.column() == PRIORITY_COL:
            editor.interpretText()
            if editor.value() != prio_start(idx.data()):
                # the number itself is redrawn from the new order; nothing is written here
                self.priorityChosen.emit(idx.siblingAtColumn(0).data(Qt.ItemDataRole.UserRole), editor.value())
            return
        super().setModelData(editor, model, idx)

    def _shifted(self, opt, idx):
        """(the option to lay the cell out with, its group info). A linked sub-mod's name cell —
        checkbox and name — sits a step in, as in a tree."""
        g = idx.data(GROUP_ROLE) if idx.column() == NAME_COL else None
        if g and getattr(self.parent(), "filtering", False):
            g = None                    # rows hidden by the filter: nothing to link
        if g and not g["main"]:
            o = QStyleOptionViewItem(opt)
            o.rect = opt.rect.adjusted(self.INDENT, 0, 0, 0)
            return o, g
        return opt, g

    def editorEvent(self, e, model, opt, idx):
        return super().editorEvent(e, model, self._shifted(opt, idx)[0], idx)     # the checkbox moved too

    def updateEditorGeometry(self, editor, opt, idx):
        if idx.column() == PRIORITY_COL:
            w = max(40, min(opt.rect.width() - 12, 56))       # the pill's size, a little bigger
            editor.setGeometry(QRect(opt.rect.center().x() - w // 2 + 1, opt.rect.center().y() - 13, w, 26))
            return
        super().updateEditorGeometry(editor, self._shifted(opt, idx)[0], idx)

    def _links(self, p, opt, idx, g):
        """Tree lines: from each sub-mod's checkbox to its main mod's, however many rows apart."""
        o = QStyleOptionViewItem(opt)
        self.initStyleOption(o, idx)
        style = opt.widget.style() if opt.widget else QApplication.style()
        box = style.subElementRect(QStyle.SubElement.SE_ItemViewItemCheckIndicator, o, opt.widget)
        r = opt.rect
        x, cy = box.center().x() + 0.5, r.center().y() + 0.5
        top, bottom = float(r.top()), float(r.bottom() + 1)
        col = QColor(C["bronze"])
        col.setAlphaF(0.55)
        p.save()
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(col, 1.5)
        pen.setCapStyle(Qt.PenCapStyle.FlatCap)
        p.setPen(pen)
        if g["main"]:
            if g["prev"]:
                p.drawLine(QPointF(x, top), QPointF(x, box.top() - 2))
            if g["next"]:
                p.drawLine(QPointF(x, box.bottom() + 3), QPointF(x, bottom))
        else:
            if g["side"] < 0:                                  # above its main: the line runs down
                p.drawLine(QPointF(x, top if g["prev"] else cy), QPointF(x, bottom))
            else:                                              # below it: the line comes from above
                p.drawLine(QPointF(x, top), QPointF(x, bottom if g["next"] else cy))
            p.drawLine(QPointF(x, cy), QPointF(box.left() + self.INDENT - 4, cy))
        p.restore()

    def _head_priority(self, p, opt, idx):
        """A group header's first cell: empty while it's open (the mods below show their own
        numbers), folded the priority numbers of the mods inside."""
        o = QStyleOptionViewItem(opt)
        self.initStyleOption(o, idx)
        o.text = ""
        style = o.widget.style() if o.widget else QApplication.style()
        style.drawControl(QStyle.ControlElement.CE_ItemViewItem, o, p, o.widget)
        r = opt.rect
        folded = bool(idx.siblingAtColumn(0).data(COLLAPSED_ROLE))
        p.save()
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        text = idx.data() or ""
        if folded and text:
            room = QRectF(r)
            if text == "–":
                p.setPen(QColor(C["dim"]))
                p.drawText(room, Qt.AlignmentFlag.AlignCenter, text)
            else:
                w = max(opt.fontMetrics.horizontalAdvance(text) + 16, 28)
                pill = QRectF(room.center().x() - w / 2, r.center().y() + 0.5 - 11, w, 22)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(C["ridge"]))
                p.drawRoundedRect(pill, 11, 11)
                p.setPen(QColor(C["silver"]))
                p.drawText(pill, Qt.AlignmentFlag.AlignCenter, text)
        p.restore()
        self._grid(p, opt)

    def head_arrow_rect(self, opt, idx):
        """Where a group header's fold arrow sits: right after its name."""
        o = QStyleOptionViewItem(opt)
        self.initStyleOption(o, idx)
        style = o.widget.style() if o.widget else QApplication.style()
        tr = style.subElementRect(QStyle.SubElement.SE_ItemViewItemText, o, o.widget)
        w = min(o.fontMetrics.horizontalAdvance(o.text), tr.width())
        return QRectF(tr.left() + w + 6, opt.rect.center().y() - 9 + 0.5, 18, 18)

    def _head_arrow(self, p, opt, idx):
        folded = bool(idx.siblingAtColumn(0).data(COLLAPSED_ROLE))
        r = self.head_arrow_rect(opt, idx)
        col = QColor(C["bronze"] if HEAD_LOOK == "bronze" else C["ash"])
        pen = QPen(col, 1.6)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        p.save()
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setPen(pen)
        c = r.center()
        if folded:                                       # pointing right: there's more inside
            p.drawPolyline([QPointF(c.x() - 2, c.y() - 4), QPointF(c.x() + 2, c.y()), QPointF(c.x() - 2, c.y() + 4)])
        else:
            p.drawPolyline([QPointF(c.x() - 4, c.y() - 2), QPointF(c.x(), c.y() + 2), QPointF(c.x() + 4, c.y() - 2)])
        p.restore()

    MENU_SPACE = 34                     # the name stops this far from the cell's right edge when a sign is there

    @staticmethod
    def menu_rect(rect):
        """Where a mod's menu sign sits in its name cell: at the right edge, the same for every row."""
        return QRectF(rect.right() - 23, rect.center().y() - 8 + 0.5, 18, 16)

    def initStyleOption(self, o, idx):
        super().initStyleOption(o, idx)
        if idx.column() == NAME_COL and idx.data(MENU_ROLE) and o.text:
            # a long name is cut short ("…") before the sign rather than running under it
            style = o.widget.style() if o.widget else QApplication.style()
            tr = style.subElementRect(QStyle.SubElement.SE_ItemViewItemText, o, o.widget)
            room = o.rect.right() - self.MENU_SPACE - tr.left()
            o.text = o.fontMetrics.elidedText(o.text, Qt.TextElideMode.ElideRight, max(0, room))

    @staticmethod
    def _menu_sign(p, r, colour):
        """Two sliders: the usual sign for settings. Each line is broken where its ring sits,
        so it reads the same over any row colour (hovered, selected)."""
        p.save()
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(QColor(colour), 1.3)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        p.setPen(pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        cx, cy, k = r.center().x(), r.center().y(), 2.2
        for dy, kx in ((-3.5, 2.5), (3.5, -2.5)):
            y = cy + dy
            p.drawLine(QPointF(cx - 6, y), QPointF(cx + kx - k - 0.6, y))
            p.drawLine(QPointF(cx + kx + k + 0.6, y), QPointF(cx + 6, y))
            p.drawEllipse(QPointF(cx + kx, y), k, k)
        p.restore()

    def sizeHint(self, opt, idx):
        s = super().sizeHint(opt, idx)
        s.setHeight(max(s.height(), self.ROW_H))
        if idx.column() == CONFLICT_COL:
            chips = idx.data(CHIPS_ROLE) or []
            s.setWidth(sum(opt.fontMetrics.horizontalAdvance(c[0]) + 26 for c in chips) + 10)
        return s

    @staticmethod
    def chip_rects(rect, fm, chips):
        """Where each status chip sits in its cell: the same layout paint() draws, so the tooltip
        under the pointer is always that chip's own."""
        x, cy = rect.x() + 6, rect.center().y() + 0.5
        out = []
        for c in chips:
            w = fm.horizontalAdvance(c[0]) + 20
            out.append(QRectF(x, cy - 11, w, 22))
            x += w + 6
        return out

    def paint(self, p, opt, idx):
        col = idx.column()
        if idx.siblingAtColumn(0).data(SEP_ROLE):
            if col != 0:
                return
            p.save()
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            r = opt.rect
            p.fillRect(r, QColor(C["raised"]))
            p.setPen(QColor(C["ridge"]))
            p.drawLine(r.left(), r.bottom(), r.right(), r.bottom())
            collapsed = bool(idx.siblingAtColumn(0).data(COLLAPSED_ROLE))
            font = QFont(opt.font)
            font.setBold(True)
            p.setFont(font)
            p.setPen(QColor(C["bronze"]))
            p.drawText(QRectF(r.x() + 10, r.y(), 20, r.height()),
                       Qt.AlignmentFlag.AlignVCenter, "▸" if collapsed else "▾")
            p.setPen(QColor(C["silver"]))
            p.drawText(QRectF(r.x() + 32, r.y(), r.width() - 140, r.height()),
                       Qt.AlignmentFlag.AlignVCenter, idx.siblingAtColumn(NAME_COL).data() or "")
            on, n = idx.siblingAtColumn(0).data(COUNT_ROLE) or (0, 0)
            p.setFont(QFont(opt.font))
            p.setPen(QColor(C["ash"]))
            p.drawText(QRectF(r.x(), r.y(), r.width() - 12, r.height()),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), section_count(on, n))
            p.restore()
            return
        if idx.siblingAtColumn(0).data(GHEAD_ROLE):
            if HEAD_LOOK == "tint":
                shade = QColor(C["bronze"])
                shade.setAlphaF(0.07)
                p.fillRect(opt.rect, shade)
            if col == PRIORITY_COL:
                self._head_priority(p, opt, idx)
                return
        if col not in (PRIORITY_COL, CONFLICT_COL):
            o, g = self._shifted(opt, idx)
            if o is not opt:
                # the strip left of an indented row's checkbox gets the row's selection/hover too
                bg = QStyleOptionViewItem(opt)
                self.initStyleOption(bg, idx)
                bg.rect = QRect(opt.rect.left(), opt.rect.top(), o.rect.left() - opt.rect.left(), opt.rect.height())
                style = opt.widget.style() if opt.widget else QApplication.style()
                style.drawPrimitive(QStyle.PrimitiveElement.PE_PanelItemViewItem, bg, p, opt.widget)
            super().paint(p, o, idx)
            if col == NAME_COL and idx.data(MENU_ROLE):
                off = bool(idx.siblingAtColumn(PRIORITY_COL).data(OFF_ROLE))
                self._menu_sign(p, self.menu_rect(opt.rect), C["menu_sign_off"] if off else C["menu_sign"])
            self._grid(p, opt)
            if g:
                self._links(p, opt, idx, g)
            if col == NAME_COL and idx.siblingAtColumn(0).data(GHEAD_ROLE):
                self._head_arrow(p, opt, idx)
            return
        o = QStyleOptionViewItem(opt)
        self.initStyleOption(o, idx)
        o.text = ""
        style = o.widget.style() if o.widget else QApplication.style()
        style.drawControl(QStyle.ControlElement.CE_ItemViewItem, o, p, o.widget)
        p.save()
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        fm = opt.fontMetrics
        cy = opt.rect.center().y() + 0.5
        off = bool(idx.data(OFF_ROLE))
        if col == PRIORITY_COL and (idx.data() or "") in ("", "–"):
            p.setPen(QColor(C["dim"]))
            p.drawText(opt.rect, Qt.AlignmentFlag.AlignCenter, idx.data() or "")
        elif col == PRIORITY_COL:
            text = idx.data() or ""
            w = max(fm.horizontalAdvance(text) + 16, 28)
            r = QRectF(opt.rect.center().x() - w / 2 + 0.5, cy - 11, w, 22)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(C["raised"] if off else C["ridge"]))
            p.drawRoundedRect(r, 11, 11)
            p.setPen(QColor(C["dim"] if off else C["silver"]))
            p.drawText(r, Qt.AlignmentFlag.AlignCenter, text)
        else:
            chips = idx.data(CHIPS_ROLE) or []
            for (text, kind, *_tip), r in zip(chips, self.chip_rects(opt.rect, fm, chips)):
                # "…-line": outlined, for what's about the mod itself (its version, gone from Nexus,
                # in the game now); filled: what's between mods (clashes, merges)
                kind, _, line = kind.partition("-")
                fg = {"bad": C["blood"], "warn": C["bronze_hi"],
                      "ok": C["moss"], "new": C["sky"]}.get(kind, C["ash"])
                p.setFont(opt.font)
                if line:
                    edge = QColor(fg)
                    edge.setAlphaF(0.55)
                    p.setPen(QPen(edge, 1.2))
                    p.setBrush(Qt.BrushStyle.NoBrush)
                    p.drawRoundedRect(r.adjusted(0.6, 0.6, -0.6, -0.6), 6, 6)
                else:
                    bg = QColor(fg)
                    bg.setAlphaF(0.16)
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(bg)
                    p.drawRoundedRect(r, 6, 6)
                p.setPen(QColor(fg))
                p.drawText(r, Qt.AlignmentFlag.AlignCenter, text)
        p.restore()
        self._grid(p, opt)

    @staticmethod
    def _grid(p, opt):
        r = opt.rect
        p.save()
        line = QColor(C["ridge"])
        line.setAlphaF(GRID_ALPHA)                 # the list's grid: there, but quiet
        p.setPen(line)
        p.drawLine(r.left(), r.bottom(), r.right(), r.bottom())
        if r.right() < opt.widget.viewport().width() - 2:      # no line on the outer edge
            p.drawLine(r.right(), r.top(), r.right(), r.bottom())
        p.restore()


class Worker(QThread):
    done = pyqtSignal(object)
    failed = pyqtSignal(str)

    def __init__(self, fn, *args):
        super().__init__()
        self.fn, self.args = fn, args

    def run(self):
        prof = perf_start()
        start = time.perf_counter()
        try:
            self.done.emit(self.fn(*self.args))
        except Exception as e:
            self.failed.emit(f"{e}\n\n{traceback.format_exc()}")
        finally:
            perf_stop(prof, getattr(self, "label", "a job"), time.perf_counter() - start)


TIP_RULE = f"<hr color='{C['ridge_hi']}' size='1'>"


def prio_label(pairs):
    """The number a mod shows: "4", or "4–5" for a mod with two folders."""
    return str(pairs[0][0]) if len(pairs) == 1 else f"{pairs[0][0]}–{pairs[-1][0]}"


def group_prio_label(numbers):
    """What a folded group's header shows for the priority numbers of the mods in it: "3–6" when
    they run in a row, "3 +2" when they don't (the lowest, and how many more), "–" for none."""
    nums = sorted(set(numbers))
    if not nums:
        return "–"
    if len(nums) == 1:
        return str(nums[0])
    if nums[-1] - nums[0] == len(nums) - 1:
        return f"{nums[0]}–{nums[-1]}"
    return f"{nums[0]} +{len(nums) - 1}"


def prio_start(text):
    m = re.match(r"\d+", text or "")
    return int(m.group()) if m else 0


def menu_tip(names, enabled=True, left_out=False):
    """The tooltip of a mod's menu sign in the list: the menu files it adds to the game (left_out:
    you switched its menu off)."""
    note = ("Left out: you switched its menu off. Right-click → Edit… to add it." if left_out
            else "" if enabled else "Switched off, so not in the game now.")
    return (f"<b>Adds {'a menu' if len(names) == 1 else 'menus'} to the game</b>" + TIP_RULE
            + "<br>".join(file_html(n) for n in names)
            + (f"{TIP_RULE}<span style='color:{C['ash']}'>{note}</span>" if note else ""))


def precompiled_tip(blob):
    """The note at the end of a priority tooltip for a mod with precompiled scripts: what they
    do to loose scripts. They don't get a number for it (see ModManager.clashes)."""
    if not blob:
        return ""
    return (f"<p style='margin:10px 0 0 0; color:{C['ash']}'>Its precompiled scripts win over loose "
            "ones for the same function.</p>")


def priority_tip(mod, rows, has_prefix, shared=(), legacy_on=False, blob=None):
    """rows: [(number, folder)] as mods.settings has them — the list shows the same numbers.
    shared: [(folder, the mod whose number it goes by, that number)] for a mod sharing its
    folder with one that has a higher priority."""
    if not mod["enabled"]:
        return f"<span style='color:{C['ash']}'>Disabled, not in the game.</span>"
    return _priority_tip(mod, rows, has_prefix, shared, legacy_on, blob) + precompiled_tip(blob)


def _priority_tip(mod, rows, has_prefix, shared, legacy_on, blob=None):
    if not rows and shared:
        return ("<b>Shares its folder</b>" + TIP_RULE + "<br>".join(
            f"<span style='color:{C['steel']}'>mods/</span>{html.escape(folder)} goes by "
            f"{html.escape(other)}'s number ({n}). Where both have a file, {html.escape(other)}'s is used."
            for folder, other, n in shared))
    if not rows:
        return ("<b>No priority needed</b>" + TIP_RULE +
                "Nothing clashes, so order doesn't matter.<br>"
                "A clash gets a number by itself.")
    kept = "1 is kept for merged scripts" + (", 2 for Script Merger's folder" if legacy_on else "")
    lines = [f"<b>Priority {prio_label(rows)}</b>: the lower number wins a clash."]
    lines += [f"<span style='color:{C['ash']}'>Double-click a number to change it, or drag the row.</span>", TIP_RULE]
    if len(rows) > 1:
        lines += ["One number per folder:"]
        lines += [f"&nbsp;&nbsp;{n}&nbsp;&nbsp;<span style='color:{C['steel']}'>mods/</span>"
                  f"{html.escape(name)}" for n, name in rows]
    lines.append(f"<span style='color:{C['ash']}'>{kept}.</span>")
    if not has_prefix:
        lines.append(f"<span style='color:{C['bronze_hi']}'>No prefix set, so mods.settings isn't written.</span>")
    return "<br>".join(lines)


def file_block(name, mods, winner=False, note=""):
    """A file name in blue, a little air, then the mods involved in load order. With
    winner=True the top one — the copy the game uses — is bold and the rest are grey."""
    lines = []
    for i, mod in enumerate(mods):
        mod = html.escape(mod)
        if winner:
            lines.append(f"<b>{mod}</b>" if i == 0 else f"<span style='color:{C['ash']}'>{mod}</span>")
        else:
            lines.append(mod)
    if note:
        lines.append(f"<span style='color:{C['ash']}'>{html.escape(note).replace(chr(10), '<br>')}</span>")
    return (f"<p style='margin:12px 0 0 0; color:{C['steel']}'>{html.escape(name)}</p>"
            f"<p style='margin:4px 0 0 0'>{'<br>'.join(lines)}</p>")


_PILLS = {}


def prio_badge(label):
    """A mod's priority number as a small rounded pill, like the list's, in front of its name in
    a tooltip. Drawn once per number into the app's scratch folder (tooltips show images, not
    rounded boxes)."""
    if label in _PILLS:
        return _PILLS[label]
    font = QApplication.font()
    fm = QFontMetricsF(font)
    h = round(fm.height()) + 2
    w = max(h + 6, round(fm.horizontalAdvance(label)) + 14)
    scale = 2                                      # drawn at twice the size: sharp on HiDPI screens
    img = QImage(w * scale, h * scale, QImage.Format.Format_ARGB32_Premultiplied)
    img.fill(Qt.GlobalColor.transparent)
    p = QPainter(img)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.scale(scale, scale)
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor(C["ridge_hi"]))
    p.drawRoundedRect(QRectF(0, 0, w, h), h / 2, h / 2)
    p.setFont(font)
    p.setPen(QColor(C["silver"]))
    p.drawText(QRectF(0, 0, w, h), Qt.AlignmentFlag.AlignCenter, label)
    p.end()
    UI_DIR.mkdir(parents=True, exist_ok=True)
    path = UI_DIR / ("prio_" + re.sub(r"[^0-9]+", "_", label) + ".png")
    img.save(str(path))
    _PILLS[label] = f"<img src='{path.as_posix()}' width='{w}' height='{h}' style='vertical-align: middle'>"
    return _PILLS[label]


def mod_lines(names, prio=None):
    """Mods one per line (names already formatted), each with its priority in front when it has
    one: a small table, so the names line up whatever the numbers' widths."""
    labels = [(prio or {}).get(key) for key, _shown in names]
    if not any(labels):
        return "<br>".join(shown for _key, shown in names)
    rows = "".join(f"<tr><td align='center' valign='middle' style='padding:1px 8px 1px 0'>{prio_badge(l) if l else ''}</td>"
                   f"<td valign='middle' style='padding:1px 0'>{shown}</td></tr>" for l, (_key, shown) in zip(labels, names))
    return f"<table cellspacing='0' cellpadding='0'>{rows}</table>"


# The order kinds of files are listed in a tooltip: what changes the story first (texts,
# journal, quests, scenes), then everything else, then what only changes how things look
# (entities, meshes, textures), mesh data last.
_KIND_FIRST = [".w3strings", ".journal", ".w2quest", ".w2phase", ".w2scene", ".w2behtree", ".w2comm",
               ".ws", ".xml", ".csv"]
_KIND_LAST = [".w2ent", ".w2mesh", ".w2mi", ".xbm", ".w2rig", ".w2anims", ".w2animev", ".w2fx", ".w2p",
              ".w2l", ".buffer"]


# what each kind of game file is, said shortly: the grey line over that kind's files in a
# tooltip. From the RED modding wiki's list of REDengine 3 formats (wiki.redmodding.org,
# redengine3-research, formats) and the game's own folders; a kind not listed gets no line
KIND_INFO = {
    ".w3strings": "Texts", ".journal": "Journal", ".w2quest": "Quests", ".w2phase": "Quest steps",
    ".w2qm": "Quest markers", ".w2je": "Journal entries", ".w2scene": "Scenes", ".w2cutscene": "Cutscenes",
    ".w2behtree": "NPC behavior", ".w2comm": "NPC spawns", ".spawntree": "Spawns", ".w2j": "NPC actions",
    ".w2steer": "Movement", ".ws": "Scripts", ".xml": "Game data", ".csv": "Data tables",
    ".w2ent": "Entities", ".w2mesh": "3D models", ".w2mi": "Materials", ".w2mg": "Shaders", ".xbm": "Textures",
    ".texarray": "Texture arrays", ".w2rig": "Skeletons", ".w3fac": "Facial rigs", ".w3dyng": "Dangle physics",
    ".w2ragdoll": "Ragdolls", ".w2anims": "Animations", ".w2p": "Particles", ".redcloth": "Cloth",
    ".redfur": "Hair (HairWorks)", ".redapex": "Destruction", ".reddest": "Destruction", ".w2w": "Worlds",
    ".w2l": "Level layers", ".w2ter": "Terrain", ".env": "Weather and lighting", ".vbrush": "Vegetation",
    ".flyr": "Trees", ".srt": "Trees (SpeedTree)", ".grassmask": "Grass", ".w2sf": "Foliage",
    ".navmesh": "NPC paths", ".w2em": "Map pins", ".w2fnt": "Fonts", ".redswf": "Menus and HUD",
    ".w3app": "Appearances", ".reddlc": "DLC definitions", ".redgame": "Game definitions",
    ".ini": "Settings files",
}


def _kind_rank(kind):
    if kind in _KIND_FIRST:
        return (0, _KIND_FIRST.index(kind), "")
    if kind in _KIND_LAST:
        return (2, _KIND_LAST.index(kind), "")
    return (1, 0, kind)


_BUFFER = re.compile(r"^(.*\.w2mesh)(\.\d+\.buffer)$", re.I)


_FOLDS = {}                   # key -> (folded, open) html of a kind's files, for ScrollTip to swap


TIP_PAD = "<!--pad-->"                           # where a fold's indent goes inside a file's note


def _join_lines(lines):
    """Lines of a tooltip, one under the other. A line ending in a note (a table) already ends
    its line: a break after it would leave an empty one."""
    out = ""
    for k, l in enumerate(lines):
        if k and not out.endswith(TIP_NOTE_END):
            out += "<br>"
        out += l
    return out


def note_html(note):
    """A note about one file, under it: indented past the file's name and dimmer, wrapping
    under itself (a table cell does that; spaces before the text wouldn't)."""
    rows = "".join(f"<tr><td>{TIP_PAD}&nbsp;&nbsp;&nbsp;&nbsp;</td><td style='color:{C['file_note']}'>{html.escape(n)}</td></tr>"
                   for n in note.split("\n") if n)
    return f"{TIP_NOTE}<table cellspacing='0' cellpadding='0'>{rows}</table>{TIP_NOTE_END}"


def _kind_block(b):
    """One kind of file in a tooltip, folded: a line with what it is (its extension when that
    isn't known) and how many. A click on it lists its files, another folds it back (ScrollTip)."""
    if b["kind"] == "label":                       # a line standing for many (texts): as it is
        return _join_lines([l.replace(TIP_PAD, "") for l in b["lines"]])
    label = KIND_INFO.get(b["kind"]) or b["kind"]
    n, total = b.get("count") or len(b["lines"]), b.get("total")
    # of how many of its kind the mod has in all, when known: "Textures 3/10"
    of = f"<span style='color:{C['file_ext']}'>/{total}</span>" if total and total >= n else ""
    head = lambda arrow: (f"<span style='color:{C['kind_light']}'>{arrow}&nbsp; {html.escape(label)}</span>"
                          f"&nbsp;&nbsp;<span style='color:{C['kind_deep']}'>{n}</span>{of}")
    key = hashlib.sha1("".join(b["lines"]).encode("utf-8", "replace")).hexdigest()[:16]
    link = lambda to, arrow: f"<a href='{to}:{key}' style='text-decoration:none'>{head(arrow)}</a>"
    folded = link("open", "▸")
    pad = "&nbsp;" * 5                           # its files sit under the label, past the arrow
    opened = _join_lines([link("fold", "▾")] + [pad + l.replace("<br>", "<br>" + pad).replace(TIP_PAD, pad) for l in b["lines"]])
    if len(_FOLDS) > 4000:
        _FOLDS.clear()
    _FOLDS[key] = (folded, opened, link("fold", "▾"), [l.replace(TIP_PAD, "") for l in b["lines"]])
    return f"<!--k:{key}-->{folded}<!--/k:{key}-->"            # every kind starts folded


TIP_COLS = "<!--cols-->"                          # a list laid out in columns: the tip takes their width
TIP_COL_MIN = 12                                  # fewer lines than this are never split into columns
TIP_COL_GAP = 28                                  # space between two columns, in px


def tip_columns(head, lines, k):
    """A kind's files in k columns, read down then across, under its folding line."""
    rows = -(-len(lines) // k)
    cols = [lines[i * rows:(i + 1) * rows] for i in range(k)]
    cells = "".join(f"<td valign='top' style='padding-right:{TIP_COL_GAP if i < len(cols) - 1 else 0}px'>"
                    f"{'<br>'.join(c)}</td>" for i, c in enumerate(cols) if c)
    return (f"{TIP_COLS}{head}<table cellspacing='0' cellpadding='0' style='margin-top:2px'><tr>"
            f"<td style='padding-right:0px'>{'&nbsp;' * 5}</td>{cells}</tr></table>")


def file_groups(entries, me=(), winner=False, prio=None, win=None, totals=None):
    """Files for a tooltip, compact: grouped by the mods involved, which are listed once per
    group, one per line, in load order. entries: [(in-game path, mods in load order, note)].
    With winner=True the first mod's copy is the one used: it's bold white and the others are
    grey. Bold means only that, everywhere: this copy wins. (me is kept for callers; unused.)
    Two files with the same name (items/ and items_plus/, say) share a line, with their folders.
    Files are listed by kind, story first; a mesh's .buffer files go on the mesh's own line.
    A thin line parts one group of mods from the next. totals ({extension: n}): how many files of
    each kind the mod has in all, shown after each kind's count ("Textures 3/10")."""
    me = {me} if isinstance(me, str) else set(me)
    groups = {}
    labels = {}                                     # a line shown as something else than its path
    for entry in entries:
        path, mods, note = entry[:3]
        if len(entry) > 3 and entry[3]:
            labels[path] = entry[3]
        groups.setdefault(tuple(dict.fromkeys(mods)), []).append((path, note or ""))
    ash, silver = C["ash"], C["silver"]
    out, groups_out = [], []
    for key, files in sorted(groups.items(), key=lambda g: (-len(g[1]), [x.lower() for x in g[0]])):
        mods = []
        for i, name in enumerate(key):
            if winner:                          # bold white: its copy is used; grey: overridden
                shown = f"<b>{html.escape(name)}</b>" if i == 0 else f"<span style='color:{ash}'>{html.escape(name)}</span>"
                top = (win or {}).get(key[0])
                if i > 0 and top and (win or {}).get(name) and win[name] != top:
                    # a click makes this one win over the bold one (see ScrollTip, MainWindow.make_win)
                    shown = f"<a href='win:{win[name]}:{top}' style='text-decoration:none'>{shown}</a>"
            else:
                shown = html.escape(name)       # merged: every mod's changes went in, all equal
            mods.append((name, shown))
        # a mesh's data (x.w2mesh.1.buffer) rides on the mesh's line when the mesh is listed too
        paths = {p.lower(): p for p, _n in files}
        buffers = {}
        kept = []
        for path, note in files:
            m = _BUFFER.match(path)
            if m and not note and m.group(1).lower() in paths and path not in labels:
                buffers.setdefault(m.group(1).lower(), []).append(m.group(2))
            else:
                kept.append((path, note))
        # twins: same name and same note on one line. Files are sorted by kind (extension), story
        # first, so every .w2phase sits together, every .w2mesh together…, with a little space between kinds
        kind = lambda name: Path(name).suffix.lower()
        joined = {}
        # a name that says nothing on its own (".w2ent", nothing before the dot) is shown with its folders
        shown_as = lambda p: labels.get(p) or (Path(p).name if Path(p).name.split(".")[0] else p)
        rank = lambda p: (-1, 0, "") if p in labels else _kind_rank(kind(p))
        extra = {}
        for path, note in sorted(kept, key=lambda f: (rank(f[0]), shown_as(f[0]).lower(), f[0].lower())):
            k = (shown_as(path), note)
            joined.setdefault(k, []).append("" if path in labels else Path(path).parent.name)
            for b in buffers.get(path.lower(), ()):
                extra.setdefault(k, []).append(b)
        blocks, last = [], None
        for (name, note), folders in joined.items():
            many = len(folders) if name in labels.values() else 0   # a labelled line stands for this many
            files_here = len(folders)                               # one entry per file on this line
            folders = [f for f in folders if f]
            this = "label" if name in labels.values() else kind(name)
            if this != last:
                blocks.append({"kind": this, "lines": [], "count": 0,
                               "total": (totals or {}).get(this) if this != "label" else None})
            last = this
            blocks[-1]["count"] += max(1, files_here)               # twins on one line count each
            line = file_html(name)
            bufs = sorted(set(extra.get((name, note), ())))
            if bufs:
                line += f"&nbsp;&nbsp;<span style='color:{C['file_ext']}'>+ {html.escape(' '.join(bufs))}</span>"
            if len(folders) > 1:
                shown = " · ".join(dict.fromkeys(folders)) if len(set(folders)) == len(folders) else f"×{len(folders)}"
                line += f"&nbsp;&nbsp;<span style='color:{ash}'>{html.escape(shown)}</span>"
            if many > 1:
                line += f"&nbsp;&nbsp;<span style='color:{C['file_name']}'>{many}</span>"
            if note:
                line += note_html(note)
            blocks[-1]["lines"].append(line)
        groups_out.append((mod_lines(mods, prio), blocks))
    for listed, blocks in groups_out:
        top = 0 if out else 10                  # after a dividing line the group starts right below it
        inner = [_kind_block(b) for b in blocks]
        if listed.startswith("<table"):
            # with priority pills: the files line up under the mods' names, past the pills, a line below them
            files_html = "".join(f"<p style='margin:{0 if k == 0 else 7}px 0 0 0'>{b}</p>" for k, b in enumerate(inner))
            out.append(listed.replace("<table ", f"<table style='margin-top:{top}px; color:{silver}' ", 1)
                       .replace("</table>", f"<tr><td></td><td style='padding-top:18px'>{files_html}</td></tr></table>"))
        else:
            files_html = "".join(f"<p style='margin:{18 if k == 0 else 7}px 0 0 0'>{b}</p>" for k, b in enumerate(inner))
            out.append(f"<p style='margin:{top + 2 if out else 12}px 0 0 0; color:{silver}'>{listed}</p>" + files_html)
    # a thin line between groups, at the end of the group above it
    rule = (f"<table width='100%' style='margin-top:12px' cellspacing='0' cellpadding='0'><tr>"
            f"<td style='border-top:1px solid {C['tip_rule']}; font-size:1px'>&nbsp;</td></tr></table>")
    return [g + rule if k < len(out) - 1 else g for k, g in enumerate(out)]


# Explanations in a tooltip wrap to the width of what it lists (file and mod names), never
# widening it themselves. They're marked so ScrollTip can measure the tooltip without them.
TIP_NOTE, TIP_NOTE_END = "<!--note-->", "<!--/note-->"
_TIP_NOTES = re.compile(re.escape(TIP_NOTE) + ".*?" + re.escape(TIP_NOTE_END), re.S)


def tip_section(title, colour, blocks, note="", rich=False):
    """A coloured title, an optional grey line on what it means, then the blocks. Everything
    is a paragraph, so Qt's spacing stays even. rich: the title is HTML, coloured by its own
    parts (the title's colour is then only the default)."""
    head = f"<p style='margin:0'><b style='color:{C[colour]}'>{title if rich else html.escape(title)}</b>"
    if note:
        head += f"<br>{TIP_NOTE}<span style='color:{C['ash']}'>{html.escape(note)}</span>{TIP_NOTE_END}"
    head += "</p>"
    return head + "".join(b if b.startswith("<p") else f"<p style='margin:10px 0 0 0'>{b}</p>" for b in blocks)


def targets_html(target):
    """mods/ and dlc/ in a cool grey-blue so the parent folder stands out."""
    head, slash, rest = target.partition("/")
    head = f"<span style='color:{C['steel']}'>{html.escape(head)}{slash}</span>"
    return head + html.escape(rest)


class ScrollTip(QFrame):
    """A tooltip that can be read to the end: as tall as the monitor allows, well clear of its
    top and bottom edges,
    wider when it needs to be, scrollable with the wheel or Up/Down/Page keys, and a fade
    with "more" at the bottom while there's more below. Stays open while the pointer is on
    its cell or on the tip itself, so you can move onto it to scroll."""
    winClicked = pyqtSignal(str, str)          # a mod's name clicked: (that mod, the one it should win over)
    PAD = 24                                   # air between the tip and the screen edges
    PANEL = 56                                 # room kept for a bottom panel Qt can't see
    SHADOW = 16                                # transparent margin around the box, for its shadow

    @classmethod
    def screen_room(cls, screen):
        """The screen minus a margin all round. On Wayland Qt often can't see desktop panels
        (the usable area comes back as the whole screen), so then extra room is kept at the
        bottom, where KDE puts its panel by default."""
        full, avail = screen.geometry(), screen.availableGeometry()
        bottom = cls.PAD + (cls.PANEL if avail == full else 0)
        return avail.adjusted(cls.PAD, cls.PAD, -cls.PAD, -bottom)

    EDGE = 0.12                                # air kept round a tooltip, as a share of the monitor

    @classmethod
    def tip_room(cls, screen):
        """Where a tooltip may go on the monitor: well clear of its edges, by EDGE of its height
        at the top and bottom and EDGE of its width at the sides, so the same on any monitor."""
        area = cls.screen_room(screen)
        avail = screen.availableGeometry()
        v = int(screen.geometry().height() * cls.EDGE)
        h = int(screen.geometry().width() * cls.EDGE)
        top, bottom = max(area.top(), avail.top() + v), min(area.bottom(), avail.bottom() - v)
        left, right = max(area.left(), avail.left() + h), min(area.right(), avail.right() - h)
        return QRect(left, top, max(1, right - left + 1), max(1, bottom - top + 1))

    @staticmethod
    def window_pos_known():
        """Does the app know where its window is on the monitor? Not on Wayland: there an app
        is only told its window's size."""
        return not QGuiApplication.platformName().lower().startswith("wayland")

    def room(self, screen):
        """Where the tip may go: the monitor, clear of its edges (tip_room), wherever the app's
        window is on it. On Wayland, where the app isn't told where its window sits, it's an area the
        monitor's size centred on the window: a maximised window gives exactly the monitor, and
        with a smaller one the desktop moves a tip that would run past the monitor's edge back
        onto it."""
        area = self.tip_room(screen)
        if not self.window_pos_known():
            win = self.parentWidget().window() if self.parentWidget() is not None else None
            if win is not None and win.isVisible():
                centre = QRect(win.mapToGlobal(QPoint(0, 0)), win.size()).center()
                full = self.screen_room(screen)
                area = QRect(area)
                area.moveCenter(QPoint(centre.x(), centre.y() + (area.center().y() - full.center().y())))
        # the row it belongs to stays within reach: a chip near the monitor's top or bottom edge
        # gets its tip right beside it, not one stopped short with a gap to cross
        # (the same at the sides: a chip close to the monitor's left edge keeps its tip by it)
        if self.anchor is not None:
            area.setTop(min(area.top(), self.anchor.top()))
            area.setBottom(max(area.bottom(), self.anchor.bottom()))
            area.setLeft(min(area.left(), self.anchor.left()))
        return area

    SPARE_LINES = 6                            # this many lines over the window: taller, not scrolled

    def stretch(self, area, need, screen):
        """A tooltip only a few lines taller than the room inside the window may grow past it
        (half above, half below) instead of scrolling, as long as it still fits on the screen.
        Anything longer keeps to the window and scrolls."""
        over = need - area.height()
        if over <= 0 or over > self.SPARE_LINES * self.text.fontMetrics().lineSpacing():
            return area
        if need > self.tip_room(screen).height():
            return area
        up = over // 2 + 1
        return area.adjusted(0, -up, 0, over - up + 2)

    def __init__(self, parent):
        super().__init__(parent, Qt.WindowType.ToolTip | Qt.WindowType.FramelessWindowHint)
        self.setObjectName("ScrollTip")
        self.setAttribute(Qt.WidgetAttribute.WA_ShowWithoutActivating)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)   # for the shadow around the box
        outer = QVBoxLayout(self)
        outer.setContentsMargins(*([self.SHADOW] * 4))
        self.body = QFrame(objectName="TipBody")
        outer.addWidget(self.body)
        lay = QVBoxLayout(self.body)
        lay.setContentsMargins(1, 1, 1, 1)
        self.area = QScrollArea()
        self.area.setWidgetResizable(True)
        self.area.setFrameShape(QFrame.Shape.NoFrame)
        self.area.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        # the scrollbar's room is always kept (it's only drawn when there's something to scroll), so
        # a tip that turns out a little taller than worked out, or gets longer when a kind of file
        # opens, doesn't jump wider or re-wrap when its scrollbar appears
        self.area.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOn)
        self.area.verticalScrollBar().setProperty("idle", True)
        self.area.verticalScrollBar().rangeChanged.connect(self._bar_idle)
        self.text = QLabel(objectName="TipText")
        self.text.setTextFormat(Qt.TextFormat.RichText)
        self.text.setWordWrap(True)
        self.text.setContentsMargins(12, 10, 12, 14)     # breathing room inside, most at the bottom
        self.text.setAlignment(Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft)
        self.text.setTextInteractionFlags(Qt.TextInteractionFlag.LinksAccessibleByMouse)
        self.text.linkActivated.connect(self._toggle_kind)     # a folded kind of file: open or fold it
        self._pos = self._placed = None
        self.area.setWidget(self.text)
        self.area.viewport().installEventFilter(self)       # the scrollbar coming or going re-wraps
        self._fitting = False
        lay.addWidget(self.area)
        self.more = QLabel("▾  more", self.body, objectName="TipMore")
        self.more.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.more.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self.more.hide()
        self.area.verticalScrollBar().valueChanged.connect(self._update_more)
        self.area.verticalScrollBar().rangeChanged.connect(self._update_more)
        self.anchor = None                     # global rect of the cell it belongs to
        self._watch = QTimer(self)
        self._watch.setInterval(150)
        self._watch.timeout.connect(self._maybe_hide)
        # Where the pointer is, as the app itself saw it. The screen position (QCursor.pos) can't be
        # trusted: on Wayland it stops updating once the pointer leaves the app's windows, so a tip
        # would think it was still being hovered and stay on screen.
        self._over_tip = False
        self._in_view = False
        self._left_at = 0.0
        self._on_anchor_at = 0.0
        self._last = None
        app = QApplication.instance()
        if app is not None:
            app.applicationStateChanged.connect(self._app_state)

    def _bar_idle(self, _lo, hi):
        """The scrollbar drawn only while there's something to scroll (its room is always kept)."""
        bar = self.area.verticalScrollBar()
        if bar.property("idle") != (hi == 0):
            bar.setProperty("idle", hi == 0)
            bar.style().unpolish(bar)
            bar.style().polish(bar)
            bar.update()

    def _toggle_kind(self, href):
        """A click on a folded kind of file (see _kind_block): swap it for its files, or back."""
        what, _, key = href.partition(":")
        if what == "win":
            mid, _, over = key.partition(":")
            self.winClicked.emit(mid, over)
            return
        pair = _FOLDS.get(key)
        if pair is None or what not in ("open", "fold") or self._pos is None:
            return
        src = self.text.text()
        mark = re.compile(r"(<!--k:" + re.escape(key) + r"-->).*?(<!--/k:" + re.escape(key) + r"-->)", re.S)
        put = lambda part: mark.sub(lambda m: m.group(1) + part + m.group(2), src, count=1)
        new = put(pair[1] if what == "open" else pair[0])
        if what == "open" and len(pair) > 3:
            new = self._in_columns(new, put, pair)
        if new == src:
            return
        keep = self.area.verticalScrollBar().value()
        # where it was put, as the app itself placed it: the window's position read back can be
        # off by a few pixels (it is on Wayland), and each click would move it by that much
        top = self._placed or self._box().topLeft()
        self.show_tip(new, self._pos, self.anchor, at=top)
        self.area.verticalScrollBar().setValue(keep)

    def _measure(self, html_text):
        """(its widest line, its height at a width) for a tooltip's text, as show_tip lays it out."""
        doc = QTextDocument()
        doc.setDefaultFont(self.text.font())
        doc.setDocumentMargin(0)
        doc.setHtml(html_text)
        m = self.text.contentsMargins()

        def height(w):
            doc.setTextWidth(w)
            return int(doc.size().height()) + m.top() + m.bottom() + 16
        return doc.idealWidth() + 2, height

    def _text_room(self):
        """(width, height) the text may take on this screen, inside the tip's frame and scrollbar."""
        screen = QApplication.screenAt(self._pos) or QApplication.primaryScreen()
        avail = self.room(screen)
        m = self.text.contentsMargins()
        return (avail.width() - m.left() - m.right() - 12 - self.area.verticalScrollBar().sizeHint().width(),
                avail.height() - 2)

    def _in_columns(self, new, put, pair):
        """A kind of file opened with more lines than fit: in two or three columns, as few as it
        takes to fit (or as many as the screen's width allows), never wider than the screen."""
        lines = pair[3]
        if len(lines) < TIP_COL_MIN or any(TIP_NOTE in l or "<table" in l for l in lines):
            return new
        room_w, room_h = self._text_room()
        wide, height = self._measure(new)
        if height(min(wide, room_w)) <= room_h:
            return new                                # fits as one list: nothing to split
        best = new
        for k in (2, 3):
            html_k = put(tip_columns(pair[2], lines, k))
            wide_k, height_k = self._measure(html_k)
            if wide_k > room_w:
                break                                 # no room for this many side by side
            best = html_k
            if height_k(wide_k) <= room_h:
                break                                 # fits now: no more columns than that
        return best

    def show_tip(self, html_text, pos, anchor, at=None):
        self._pos = pos
        self.anchor = anchor                   # the room keeps its row within reach
        screen = QApplication.screenAt(pos) or QApplication.primaryScreen()
        avail = self.room(screen)
        self.text.setText(html_text)
        self.area.verticalScrollBar().setValue(0)
        # measure the text itself: its natural width up to half the screen (wider text wraps),
        # its height at that width, then cap the height at the screen and scroll the rest
        m = self.text.contentsMargins()
        doc = QTextDocument()
        doc.setDefaultFont(self.text.font())
        doc.setDocumentMargin(0)
        doc.setHtml(html_text)
        char = self.text.fontMetrics().averageCharWidth()
        line = char * 64                                              # a comfortable reading width
        natural = doc.idealWidth() + 2
        if TIP_NOTE in html_text:
            # explanations wrap to what the tooltip lists, with a little room to spare
            bare = QTextDocument()
            bare.setDefaultFont(self.text.font())
            bare.setDocumentMargin(0)
            bare.setHtml(_TIP_NOTES.sub("", html_text))
            natural = min(natural, max(bare.idealWidth() + 2 + 2 * char, char * 34))
        text_w = min(natural, avail.width() // 2 - m.left() - m.right(), line)

        def need_at(w):
            doc.setTextWidth(w)
            return int(doc.size().height()) + m.top() + m.bottom() + 16     # the label lays out a touch taller
        need = need_at(text_w)
        room_w = avail.width() - m.left() - m.right() - 12 - self.area.verticalScrollBar().sizeHint().width()
        # how wide what it lists is (its explanation lines left out: they wrap to the list, and
        # never widen a tooltip themselves)
        widest = max(text_w, min(natural, room_w))
        if TIP_COLS in html_text:
            text_w = widest                           # a list in columns: as wide as its columns
        elif need > avail.height() - 2 and widest > text_w:
            # too tall to fit: wider before it scrolls, but only where that really makes it
            # shorter (wrapped lines straightening out), and only as wide as it takes
            room_h = avail.height() - 2
            best = need_at(widest)
            if best < need - 3 * self.text.fontMetrics().lineSpacing():
                goal = room_h if best <= room_h else best + self.text.fontMetrics().lineSpacing()
                lo, hi = text_w, widest
                while hi - lo > 6:
                    mid = (lo + hi) / 2
                    lo, hi = (lo, mid) if need_at(mid) <= goal else (mid, hi)
                text_w = hi
        need = need_at(text_w)
        # with the scrollbar's room in, whether it's needed or not (see __init__)
        width = min(int(text_w) + m.left() + m.right() + 4 + self.area.verticalScrollBar().sizeHint().width() + 6,
                    avail.width())
        avail = self.stretch(avail, need + 2, screen)
        height = min(need, avail.height() - 2)            # the frame adds 2 px
        x = min(max(pos.x() + 14, avail.left()), avail.right() - width)
        y = pos.y() + 18
        self._keep_top = None
        if at is not None:                    # opened or folded in place: it stays where it was,
            x, y = min(at.x(), avail.right() - width), at.y()     # and scrolls when longer than the room below
            if avail.bottom() - y >= 240:
                height = min(height, avail.bottom() - y)
                self._keep_top = y
        if y + height + 2 > avail.bottom() + 1:          # the box is height + 2 tall (its frame)
            y = max(avail.top(), avail.bottom() + 1 - (height + 2))
        self._set_box(QRect(x, y, width + 2, height + 2))
        self._placed = QPoint(x, y)
        self.anchor = anchor
        self._in_view, self._last = True, anchor.center() if anchor is not None else None
        self._on_anchor_at = time.monotonic()
        self._fit_text()
        self.show()
        self.raise_()
        self._place_more()
        self._update_more()

    def _box(self):
        """The visible box, in screen coordinates (the window is bigger by the shadow margin)."""
        s = self.SHADOW
        return self.geometry().adjusted(s, s, -s, -s)

    def _set_box(self, r):
        s = self.SHADOW
        self.setGeometry(r.adjusted(-s, -s, s, s))

    def paintEvent(self, e):
        """A soft shadow under the box, a little lower than it, so the tip lifts off the list."""
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        s = self.SHADOW
        box = QRectF(s, s, self.width() - 2 * s, self.height() - 2 * s)
        for i in range(s, 0, -1):
            path = QPainterPath()
            path.addRoundedRect(box.adjusted(-i, -i + 5, i, i + 5), 6 + i, 6 + i)
            p.fillPath(path, QColor(0, 0, 0, int(70 * (1 - i / s) ** 2 + 2)))
        p.end()

    def eventFilter(self, obj, e):
        if e.type() == QEvent.Type.Resize and obj is self.area.viewport() and self.isVisible() \
                and e.oldSize().width() != e.size().width():
            self._fit_text()
        return False

    def _fit_text(self):
        """Make the text exactly as tall as it is at the width it really has, and the tip no
        taller than that. Qt's own estimate for wrapped text can come out far too tall (it's
        worked out at the narrowest width the text could wrap to), which left long empty
        stretches at the bottom of big tooltips."""
        if self._fitting:
            return
        m = self.text.contentsMargins()
        width = self.area.viewport().width()
        if width <= 0:
            return
        self._fitting = True
        try:
            self._fit_now(m, width)
        finally:
            self._fitting = False

    def _fit_now(self, m, width):
        doc = QTextDocument()
        doc.setDefaultFont(self.text.font())
        doc.setDocumentMargin(0)
        doc.setHtml(self.text.text())
        doc.setTextWidth(max(1, width - m.left() - m.right()))
        need = int(doc.size().height() + 0.999) + m.top() + m.bottom() + 2
        if self.text.height() != need or self.text.minimumHeight() != need:
            self.text.setFixedHeight(need)
        # as tall as the text, as far as the screen allows: no room left over, no needless scrolling
        screen = self.screen() or QApplication.primaryScreen()
        room = self.stretch(self.room(screen), need + 4, screen)
        if getattr(self, "_keep_top", None) is not None:
            room.setTop(self._keep_top)       # opened in place: grow down only, then scroll
        want = min(need + 4, room.height())
        g = self._box()
        if want != g.height():
            g.setHeight(want)
            if g.bottom() > room.bottom():
                g.moveBottom(room.bottom())
            self._set_box(g)
        self._watch.start()

    def scroll_by(self, key):
        bar = self.area.verticalScrollBar()
        step = {Qt.Key.Key_Up: -bar.singleStep() * 3, Qt.Key.Key_Down: bar.singleStep() * 3,
                Qt.Key.Key_PageUp: -bar.pageStep(), Qt.Key.Key_PageDown: bar.pageStep()}.get(key)
        if step is None:
            return False
        bar.setValue(bar.value() + step)
        return True

    def resizeEvent(self, e):
        super().resizeEvent(e)
        if self.isVisible() and e.oldSize().width() != e.size().width():
            self._fit_text()                               # a new width wraps the text anew
        self._place_more()

    def _place_more(self):
        h = self.more.sizeHint().height() + 8
        self.more.setGeometry(1, self.body.height() - h - 1, self.body.width() - 2, h)

    def _update_more(self, *_):
        bar = self.area.verticalScrollBar()
        if 0 < bar.maximum() <= 40 and self.isVisible():
            # only a few pixels short: grow to fit when the screen has room, instead of scrolling
            g = self._box()
            screen = self.stretch(self.room(self.screen()), g.height() + bar.maximum(), self.screen())
            if g.height() + bar.maximum() <= screen.height():
                g.setHeight(g.height() + bar.maximum())
                if g.bottom() > screen.bottom():
                    g.moveBottom(screen.bottom())
                self._set_box(g)
                return
        self.more.setVisible(bar.maximum() > 0 and bar.value() < bar.maximum())
        self.more.raise_()

    # --- what the list tells the tip about the pointer
    def pointer_at(self, global_pos):
        self._in_view, self._last = True, global_pos
        if self.anchor is not None and self.anchor.contains(global_pos):
            self._on_anchor_at = time.monotonic()

    def pointer_left(self):
        self._in_view, self._left_at = False, time.monotonic()

    def enterEvent(self, e):
        self._over_tip = True
        super().enterEvent(e)

    def leaveEvent(self, e):
        self._over_tip = False
        self._left_at = time.monotonic()
        super().leaveEvent(e)

    def _app_state(self, state):
        if state != Qt.ApplicationState.ApplicationActive:
            self.hide_tip()                     # alt-tab, or another window took over
            QToolTip.hideText()

    def _maybe_hide(self):
        if QApplication.applicationState() != Qt.ApplicationState.ApplicationActive:
            self.hide_tip()
            return
        if self._over_tip:
            return                              # reading or scrolling it
        if self._in_view:
            if self.anchor is not None and self._last is not None and self.anchor.contains(self._last):
                return                          # still on its chip
            if time.monotonic() - self._on_anchor_at < 0.25:
                return                          # crossing the few pixels between chip and tip
            self.hide_tip()
            return
        if time.monotonic() - self._left_at < 0.35:
            return                              # a moment to move from the chip onto the tip
        self.hide_tip()

    def hide_tip(self):
        self._watch.stop()
        self.anchor = None
        self._over_tip = False
        self.hide()


class ModTree(QTreeWidget):
    orderChanged = pyqtSignal()
    filesDropped = pyqtSignal(list)
    collapseChanged = pyqtSignal(str, bool)

    def __init__(self):
        super().__init__()
        self.tip = ScrollTip(self)
        self.filtering = False                       # while the filter is on, rows aren't linked
        self.setHeaderLabels(["Priority", "Mod", "Version", "Status", "Installed"])
        self.setRootIsDecorated(False)
        self.setIndentation(0)
        self.setUniformRowHeights(True)
        self.setObjectName("ModList")
        self.setItemDelegate(RowDelegate(self))
        self.setMouseTracking(True)
        self.setSelectionMode(QAbstractItemView.SelectionMode.ExtendedSelection)
        self.setDragDropMode(QAbstractItemView.DragDropMode.InternalMove)
        self.setDefaultDropAction(Qt.DropAction.MoveAction)
        self.setDragDropOverwriteMode(False)
        self.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)   # edits start on double-click, F2 or the menu
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        h = self.header()
        for c in range(COLUMNS):
            h.setSectionResizeMode(c, QHeaderView.ResizeMode.ResizeToContents)
        h.setSectionResizeMode(NAME_COL, QHeaderView.ResizeMode.Stretch)
        h.setMinimumSectionSize(70)
        h.setStretchLastSection(False)

    def sep_blocks(self):
        """[(separator item or None, [member items])] in list order."""
        blocks, current, members = [], None, []
        for i in range(self.topLevelItemCount()):
            it = self.topLevelItem(i)
            if it.data(0, SEP_ROLE):
                blocks.append((current, members))
                current, members = it, []
            else:
                members.append(it)
        blocks.append((current, members))
        return [b for b in blocks if b[0] is not None or b[1]]

    def refresh_counts(self):
        for sep, members in self.sep_blocks():
            if sep is not None:
                members = [it for it in members if not it.data(0, GHEAD_ROLE)]     # mods, not group headers
                on = sum(1 for it in members if it.checkState(NAME_COL) == Qt.CheckState.Checked)
                sep.setData(0, COUNT_ROLE, (on, len(members)))

    def group_items(self, gid):
        """The rows of the mods in a group (not its header)."""
        out = []
        for i in range(self.topLevelItemCount()):
            it = self.topLevelItem(i)
            g = it.data(NAME_COL, GROUP_ROLE)
            if g and g.get("run") == gid and not it.data(0, GHEAD_ROLE):
                out.append(it)
        return out

    def apply_collapse(self, filtering=False):
        folded = set()
        for i in range(self.topLevelItemCount()):
            it = self.topLevelItem(i)
            if it.data(0, GHEAD_ROLE) and it.data(0, COLLAPSED_ROLE):
                folded.add(it.data(0, GHEAD_ROLE))
        for sep, members in self.sep_blocks():
            hide = bool(sep is not None and sep.data(0, COLLAPSED_ROLE) and not filtering)
            for it in members:
                g = it.data(NAME_COL, GROUP_ROLE)
                in_fold = bool(g and not g["main"] and g.get("run") in folded and not filtering)
                if hide or in_fold:
                    it.setHidden(True)
                elif not filtering:
                    it.setHidden(False)

    def toggle_collapse(self, item, value=None):
        if not (item.data(0, SEP_ROLE) or item.data(0, GHEAD_ROLE)):
            return
        state = (not item.data(0, COLLAPSED_ROLE)) if value is None else value
        item.setData(0, COLLAPSED_ROLE, state)
        if item.data(0, GHEAD_ROLE):                     # folded: no line down from its checkbox
            g = dict(item.data(NAME_COL, GROUP_ROLE) or {})
            g["next"] = not state
            item.setData(NAME_COL, GROUP_ROLE, g)
        self.apply_collapse()
        self.collapseChanged.emit(item.data(0, Qt.ItemDataRole.UserRole), state)
        if value is None and not state and item.data(0, SEP_ROLE):     # you opened it (not a drag or the app)
            QTimer.singleShot(0, lambda: self.show_section(item))

    def show_section(self, sep):
        """Scroll an opened section's mods into view, only as far as needed: nothing moves when
        they fit already, and its header never leaves the top. Taller than the list: header on top."""
        try:
            self.executeDelayedItemsLayout()
            members = next((m for s, m in self.sep_blocks() if s is sep), [])
            shown = [it for it in members if not it.isHidden()]
            if not shown:
                return
            head, last = self.visualItemRect(sep), self.visualItemRect(shown[-1])
            room = self.viewport().height()
            if head.isNull() or last.isNull() or last.bottom() < room:
                return                                   # all of it on screen already
            if last.bottom() - head.top() >= room:
                self.scrollToItem(sep, QAbstractItemView.ScrollHint.PositionAtTop)
            else:
                self.scrollToItem(shown[-1], QAbstractItemView.ScrollHint.PositionAtBottom)
        except RuntimeError:
            pass                                         # the list was rebuilt meanwhile

    def chip_at(self, pos):
        """(the status chip's tooltip, its rectangle on screen) under a viewport point, or None.
        A mod's menu sign in its name cell counts as one."""
        idx = self.indexAt(pos)
        if idx.isValid() and idx.column() == NAME_COL and idx.data(MENU_ROLE):
            box = RowDelegate.menu_rect(self.visualRect(idx)).adjusted(-5, -8, 5, 8)
            if box.contains(QPointF(pos)):
                box = box.toAlignedRect()
                return idx.data(MENU_ROLE), QRect(self.viewport().mapToGlobal(box.topLeft()), box.size())
            return None
        if not idx.isValid() or idx.column() != CONFLICT_COL:
            return None
        chips = idx.data(CHIPS_ROLE) or []
        for c, r in zip(chips, RowDelegate.chip_rects(self.visualRect(idx), self.fontMetrics(), chips)):
            box = r.adjusted(-3, -9, 3, 9)                    # the gap between chips counts too
            if len(c) > 2 and c[2] and box.contains(QPointF(pos)):
                box = box.toAlignedRect()
                return c[2], QRect(self.viewport().mapToGlobal(box.topLeft()), box.size())
        return None

    def viewportEvent(self, e):
        if e.type() == QEvent.Type.ToolTip:
            hit = self.chip_at(e.pos())
            if hit:
                QToolTip.hideText()
                tip, anchor = hit
                if not (self.tip.isVisible() and self.tip.anchor == anchor):
                    self.tip.show_tip(tip, e.globalPos(), anchor)
                return True
            self.tip.hide_tip()
            if self.indexAt(e.pos()).column() == CONFLICT_COL:
                QToolTip.hideText()
                return True                                  # beside the chips: no tooltip
        elif e.type() == QEvent.Type.MouseMove:
            local = e.position().toPoint()
            self.tip.pointer_at(self.viewport().mapToGlobal(local))
            if self.tip.isVisible():
                # moving straight onto the next chip swaps the tooltip at once, without waiting
                hit = self.chip_at(local)
                if hit and hit[1] != self.tip.anchor:
                    self.tip.show_tip(hit[0], e.globalPosition().toPoint(), hit[1])
                    self.tip.pointer_at(self.viewport().mapToGlobal(local))
        elif e.type() == QEvent.Type.Enter:
            self.tip._in_view = True
        elif e.type() == QEvent.Type.Leave:
            self.tip.pointer_left()             # the tip decides: onto it, or gone
        return super().viewportEvent(e)

    def keyPressEvent(self, e):
        if self.tip.isVisible():
            if e.key() == Qt.Key.Key_Escape:
                self.tip.hide_tip()
                return
            if self.tip.scroll_by(e.key()):
                return                       # Up/Down/Page scroll the open tip, not the list
        super().keyPressEvent(e)

    def startDrag(self, actions):
        extra = self.prepare_drag()
        try:
            super().startDrag(actions)
        finally:
            self.drag_ids = []
            for it in extra:                         # so "Remove section" later means just the section
                try:
                    it.setSelected(False)
                except RuntimeError:
                    pass

    def prepare_drag(self):
        """Dragging a separator takes its whole section along. Rows of a folded section are
        hidden and Qt never drags hidden rows, so they're remembered to put back under it.
        Returns the rows selected just for this drag."""
        extra = []
        self.drag_folded = {}
        for sep, members in self.sep_blocks():
            if sep is not None and sep.isSelected():
                if sep.data(0, COLLAPSED_ROLE):
                    self.drag_folded[sep.data(0, Qt.ItemDataRole.UserRole)] = \
                        [it.data(0, Qt.ItemDataRole.UserRole) for it in members]
                else:
                    extra += members
        for it in extra:
            it.setSelected(True)
        # a folded group's header: its hidden mods come along, put back under it afterwards
        hidden = {i for members in self.drag_folded.values() for i in members}
        for it in self.selectedItems():
            gid = it.data(0, GHEAD_ROLE)
            if gid and it.data(0, COLLAPSED_ROLE) and it.data(0, Qt.ItemDataRole.UserRole) not in hidden:
                self.drag_folded[it.data(0, Qt.ItemDataRole.UserRole)] = \
                    [m.data(0, Qt.ItemDataRole.UserRole) for m in self.group_items(gid)]
        # dragging a main mod takes its linked rows (optional files, patches) along, in order. They
        # only move in the list: their priority stays their own (see MainWindow.on_order_changed).
        # A group's header takes its mods along like a section: they move as one, priority too
        runs = {it.data(NAME_COL, GROUP_ROLE)["run"] for it in self.selectedItems()
                if (it.data(NAME_COL, GROUP_ROLE) or {}).get("main")}
        heads = {it.data(0, GHEAD_ROLE) for it in self.selectedItems() if it.data(0, GHEAD_ROLE)}
        self.drag_linked = []
        if runs and not getattr(self, "filtering", False):
            for i in range(self.topLevelItemCount()):
                it = self.topLevelItem(i)
                g = it.data(NAME_COL, GROUP_ROLE)
                if g and g["run"] in runs and not it.isSelected() and not it.isHidden():
                    it.setSelected(True)
                    extra.append(it)
                    if g["run"] not in heads:
                        self.drag_linked.append(it.data(0, Qt.ItemDataRole.UserRole))
        # which rows are being dragged, kept now: Qt's drop takes the rows out and puts them
        # back unselected, so afterwards the selection no longer says which ones moved
        self.drag_ids = [it.data(0, Qt.ItemDataRole.UserRole) for it in self.selectedItems()]
        self.drag_ids += [i for members in self.drag_folded.values() for i in members]
        return extra

    def _external(self, e):
        return e.mimeData().hasUrls() and e.source() is not self

    def dragEnterEvent(self, e):
        if self._external(e):
            e.acceptProposedAction()
        else:
            super().dragEnterEvent(e)

    def dragMoveEvent(self, e):
        if self._external(e):
            e.acceptProposedAction()
            return
        it = self.itemAt(e.position().toPoint())          # open a section you drag onto
        if it is not None and it.data(0, SEP_ROLE) and it.data(0, COLLAPSED_ROLE) \
                and not it.isSelected():                    # (not the one being dragged)
            self.toggle_collapse(it, False)
        super().dragMoveEvent(e)

    def dropEvent(self, e):
        if self._external(e):
            paths = [u.toLocalFile() for u in e.mimeData().urls() if u.isLocalFile()]
            paths = [p for p in paths if p.lower().endswith(ARCHIVE_EXTS)]
            e.acceptProposedAction()
            if paths:
                self.filesDropped.emit(paths)
            return
        super().dropEvent(e)
        self.orderChanged.emit()


def merger_ok(path):
    """Is this a Script Merger program that exists? Only then is it offered in the menu."""
    if not path:
        return False
    p = Path(str(path).strip()).expanduser()
    return p.is_file() and p.suffix.lower() == ".exe"


class SetupDialog(RememberingDialog):
    window_key = "setup"

    def __init__(self, parent, game="", prefix=""):
        super().__init__(parent)
        self.setWindowTitle("Settings")
        self.setMinimumWidth(680)
        v = QVBoxLayout(self)
        v.setContentsMargins(22, 20, 22, 18)
        v.setSpacing(12)
        t = QLabel("Settings", objectName="DialogTitle")
        v.addWidget(t)
        # one grid, three columns (label, field, one button), in groups with a small heading: every
        # field starts and ends at the same place, and every button is the same width
        grid = QGridLayout()
        grid.setHorizontalSpacing(12)
        grid.setVerticalSpacing(10)
        grid.setColumnStretch(1, 1)
        row = [0]
        labels, side = [], []

        def heading(text, first=False):
            h = QLabel(text, objectName="SectionHead")
            if not first:
                grid.setRowMinimumHeight(row[0], 10)          # a little air above each group
                row[0] += 1
            grid.addWidget(h, row[0], 0, 1, 3)
            row[0] += 1

        def line(label, field, button=None, tip=""):
            lab = QLabel(label)
            labels.append(lab)
            for w in (lab, field):
                if tip:
                    w.setToolTip(tip)
            grid.addWidget(lab, row[0], 0)
            grid.addWidget(field, row[0], 1)
            if button is not None:
                side.append(button)
                grid.addWidget(button, row[0], 2)
            row[0] += 1
            return lab

        def link(button):
            grid.addWidget(button, row[0], 1, Qt.AlignmentFlag.AlignLeft)
            row[0] += 1

        self.game = QLineEdit(str(game or ""))
        self.prefix = QLineEdit(str(prefix or ""))
        self.game.textChanged.connect(self._known_game)
        self.prefix.setPlaceholderText("e.g. …/steamapps/compatdata/292030/pfx")
        heading("Game", first=True)
        for label, edit, title, tip in (
                ("Game folder", self.game, "Select The Witcher 3 folder",
                 "The Witcher 3's own folder, the one with bin and content in it."),
                ("Prefix", self.prefix, "Select the Wine/Proton prefix",
                 "The Proton/Wine prefix the game runs in. It holds the game's settings files. Without it, "
                 "load order isn't applied.")):
            b = QPushButton("Browse…")
            b.clicked.connect(lambda _c=False, e=edit, t=title: self._browse(e, t))
            line(label, edit, b, tip)
        det = QPushButton("Detect Steam install", objectName="Link")
        det.setCursor(Qt.CursorShape.PointingHandCursor)
        det.setToolTip("Fill in both from Steam, for a Steam install.")
        det.clicked.connect(self.detect)
        link(det)

        cfg = parent.cfg if parent else {}
        self._login = None
        logged_in = cfg.get("nexus_key") == NEXUS_OAUTH and bool(oauth_tokens())
        self._sso = {"nexus_key": NEXUS_OAUTH if logged_in else "", "nexus_login": "oauth" if logged_in else "",
                     "nexus_user": cfg.get("nexus_user", "") if logged_in else ""}
        # with the app's client ID: a login button instead of the key field (see NEXUS_CLIENT_ID)
        self.login_state = QLabel(objectName="Muted")
        self.login_btn = QPushButton()
        self.login_btn.clicked.connect(self._login_clicked)
        self.key = QLineEdit(cfg.get("nexus_key", ""))
        self.key.setEchoMode(QLineEdit.EchoMode.Password)
        self.key.setPlaceholderText("the developer's own key, for testing")
        show = QPushButton("Show")
        show.setCheckable(True)
        show.toggled.connect(lambda on: (self.key.setEchoMode(
            QLineEdit.EchoMode.Normal if on else QLineEdit.EchoMode.Password), show.setText("Hide" if on else "Show")))
        if NEXUS_CLIENT_ID:
            heading("Nexus")
            line("Account", self.login_state, self.login_btn)
            for w in (self.key, show):
                w.hide()
            self._show_login()
        elif nexus_on(cfg):
            heading("Nexus")
            line("API key", self.key, show)               # the developer's own key: the old field
            for w in (self.login_state, self.login_btn):
                w.hide()
        else:
            for w in (self.key, show, self.login_state, self.login_btn):
                w.hide()

        # the font the Script Decisions window shows code in, with a line to judge it by
        heading("Script decisions")
        self.code_font = QComboBox()
        fonts = fixed_fonts()
        self.code_font.addItems(fonts)
        current = code_font()
        if current in fonts:
            self.code_font.setCurrentText(current)
        self.code_size = QSpinBox()
        self.code_size.setRange(8, 20)
        self.code_size.setSuffix(" pt")
        self.code_size.setValue(int(round(code_size())))
        self.code_size.setToolTip("Code size")
        line("Code font", self.code_font, self.code_size,
             "The font for code in Script decisions.\n"
             "JetBrains Mono reads best. On Fedora: sudo dnf install jetbrains-mono-fonts-all")
        self.font_preview = QLabel()
        self.font_preview.setTextFormat(Qt.TextFormat.RichText)
        self.font_preview.setStyleSheet(f"QLabel {{ background: {C['well']}; border: 1px solid {C['ridge']}; "
                                        "border-radius: 7px; padding: 8px 12px; }")
        grid.addWidget(self.font_preview, row[0], 1, 1, 2)
        row[0] += 1
        self.code_font.currentTextChanged.connect(self._preview_font)
        self.code_size.valueChanged.connect(self._preview_font)
        self._preview_font()
        v.addLayout(grid)

        # the old Script Merger, for anyone who still wants to run it: its own card, since
        # merging here doesn't need it
        card = QFrame(objectName="SettingsCard")
        card.setStyleSheet(f"QFrame#SettingsCard {{ background: {C['raised']}; border: 1px solid {C['ridge']}; "
                           f"border-radius: 8px; }} QFrame#SettingsCard QLabel {{ background: transparent; border: 0; }}")
        cv = QVBoxLayout(card)
        cv.setContentsMargins(14, 8, 14, 8)
        cv.setSpacing(8)
        # folds to one line: the heading, and how it stands on the right
        head_row = QHBoxLayout()
        head_row.setSpacing(8)
        self.merger_head = QPushButton(objectName="CardHead")
        self.merger_head.setCheckable(True)
        self.merger_head.setCursor(Qt.CursorShape.PointingHandCursor)
        self.merger_head.setToolTip(
            "Scripts are merged by the app. To run Script Merger yourself, set its path:\n"
            "“Run Script Merger” then shows in the ••• menu. It runs through Wine, in the game's prefix.")
        self.merger_head.toggled.connect(self._fold_merger)
        head_row.addWidget(self.merger_head, 1)
        self.merger_summary = QLabel()
        head_row.addWidget(self.merger_summary)
        cv.addLayout(head_row)
        self.merger_body = QWidget()
        self.merger_body.setStyleSheet("background: transparent;")
        bv = QVBoxLayout(self.merger_body)
        bv.setContentsMargins(0, 0, 0, 6)
        bv.setSpacing(8)
        merge_row = QHBoxLayout()
        merge_row.setSpacing(12)
        merge_lab = QLabel("Path")
        self.merger = QLineEdit(parent.cfg.get("merger_path", "") if parent else "")
        self.merger.setPlaceholderText("path to ScriptMerger.exe")
        pick = QPushButton("Browse…")
        pick.clicked.connect(self.browse_merger)
        merge_row.addWidget(merge_lab)
        merge_row.addWidget(self.merger, 1)
        merge_row.addWidget(pick)
        side.append(pick)
        bv.addLayout(merge_row)
        self.merger_state = QLabel(objectName="Muted")
        bv.addWidget(self.merger_state)
        cv.addWidget(self.merger_body)
        self.merger.textChanged.connect(self._check_merger)
        self._check_merger()
        opened = bool(load_config().get("merger_card_open", False))
        self.merger_head.setChecked(opened)
        self._fold_merger(opened, remember=False)
        v.addSpacing(4)
        v.addWidget(card)

        width = max(lab.sizeHint().width() for lab in labels)   # keep the fields aligned
        for lab in labels:
            lab.setFixedWidth(width)
        # every button on the right the same width, and the size box with them
        bw = max(max(b.sizeHint().width() for b in side), self.code_size.sizeHint().width(),
                 max(QPushButton(t).sizeHint().width() for t in ("Browse…", "Show", "Hide")))
        for b in side:
            if b is not self.login_btn:
                b.setFixedWidth(bw)
        self.code_size.setFixedWidth(bw)
        self.code_size.setFixedHeight(self.code_font.sizeHint().height())   # as tall as the font box beside it
        # the card's own padding and border push its field right (and its button left): take that
        # off its label and button, so its field lines up with the ones above
        inset = cv.contentsMargins().left() + 1 + bv.contentsMargins().left()
        merge_lab.setFixedWidth(max(merge_lab.sizeHint().width(), width - inset))
        pick.setFixedWidth(bw)

        self.info = QLabel(objectName="Warn")
        self.info.setWordWrap(True)
        v.addWidget(self.info)
        v.addStretch(1)
        bb = QDialogButtonBox(QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
        bb.button(QDialogButtonBox.StandardButton.Ok).setText("Save")
        bb.button(QDialogButtonBox.StandardButton.Ok).setObjectName("Primary")
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        # the app itself, bottom left, across from Save and Cancel: its icon, name and version
        foot = QHBoxLayout()
        foot.setSpacing(12)
        logo = QLabel()
        logo.setPixmap(app_icon().pixmap(QSize(56, 56), self.devicePixelRatioF()))
        logo.setFixedSize(56, 56)
        about = QLabel(f"<b>{html.escape(APP_NAME)}</b><br><span style='color:{C['ash']}'>Version {html.escape(APP_VERSION)}</span>")
        foot.addWidget(logo, 0, Qt.AlignmentFlag.AlignVCenter)
        foot.addWidget(about, 0, Qt.AlignmentFlag.AlignVCenter)
        foot.addStretch(1)
        foot.addWidget(bb, 0, Qt.AlignmentFlag.AlignVCenter)
        v.addLayout(foot)
        if not game:
            self.detect(quiet=True)
        self.restore_size()

    def _preview_font(self, *_):
        cc = CODE_COLOURS
        bits = [("if", cc["ctl"]), ("( ", C["silver"]), ("IsItemSingletonItem", cc["fn"]), ("( ", C["silver"]),
                ("l_items", cc["var"]), ("[", C["silver"]), ("0", cc["num"]), ("] )  ", C["silver"]),
                ("// 0O 1lI", cc["cm"])]
        body = "".join(f"<span style='color:{c}'>{html.escape(t)}</span>" for t, c in bits)
        self.font_preview.setText(f"<span style=\"font-family:'{self.code_font.currentText()}'; "
                                  f"font-size:{self.code_size.value()}pt; white-space:pre;\">{body}</span>")

    def _fit_height(self):
        """Never shorter than the contents need at this width — wrapped text takes more lines
        in a narrower window, so the least height is worked out again whenever it changes."""
        lay = self.layout()
        if lay is None:
            return
        lay.invalidate()
        need = lay.totalHeightForWidth(self.width()) if lay.hasHeightForWidth() else lay.totalMinimumSize().height()
        need = max(need, lay.totalMinimumSize().height())
        if need > 0 and need != self.minimumHeight():
            self.setMinimumHeight(need)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._fit_height()

    def showEvent(self, e):
        super().showEvent(e)
        QTimer.singleShot(0, self._fit_height)

    def _check_merger(self):
        text = self.merger.text().strip()
        if not text:
            msg, short, colour = "Not set, so the menu entry stays hidden.", "Not set", C["ash"]
        elif merger_ok(text):
            msg, short, colour = "✓ Found. “Run Script Merger” is in the ••• menu.", "✓ Found", C["moss"]
        else:
            msg, short, colour = "✕ No ScriptMerger.exe there, so the menu entry stays hidden.", "✕ Not found", C["blood"]
        self.merger_state.setText(msg)
        self.merger_state.setStyleSheet(f"color: {colour};")
        self.merger_summary.setText(short)
        self.merger_summary.setStyleSheet(f"color: {colour};")

    def _fold_merger(self, opened, remember=True):
        was_h = self.merger_body.height() if self.merger_body.isVisible() else 0
        self.merger_body.setVisible(opened)
        self.merger_head.setText(("▾" if opened else "▸") + "   Legacy Script Merger")
        self.merger_summary.setVisible(not opened)      # the full line shows inside when open
        if remember:
            cfg = load_config()
            cfg["merger_card_open"] = opened
            save_config(cfg)
            main_cfg = getattr(self.parent(), "cfg", None)
            if isinstance(main_cfg, dict):
                main_cfg["merger_card_open"] = opened        # its copy is saved too — keep them in step
            if opened and self.isVisible():
                # make room for it: the window grows by what the card now needs
                def grow():
                    self.layout().activate()
                    self._fit_height()
                    if self.height() < self.minimumHeight():
                        self.resize(self.width(), self.minimumHeight())
                QTimer.singleShot(0, grow)
            if not opened and was_h and self.isVisible():
                # closing it gives the room back instead of leaving a gap
                self._fit_height()
                QTimer.singleShot(0, lambda h=was_h: self.resize(self.width(), max(self.minimumHeight(),
                                                                                  self.height() - h - 8)))

    def browse_merger(self):
        start = self.merger.text() or str(Path.home())
        f, _ = QFileDialog.getOpenFileName(self, "Find ScriptMerger.exe", start,
                                           "Programs (*.exe);;All files (*)")
        if f:
            self.merger.setText(f)

    def _browse(self, edit, title):
        start = edit.text() or str(Path.home())
        d = QFileDialog.getExistingDirectory(self, title, start)
        if d:
            edit.setText(d)

    def _known_game(self, text):
        """A game folder the app has lived in before: its prefix is filled in from the settings
        kept there (the app's own settings come back too, once it moves in)."""
        if self.prefix.text().strip():
            return
        kept = _read_json(Path(text.strip()).expanduser() / MANAGER_DIRNAME / CONFIG_NAME) if text.strip() else {}
        if not kept.get("prefix"):
            return
        self.prefix.setText(kept["prefix"])
        # the window's other settings too, so its defaults don't replace the ones you had
        if kept.get("merger_path") and getattr(self, "merger", None) is not None:
            self.merger.setText(kept["merger_path"])
        if kept.get("code_font") and getattr(self, "code_font", None) is not None:
            i = self.code_font.findText(kept["code_font"])
            if i >= 0:
                self.code_font.setCurrentIndex(i)
        if kept.get("code_size") and getattr(self, "code_size", None) is not None:
            self.code_size.setValue(int(kept["code_size"]))
        if getattr(self, "info", None) is not None:
            self.info.setText("Your settings from before are in this game folder: they're used again.")

    def detect(self, quiet=False):
        g, p = detect_steam()
        if g:
            self.game.setText(str(g))
            self.prefix.setText(str(p) if p else "")
            lib = Path(g).parent.parent.parent                   # <library>/steamapps/common/<game>
            away = bool(p) and lib not in Path(p).parents
            self.info.setText("Found the Steam install." + ("" if p else
                              " No prefix yet. Run the game once through Steam, then detect again.")
                              + (" Its prefix is in another Steam library." if away else ""))
            self.info.setToolTip(f"Prefix: {p}" if away else "")
        elif not quiet:
            self.info.setText("No Steam install found. Pick the folders manually.")

    # --- Nexus login (only with NEXUS_CLIENT_ID set)
    def _show_login(self):
        if self._login is not None:
            self.login_state.setText("Waiting for you to allow it on the Nexus page…")
            self.login_state.setToolTip("Your browser opened a Nexus page asking to let W3 Linux Mod Manager use your "
                                        "account. Give it access there, and the login finishes by itself.\n"
                                        "No browser? Cancel and try again.")
            self.login_btn.setText("Cancel")
        elif self._sso["nexus_key"]:
            who = self._sso["nexus_user"]
            self.login_state.setText(f"Logged in as {who}" if who else "Logged in")
            self.login_state.setToolTip("Used for update checks and “Mod Manager Download” links.")
            self.login_btn.setText("Log out")
        else:
            self.login_state.setText("Not logged in")
            self.login_state.setToolTip("Optional, for update checks and “Mod Manager Download” links. "
                                        "A free account is enough.")
            self.login_btn.setText("Log in with Nexus")

    def _keep_login(self):
        """A login or logout counts straight away, OK or not: it happened on Nexus too."""
        main = self.parent()
        if main is not None and hasattr(main, "cfg"):
            main.cfg.update(self._sso)
            save_config(main.cfg)
            for hook in ("show_limits", "_update_nxm"):     # the login already asked Nexus
                try:
                    getattr(main, hook)()
                except AttributeError:                   # first start: the main window isn't built yet
                    pass
        self._show_login()

    def _login_clicked(self):
        if self._login is not None:                      # waiting: cancel
            self._login.cancel()
            self._login = None
            self._show_login()
            return
        if self._sso["nexus_key"]:                       # logged in: log out
            oauth_set({})
            self._sso = {"nexus_key": "", "nexus_login": "", "nexus_user": ""}
            self._keep_login()
            return
        login = self._login = NexusLogin(self)
        login.page.connect(lambda url: QDesktopServices.openUrl(QUrl(url)))
        login.done.connect(lambda tokens, name, l=login: self._logged_in(l, tokens, name))
        login.failed.connect(lambda msg, l=login: self._login_failed(l, msg))
        login.finished.connect(login.deleteLater)
        login.start()
        self._show_login()

    def _logged_in(self, login, tokens, name):
        if login is not self._login:                     # cancelled meanwhile
            return
        self._login = None
        oauth_set(tokens)
        self._sso = {"nexus_key": NEXUS_OAUTH, "nexus_login": "oauth", "nexus_user": name}
        self._keep_login()

    def _login_failed(self, login, msg):
        if login is not self._login:
            return
        self._login = None
        self._show_login()
        QMessageBox.warning(self, "Nexus login", msg)

    def done(self, r):
        if self._login is not None:                      # closing the window stops a login waiting
            self._login.cancel()
            self._login = None
        super().done(r)

    def accept(self):
        if not is_game_dir(self.game.text()):
            QMessageBox.warning(self, "Wrong folder",
                                "That's not a Witcher 3 folder: witcher3.exe isn't in bin/x64_dx12 or bin/x64.")
            return
        if self.prefix.text().strip():
            if not normalize_prefix(self.prefix.text()):
                QMessageBox.warning(self, "Wrong folder", "That's not a Wine prefix: there's no drive_c inside.")
                return
        else:
            r = QMessageBox.question(self, "No prefix",
                                     "Without a prefix the load order won't be written to mods.settings.\n"
                                     "Continue anyway?")
            if r != QMessageBox.StandardButton.Yes:
                return
        super().accept()

    def values(self):
        p = normalize_prefix(self.prefix.text())
        return {"game_dir": str(Path(self.game.text()).expanduser()),
                "prefix": str(p) if p else "",
                **(dict(self._sso) if NEXUS_CLIENT_ID else
                   {"nexus_key": self.key.text().strip()} if self.key.isVisibleTo(self) else {}),
                "merger_path": self.merger.text().strip(),
                "code_font": self.code_font.currentText(),
                "code_size": self.code_size.value()}


_NG_WORDS = re.compile(r"(?<![a-z])(ng|next[ _-]?gen(eration)?|nextgen|new[ _-]?gen|4\.\d+|v4|dx12|x64_dx12)(?![a-z])", re.I)
_OG_WORDS = re.compile(r"(?<![a-z])(og|old[ _-]?gen|classic|legacy|pre[ _-]?ng|1\.3\d*|v1\.3\d*|dx11)(?![a-z])", re.I)


_GEN_CACHE = {}


def game_generation(game):
    """'rem' for the Remastered (5.00 and later: its scripts are UTF-8, 4.x's were UTF-16), 'ng'
    for next-gen 4.x (a DX12 build in bin/x64_dx12), 'og' for the classic game, None when there's
    no game folder to look at. Worked out again only when the game's files change."""
    if not game:
        return None
    game = Path(game)
    scripts = ci_path(game, VANILLA_SCRIPTS)
    probe = next((p for p in (ci_path(scripts, r) for r in ("game/r4Game.ws", "core/math.ws", "game/player/r4Player.ws"))
                  if p.is_file()), None)
    dx12 = ci_path(game, "bin/x64_dx12")
    dx11 = ci_path(game, "bin/x64/witcher3.exe").is_file()
    try:
        key = (str(game), str(probe), probe.stat().st_mtime_ns if probe else 0, dx12.is_dir(), dx11)
    except OSError:
        key = (str(game), None, 0, dx12.is_dir(), dx11)
    if key in _GEN_CACHE:
        return _GEN_CACHE[key]
    gen = "ng" if dx12.is_dir() else "og"
    if probe is not None:
        try:
            with open(probe, "rb") as f:
                head = f.read(512)
            if head and not (head[:2] in (b"\xff\xfe", b"\xfe\xff") or head.count(b"\x00") > 20):
                gen = "rem"
        except OSError:
            pass
    elif dx12.is_dir() and not dx11:
        gen = "rem"                     # no loose scripts to look at: DX12 only (4.x also had bin/x64)
    _GEN_CACHE[key] = gen
    return gen


def generation_name(gen):
    return {"rem": "Remastered", "ng": "Next-Gen", "og": "Classic"}.get(gen, "")


_REM_WORDS = re.compile(r"(?<![a-z])(rem|remaster(ed)?|5\.\d+|v5)(?![a-z])", re.I)


def variant_generation(path_text):
    """Which game a variant folder says it's for, from words in its path: 'rem', 'ng', 'og' or None."""
    if _REM_WORDS.search(path_text):
        return "rem"
    ng, og = bool(_NG_WORDS.search(path_text)), bool(_OG_WORDS.search(path_text))
    return "ng" if ng and not og else "og" if og and not ng else None


def exclusive_sets(plan):
    """Groups of plan rows that install to the same place — versions of one mod, where only
    one can go in. {row index: set id}, only for rows that share a target with another."""
    targets = [set(t.lower() for t in planned_targets([dict(e, include=True)]) if "/" in t) for e in plan]
    parent = list(range(len(plan)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    for i in range(len(plan)):
        for j in range(i + 1, len(plan)):
            if targets[i] & targets[j]:
                parent[find(i)] = find(j)
    sets = {}
    for i in range(len(plan)):
        sets.setdefault(find(i), []).append(i)
    return {i: root for root, members in sets.items() if len(members) > 1 for i in members}


def effective_kind(choice, src):
    """Mod/DLC folders get a content/ layer added automatically when they lack one."""
    if choice == "mod":
        return "mods" if _has_content(src) else "wrap"
    if choice == "dlc":
        return "dlc" if _has_content(src) else "dlcwrap"
    return choice


def dest_path(kind, name, rel):
    if kind == "mods":
        return f"mods/{name}/{rel}"
    if kind == "wrap":
        return f"mods/{name}/content/{rel}"
    if kind == "dlc":
        return f"dlc/{name}/{rel}"
    if kind == "dlcwrap":
        return f"dlc/{name}/content/{rel}"
    if kind == "bin":
        return f"bin/{rel}"
    first, _, rest = rel.partition("/")
    return (first.lower() if first.lower() in ("mods", "dlc", "bin") else first) + ("/" + rest if rest else "")


def list_files(src):
    base = Path(src)
    out = []
    for dp, dn, fn in os.walk(base):
        dn.sort()
        out += [Path(dp, f).relative_to(base).as_posix() for f in sorted(fn)]
    return out


def fill_path_tree(tree, paths, count_col=1):
    """Show a flat list of relative paths as a folder tree with per-folder counts."""
    dirs, files = set(), {}
    for rel in paths:
        d, _, f = rel.rpartition("/")
        files.setdefault(d, {})[f.lower()] = f
        while d:
            dirs.add(d)
            d = d.rpartition("/")[0]
    files = {d: list(v.values()) for d, v in files.items()}
    counts = {d: 0 for d in dirs}
    for d, fl in files.items():
        p = d
        while p:
            counts[p] += len(fl)
            p = p.rpartition("/")[0]

    tree.setUpdatesEnabled(False)
    tree.clear()
    grey = QBrush(QColor(C["ash"]))
    nodes = {}
    for d in sorted(dirs, key=lambda x: x.lower()):          # parents sort before children
        parent, _, leaf = d.rpartition("/")
        it = QTreeWidgetItem([leaf + "/", str(counts[d])])
        it.setTextAlignment(count_col, Qt.AlignmentFlag.AlignRight)
        (nodes[parent].addChild if parent else tree.addTopLevelItem)(it)
        nodes[d] = it
    for d, fl in files.items():
        parent = nodes.get(d)
        for f in sorted(fl, key=str.lower):
            it = QTreeWidgetItem([f])
            it.setForeground(0, grey)
            (parent.addChild if parent else tree.addTopLevelItem)(it)

    # collapsed by default; mods/ and dlc/ open one level so the folder names are visible
    for i in range(tree.topLevelItemCount()):
        top = tree.topLevelItem(i)
        top.setExpanded(top.text(0) in ("mods/", "dlc/"))
    tree.setUpdatesEnabled(True)


CODE_FONTS = ("JetBrains Mono", "Hack", "Fira Code", "Source Code Pro", "Cascadia Mono",
              "Noto Sans Mono", "DejaVu Sans Mono", "Liberation Mono")
CODE_SIZE = 11
_code_font = None


def code_size():
    """The code's point size: yours from Settings, or 11."""
    try:
        return max(7, min(24, float(load_config().get("code_size") or CODE_SIZE)))
    except (TypeError, ValueError):
        return CODE_SIZE


def fixed_fonts():
    """Every installed fixed-width font family, the good coding fonts first."""
    fams = [f for f in QFontDatabase.families() if QFontDatabase.isFixedPitch(f)
            and not re.search(r"emoji|symbol|icons?\b|nerd font propo", f, re.I)]
    good = [f for f in CODE_FONTS if f in fams]
    return good + sorted((f for f in fams if f not in good), key=str.lower)


def code_font():
    """The first easy-to-read coding font that's actually installed (KDE ships Hack), or the
    system's own fixed-width font. Qt's rich text doesn't fall back through a list of names
    by itself, so it's picked here."""
    global _code_font
    if _code_font is None:
        installed = set(QFontDatabase.families())
        mine = load_config().get("code_font")
        _code_font = mine if mine in installed else \
            next((f for f in CODE_FONTS if f in installed),
                 QFontDatabase.systemFont(QFontDatabase.SystemFont.FixedFont).family())
    return _code_font


# --- showing code ---------------------------------------------------------------
# Display only: this never touches what gets merged. Tabs show as four spaces, the
# indentation every visible line shares is trimmed, and within a changed line the
# exact characters that differ are marked — so "0.1" -> "0.05" is visible at a glance.
# WitcherScript colours, as the WitcherScript extension shows them in VS Code (Dark+)
CODE_COLOURS = {
    "kw": "#569cd6",      # keywords and modifiers: function var class private new default …
    "ctl": "#c586c0",     # flow: if else for while do switch case break continue return delete
    "const": "#569cd6",   # true false NULL, this super parent virtual_parent, theGame thePlayer …
    "type": "#4ec9b0",    # types: int float name CName array, and classes/structs/enums where
                          # the grammar puts a type (after ':', extends, new, casts …)
    "fn": "#dcdcaa",      # anything called or declared as a function: GetWitcherPlayer(
    "var": "#9cdcfe",     # other names
    "enum": "#4fc1ff",    # enum values and constants: EET_Burning, MAX_LEVEL
    "str": "#ce9178",     # "text" and 'name' literals alike
    "cn": "#ce9178",
    "num": "#b5cea8",
    "cm": "#6a9955",      # comments
    "ann": "#c586c0",     # @wrapMethod and friends (the extension leaves these plain)
    "punct": "#808080",   # XML: < > / = around tags, as VS Code shows them
}
# From the WitcherScript IDE grammar (SpontanCombust/witcherscript-ide) and its native types
_WS_CONTROL = frozenset("break case continue delete do else for if return switch while".split())
_WS_KEYWORDS = frozenset("""autobind class enum event function state struct var abstract statemachine
    cleanup entry exec final latent quest reward storyscene timer const editable inlined optional out
    saved private protected public default defaults extends import hint in new single""".split())
_WS_CONSTANTS = frozenset("""true false NULL parent super this virtual_parent theGame theServer thePlayer
    theCamera theUI theSound theDebug theTimer theInput theTelemetry""".split())
_WS_TYPES = frozenset("""void Byte byte Int8 Int32 int Uint64 Float float Bool bool String string
    CName name array""".split())
_TYPE_AFTER = frozenset("class struct extends new enum state".split())
_ENUM_NAME = re.compile(r"^(?:[A-Z]+_\w+|[A-Z0-9_]{3,})$")
_CAST = re.compile(r"\(\s*\w+\s*\)\s*\(*\s*\w")
_HL_RE = re.compile(r"""(?P<cm>//.*)|(?P<cmo>/\*)|(?P<str>"(?:\\.|[^"\\])*"?)"""
                    r"""|(?P<cn>'(?:\\.|[^'\\])*'?)|(?P<ann>@[A-Za-z_]\w*)"""
                    r"""|(?P<num>(?<![\w.])(?:0[xX][0-9a-fA-F]+|\d+\.\d*f?|\.\d+f?|\d+)(?![\w.]))"""
                    r"""|(?P<id>[A-Za-z_]\w*)""")


_XML_NAME = re.compile(r"[\w:.-]+")


def _xml_char_styles(text, in_comment):
    """XML colours, as VS Code shows them: tag names blue, attribute names light blue, values
    orange, comments green, the brackets grey. Same shape as _char_styles."""
    tags = [None] * len(text)
    pos, in_tag = 0, False

    def paint(a, b, tag):
        tags[a:b] = [tag] * (b - a)
    if in_comment:
        end = text.find("-->")
        stop = len(text) if end < 0 else end + 3
        paint(0, stop, "cm")
        if end < 0:
            return tags, True
        pos = stop
    while pos < len(text):
        ch = text[pos]
        if in_tag:
            if ch.isspace():
                pos += 1
            elif text.startswith("/>", pos) or ch == ">":
                n = 2 if ch == "/" else 1
                paint(pos, pos + n, "punct")
                pos, in_tag = pos + n, False
            elif ch == "=":
                paint(pos, pos + 1, "punct")
                pos += 1
            elif ch in "\"'":
                end = text.find(ch, pos + 1)
                end = len(text) if end < 0 else end + 1
                paint(pos, end, "str")
                pos = end
            else:
                m = _XML_NAME.match(text, pos)
                end = m.end() if m else pos + 1
                paint(pos, end, "var")
                pos = end
            continue
        nxt = text.find("<", pos)
        if nxt < 0:
            break
        pos = nxt
        if text.startswith("<!--", pos):
            end = text.find("-->", pos + 4)
            stop = len(text) if end < 0 else end + 3
            paint(pos, stop, "cm")
            if end < 0:
                return tags, True
            pos = stop
        elif text.startswith("<?", pos) or text.startswith("<!", pos):
            end = text.find(">", pos)
            stop = len(text) if end < 0 else end + 1
            paint(pos, stop, "punct")
            pos = stop
        else:
            n = 2 if text.startswith("</", pos) else 1
            paint(pos, pos + n, "punct")
            m = _XML_NAME.match(text, pos + n)
            end = m.end() if m else pos + n
            paint(pos + n, end, "kw")
            pos, in_tag = end, True
    return tags, False


def char_styles(lang):
    return _xml_char_styles if lang == "xml" else _char_styles


class ScriptHighlighter(QSyntaxHighlighter):
    """Live WitcherScript colours for an editor — the same tokenizer and colours as the
    read-only code cards, so typed code looks exactly like the code around it."""
    lang = "ws"

    def __init__(self, document):
        super().__init__(document)
        self._formats = {}
        for tag, colour in CODE_COLOURS.items():
            f = QTextCharFormat()
            f.setForeground(QColor(colour))
            f.setFontItalic(tag == "cm")                  # comments are italic in the cards too
            self._formats[tag] = f

    def highlightBlock(self, text):
        tags, still_open = char_styles(self.lang)(text, self.previousBlockState() == 1)
        start = 0
        for i in range(1, len(tags) + 1):
            if i == len(tags) or tags[i] != tags[start]:
                fmt = self._formats.get(tags[start])
                if fmt is not None:
                    self.setFormat(start, i - start, fmt)
                start = i
        self.setCurrentBlockState(1 if still_open else 0)


def _mute(colour, amount=0.18):
    """A colour pulled toward the code background — for lines that didn't change."""
    a = QColor(colour)
    b = QColor(C["well"])
    mix = lambda x, y: round(x + (y - x) * amount)
    return QColor(mix(a.red(), b.red()), mix(a.green(), b.green()), mix(a.blue(), b.blue())).name()


def _expand(text):
    return text.replace("\t", "    ")


def _indent(text):
    t = _expand(text)
    return len(t) - len(t.lstrip(" "))


def _word_tag(text, start, end):
    """What a name is, the way the WitcherScript grammar decides it: by the word itself, then
    by where it stands (a type after ':', extends, new, in a cast …), then by its shape."""
    word = text[start:end]
    before = text[:start].rstrip()
    after = text[end:].lstrip()
    if word == "default":
        return "ctl" if after.startswith(":") else "kw"       # "default:" in a switch is flow
    if word in _WS_CONTROL:
        return "ctl"
    if word in _WS_KEYWORDS:
        return "kw"
    if word in _WS_CONSTANTS:
        return "const"
    if word in _WS_TYPES or (word in ("map", "set") and after.startswith("<")):
        return "type"                                          # 5.00 added map<K, V> and set<T>
    prev = re.search(r"(\w+)$", before)
    prev = prev.group(1) if prev else ""
    if prev in _TYPE_AFTER and before.endswith(prev):
        return "type"                                          # class X, extends X, new X …
    if prev == "in" and re.search(r"\bstate\b", before):
        return "type"                                          # state Combat in CR4Player
    if before.endswith(":") and not before.endswith("::") \
            and not re.search(r"\b(case\s+[^:]+|default)\s*:$", before):
        return "type"                                          # var x : T, (a : T), ) : T
    if before.endswith(("<", ",")) and re.search(r"\b(array|map|set)\s*<[^<>;()]*$", before):
        return "type"                                          # array<T>
    if re.search(r"@\w+\s*\($", before):
        return "type"                                          # @wrapMethod(CR4Player)
    call = re.search(r"(\w+)\s*\($", before)                   # Foo(x), if (x) … aren't casts
    if before.endswith("(") and not (call and call.group(1) not in ("return", "case", "delete", "else", "do")) \
            and _CAST.match(text, len(before) - 1):
        return "type"                                          # (CR4Player)thePlayer
    if after.startswith("("):
        return "fn"
    if _ENUM_NAME.match(word):
        return "enum"
    return "var"


def _char_styles(text, in_comment):
    """A colour tag per character of an already tab-expanded line, and whether a block
    comment is still open at its end."""
    tags = [None] * len(text)
    pos = 0
    if in_comment:
        end = text.find("*/")
        stop = len(text) if end < 0 else end + 2
        tags[:stop] = ["cm"] * stop
        if end < 0:
            return tags, True
        pos = stop
    while pos < len(text):
        m = _HL_RE.search(text, pos)
        if not m:
            break
        kind = m.lastgroup
        if kind == "cmo":
            end = text.find("*/", m.end())
            stop = len(text) if end < 0 else end + 2
            tags[m.start():stop] = ["cm"] * (stop - m.start())
            if end < 0:
                return tags, True
            pos = stop
            continue
        tag = {"cm": "cm", "str": "str", "cn": "cn", "num": "num", "ann": "ann"}.get(kind)
        if kind == "id":
            tag = _word_tag(text, m.start(), m.end())
        if tag:
            tags[m.start():m.end()] = [tag] * (m.end() - m.start())
        pos = m.end()
    return tags, False


_KEY_ATTR = re.compile(r'\b(?:id|name|varId)\s*=\s*"([^"]*)"')


def _similar(old, new):
    """Close enough to show as one line edited? Never two XML entries with different ids."""
    a, b = _KEY_ATTR.search(old), _KEY_ATTR.search(new)
    if a and b and a.group(1) != b.group(1):
        return False
    return difflib.SequenceMatcher(None, old, new, autojunk=False).ratio() >= 0.5


def _char_changes(old, new):
    """(ranges in old that were removed or replaced, ranges in new that were added or changed)."""
    gone, added = [], []
    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, old, new, autojunk=False).get_opcodes():
        if tag in ("replace", "delete") and i2 > i1:
            gone.append((i1, i2))
        if tag in ("replace", "insert") and j2 > j1:
            added.append((j1, j2))
    return gone, added


def _rows_vs_base(base_region, lines, first_num, split_unpaired=False):
    """A version of the region against vanilla: unchanged lines keep their vanilla line
    number, new or changed ones are tinted, with the changed characters marked.
    split_unpaired: a replaced line that isn't an edit of the one it replaces (XML: another
    entry) shows as removed, not as the new line's older self."""
    rows = []
    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, base_region, lines,
                                                       autojunk=False).get_opcodes():
        gone = (i2 - i1) - (j2 - j1) if tag in ("replace", "delete") else 0
        unpaired = []
        if split_unpaired and tag == "replace":
            unpaired = [i for i in range(i1, i2)
                        if not (i - i1 + j1 < j2 and _similar(_expand(base_region[i]), _expand(lines[i - i1 + j1])))]
            gone = len(unpaired)
        for k in range(j1, j2):
            if tag == "equal":
                rows.append((first_num + i1 + (k - j1), lines[k], "same", ()))
                continue
            spans = ()
            paired = i1 + (k - j1)
            if tag == "replace" and paired < i2:
                old, new = _expand(base_region[paired]), _expand(lines[k])
                if _similar(old, new):
                    spans = tuple(_char_changes(old, new)[1])
            rows.append(("", lines[k], "add", spans))
        if gone > 0:
            # vanilla lines this version doesn't have: said in a row of their own, where they'd be,
            # instead of the line numbers just jumping
            lo = unpaired[0] if unpaired else i2 - gone
            hi = unpaired[-1] + 1 if unpaired else i2
            first, last = first_num + lo, first_num + hi - 1
            where = f"{first}" if first == last else f"{first}–{last}"
            lead = next((l[:len(l) - len(l.lstrip())] for l in base_region[lo:hi] if l.strip()), "")
            rows.append(("", f"{lead}{gone} line{'s' * (gone != 1)} removed ({where})", "del", ()))
    return rows


def _base_rows(base_region, variants, first_num):
    """Vanilla's region: every line some mod changed is tinted, with the characters they changed marked."""
    changed, spans = set(), {}
    for lines in variants:
        for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, base_region, lines,
                                                           autojunk=False).get_opcodes():
            if tag not in ("replace", "delete"):
                continue
            for i in range(i1, i2):
                changed.add(i)
                j = j1 + (i - i1)
                if tag == "replace" and j < j2:
                    old, new = _expand(base_region[i]), _expand(lines[j])
                    if _similar(old, new):
                        spans.setdefault(i, set()).update(_char_changes(old, new)[0])
    return [(first_num + i, line, "chg" if i in changed else "same", tuple(sorted(spans.get(i, ()))))
            for i, line in enumerate(base_region)]


def _insertions(base, lines):
    """{position: added lines} when `lines` only adds to `base`; None if it changes or removes anything."""
    ins = {}
    for tag, i1, _i2, j1, j2 in difflib.SequenceMatcher(None, base, lines, autojunk=False).get_opcodes():
        if tag == "equal":
            continue
        if tag != "insert":
            return None
        ins.setdefault(i1, []).extend(lines[j1:j2])
    return ins


def both_additions(base, a, b):
    """When two mods only *add* lines to the same spot, both can be kept: vanilla's lines
    once, plus each mod's additions. Returns (a's first, b's first), or None when either
    mod replaces or removes anything — gluing replaced lines together would run both
    versions of the same statement, which is never what either mod meant."""
    ia, ib = _insertions(base, a), _insertions(base, b)
    if ia is None or ib is None:
        return None

    def build(first, second):
        out = []
        for i in range(len(base) + 1):
            out += first.get(i, []) + second.get(i, [])
            if i < len(base):
                out.append(base[i])
        return out

    return build(ia, ib), build(ib, ia)


_WORD_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _brace_marks(lines):
    """[(line, column, '{' or '}')] of every brace that counts — not in comments or strings —
    and {(line, col): (line, col)} pairing each with its partner, both ways."""
    braces, in_comment = [], False
    for n, text in enumerate(lines):
        tags, in_comment2 = _char_styles(text, in_comment)
        for k, ch in enumerate(text):
            if ch in "{}" and tags[k] not in ("cm", "str"):
                braces.append((n, k, ch))
        in_comment = in_comment2
    pairs, stack = {}, []
    for n, k, ch in braces:
        if ch == "{":
            stack.append((n, k))
        elif stack:
            o = stack.pop()
            pairs[o], pairs[(n, k)] = (n, k), o
    return braces, pairs


def _sel(cursor, colour, full_width=False, outline=False):
    s = QTextEdit.ExtraSelection()
    s.cursor = cursor
    fmt = QTextCharFormat()
    fmt.setBackground(QColor(colour))
    if full_width:
        fmt.setProperty(QTextFormat.Property.FullWidthSelection, True)
    if outline:
        fmt.setFontWeight(QFont.Weight.Bold)
    s.format = fmt
    return s


FADE = "#474e57"                 # code outside what you've picked out: there, but out of the way


def fade_outside(doc, start, end):
    """Extra selections that grey out everything in the document except [start, end)."""
    out = []
    for a, b in ((0, start), (end, doc.characterCount() - 1)):
        if b > a:
            c = QTextCursor(doc)
            c.setPosition(a)
            c.setPosition(b, QTextCursor.MoveMode.KeepAnchor)
            s = QTextEdit.ExtraSelection()
            s.cursor = c
            fmt = QTextCharFormat()
            fmt.setForeground(QColor(FADE))
            s.format = fmt
            out.append(s)
    return out


def brace_mark(cursor, colour=None):
    """A brace picked out by its colour alone — bronze for a pair, red for one without."""
    s = QTextEdit.ExtraSelection()
    s.cursor = cursor
    fmt = QTextCharFormat()
    fmt.setForeground(QColor(colour or C["bronze_hi"]))
    fmt.setFontWeight(QFont.Weight.Bold)
    s.format = fmt
    return s


def soft_selection(widget):
    """No selection colour over code: what you select keeps its colours and everything else
    fades (see fade_outside), which reads far better than a solid bronze band."""
    pal = widget.palette()
    for group in (QPalette.ColorGroup.Active, QPalette.ColorGroup.Inactive):
        pal.setColor(group, QPalette.ColorRole.Highlight, QColor(0, 0, 0, 0))
        pal.setBrush(group, QPalette.ColorRole.HighlightedText, QBrush(Qt.BrushStyle.NoBrush))
    widget.setPalette(pal)


def _rgba(key, alpha):
    q = QColor(C[key])
    q.setAlphaF(alpha)
    return q


class CodeView(QTextBrowser):
    """Read-only code: line numbers, light syntax colours, tinted changes, marked characters.
    Long stretches no mod touched fold into one '··· N unchanged lines' row (click to open).
    Click beside a brace to see its pair and the block between; double-click one to select
    the block. Click a name to light it up everywhere. Copying leaves the line numbers out."""
    TINT = {"add": ("rgba(127,191,138,0.13)", "rgba(127,191,138,0.45)"),
            "chg": ("rgba(219,185,119,0.11)", "rgba(219,185,119,0.42)")}
    # changed lines are painted as one section per run (not a band per line): fill, left edge
    BAND = {"add": (QColor(127, 191, 138, 46), QColor(127, 191, 138, 170)),
            "del": (QColor(214, 106, 94, 30), QColor(214, 106, 94, 160)),
            "chg": (QColor(219, 185, 119, 34), QColor(219, 185, 119, 150))}
    MARK = {"add": "+", "chg": "~", "del": "−"}
    lang = "ws"                  # "xml" for XML files: their own colours
    KEEP_NEAR = 3                # unchanged lines kept in view next to a change
    FOLD_MIN = 4                 # never fold fewer lines than this
    foldOpened = pyqtSignal(int)
    wordClicked = pyqtSignal(str)
    braceFocused = pyqtSignal(object)   # (vanilla line, "{" or "}", which one on the line) or None

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setLineWrapMode(QTextBrowser.LineWrapMode.NoWrap)
        self.setOpenLinks(False)
        self.setFrameShape(QFrame.Shape.NoFrame)
        # the frame around it gives the dark background, so the changed-line sections can be
        # painted under the text
        self.setStyleSheet("QTextBrowser { background: transparent; border: 0; }")
        self.viewport().setAutoFillBackground(False)
        soft_selection(self)
        self._rows, self._blocks, self._info = [], [], []
        self._pairs, self._args, self._open = {}, None, set()
        self._brace_sel, self._word_sel, self._word = [], [], ""
        self._sel_fade, self._brace_fade = [], []
        self._quiet = False
        self.cursorPositionChanged.connect(self._cursor_moved)
        self.selectionChanged.connect(self._selection_changed)

    # --- showing
    def show_rows(self, rows, dedent=0, digits=3, unfolded=None):
        """rows: [(number or '', text, kind, changed character ranges)], kind in add/chg/ctx/same.
        unfolded: the ids of the folds that are open (shared by every view of one decision)."""
        self._rows = list(rows)
        self._args = (dedent, digits)
        self._open = unfolded if unfolded is not None else set()
        self._brace_sel, self._brace_fade, self._sel_fade = [], [], []
        self._render(keep_scroll=False)

    def rerender(self):
        if self._args is not None:
            self._render(keep_scroll=True)

    def _folds(self):
        """{first hidden row: (fold id, one past the last)} for every long unchanged stretch.
        Kept in view: the function's first and last lines, a few lines either side of a change,
        and every line whose brace pairs with one outside the stretch — with its `for(…)` /
        `if(…)` line. So a fold only ever hides whole blocks, starts and ends on a block's edge,
        and you always know where you are."""
        rows = self._rows
        runs, n = [], 0
        while n < len(rows):
            if rows[n][2] == "ctx":
                m = n
                while m < len(rows) and rows[m][2] == "ctx":
                    m += 1
                runs.append((n, m))
                n = m
            else:
                n += 1
        braces = {}                                        # row -> [(col, partner row or None)]
        for n, info in enumerate(self._info):
            for k, ch in enumerate(info["shown"]):
                if ch in "{}" and info["tags"][k] not in ("cm", "str", "del"):
                    partner = self._pairs.get((n, k))
                    braces.setdefault(n, []).append((k, partner[0] if partner else None))
        out = {}
        for rid, (a, b) in enumerate(runs):
            top = 1 if a == 0 else self.KEEP_NEAR           # the function's first line stays
            bottom = 1 if b == len(rows) else self.KEEP_NEAR  # …and its last
            lo, hi = a + top, b - bottom
            keep = set()
            for row in range(lo, hi):
                for k, prow in braces.get(row, ()):
                    if prow is None or not lo <= prow < hi:   # it pairs with something outside
                        keep.add(row)
                        shown = self._info[row]["shown"]
                        if shown[k] == "{" and shown.strip() == "{" and row - 1 >= lo:
                            keep.add(row - 1)                 # its for(…) / if(…) line
            # a lone { just below the stretch (kept for being near a change) keeps its line too
            if lo < hi < len(rows) and self._info[hi]["shown"].strip() == "{":
                keep.add(hi - 1)
            seg, n = 0, lo
            while n < hi:
                if n in keep:
                    n += 1
                    continue
                m = n
                while m < hi and m not in keep:
                    m += 1
                fid = rid * 100 + seg
                seg += 1
                if m - n >= self.FOLD_MIN and fid not in self._open:
                    out[n] = (fid, m)
                n = m
        return out

    def _render(self, keep_scroll):
        dedent, digits = self._args
        h, v = self.horizontalScrollBar().value(), self.verticalScrollBar().value()
        out = [f"<div style=\"font-family:'{code_font()}'; font-size:{code_size()}pt; white-space:pre;\">"]
        self._info, self._blocks = [], []
        in_comment = False
        shown_lines = []
        for num, text, kind, spans in self._rows:
            full = _expand(text)
            if kind == "del":
                tags = ["del"] * len(full)                # a note, not code
            else:
                tags, in_comment = char_styles(self.lang)(full, in_comment)
            cut = min(dedent, _indent(text)) if full.strip() else len(full)
            shown = full[cut:]
            gutter = f"{str(num):>{digits}} {self.MARK.get(kind, ' ')} "
            marked = [False] * len(shown)
            for a, b in spans:
                for k in range(max(a - cut, 0), min(b - cut, len(shown))):
                    marked[k] = True
            self._info.append({"gutter": len(gutter), "shown": shown, "text": text, "tags": tags[cut:],
                               "marked": marked, "gut": gutter, "kind": kind})
            shown_lines.append("" if kind == "del" else shown)
        _braces, self._pairs = _brace_marks(shown_lines)
        folds = self._folds()
        n = 0
        while n < len(self._rows):
            if n in folds:
                fid, end = folds[n]
                count = end - n
                self._blocks.append(("fold", fid, n, end))
                first = self._info[n]["shown"]              # sits at the indent of what it hides
                indent = len(first) - len(first.lstrip(" "))
                label = f"{' ' * (digits + 3 + indent)}···  {count} unchanged lines"
                out.append(f"<p style=\"margin:0; padding:0 10px 0 0; line-height:125%; "
                           f"background-color:rgba(255,255,255,0.035);\"><span style=\"color:{C['ash']};\">"
                           f"{html.escape(label)}</span></p>")
                n = end
                continue
            info = self._info[n]
            kind = info["kind"]
            shown, tags, marked = info["shown"], info["tags"], info["marked"]
            tint, strong = self.TINT.get(kind, (None, None))
            body, k = [], 0
            while k < len(shown):
                j = k
                while j < len(shown) and tags[j] == tags[k] and marked[j] == marked[k]:
                    j += 1
                tag = tags[k]
                colour = C["blood"] if tag == "del" else CODE_COLOURS.get(tag, C["silver"])
                if kind == "ctx":
                    colour = _mute(colour)          # unchanged: same colours, a step quieter
                style = f"color:{colour};"
                if tag in ("cm", "del"):
                    style += " font-style:italic;"
                if marked[k] and strong:
                    style += f" background-color:{strong}; border-radius:2px;"
                body.append(f"<span style=\"{style}\">{html.escape(shown[k:j])}</span>")
                k = j
            line_style = "margin:0; padding:0 10px 0 0; line-height:125%;"
            self._blocks.append(("row", n))
            out.append(f"<p style=\"{line_style}\"><span style=\"color:{C['dim']};\">"
                       f"{html.escape(info['gut'])}</span>{''.join(body) or ' '}</p>")
            n += 1
        out.append("</div>")
        self._quiet = True
        self.setHtml("".join(out))
        self._quiet = False
        if keep_scroll:
            self.horizontalScrollBar().setValue(h)
            self.verticalScrollBar().setValue(v)
        self._brace_sel, self._brace_fade, self._sel_fade = [], [], []
        self.highlight_word(self._word)

    # --- where things are
    def _block_of_row(self, row):
        for b, entry in enumerate(self._blocks):
            if entry[0] == "row" and entry[1] == row:
                return b, None
            if entry[0] == "fold" and entry[2] <= row < entry[3]:
                return b, entry[1]
        return None, None

    def _cursor_at(self, row, col, length=1):
        b, fid = self._block_of_row(row)
        block = self.document().findBlockByNumber(b)
        c = QTextCursor(block)
        if fid is None:
            c.setPosition(block.position() + self._info[row]["gutter"] + col)
            c.setPosition(block.position() + self._info[row]["gutter"] + col + length,
                          QTextCursor.MoveMode.KeepAnchor)
        return c, fid

    def _spot(self, cursor):
        """(row, column in the shown code) under a text cursor, or None on a fold / the gutter."""
        b = cursor.blockNumber()
        if b >= len(self._blocks) or self._blocks[b][0] != "row":
            return None
        row = self._blocks[b][1]
        return row, cursor.positionInBlock() - self._info[row]["gutter"]

    def _brace_near(self, spot):
        if spot is None:
            return None
        row, col = spot
        for k in (col, col - 1):
            if (row, k) in self._pairs or (0 <= k < len(self._info[row]["shown"])
                                           and self._info[row]["shown"][k] in "{}"
                                           and self._info[row]["tags"][k] not in ("cm", "str", "del")):
                return row, k
        return None

    # --- clicking
    def _cursor_moved(self):
        if self._quiet:
            return
        cur = self.textCursor()
        if cur.hasSelection():
            return
        spot = self._spot(cur)
        brace = self._brace_near(spot)
        self._show_pair(brace)
        self.braceFocused.emit(self._brace_key(brace))
        word = ""
        if brace is None and spot is not None:
            row, col = spot
            for m in _WORD_RE.finditer(self._info[row]["shown"]):
                if m.start() <= col <= m.end() and self._info[row]["tags"][m.start()] not in ("cm", "str", "del"):
                    word = m.group()
                    break
        self.wordClicked.emit(word)

    def _block_span(self, lo, hi):
        """Document positions from the start of the block's first line — its for(…)/if(…) line
        when the brace sits alone on the next one — to the end of its closing line."""
        first = lo[0]
        if self._info[first]["shown"].strip() == "{" and first > 0:
            first -= 1
        doc = self.document()
        b1, _ = self._block_of_row(first)
        b2, _ = self._block_of_row(hi[0])
        start = doc.findBlockByNumber(b1).position()
        last = doc.findBlockByNumber(b2)
        return start, last.position() + last.length() - 1

    def _show_pair(self, brace):
        """Beside a brace: the rest of the code fades, the block and its opening line stay as
        they are, and the two braces turn bronze. A brace without a partner turns red."""
        self._brace_sel, self._brace_fade = [], []
        if brace is not None:
            partner = self._pairs.get(brace)
            c, _ = self._cursor_at(*brace)
            if partner is None:
                self._brace_sel.append(brace_mark(c, C["blood"]))
            else:
                lo, hi = sorted((brace, partner))
                self._brace_fade = fade_outside(self.document(), *self._block_span(lo, hi))
                for spot in (brace, partner):
                    c, fid = self._cursor_at(*spot)
                    if fid is None:
                        self._brace_sel.append(brace_mark(c))
        self._apply()

    def _valid_braces(self, row, ch):
        info = self._info[row]
        return [k for k, c in enumerate(info["shown"]) if c == ch and info["tags"][k] not in ("cm", "str", "del")]

    def _brace_key(self, brace):
        """Where a brace is in terms every column shares: its vanilla line number. A line a mod
        added has none, so it can't be matched in the other columns."""
        if brace is None:
            return None
        row, k = brace
        num = self._rows[row][0]
        if num == "" or num is None:
            return None
        ch = self._info[row]["shown"][k]
        same = self._valid_braces(row, ch)
        return (num, ch, same.index(k) if k in same else 0)

    def focus_brace(self, key):
        """Show the block of the brace another column picked out, here: the same vanilla line,
        and this column's own partner for it (a mod may have made the block longer)."""
        brace = None
        if key is not None:
            num, ch, nth = key
            row = next((r for r, x in enumerate(self._rows) if x[0] == num), None)
            if row is not None:
                same = self._valid_braces(row, ch)
                if len(same) > nth:
                    brace = (row, same[nth])
        if brace is not None and brace not in self._pairs:
            brace = None                               # no partner here: nothing to show
        self._show_pair(brace)

    def _selection_changed(self):
        """Whatever you select stays in full colour; the rest fades."""
        cur = self.textCursor()
        self._sel_fade = fade_outside(self.document(), cur.selectionStart(), cur.selectionEnd()) \
            if cur.hasSelection() else []
        self._apply()

    def highlight_word(self, word):
        """Light up every use of this name (not inside comments or strings)."""
        self._word = word
        self._word_sel = []
        if word:
            rx = re.compile(r"(?<![A-Za-z0-9_])" + re.escape(word) + r"(?![A-Za-z0-9_])")
            for entry in self._blocks:
                if entry[0] != "row":
                    continue
                info = self._info[entry[1]]
                for m in rx.finditer(info["shown"]):
                    if info["tags"][m.start()] not in ("cm", "str", "del"):
                        c, _ = self._cursor_at(entry[1], m.start(), len(word))
                        self._word_sel.append(_sel(c, QColor(255, 255, 255, 38)))
        self._apply()

    def _apply(self):
        # a selection's fade wins over a brace's; the brace colours and name tints go on top
        self.setExtraSelections((self._sel_fade or self._brace_fade) + self._word_sel + self._brace_sel)

    def open_fold(self, fid):
        self._open.add(fid)
        self.rerender()

    def scroll_to_change(self):
        """Bring the first changed line into view, a couple of lines down from the top."""
        for b, entry in enumerate(self._blocks):
            if entry[0] == "row" and self._info[entry[1]]["kind"] in ("add", "chg", "del"):
                # the cursor put on the change, then made visible: works before the view has
                # laid itself out, which setting the scrollbar doesn't
                self._quiet = True
                target = QTextCursor(self.document().findBlockByNumber(min(len(self._blocks) - 1, b + 3)))
                self.setTextCursor(target)
                self.ensureCursorVisible()
                self.setTextCursor(QTextCursor(self.document().findBlockByNumber(b)))
                self._quiet = False
                return

    def first_mark_x(self):
        """Where, across the text, the first changed character is (document pixels), or None."""
        for b, entry in enumerate(self._blocks):
            if entry[0] != "row":
                continue
            info = self._info[entry[1]]
            if info["kind"] in ("add", "chg") and any(info["marked"]):
                c = QTextCursor(self.document().findBlockByNumber(b))
                c.setPosition(c.position() + info["gutter"] + info["marked"].index(True))
                return self.cursorRect(c).x() + self.horizontalScrollBar().value()
        return None

    def show_mark_sideways(self, x):
        """Scroll across so x (document pixels) is in view, a third of the way in."""
        bar, room = self.horizontalScrollBar(), self.viewport().width()
        if x is not None and not (bar.value() <= x <= bar.value() + room * 0.85):
            bar.setValue(max(0, int(x - room / 3)))

    def _paint_bands(self):
        """Each run of added (or changed) lines as one section: a light fill across the full
        width, with a thin coloured edge on the left."""
        lay = self.document().documentLayout()
        top = self.verticalScrollBar().value()
        width = self.viewport().width()
        p = QPainter(self.viewport())
        block = self.document().begin()
        run_kind, run_top, run_bottom = None, 0.0, 0.0

        def flush():
            if run_kind in self.BAND:
                fill, edge = self.BAND[run_kind]
                p.fillRect(QRectF(0, run_top, width, run_bottom - run_top), fill)
                p.fillRect(QRectF(0, run_top, 3, run_bottom - run_top), edge)
        for entry in self._blocks:
            kind = self._info[entry[1]]["kind"] if entry[0] == "row" else None
            r = lay.blockBoundingRect(block)
            y1, y2 = r.top() - top, r.bottom() - top
            if kind == run_kind and kind in self.BAND:
                run_bottom = y2
            else:
                flush()
                run_kind, run_top, run_bottom = kind, y1, y2
            block = block.next()
        flush()
        p.end()

    def paintEvent(self, e):
        """Changed-line sections under the text, then the text, then faint indent guides: a
        line at every indent level, so nested blocks read at a glance."""
        if self._blocks and self._args is not None:
            self._paint_bands()
        super().paintEvent(e)
        if not self._blocks or self._args is None:
            return
        font = QFont(code_font())
        font.setPointSizeF(code_size())
        step = QFontMetricsF(font).horizontalAdvance(" ")
        x0 = self.document().documentMargin() + (self._args[1] + 3) * step - self.horizontalScrollBar().value()
        top = self.verticalScrollBar().value()
        lay = self.document().documentLayout()
        levels = []
        for entry in self._blocks:
            if entry[0] != "row":
                levels.append(None)
                continue
            shown = self._info[entry[1]]["shown"]
            blank = not shown.strip() or self._info[entry[1]]["kind"] == "del"
            levels.append((len(shown) - len(shown.lstrip(" "))) // 4 if not blank else -1)
        for i, lv in enumerate(levels):                    # blank lines carry on the guides around them
            if lv == -1:
                before = next((x for x in reversed(levels[:i]) if x not in (None, -1)), 0)
                after = next((x for x in levels[i + 1:] if x not in (None, -1)), 0)
                levels[i] = min(before, after)
        p = QPainter(self.viewport())
        p.setPen(QPen(QColor(255, 255, 255, 20), 1))
        height = self.viewport().height()
        block = self.document().begin()
        for lv in levels:
            if lv:
                r = lay.blockBoundingRect(block)
                y1, y2 = r.top() - top, r.bottom() - top
                if y2 >= 0 and y1 <= height:
                    for k in range(lv):
                        x = round(x0 + k * 4 * step + step * 0.5) + 0.5
                        if x > x0 - step:
                            p.drawLine(QPointF(x, y1), QPointF(x, y2))
            block = block.next()
        p.end()

    def mouseReleaseEvent(self, e):
        super().mouseReleaseEvent(e)
        if e.button() == Qt.MouseButton.LeftButton and not self.textCursor().hasSelection():
            b = self.cursorForPosition(e.position().toPoint()).blockNumber()
            if b < len(self._blocks) and self._blocks[b][0] == "fold":
                self.foldOpened.emit(self._blocks[b][1])

    def mouseDoubleClickEvent(self, e):
        """Double-click a brace: select the whole block, braces included."""
        brace = self._brace_near(self._spot(self.cursorForPosition(e.position().toPoint())))
        partner = self._pairs.get(brace) if brace else None
        if partner is None:
            super().mouseDoubleClickEvent(e)
            return
        for spot in (brace, partner):
            _b, fid = self._block_of_row(spot[0])
            if fid is not None:
                self.foldOpened.emit(fid)                 # open it first, everywhere
        lo, hi = sorted((brace, partner))
        a, _ = self._cursor_at(*lo)
        z, _ = self._cursor_at(*hi)
        sel = QTextCursor(self.document())
        sel.setPosition(a.selectionStart())
        sel.setPosition(z.selectionEnd(), QTextCursor.MoveMode.KeepAnchor)
        self._quiet = True
        self.setTextCursor(sel)
        self._quiet = False
        self._show_pair(brace)
        self._selection_changed()

    def createMimeDataFromSelection(self):
        """Copy the code, not the line numbers: whole lines come out exactly as in the script
        (tabs and all), folded lines included."""
        cur = self.textCursor()
        start, end = cur.selectionStart(), cur.selectionEnd()
        doc = self.document()
        out = []
        block = doc.findBlock(start)
        while block.isValid() and block.position() <= end:
            entry = self._blocks[block.blockNumber()] if block.blockNumber() < len(self._blocks) else None
            if entry and entry[0] == "fold":
                out += [self._info[r]["text"] for r in range(entry[2], entry[3])]
            elif entry and self._info[entry[1]]["kind"] == "del":
                pass                                      # a note about removed lines, not code
            elif entry:
                info = self._info[entry[1]]
                g = block.position() + info["gutter"]
                a = max(start, g) - g
                z = min(end, block.position() + block.length() - 1) - g
                lead = len(info["shown"]) - len(info["shown"].lstrip())
                if a <= lead and z >= len(info["shown"]):
                    out.append(info["text"])              # the whole line, indentation and all
                elif z > a:
                    out.append(info["shown"][a:z])
            block = block.next()
        md = QMimeData()
        md.setText("\n".join(out))
        return md


def module_name(folder, pack):
    """A readable name for one folder of a mod that ships several: modlegoDeleveledEconomy in
    "lego" -> "Deleveled Economy". The pack's name and the "mod" prefix are dropped, and
    words split where the author capitalised them."""
    name = folder[3:] if folder.lower().startswith("mod") else folder
    prefix = re.sub(r"[^a-z0-9]", "", pack.lower())
    if prefix and name.lower().startswith(prefix) and len(name) > len(prefix):
        name = name[len(prefix):]
    name = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", name.replace("_", " ")).strip(" -")
    return (name[:1].upper() + name[1:]) if name else folder


def short_group(mods):
    """Every mod that made the very same change, by name."""
    mods = list(mods)
    return mods[0] if len(mods) == 1 else ", ".join(mods[:-1]) + f" & {mods[-1]}"


class ElidedLabel(QLabel):
    """A one-line title that shortens itself with … instead of holding the window wide."""

    def __init__(self, text, colour, parent=None):
        super().__init__(parent)
        self._full = text
        self.setStyleSheet(f"color:{colour}; font-weight:600;")
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.setMinimumWidth(20)
        self.setText(text)

    def setFullText(self, text):
        self._full = text
        self.setToolTip(text)
        self._elide()

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._elide()

    def _elide(self):
        shown = self.fontMetrics().elidedText(self._full, Qt.TextElideMode.ElideRight,
                                              max(20, self.width() - 6))
        if shown != self.text():
            self.setText(shown)


class ChoiceButton(QPushButton):
    """A button whose contents are its own layout (letter tag + wrapping text), sized by it,
    so a long label gets more lines instead of being cut."""

    def hasHeightForWidth(self):
        return self.layout() is not None

    def heightForWidth(self, w):
        return max(self.minimumHeight(), self.layout().heightForWidth(w))

    def sizeHint(self):
        return self.layout().sizeHint() if self.layout() else super().sizeHint()

    def minimumSizeHint(self):
        return self.layout().minimumSize() if self.layout() else super().minimumSizeHint()


# The resolver's columns are lettered like Script Merger's: A is vanilla, B, C… are the mods,
# and every choice button carries the letters of the columns it takes its lines from.
def letter_colour(letter):
    return {"A": C["ash"], "B": C["bronze_hi"], "C": C["steel"], "D": C["moss"]}.get(letter, C["silver"])


def letter_badge(letters, parent=None):
    """A small rounded tag: "B", "B+C", or ✎. Mixed letters take the first one's colour."""
    col = letter_colour(letters[0]) if letters[:1].isalpha() else C["silver"]
    q = QColor(col)
    lab = QLabel(letters, parent)
    lab.setAlignment(Qt.AlignmentFlag.AlignCenter)
    lab.setFixedHeight(20)
    lab.setMinimumWidth(20)
    lab.setStyleSheet(f"QLabel {{ color: {col}; background: rgba({q.red()},{q.green()},{q.blue()},0.16); "
                      f"border: 1px solid rgba({q.red()},{q.green()},{q.blue()},0.55); border-radius: 5px; "
                      f"font-weight: 700; font-size: 9pt; padding: 0 4px; }}")
    lab.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
    return lab


def _people(names):
    names = list(names)
    if not names:
        return "the other mod"
    return names[0] if len(names) == 1 else ", ".join(names[:-1]) + f" and {names[-1]}"


class TopEdgeDrag(QObject):
    """Lets a card's edge be dragged like the divider next to it: grab the top (or bottom) few
    pixels of the card and the two sides of the splitter change, as if you'd grabbed the
    divider itself."""
    GRAB = 7

    def __init__(self, card, splitter, bottom=False):
        super().__init__(card)
        self.card, self.split, self._from, self.bottom = card, splitter, None, bottom
        card.setMouseTracking(True)
        card.installEventFilter(self)

    def _on_edge(self, y):
        return y >= self.card.height() - self.GRAB if self.bottom else y <= self.GRAB

    def eventFilter(self, obj, e):
        t = e.type()
        if t == QEvent.Type.MouseMove:
            y = e.position().y()
            if self._from is not None:
                start_y, sizes = self._from
                d = int(e.globalPosition().y() - start_y)
                top = max(120, min(sizes[0] + d, sizes[0] + sizes[1] - 120))
                self.split.setSizes([top, sizes[0] + sizes[1] - top])
                self.split.splitterMoved.emit(top, 1)      # same as dragging the divider itself
                return True
            if self._on_edge(y):
                self.card.setCursor(Qt.CursorShape.SplitVCursor)
            else:
                self.card.unsetCursor()
        elif t == QEvent.Type.MouseButtonPress and e.button() == Qt.MouseButton.LeftButton \
                and self._on_edge(e.position().y()):
            self._from = (e.globalPosition().y(), self.split.sizes())
            return True
        elif t == QEvent.Type.MouseButtonRelease and self._from is not None:
            self._from = None
            return True
        elif t == QEvent.Type.Leave and self._from is None:
            self.card.unsetCursor()
        return False


class FoldedColumn(QAbstractButton):
    """A folded column: a slim strip with its name written down it. Click to open it."""

    def __init__(self, text, parent=None):
        super().__init__(parent)
        self.setText(text)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedWidth(self._width())
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Expanding)   # as tall as the columns

    def _font(self):
        font = QFont(self.font())
        font.setWeight(QFont.Weight.DemiBold)
        return font

    def _width(self):
        """Wide enough for the text standing on its side, with room either side — whatever
        the font size or display scaling."""
        fm = QFontMetricsF(self._font())
        return max(34, int(fm.ascent() + fm.descent() + 16))

    def changeEvent(self, e):
        super().changeEvent(e)
        if e.type() == QEvent.Type.FontChange:
            self.setFixedWidth(self._width())

    def sizeHint(self):
        return QSize(self._width(), 120)

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        p.setPen(QPen(QColor(C["ridge_hi"] if self.underMouse() else C["ridge"]), 1))
        p.setBrush(QColor(C["raised"] if self.underMouse() else C["slate"]))
        p.drawRoundedRect(r, 8, 8)
        font = self._font()
        fm = QFontMetricsF(font)
        # turned a quarter clockwise, the text's height lies across the strip: centre that
        p.translate(self.width() / 2 - (fm.ascent() - fm.descent()) / 2, 14)
        p.rotate(90)
        p.setPen(QColor(C["silver"] if self.underMouse() else C["ash"]))
        p.setFont(font)
        room = self.height() - 28
        p.drawText(QPointF(0, 0), fm.elidedText(self.text(), Qt.TextElideMode.ElideRight, room))

    def enterEvent(self, e):
        self.update()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self.update()
        super().leaveEvent(e)


HEAD_ROLE = Qt.ItemDataRole.UserRole + 2              # a section header in the decisions list


class ScriptRowDelegate(QStyledItemDelegate):
    """A script in the decisions list: its name, and on the right how many decisions it has
    left (a bronze count) or a green tick once they're all made."""
    ROW_H = 34
    HEAD_H = 30

    def sizeHint(self, option, index):
        if index.data(HEAD_ROLE):
            return QSize(option.rect.width(), self.HEAD_H + (8 if index.row() else 0))
        return QSize(option.rect.width(), self.ROW_H)

    def paint(self, p, option, index):
        head = index.data(HEAD_ROLE)
        if head:
            # a section header: its name, and how many decisions are open in it
            p.save()
            r = QRectF(option.rect).adjusted(14, 8 if index.row() else 0, -12, 0)
            font = QFont(option.font)
            font.setWeight(QFont.Weight.DemiBold)
            p.setFont(font)
            p.setPen(QColor(C["ash"]))
            p.drawText(r, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), head)
            left = index.data(Qt.ItemDataRole.UserRole + 1) or 0
            p.setFont(QFont(option.font))
            p.setPen(QColor(C["bronze_hi"] if left else C["moss"]))
            p.drawText(r, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                       f"{left} left" if left else "✓")
            p.setPen(QColor(C["ridge"]))
            p.drawLine(QPointF(r.left(), r.bottom() - 0.5), QPointF(r.right(), r.bottom() - 0.5))
            p.restore()
            return
        p.save()
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(option.rect).adjusted(4, 2, -4, -2)
        selected = bool(option.state & QStyle.StateFlag.State_Selected)
        hover = bool(option.state & QStyle.StateFlag.State_MouseOver)
        if selected or hover:
            bg = QColor(C["bronze"])
            bg.setAlphaF(0.20 if selected else 0.08)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(bg)
            p.drawRoundedRect(r, 6, 6)
        left = index.data(Qt.ItemDataRole.UserRole + 1) or 0
        font = QFont(option.font)
        fm = QFontMetricsF(font)
        # right: the count, or a tick
        if left:
            txt = str(left)
            w = max(22.0, fm.horizontalAdvance(txt) + 12)
            pill = QRectF(r.right() - 8 - w, r.center().y() - 10, w, 20)
            fill = QColor(C["bronze"])
            fill.setAlphaF(0.22)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(fill)
            p.drawRoundedRect(pill, 10, 10)
            p.setPen(QColor(C["bronze_hi"]))
            p.drawText(pill, Qt.AlignmentFlag.AlignCenter, txt)
            right_edge = pill.left() - 8
        else:
            tick = QRectF(r.right() - 30, r.top(), 22, r.height())
            p.setPen(QColor(C["moss"]))
            p.drawText(tick, Qt.AlignmentFlag.AlignCenter, "✓")
            right_edge = tick.left() - 4
        name_rect = QRectF(r.left() + 10, r.top(), right_edge - r.left() - 10, r.height())
        if selected:
            font.setWeight(QFont.Weight.DemiBold)
            p.setFont(font)
            fm = QFontMetricsF(font)
        p.setPen(QColor(C["silver"] if left else C["moss"]))
        name = fm.elidedText(index.data(Qt.ItemDataRole.DisplayRole) or "", Qt.TextElideMode.ElideRight,
                             name_rect.width())
        p.drawText(name_rect, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), name)
        p.restore()


class ScriptResolverDialog(RememberingDialog):
    """Walk through every decision the merger couldn't make on its own."""
    window_key = "resolver"
    CONTEXT = 4
    WHOLE_FUNCTION = 80

    def __init__(self, parent, mgr, keys):
        super().__init__(parent)
        self.setWindowTitle("Script decisions")
        self.resize(1280, 820)
        self.mgr = mgr
        self.details = {}                 # key -> merge_details result
        self.answers = {}                 # key -> {item key: (choice id, lines)}
        self.current_key = None
        self.index = 0
        self._views = []
        self._syncing = False
        self._opts = []
        self._choices = []
        self._loading = False
        self._lang = "ws"                              # "xml" while an XML file is on screen

        v = QVBoxLayout(self)
        v.setContentsMargins(20, 18, 20, 16)
        v.setSpacing(14)
        # fold the script list away, and bring it back — remembered between openings. It sits
        # in the button row, as wide as the list, right under it
        self.list_btn = QPushButton(objectName="ListToggle")
        self.list_btn.setCheckable(True)
        self.list_btn.toggled.connect(self._show_list)
        self.accept_all = QPushButton("Keep every suggested merge")
        self.accept_all.setToolTip("Keep the combined version for every open “Worth a look”. Conflicts, "
                                   "and lines that would run twice, still need you.")
        self.accept_all.clicked.connect(self.accept_suggestions)

        self.split = split = QSplitter(Qt.Orientation.Horizontal)
        split.setChildrenCollapsible(False)
        # left: the scripts that need you, with how many decisions each has left
        self.side = QWidget()
        sv = QVBoxLayout(self.side)
        sv.setContentsMargins(0, 0, 0, 0)
        sv.setSpacing(8)
        side_head = QHBoxLayout()
        side_head.setContentsMargins(4, 0, 4, 0)
        side_title = self.side_title = QLabel("Scripts")
        side_title.setStyleSheet("font-size: 12pt; font-weight: 600;")
        side_head.addWidget(side_title, 1)
        self.summary = QLabel(objectName="Muted")
        side_head.addWidget(self.summary, 0, Qt.AlignmentFlag.AlignBottom)
        sv.addLayout(side_head)
        self.scripts = QListWidget(objectName="ScriptList")
        self.scripts.setMinimumWidth(220)
        self.scripts.setItemDelegate(ScriptRowDelegate(self.scripts))
        self.scripts.currentRowChanged.connect(self.pick_script)
        sv.addWidget(self.scripts, 1)
        split.addWidget(self.side)

        right = QWidget()
        rv = QVBoxLayout(right)
        rv.setContentsMargins(16, 0, 0, 0)
        rv.setSpacing(12)

        # which script, where in it, and which decision: one bar across the top
        bar = QFrame(objectName="DecisionBar")
        bar.setStyleSheet(f"QFrame#DecisionBar {{ background: {C['raised']}; border: 1px solid {C['ridge']}; "
                          f"border-radius: 8px; }} QFrame#DecisionBar QLabel {{ background: transparent; border: 0; }}")
        top = QHBoxLayout(bar)
        top.setContentsMargins(18, 12, 14, 12)
        top.setSpacing(10)
        where = QVBoxLayout()
        where.setSpacing(3)
        self.where_file = QLabel()                                   # the script: which file
        self.where_file.setTextFormat(Qt.TextFormat.RichText)
        self.where_file.setStyleSheet("font-size: 15pt; font-weight: 600;")
        self.where = QLabel()                                        # where in it: the function
        self.where.setTextFormat(Qt.TextFormat.RichText)
        self.where.setStyleSheet(f"color: {C['silver']}; font-size: 11pt;")
        file_row = QHBoxLayout()
        file_row.setSpacing(12)
        file_row.addWidget(self.where_file)
        self.kind = QLabel()                                         # Conflict / Worth a look tag
        self.kind.setTextFormat(Qt.TextFormat.PlainText)
        file_row.addWidget(self.kind, 0, Qt.AlignmentFlag.AlignVCenter)
        file_row.addStretch(1)
        where.addLayout(file_row)
        where.addWidget(self.where)
        top.addLayout(where, 1)
        self.prev_btn = QPushButton("‹ Previous")
        self.next_btn = QPushButton("Next ›")
        self.step = QLabel()
        self.step.setStyleSheet(f"color: {C['ash']}; padding: 0 6px;")
        self.prev_btn.clicked.connect(lambda: self.show_item(self.index - 1))
        self.next_btn.clicked.connect(lambda: self.show_item(self.index + 1))
        for wdg in (self.prev_btn, self.step, self.next_btn):
            top.addWidget(wdg, 0, Qt.AlignmentFlag.AlignVCenter)
        rv.addWidget(bar)

        self.columns = QSplitter(Qt.Orientation.Horizontal)
        self.columns.setChildrenCollapsible(False)
        # code on top, the result under it: the code starts as tall as it needs, the result
        # gets the rest, and the divider between them can be dragged
        self.vsplit = QSplitter(Qt.Orientation.Vertical)
        self.vsplit.setChildrenCollapsible(False)
        self.vsplit.setHandleWidth(12)
        upper = QWidget()                              # the code, and the choices under it
        self.upper_v = QVBoxLayout(upper)
        self.upper_v.setContentsMargins(0, 0, 0, 0)
        self.upper_v.setSpacing(10)
        self.upper_v.addWidget(self.columns, 1)
        # a mod that leaves out a big piece of the game's code here (often: made for an older
        # game version) — worth knowing before picking it
        self.removal_note = QLabel()
        self.removal_note.setWordWrap(True)
        self.removal_note.setTextFormat(Qt.TextFormat.RichText)
        self.removal_note.setStyleSheet(f"QLabel {{ color: {C['bronze_hi']}; background: rgba(201,164,92,0.10); "
                                        "border: 1px solid rgba(201,164,92,0.40); border-radius: 6px; "
                                        "padding: 5px 10px; }")
        self.removal_note.hide()
        self.upper_v.addWidget(self.removal_note)
        self.vsplit.addWidget(upper)
        lower = QWidget()                              # the result: its top edge is the divider
        lower_v = QVBoxLayout(lower)
        lower_v.setContentsMargins(0, 0, 0, 0)
        lower_v.setSpacing(10)
        self.vsplit.addWidget(lower)
        self.vsplit.setStretchFactor(0, 0)
        self.vsplit.setStretchFactor(1, 1)
        self.vsplit.splitterMoved.connect(lambda *_: self._remember_sizes())
        self.columns.splitterMoved.connect(lambda *_: self._remember_sizes())
        rv.addWidget(self.vsplit, 1)

        # the mods' column titles are the choices; this row holds the ones that aren't a single
        # column (both additions, edit by hand…), and what the picked one means
        extras = QHBoxLayout()
        extras.setSpacing(8)
        self.extra_box = QHBoxLayout()
        self.extra_box.setSpacing(8)
        extras.addLayout(self.extra_box)
        self.option_note = QLabel(objectName="Muted")
        self.option_note.setWordWrap(True)
        extras.addWidget(self.option_note, 1)
        self.upper_v.addLayout(extras)
        # what the picked version would break, found before you save (hidden when all is well)
        self.check_note = QLabel()
        self.check_note.setWordWrap(True)
        self.check_note.setTextFormat(Qt.TextFormat.RichText)
        self.check_note.setStyleSheet(f"QLabel {{ color: {C['blood']}; background: rgba(214,106,94,0.10); "
                                      "border: 1px solid rgba(214,106,94,0.35); border-radius: 6px; "
                                      "padding: 5px 10px; }")
        self.check_note.hide()
        self.upper_v.addWidget(self.check_note)
        # what a mod's kept changes still lean on in the lines being dropped (compiles, but may
        # not do what the mod meant)
        self.depends_note = QLabel()
        self.depends_note.setWordWrap(True)
        self.depends_note.setTextFormat(Qt.TextFormat.RichText)
        self.depends_note.setStyleSheet(f"QLabel {{ color: {C['bronze_hi']}; background: rgba(201,164,92,0.10); "
                                        "border: 1px solid rgba(201,164,92,0.40); border-radius: 6px; "
                                        "padding: 5px 10px; }")
        self.depends_note.hide()
        self.upper_v.addWidget(self.depends_note)

        self.result_stack = QStackedWidget()
        empty = QLabel("Click the version to keep. What the game will run shows here.", objectName="Muted")
        empty.setAlignment(Qt.AlignmentFlag.AlignCenter)
        empty.setWordWrap(True)
        self.result_view = CodeView()
        self._open_folds = set()                        # folds opened for the decision on screen
        self.result_view.foldOpened.connect(self._open_fold)
        self.result_view.wordClicked.connect(self._highlight_word)
        self.result_view.braceFocused.connect(lambda key: self._sync_brace(self.result_view, key))
        edit_page = QWidget()
        ep = QVBoxLayout(edit_page)
        ep.setContentsMargins(6, 4, 6, 4)
        ep.setSpacing(4)
        self.edit_hint = QLabel(objectName="Muted")
        ep.addWidget(self.edit_hint)
        self.result_edit = QPlainTextEdit()
        self.result_edit.setStyleSheet(
            f"QPlainTextEdit {{ font-family: '{code_font()}'; font-size: {code_size()}pt; background: {C['well']}; "
            f"border: 1px solid {C['bronze']}; border-radius: 6px; padding: 6px; }}")
        self.result_edit.setLineWrapMode(QPlainTextEdit.LineWrapMode.NoWrap)
        self.result_edit.setTabStopDistance(
            QFontMetricsF(self.result_edit.font()).horizontalAdvance(" ") * 4)
        self.result_edit.textChanged.connect(self.edited)
        self.result_edit.cursorPositionChanged.connect(self._edit_braces)
        self.result_edit.selectionChanged.connect(self._edit_braces)
        self.result_edit.textChanged.connect(self._edit_braces)
        self._highlighter = ScriptHighlighter(self.result_edit.document())
        soft_selection(self.result_edit)
        ep.addWidget(self.result_edit, 1)
        for wdg in (empty, self.result_view, edit_page):
            self.result_stack.addWidget(wdg)
        frame = QFrame()
        frame.setObjectName("ResultFrame")
        frame.setStyleSheet(f"QFrame#ResultFrame {{ background: {C['well']}; border: 1px solid "
                            f"{C['ridge']}; border-radius: 8px; }}")
        fl = QVBoxLayout(frame)
        fl.setContentsMargins(4, 4, 4, 4)
        self.result_title = QLabel(objectName="Muted")
        self.result_title.setContentsMargins(6, 2, 0, 0)
        fl.addWidget(self.result_title)
        fl.addWidget(self.result_stack, 1)
        lower_v.addWidget(frame, 1)
        self._edge_drag = TopEdgeDrag(frame, self.vsplit)

        split.addWidget(right)
        split.setStretchFactor(1, 1)
        list_w = _int(load_config().get("resolver_list_w"), 240)
        split.setSizes([max(180, list_w), 1040])
        split.splitterMoved.connect(lambda *_: (self._fit_list_btn(), self._remember_sizes()))
        v.addWidget(split, 1)

        # the primary button walks you through: "Save & Next" while decisions are open, then
        # "Save & Finish"; the other one keeps what's answered for later, or cancels once
        # there's nothing left to come back to
        self.save_btn = QPushButton(objectName="Primary")
        self.save_btn.clicked.connect(self._save_clicked)
        self.later_btn = QPushButton()
        self.later_btn.clicked.connect(self._later_clicked)
        buttons = QHBoxLayout()
        buttons.setSpacing(12)
        self.list_btn.setFixedWidth(240)
        buttons.addWidget(self.list_btn)
        buttons.addWidget(self.accept_all)
        buttons.addStretch(1)
        buttons.addWidget(self.save_btn)
        buttons.addWidget(self.later_btn)
        v.addLayout(buttons)

        self.choice_group = QButtonGroup(self)
        self.choice_group.setExclusive(True)
        self.choice_group.idClicked.connect(self.choose)
        # keyboard: A (vanilla), B, C… pick that column; 1, 2… the choices under the code (in order);
        # ← → the previous/next decision; Enter saves and moves on. None of them fire while
        # you're typing in your own version — the text box keeps those keys.
        self._keys = {}
        for ch in "ABCDEFG123456":
            QShortcut(QKeySequence(ch), self, activated=lambda c=ch: self._key_pick(c))
        QShortcut(QKeySequence(Qt.Key.Key_Left), self, activated=lambda: self.prev_btn.isEnabled() and self.prev_btn.click())
        QShortcut(QKeySequence(Qt.Key.Key_Right), self, activated=lambda: self.next_btn.isEnabled() and self.next_btn.click())
        for key in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
            QShortcut(QKeySequence(key), self, activated=lambda: self.save_btn.isEnabled() and self.save_btn.click())
        self.prev_btn.setToolTip("Previous decision  (←)")
        self.next_btn.setToolTip("Next decision  (→)")
        self.list_btn.blockSignals(True)
        self.list_btn.setChecked(load_config().get("resolver_list", True))
        self.list_btn.blockSignals(False)

        for key in keys:
            det = mgr.merge_details(key)
            if not det or not det.get("items"):
                continue
            self.details[key] = det
            self.answers[key] = {}
            for it in det["items"]:
                if it["resolution"] is not None:
                    self.answers[key][it["key"]] = (self._which(it, it["resolution"]), it["resolution"])
        # scripts first, then XML; a header over each only when both kinds are there
        parts = [("Scripts", [k for k in self.details if not k.startswith(XML_KEY)]),
                 ("XML", [k for k in self.details if k.startswith(XML_KEY)])]
        both = all(ks for _t, ks in parts)
        for title, ks in parts:
            if both:
                head = QListWidgetItem()
                head.setData(HEAD_ROLE, title)
                head.setFlags(Qt.ItemFlag.NoItemFlags)
                self.scripts.addItem(head)
            for key in ks:
                row = QListWidgetItem()
                row.setData(Qt.ItemDataRole.UserRole, key)
                self.scripts.addItem(row)
        self.refresh_list()
        self.restore_size()
        self._answers_at_open = {k: dict(v) for k, v in self.answers.items()}
        if self._file_keys():
            self.scripts.setCurrentRow(self._row_of(self._file_keys()[0]))

    # --- choices for one item
    def _options(self, it):
        """[(id, label, lines, what it means)]. "Both" is only offered where it's sound."""
        names = [short_group(var["mods"]) for var in it["variants"]]
        everyone = _people(names)
        combined = it.get("options") or {}
        opts = []
        xml = bool(it.get("part"))                    # an XML item: says which part of the file
        if it.get("why") == "removes":
            what = "values" if it.get("part") == "tag" else "entries"
            moved = it.get("moved")
            if moved:
                movers = _people(moved)
                n = sum(moved.values())
                opts.append(("follow", "Follow the move (suggested)", combined["follow"],
                             f"{movers} moved {n} of the game's entries to a file of its own, so "
                             f"{'it stays' if n == 1 else 'they stay'} out here. Everything else is kept."))
                opts.append(("keep", "Keep the game's too", combined["keep"],
                             f"{everyone}'s changes, plus the game's {what}. {movers} has them in its own "
                             "file too, so they'd be there twice."))
            else:
                opts.append(("keep", "Keep both (suggested)", combined["keep"],
                             f"{everyone}'s changes, plus the game's {what}. Safest when a mod was made for "
                             "an older game version."))
            for n, name in enumerate(names):
                opts.append((f"v{n}", f"Only {name}", combined.get(f"v{n}", it["variants"][n]["lines"]),
                             f"{name}'s version as it is. The game's {what} it leaves out are dropped."))
            opts.append(("base", "Use Vanilla", combined["base"],
                         f"The game's own version here. {everyone}'s changes here are dropped."))
            opts.append(("edit", "Edit by hand", None,
                         "Start from the current choice and write it yourself. You're warned if it isn't "
                         "valid XML."))
            return opts
        if it["kind"] == "review":
            why = it.get("why")
            note = {
                "edge": f"Both changes. {everyone} changed lines right next to each other. Check it still "
                        "reads the way both meant.",
                "same_spot": f"Both mods' lines, {names[0]}'s first. Check the order doesn't matter.",
                "repeated": f"Every change from {everyone}, combined, which runs "
                            f"{it.get('repeated') or 'the same line'} twice. Keep it only if that's fine.",
            }.get(why, f"Every change from {everyone}, combined. Read it once: the game runs this.")
            opts.append(("both", "Keep both (suggested)", it["proposed"], note))
            if why == "same_spot" and len(it["variants"]) == 2:
                both = both_additions(it["base"], it["variants"][0]["lines"], it["variants"][1]["lines"])
                if both and both[1] != it["proposed"]:
                    opts.append(("ba", f"Both, {names[1]} first", both[1],
                                 f"Both mods' lines, {names[1]}'s before {names[0]}'s."))
        for n, (name, var) in enumerate(zip(names, it["variants"])):
            others = _people(x for k, x in enumerate(names) if k != n)
            if it["kind"] == "review":
                opts.append((f"v{n}", f"Only {name}", var["lines"],
                             f"Just {name}'s change here. {others}'s is dropped."))
            elif combined.get(f"v{n}") is not None and combined[f"v{n}"] != var["lines"]:
                opts.append((f"v{n}", f"Use {name}", combined[f"v{n}"],
                             f"{name}'s version where they clash. Every other change here is kept."))
            else:
                opts.append((f"v{n}", f"Use {name}", var["lines"], f"Dropped here: {others}."))
        if it["kind"] == "conflict" and len(it["variants"]) == 2:
            both = both_additions(it["base"], it["variants"][0]["lines"], it["variants"][1]["lines"])
            if both:
                ab, ba = both
                if ab == ba:
                    opts.append(("ab", "Keep both additions", ab,
                                 "Both mods only add lines here, so both stay. Nothing is dropped."))
                else:
                    for cid, first, second, text in (("ab", names[0], names[1], ab),
                                                     ("ba", names[1], names[0], ba)):
                        opts.append((cid, f"Both, {first} first", text,
                                     f"Both mods only add lines here, so both stay, {first}'s first."))
        vanilla = combined.get("base")
        if xml:
            opts.append(("base", "Use Vanilla", vanilla if vanilla is not None else list(it["base"]),
                         "The game's own version here. Each mod's other changes in this file still go in."))
            opts.append(("edit", "Edit by hand", None,
                         "Start from the current choice and write it yourself. You're warned if it isn't "
                         "valid XML."))
            return opts
        if vanilla is not None and vanilla != list(it["base"]):
            opts.append(("base", "Use Vanilla", vanilla,
                         "The game's own lines where they clash. Every other change here is kept."))
        else:
            opts.append(("base", "Use Vanilla", list(it["base"]),
                         "The game's own lines here. Each mod's other changes in this script still go in. "
                         "You're warned if it wouldn't compile."))
        opts.append(("edit", "Edit by hand", None,
                     "Start from the current choice and write the lines yourself. You're warned if they "
                     "wouldn't compile."))
        return opts

    @staticmethod
    def _letters(cid, count):
        """The columns a choice takes its lines from: v0 → B, ab → B+C, both → B+C…, edit → ✎."""
        mods = [chr(ord("B") + n) for n in range(count)]
        if cid == "edit":
            return "✎"
        if cid == "base":
            return "A"
        if cid == "follow":
            return "↪"                              # the move followed: see its label
        if cid == "both":
            return "+".join(mods)
        if cid == "keep":
            return "+".join(["A"] + mods)
        if cid in ("ab", "ba"):
            return "+".join(mods[:2] if cid == "ab" else mods[1::-1])
        return mods[int(cid[1:])]

    def _which(self, it, lines):
        for cid, _label, text, _note in self._options(it):
            if text is not None and list(text) == list(lines):
                return cid
        return "edit"

    # --- navigation
    def _file_keys(self):
        """The files in the list, in list order (section headers left out)."""
        return [self.scripts.item(r).data(Qt.ItemDataRole.UserRole) for r in range(self.scripts.count())
                if not self.scripts.item(r).data(HEAD_ROLE)]

    def _row_of(self, key):
        return next(r for r in range(self.scripts.count())
                    if self.scripts.item(r).data(Qt.ItemDataRole.UserRole) == key)

    def refresh_list(self):
        left_total = 0
        head, per_head = None, {}
        for r in range(self.scripts.count()):
            row = self.scripts.item(r)
            if row.data(HEAD_ROLE):
                head = row
                per_head[id(head)] = (head, 0)
                continue
            key = row.data(Qt.ItemDataRole.UserRole)
            det = self.details[key]
            left = sum(1 for it in det["items"] if it["key"] not in self.answers[key])
            left_total += left
            name = det["rel"].rsplit("/", 1)[-1]
            row.setText(name)
            row.setData(Qt.ItemDataRole.UserRole + 1, left)
            row.setToolTip(det["rel"] + (f"\n{left} decision{'s' * (left != 1)} left" if left else "\nall decided"))
            row.setForeground(QBrush(QColor(C["silver"] if left else C["moss"])))
            if head is not None:
                h, c = per_head[id(head)]
                per_head[id(head)] = (h, c + left)
        for h, c in per_head.values():
            h.setData(Qt.ItemDataRole.UserRole + 1, c)
        n = len(self._file_keys())
        xml = [k.startswith(XML_KEY) for k in self.details]
        noun = "files" if any(xml) and not all(xml) else "XML files" if xml and all(xml) else "scripts"
        self.side_title.setText(noun[0].upper() + noun[1:])
        self.summary.setText(f"{left_total} left" if left_total else "all decided")
        self.summary.setToolTip(f"{n} {noun} · {left_total} decision{'s' * (left_total != 1)} left")
        self.list_btn.setVisible(n > 1)
        self._show_list(self.list_btn.isChecked())

    def _fit_list_btn(self):
        """Keep the toggle exactly as wide as the script list; while the list is hidden it keeps
        the width the list had, so it doesn't jump around."""
        if self.side.isVisible() and self.side.width() > 0:
            self.list_btn.setFixedWidth(self.side.width())

    def showEvent(self, e):
        super().showEvent(e)
        QTimer.singleShot(0, self._fit_list_btn)
        QTimer.singleShot(0, self._fit_columns)      # once it has its real size

    def _show_list(self, on):
        on = on and len(self._file_keys()) > 1
        self.side.setVisible(on)
        noun = "file" if any(k.startswith(XML_KEY) for k in self.details) else "script"
        self.list_btn.setText(f"‹  Hide {noun} list" if on else f"Show {noun} list  ›")
        QTimer.singleShot(0, self._fit_list_btn)
        try:
            cfg = load_config()
            if cfg.get("resolver_list", True) != bool(self.list_btn.isChecked()):
                cfg["resolver_list"] = bool(self.list_btn.isChecked())
                save_config(cfg)
        except OSError:
            pass
        open_reviews = any(it["kind"] == "review" and it.get("why") != "repeated" and it["key"] not in self.answers[k]
                           for k, d in self.details.items() for it in d["items"])
        self.accept_all.setVisible(open_reviews)

    def pick_script(self, row):
        if row < 0 or self.scripts.item(row).data(HEAD_ROLE):
            return
        self.current_key = self.scripts.item(row).data(Qt.ItemDataRole.UserRole)
        items = self.details[self.current_key]["items"]
        first_open = next((i for i, it in enumerate(items)
                           if it["key"] not in self.answers[self.current_key]), 0)
        self.show_item(first_open)

    def show_item(self, index):
        det = self.details[self.current_key]
        items = det["items"]
        self.index = max(0, min(index, len(items) - 1))
        it = items[self.index]
        self._loading = True
        self._lang = det.get("lang", "ws")
        self.result_view.lang = self._lang
        if self._highlighter.lang != self._lang:
            self._highlighter.lang = self._lang
            self._highlighter.rehighlight()

        fn = it["function"]
        folder, _, name = det["rel"].rpartition("/")
        self.where_file.setText((f"<span style='color:{C['ash']}; font-weight:400;'>{html.escape(folder)}/</span>"
                                 if folder else "") + html.escape(name))
        self.where_file.setToolTip(det["rel"])
        first, last = it["start"] + 1, max(it["end"], it["start"] + 1)
        lines_txt = f"line {first}" if first == last else f"lines {first}–{last}"
        muted = f"color:{C['ash']};"
        if fn:
            owner = f"<span style='{muted}'>&nbsp;&nbsp;in class {html.escape(fn['owner'])}</span>" if fn["owner"] else ""
            self.where.setText(f"<span style='{muted}'>Function&nbsp;&nbsp;</span>{html.escape(fn['name'])}(){owner}"
                               f"<span style='{muted}'>&nbsp;&nbsp;·&nbsp;&nbsp;{lines_txt}</span>")
        elif it.get("where"):
            self.where.setText(f"{html.escape(it['where'])}"
                               f"<span style='{muted}'>&nbsp;&nbsp;·&nbsp;&nbsp;{lines_txt}</span>")
        else:
            self.where.setText(f"{lines_txt[0].upper() + lines_txt[1:]}<span style='{muted}'>, outside any function</span>")
        self.step.setText(f"Decision {self.index + 1} of {len(items)}")
        self.prev_btn.setEnabled(self.index > 0)
        self.next_btn.setEnabled(self.index < len(items) - 1)
        for wdg in (self.prev_btn, self.step, self.next_btn):
            wdg.setVisible(len(items) > 1)

        who = [short_group(var["mods"]) for var in it["variants"]]
        everyone = _people(who)
        # the columns below say who's who, so the sentence doesn't repeat every name
        mods = "Both mods" if len(who) == 2 else f"All {len(who)} mods"
        if it["kind"] == "conflict":
            badge, colour = "Conflict", C["blood"]
            if it.get("why") == "attributes":
                self.kind.setToolTip(f"{mods} set the same value differently. Pick one. Every other change "
                                     "here is kept.")
            elif it.get("why") == "structure":
                self.kind.setToolTip(f"{everyone} change this spot in ways that don't fit together. Kept side "
                                     "by side, it wouldn't compile.\n\n"
                                     "Pick one version, or combine them in Edit by hand.")
            else:
                self.kind.setToolTip(f"{mods} changed {lines_txt} in different ways, so both can't stay. "
                                     "Pick one.")
        else:
            badge, colour = "Worth a look", C["bronze_hi"]
            self.kind.setToolTip({
                "edge": f"{everyone} changed lines right next to each other. They fit together, but "
                        "check the result reads the way both meant.",
                "same_spot": f"{everyone} add lines at the same spot. Both are kept, the higher priority "
                             "first. Check the order doesn't matter.",
                "repeated": f"{everyone} each add {it.get('repeated') or 'the same line'} in a different place, "
                            "so combined it runs twice. Usually both mods doing the same job.",
                "removes": f"{everyone} leave{'s' if len(who) == 1 else ''} out part of the game's own "
                           f"{'values' if it.get('part') == 'tag' else 'entries'} here. Often a mod made for "
                           "an older game version, not a choice.\n\n"
                           "Suggested: keep the game's, and add the mod's changes.",
            }.get(it.get("why"), f"{everyone} changed {'this function' if fn else 'these lines'}. They combine, "
                                 "but check the result."))
            if it.get("moved"):
                self.kind.setToolTip(
                    f"{_people(it['moved'])} leave{'s' if len(it['moved']) == 1 else ''} out some of the game's own "
                    "entries here, but has them in its own file: moved, not removed.\n\n"
                    "Suggested: follow the move, and keep every mod's other changes.")
        q = QColor(colour)
        self.kind.setStyleSheet(f"QLabel {{ color: {colour}; font-weight: 600; "
                                f"background: rgba({q.red()},{q.green()},{q.blue()},0.14); "
                                f"border: 1px solid rgba({q.red()},{q.green()},{q.blue()},0.45); border-radius: 6px; "
                                "padding: 2px 9px; }")
        self.kind.setText(badge)

        if self._lang == "xml":
            self.removal_note.hide()                  # removals are asked about in XML
        else:
            self._removal_warning(it, who)

        # context: the whole function when it's short, otherwise a few lines either side
        base = det["base_lines"]
        if fn and fn["last"] - fn["first"] <= self.WHOLE_FUNCTION:
            lo_ctx, hi_ctx = fn["first"], fn["last"] + 1
        else:
            lo_ctx, hi_ctx = max(0, it["start"] - self.CONTEXT), min(len(base), it["end"] + self.CONTEXT)
        lo_ctx, hi_ctx = min(lo_ctx, it["start"]), max(hi_ctx, it["end"])
        self._ctx = (lo_ctx, hi_ctx)
        shown = base[lo_ctx:hi_ctx] + [l for var in it["variants"] for l in var["lines"]] \
            + list(it["proposed"] or [])
        self._dedent = min((_indent(l) for l in shown if l.strip()), default=0)
        self._digits = len(str(hi_ctx))

        self._open_folds = set()
        self.result_view.highlight_word("")
        for btn in self._choices:
            if btn is not None:
                self.choice_group.removeButton(btn)
                btn.setParent(None)
        self._opts = self._options(it)
        self._choices = [None] * len(self._opts)
        self._keys = {}
        self._frames = {}
        while self.columns.count():
            self.columns.widget(0).setParent(None)
        self._views = []
        vanilla = self._wrap(_base_rows(it["base"], [var["lines"] for var in it["variants"]],
                                        it["start"] + 1), it)
        self.columns.addWidget(self._column("Vanilla", "", vanilla, letter_colour("A"), letter="A",
                                            choice=next(i for i, o in enumerate(self._opts) if o[0] == "base"),
                                            is_vanilla=True))
        for n, (name, var) in enumerate(zip(who, it["variants"])):
            letter = chr(ord("B") + n)
            pick = next(i for i, o in enumerate(self._opts) if o[0] == f"v{n}")
            self.columns.addWidget(self._column(name, "", self._variant_rows(it, var["lines"]),
                                                letter_colour(letter), full="\n".join(var["mods"]),
                                                letter=letter, choice=pick))
        self._fold_vanilla(bool(load_config().get("resolver_vanilla_folded", False)), remember=False)
        self._link_scrolling()
        self._fit_columns()
        for delay in (0, 80, 250):                       # a change far along a long line: scroll to it
            QTimer.singleShot(delay, self._columns_sideways)

        extra = [n for n, o in enumerate(self._opts) if self._choices[n] is None]
        badges = {n: letter_badge(self._letters(self._opts[n][0], len(it["variants"]))) for n in extra}
        for n in extra:
            cid, label, _text, note = self._opts[n]
            btn = ChoiceButton()
            btn.setCheckable(True)
            btn.setObjectName("Choice")
            row = QHBoxLayout(btn)
            row.setContentsMargins(8, 6, 12, 6)
            row.setSpacing(9)
            row.addWidget(badges[n], 0, Qt.AlignmentFlag.AlignVCenter)
            text = QLabel(label)
            text.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
            text.setStyleSheet("background: transparent; border: 0;")
            row.addWidget(text)
            btn.toggled.connect(lambda on, t=text: t.setStyleSheet(
                "background: transparent; border: 0;" + (f" color: {C['bronze_hi']};" if on else "")))
            btn.setFixedHeight(34)
            key = str(extra.index(n) + 1)
            self._keys[key] = n
            btn.setToolTip(f"{label}  ({key})\n\n{note}")
            self.choice_group.addButton(btn, n)
            self.extra_box.addWidget(btn)
            self._choices[n] = btn
        answer = self.answers[self.current_key].get(it["key"])
        if answer:
            n = next((i for i, o in enumerate(self._opts) if o[0] == answer[0]), len(self._opts) - 1)
            self._choices[n].setChecked(True)
            self.option_note.setText(self._opts[n][3])
            self._show_result(answer[0], answer[1])
            self._mark_columns(answer[0])
        else:
            self._mark_columns(None)
            self.option_note.setText("")
            self.result_title.setText("")
            self.result_stack.setCurrentIndex(0)
        self._update_answered()
        self._loading = False
        self._live_check()

    def _column(self, title, subtitle, rows, colour, full="", letter="", choice=None, is_vanilla=False):
        box = QWidget()
        lay = QVBoxLayout(box)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(4)
        if subtitle:
            lab = QLabel(f"<span style='color:{colour}; font-weight:600;'>{html.escape(title)}</span>"
                         f"<span style='color:{C['dim']};'>&nbsp;&nbsp;{html.escape(subtitle)}</span>")
            lab.setTextFormat(Qt.TextFormat.RichText)
            lab.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        else:
            lab = ElidedLabel(title, colour)
        lab.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        if choice is None:
            head = QWidget()
        else:
            head = ChoiceButton()
            head.setCheckable(True)
            head.setObjectName("Choice")
            head.setCursor(Qt.CursorShape.PointingHandCursor)
            _cid, label, _lines, note = self._opts[choice]
            self._keys[letter] = choice
            head.setToolTip(f"{label}  ({letter})\n\n{note}" + (f"\n\n{full}" if full and full != title else ""))
            self.choice_group.addButton(head, choice)
            self._choices[choice] = head
        head.setFixedHeight(34)
        hl = QHBoxLayout(head)
        hl.setContentsMargins(8, 0, 12, 0)
        hl.setSpacing(9)
        if letter:
            hl.addWidget(letter_badge(letter), 0, Qt.AlignmentFlag.AlignVCenter)
        hl.addWidget(lab, 1)
        if choice is not None:
            tick = QLabel("✓")
            tick.setStyleSheet(f"color: {C['bronze_hi']}; font-weight: 700; background: transparent; border: 0;")
            tick.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
            tick.hide()
            hl.addWidget(tick)
            head.toggled.connect(tick.setVisible)
        if is_vanilla:
            # its own small button: the title picks Vanilla, this folds the column away
            fold = QToolButton()
            fold.setText("‹")
            fold.setCursor(Qt.CursorShape.PointingHandCursor)
            fold.setToolTip("Fold this column away and give the mods' columns more room")
            fold.setStyleSheet(f"QToolButton {{ color: {C['ash']}; background: transparent; border: 0; "
                               "padding: 0 4px; font-size: 13pt; } "
                               f"QToolButton:hover {{ color: {C['silver']}; }}")
            fold.clicked.connect(lambda: self._fold_vanilla(True))
            hl.addWidget(fold)
            self._vanilla_fold = fold
        view = CodeView()
        view.lang = self._lang
        view.show_rows(rows, self._dedent, self._digits, unfolded=self._open_folds)
        view.foldOpened.connect(self._open_fold)
        view.wordClicked.connect(self._highlight_word)
        view.braceFocused.connect(lambda key, v=view: self._sync_brace(v, key))
        self._views.append(view)
        frame = QFrame()
        frame.setObjectName("CodeFrame")
        frame.setStyleSheet(f"QFrame#CodeFrame {{ background: {C['well']}; border: 1px solid "
                            f"{C['ridge']}; border-radius: 8px; }}")
        fl = QVBoxLayout(frame)
        fl.setContentsMargins(4, 4, 4, 8)              # a little room at the bottom to grab
        fl.addWidget(view)
        TopEdgeDrag(frame, self.vsplit, bottom=True)   # its bottom edge moves the divider too
        if letter:
            self._frames[letter] = frame
        lay.addWidget(head)                            # whose code it is, before you read it
        lay.addWidget(frame, 1)
        if is_vanilla:
            strip = FoldedColumn(f"{letter}  ·  {title}")
            strip.setToolTip("Show the game's own version again")
            strip.clicked.connect(lambda: self._fold_vanilla(False))
            lay.addWidget(strip, 1)
            self._vanilla = (box, head, frame, strip)
        return box

    def _columns_sideways(self):
        """The columns scroll together; bring the first changed character any of them marks into view."""
        views = [v for v in self._views if v.isVisible()]
        xs = [x for x in (v.first_mark_x() for v in views) if x is not None]
        if views and xs:
            views[0].show_mark_sideways(min(xs))

    def _remember_sizes(self):
        """You dragged a divider: keep its place (once you've let go) for the next decision and
        the next time this window opens."""
        if not hasattr(self, "_size_timer"):
            self._size_timer = QTimer(self, singleShot=True, interval=400)
            self._size_timer.timeout.connect(self._store_sizes)
        self._size_timer.start()

    def _store_sizes(self):
        cfg = load_config()
        v = self.vsplit.sizes()
        if sum(v) > 0:
            cfg["resolver_code_share"] = round(v[0] / sum(v), 4)
        if self.side.isVisible() and self.split.sizes()[0] > 0:
            cfg["resolver_list_w"] = self.split.sizes()[0]
        cols = self.columns.sizes()
        van = getattr(self, "_vanilla", None)
        if len(cols) > 1 and van and van[2].isVisible():            # only while vanilla is open
            widths = cfg.get("resolver_columns") if isinstance(cfg.get("resolver_columns"), dict) else {}
            widths[str(len(cols))] = [round(c / sum(cols), 4) for c in cols]
            cfg["resolver_columns"] = widths
        save_config(cfg)

    def _saved_columns(self, n):
        widths = load_config().get("resolver_columns")
        got = widths.get(str(n)) if isinstance(widths, dict) else None
        if isinstance(got, list) and len(got) == n and all(isinstance(x, (int, float)) and x > 0 for x in got):
            return got
        return None

    def _fold_vanilla(self, folded, remember=True):
        """Fold the vanilla column to a slim strip (the mods' columns take its room), or open it."""
        if not getattr(self, "_vanilla", None):
            return
        box, head, frame, strip = self._vanilla
        head.setVisible(not folded)
        frame.setVisible(not folded)
        strip.setVisible(folded)
        if folded:
            box.setFixedWidth(strip.width())
        else:
            box.setMinimumWidth(0)
            box.setMaximumWidth(16777215)
        n = self.columns.count()
        total = max(sum(self.columns.sizes()), self.columns.width(), 600)
        saved = self._saved_columns(n)
        if folded:
            rest = total - strip.width()
            mods = saved[1:] if saved else [1.0] * (n - 1)             # the mods keep their shares
            self.columns.setSizes([strip.width()] + [int(rest * m / sum(mods)) for m in mods])
        elif saved:
            self.columns.setSizes([int(total * f) for f in saved])
        else:
            self.columns.setSizes([2 * total // (3 * n - 1)] + [3 * total // (3 * n - 1)] * (n - 1))
        if remember:
            cfg = load_config()
            if cfg.get("resolver_vanilla_folded", False) != folded:
                cfg["resolver_vanilla_folded"] = folded
                save_config(cfg)

    def _fit_columns(self):
        """The code boxes are as tall as the code in them (up to about two thirds of the
        space), so a short change doesn't leave big empty boxes; the result takes the rest."""
        if not self._views:
            return
        doc_h = max(int(view.document().size().height()) for view in self._views)
        bar = self._views[0].horizontalScrollBar().sizeHint().height()
        need = 34 + 4 + doc_h + bar + 8 + 6 + 10 + 34     # title, code, frame, the choices row
        total = sum(self.vsplit.sizes())
        if total <= 0:
            return
        share = load_config().get("resolver_code_share")
        if isinstance(share, (int, float)) and 0.1 <= share <= 0.9:
            top = int(total * share)                   # where you last put the divider
        else:
            top = min(need, int(total * 0.62))         # until then: as tall as the code
        self.vsplit.setSizes([top, total - top])

    def resizeEvent(self, e):
        super().resizeEvent(e)
        self._fit_list_btn()

    def _mark_columns(self, cid):
        """The columns the picked version takes its lines from get a bronze edge."""
        picked = set(self._letters(cid, len(self._frames) - 1)) if cid and cid != "edit" else set()
        for letter, frame in self._frames.items():
            edge = C["bronze"] if letter in picked else C["ridge"]
            frame.setStyleSheet(f"QFrame#CodeFrame {{ background: {C['well']}; border: 1px solid {edge}; "
                                "border-radius: 8px; }")

    def _edit_braces(self):
        """In your own version: the brace beside the cursor and its pair (with the block between
        tinted), and any brace without a partner in red — the usual way a hand edit breaks."""
        ed = self.result_edit
        doc = ed.document()
        braces, pairs = _brace_marks(ed.toPlainText().split("\n"))

        def at(n, k, length=1):
            block = doc.findBlockByNumber(n)
            c = QTextCursor(block)
            c.setPosition(block.position() + k)
            c.setPosition(block.position() + k + length, QTextCursor.MoveMode.KeepAnchor)
            return c
        cur = ed.textCursor()
        sels = []
        if cur.hasSelection():                                     # what you selected, in full colour
            sels += fade_outside(doc, cur.selectionStart(), cur.selectionEnd())
        else:
            n, col = cur.blockNumber(), cur.positionInBlock()
            here = next(((n, k) for k in (col, col - 1) if (n, k) in pairs), None)
            if here is not None:
                lo, hi = sorted((here, pairs[here]))
                first = lo[0] - 1 if lo[0] > 0 and doc.findBlockByNumber(lo[0]).text().strip() == "{" else lo[0]
                last = doc.findBlockByNumber(hi[0])
                sels += fade_outside(doc, doc.findBlockByNumber(first).position(),
                                     last.position() + last.length() - 1)
                sels += [brace_mark(at(*spot)) for spot in (here, pairs[here])]
        # a brace without a partner stays red whatever else is going on: it would break the script.
        # Only when the lines really are off, though — a block often closes past the lines you're
        # editing, just as in the version you started from
        it = None
        if self.current_key and self.details.get(self.current_key, {}).get("items"):
            it = self.details[self.current_key]["items"][self.index]
        def net(lines):
            text = _strip_code("\n".join(lines))
            return text.count("{") - text.count("}")
        fine = {net(it["base"])} | {net(v["lines"]) for v in it["variants"]} if it else {0}
        if net(ed.toPlainText().split("\n")) not in fine:
            sels += [_sel(at(n, k), _rgba("blood", 0.5)) for n, k, _ch in braces if (n, k) not in pairs]
        ed.setExtraSelections(sels)

    def _open_fold(self, fid):
        """A fold opened in one view opens in all of them, so the columns stay side by side."""
        self._open_folds.add(fid)
        for view in self._views + [self.result_view]:
            view.rerender()
        self._fit_columns()

    def _sync_brace(self, source, key):
        """A block picked out in one column is picked out in the others too."""
        for view in self._views + [self.result_view]:
            if view is not source:
                view.focus_brace(key)

    def _highlight_word(self, word):
        for view in self._views + [self.result_view]:
            view.highlight_word(word)

    def _link_scrolling(self):
        """The columns scroll together, so the same spot stays side by side."""
        for attr in ("verticalScrollBar", "horizontalScrollBar"):
            bars = [getattr(view, attr)() for view in self._views]
            for bar in bars:
                bar.valueChanged.connect(lambda value, src=bar, group=bars: self._sync(value, src, group))

    def _sync(self, value, src, bars):
        if self._syncing:
            return
        self._syncing = True
        try:
            for bar in bars:
                if bar is not src:
                    bar.setValue(value)
        finally:
            self._syncing = False

    def _wrap(self, middle, it):
        base = self.details[self.current_key]["base_lines"]
        lo_ctx, hi_ctx = self._ctx
        before = [(n + 1, base[n], "ctx", ()) for n in range(lo_ctx, it["start"])]
        after = [(n + 1, base[n], "ctx", ()) for n in range(it["end"], hi_ctx)]
        return before + middle + after

    def _variant_rows(self, it, lines):
        return self._wrap(_rows_vs_base(it["base"], list(lines), it["start"] + 1, self._lang == "xml"), it)

    # --- answering
    def choose(self, n):
        if self._loading:
            return
        it = self.details[self.current_key]["items"][self.index]
        cid, _label, text, note = self._opts[n]
        self.option_note.setText(note)
        self._mark_columns(cid)
        if cid == "edit":
            prev = self.answers[self.current_key].get(it["key"])
            start = prev[1] if prev else (it["proposed"] or it["variants"][0]["lines"])
            self.answers[self.current_key][it["key"]] = ("edit", list(start))
            self._show_result("edit", start)
        else:
            self.answers[self.current_key][it["key"]] = (cid, list(text))
            self._show_result(cid, text)
        self._update_answered()
        self.refresh_list()
        self._live_check()

    BIG_REMOVAL = 8                                    # non-blank vanilla lines a mod leaves out

    def _removal_warning(self, it, who):
        """Say so when a mod's version leaves out a big piece of the game's code here: picking
        it drops that code. Mods made for an older game version (before 4.0's next-gen update)
        look exactly like this. Code put inside a comment counts as left out: the game skips it."""
        def live(lines):
            """(line, its code without comments) for every line that has code left."""
            code = _strip_code("\n".join(lines)).split("\n")
            return [(l, " ".join(c.split())) for l, c in zip(lines, code) if c.strip()]
        base = live(it["base"])
        found = []
        for n, (name, var) in enumerate(zip(who, it["variants"])):
            gone = []
            for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, [c for _l, c in base],
                                                               [c for _l, c in live(var["lines"])],
                                                               autojunk=False).get_opcodes():
                if tag in ("replace", "delete") and (i2 - i1) > (j2 - j1):
                    gone += [l for l, _c in base[i2 - ((i2 - i1) - (j2 - j1)):i2]]
            real = gone
            if len(real) >= self.BIG_REMOVAL:
                found.append((chr(ord("B") + n), name, len(gone), real))
        if not found:
            self.removal_note.hide()
            return
        letters = " and ".join(f for f, *_ in found)
        count = max(g for _f, _n, g, _r in found)
        # something recognisable from what's missing: a quoted name, or else a call
        text = "\n".join(found[0][3])
        hint = re.search(r'"([A-Za-z_]\w{3,})"', text) or re.search(r"\b([A-Z]\w{3,})\s*\(", text)
        also = f", including <code>{html.escape(hint.group(1))}</code>" if hint else ""
        verb = "removes" if len(found) == 1 else "remove"
        self.removal_note.setText(
            f"⚠&nbsp; <b>{letters} {verb} {count} of the game's lines here</b>{also}. "
            f"Picking {'it' if len(found) == 1 else 'either'} drops that code. To keep it, use Vanilla "
            "or Edit by hand.")
        self.removal_note.setToolTip(
            "\n".join(f"{f}  {n}: {g} lines left out" for f, n, g, _r in found) +
            "\n\nOften a mod made for an older game version, without code the game added later.")
        self.removal_note.show()

    def _live_check(self):
        """Would the version you picked compile? The same checks the merge runs, on this
        decision's function as it would come out: brackets that don't balance against the
        lines they replace, a local used after its `var` line is gone, one declared twice.
        Only a warning: you can still save, but the script then stays unmerged (the top
        mod's copy is used) until it's put right."""
        note = self.check_note
        key = self.current_key
        det = self.details.get(key) if key else None
        it = det["items"][self.index] if det and det.get("items") else None
        answer = self.answers[key].get(it["key"]) if it else None
        deps = (it.get("depends") or {}).get(answer[0]) if it and answer else None
        if deps:
            names = {}
            for mod, name in deps:
                names.setdefault(short_group([mod]), []).append(name)
            said = "; ".join(f"{html.escape(m)}'s other changes here still use "
                             + ", ".join(f"<code>{html.escape(n)}</code>" for n in ns) for m, ns in names.items())
            self.depends_note.setText(f"⚠&nbsp; {said}, set up in the lines being dropped. "
                                      "It may still work, but check it.")
            self.depends_note.setToolTip("That mod's other lines here use names set only in the lines "
                                         "being dropped.\n"
                                         "Pick that mod's version, or combine them in Edit by hand.")
            self.depends_note.show()
        else:
            self.depends_note.hide()
        if not it or not answer or not det.get("versions"):
            note.hide()
            return
        if it.get("part"):
            # XML: your version must be well-formed — entries, or the one start tag
            text = "\n".join(answer[1]).strip()
            problem = None
            if it["part"] == "tag":
                m = _XML_TOKEN.match(text)
                if not m or m.lastgroup != "start" or m.end() != len(text):
                    problem = "it should be exactly one start tag, like <Var … />"
            elif text:
                try:
                    parse_xml("<__merge>" + text + "</__merge>")
                except XmlError as e:
                    problem = str(e)
            if problem:
                note.setText("⚠&nbsp; <b>This isn't valid XML:</b> " + html.escape(problem) + ".")
                note.setToolTip("You can still save it, but the file stays unmerged until you change it. "
                                "Until then, the higher priority's copy is used.")
                note.show()
            else:
                note.hide()
            return
        problems = []
        # 1. brackets: the new lines must open and close as many as the lines they replace
        def net(lines):
            text = _strip_code("\n".join(lines))
            return {o: text.count(o) - text.count(c) for o, c in ("{}", "()", "[]")}
        mine = net(answer[1])
        fine = [net(it["base"])] + [net(v["lines"]) for v in it["variants"]]   # what the inputs have here
        if mine not in fine:
            orig = fine[0]
            for o, c in ("{}", "()", "[]"):
                d = mine[o] - orig[o]
                if d:
                    problems.append(f"{abs(d)} more “{o if d > 0 else c}” than “{c if d > 0 else o}”: the "
                                    "brackets don't balance")
        # 2. locals, on the whole script as it would be assembled with your answers so far
        fill = {}
        for other in det["items"]:
            got = self.answers[key].get(other["key"])
            fill[other["key"]] = got[1] if got else (other["resolution"] or other["variants"][0]["lines"])
        try:
            built = merge_script(det["base_lines"], det["versions"], fill, key, assemble_only=True)
        except Exception:
            built = None
        fn = it.get("function")
        if built and built.get("status") == "assembled" and fn:
            nb, nv, nm = _norm(det["base_lines"]), [(l, _norm(v)) for l, v in det["versions"]], _norm(built["lines"])
            for owner, name, _line, what in local_problems(nb, nv, nm) + structure_problems(nb, nv, nm):
                if name.lower() == fn["name"].lower() and owner.lower() == (fn["owner"] or "").lower():
                    problems.append(what.replace("its var line is gone", "it's no longer declared")
                                        .replace(" (the game requires them first)", ""))
        if not problems:
            note.hide()
            return
        note.setText("⚠&nbsp; <b>This wouldn't compile:</b> " + html.escape("; ".join(dict.fromkeys(problems))) + ".")
        note.setToolTip("You can still save it, but the script stays unmerged until you change it. Until "
                        "then, the higher priority's copy is used.\nPick another version, or fix it in Edit by hand.")
        note.show()

    def _show_result(self, cid, lines):
        it = self.details[self.current_key]["items"][self.index]
        first, last = it["start"] + 1, max(it["end"], it["start"] + 1)
        if cid == "edit":
            self.result_title.setText("Your version")
            if it["end"] == it["start"]:
                where = f"Added after vanilla line {it['start']}" if it["start"] else "Added at the top of the file"
            elif it["end"] - it["start"] == 1:
                where = f"Replaces vanilla line {first}"
            else:
                where = f"Replaces vanilla lines {first}–{last}"
            self.edit_hint.setText(where)
            self._loading, was = True, self._loading
            self.result_edit.setPlainText("\n".join(lines))
            self._loading = was
            self.result_stack.setCurrentIndex(2)
            self.result_edit.setFocus()
        else:
            self.result_title.setText("What the game will run")
            self.result_view.show_rows(self._variant_rows(it, list(lines)), self._dedent, self._digits,
                                       unfolded=self._open_folds)
            for delay in (0, 80, 250):                   # again once the box has its real size
                QTimer.singleShot(delay, self.result_view.scroll_to_change)
                QTimer.singleShot(delay, lambda: self.result_view.show_mark_sideways(self.result_view.first_mark_x()))
            self.result_stack.setCurrentIndex(1)

    def edited(self):
        if self._loading or self.current_key is None:
            return
        it = self.details[self.current_key]["items"][self.index]
        self.answers[self.current_key][it["key"]] = ("edit", self.result_edit.toPlainText().split("\n"))
        if not hasattr(self, "_check_timer"):
            self._check_timer = QTimer(self, singleShot=True, interval=350)
            self._check_timer.timeout.connect(self._live_check)
        self._check_timer.start()                      # once you pause typing

    def _open_items(self):
        """(script key, item index) of every decision still open, in list order."""
        out = []
        for key in self._file_keys():
            out += [(key, i) for i, it in enumerate(self.details[key]["items"])
                    if it["key"] not in self.answers[key]]
        return out

    def _next_open(self):
        """The next open decision after the one on screen, wrapping around; None when done."""
        open_items = self._open_items()
        if not open_items:
            return None
        keys = self._file_keys()
        here = (keys.index(self.current_key), self.index) if self.current_key in keys else (-1, -1)
        after = [o for o in open_items if (keys.index(o[0]), o[1]) > here]
        return (after or open_items)[0]

    def _update_answered(self):
        """Set the two buttons for where you are: Save & Next / Decide later while decisions are
        open, Save & Finish / Cancel once every one is answered."""
        if not hasattr(self, "save_btn"):
            return
        left = len(self._open_items())
        here = self.current_key is not None and self.details[self.current_key]["items"] \
            and self.details[self.current_key]["items"][self.index]["key"] in self.answers[self.current_key]
        if left:
            self.save_btn.setText("Save && Next  ›")
            self.save_btn.setEnabled(bool(here))
            self.save_btn.setToolTip("Keep this answer, go to the next one.  (Enter)" if here
                                     else "Pick a version to keep first.")
            self.later_btn.setText("Decide later")
            self.later_btn.setToolTip(f"Save your answers and close. The {left} left stay marked. Until "
                                      "then, the higher priority's copy is used.")
        else:
            self.save_btn.setText("Save && Finish")
            self.save_btn.setEnabled(True)
            self.save_btn.setToolTip("Save every answer and merge. You're only asked again if a mod "
                                     "changes these lines.  (Enter)")
            self.later_btn.setText("Cancel")
            self.later_btn.setToolTip("Close without saving these answers.")

    def _key_pick(self, ch):
        n = self._keys.get(ch)
        if n is not None and self._choices[n] is not None:
            self._choices[n].click()

    def _save_clicked(self):
        nxt = self._next_open()
        if nxt is None:
            self.accept()
            return
        key, index = nxt
        if key != self.current_key:
            self.scripts.blockSignals(True)
            self.scripts.setCurrentRow(self._row_of(key))
            self.scripts.blockSignals(False)
            self.current_key = key
        self.show_item(index)

    def _later_clicked(self):
        self.reject()

    def _changed(self):
        return {k: dict(v) for k, v in self.answers.items()} != getattr(self, "_answers_at_open", None)

    def reject(self):
        """Decide later, Esc and the window's close button all do the same: while decisions are
        still open, what you've answered is kept and the rest waits. Once every one is answered
        this is Cancel, and nothing from this session is saved."""
        if self._open_items() and self._changed():
            self.accept()
        else:
            super().reject()

    def accept_suggestions(self):
        for key, det in self.details.items():
            for it in det["items"]:
                # the ones that would run a line twice need a real look, so they're left
                if it["kind"] == "review" and it.get("why") != "repeated" and it["key"] not in self.answers[key]:
                    cid = ("follow" if it.get("moved") else "keep") if it.get("why") == "removes" else "both"
                    self.answers[key][it["key"]] = (cid, list(it["proposed"]))
        self.refresh_list()
        if self.current_key:
            self.show_item(self.index)

    def result_answers(self):
        """{script key: {item key: lines}} for everything answered."""
        return {key: {k: lines for k, (_cid, lines) in ans.items()}
                for key, ans in self.answers.items() if ans}


class MergerPathsDialog(RememberingDialog):
    """Script Merger's saved paths are wrong for this prefix — show what changes."""
    window_key = "merger_paths"
    FIX, RUN = 1, 2

    def __init__(self, parent, config_path, wrong, unfixable=()):
        super().__init__(parent)
        self.setWindowTitle("Script Merger")
        self.resize(760, 380)
        self.choice = 0
        v = QVBoxLayout(self)
        v.setContentsMargins(22, 20, 22, 18)
        v.setSpacing(12)
        v.addWidget(QLabel("Script Merger's paths are wrong", objectName="DialogTitle"))
        sub = QLabel("Its saved paths don't exist in this prefix, so it crashes on start. These are the "
                     "right ones.",
                     objectName="Muted")
        sub.setWordWrap(True)
        v.addWidget(sub)

        table = QTableWidget(len(wrong), 3)
        table.setHorizontalHeaderLabels(["Setting", "Saved", "Needed here"])
        table.verticalHeader().setVisible(False)
        table.setShowGrid(True)
        table.setWordWrap(False)
        table.setTextElideMode(Qt.TextElideMode.ElideMiddle)   # keep the drive letter visible
        table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
        table.setEditTriggers(QAbstractItemView.EditTrigger.NoEditTriggers)
        head = table.horizontalHeader()
        head.setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
        head.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        head.setSectionResizeMode(2, QHeaderView.ResizeMode.Stretch)
        table.verticalHeader().setDefaultSectionSize(34)
        for row, (key, stored, want) in enumerate(wrong):
            for col, text in enumerate((key, stored or "(not set)", want)):
                item = QTableWidgetItem(text)
                item.setToolTip(text)
                if col == 1:
                    item.setForeground(QBrush(QColor(C["ash"])))
                elif col == 2:
                    item.setForeground(QBrush(QColor(C["moss"])))
                table.setItem(row, col, item)
        v.addWidget(table, 1)

        note = ""
        if unfixable:
            note = ("\nAlso broken, with no value the app can work out: "
                    + ", ".join(k for k, _v in unfixable))
        foot = QLabel(f"{config_path}\nThe original is kept alongside it as .original." + note,
                      objectName="Muted")
        foot.setWordWrap(True)
        v.addWidget(foot)

        bb = QDialogButtonBox()
        fix = bb.addButton("Fix and run", QDialogButtonBox.ButtonRole.AcceptRole)
        fix.setObjectName("Primary")
        run = bb.addButton("Run without fixing", QDialogButtonBox.ButtonRole.ActionRole)
        bb.addButton(QDialogButtonBox.StandardButton.Cancel)
        fix.clicked.connect(lambda: self._done(self.FIX))
        run.clicked.connect(lambda: self._done(self.RUN))
        bb.rejected.connect(self.reject)
        v.addWidget(bb)
        self.restore_size()

    def _done(self, choice):
        self.choice = choice
        self.accept()


def tree_content_height(tree):
    """How tall a file tree is with every row it shows (opened folders included), its header
    and frame: what it needs to show all of them without a scrollbar."""
    first = tree.topLevelItem(0) if tree.topLevelItemCount() else None
    rows, it = 0, first
    while it is not None:                                 # the rows on view, folded folders skipped
        rows += 1
        it = tree.itemBelow(it)
    rh = tree.visualItemRect(first).height() if first is not None else 0
    if rh <= 0:
        rh = tree.fontMetrics().height() + 8
    h = 0 if tree.isHeaderHidden() else tree.header().sizeHint().height()
    if tree.horizontalScrollBar().isVisible():
        h += tree.horizontalScrollBar().height()
    return h + rows * rh + 2 * tree.frameWidth() + 4


TITLE_BAR = 34                                            # the desktop's title bar over a window


def window_room(win, placed_h=None):
    """(room below the window's top, room above it) on its screen, so it can grow without
    running off the bottom. On Wayland an app is never told where its window is: KDE puts a
    dialog in the middle, over the app's window, so it's taken to be there, as tall as it was
    when it opened (placed_h). Elsewhere the window's real place is used."""
    screen = win.screen() or QApplication.primaryScreen()
    if screen is None:
        return 10 ** 6, 0
    area = ScrollTip.screen_room(screen)
    if QApplication.platformName().startswith("wayland"):
        avail = screen.availableGeometry()
        top = avail.top() + max(0, (avail.height() - (placed_h or win.height()) - TITLE_BAR) // 2)
        title = TITLE_BAR
    else:
        top = win.frameGeometry().top()
        title = max(0, win.geometry().top() - top)
    return area.bottom() - top - title, max(0, top - area.top())


def fit_window_to_tree(win, tree, placed_h=None, at_least=None):
    """Make a window just tall enough for its file tree's rows, no taller than the screen
    leaves room for (then the tree scrolls), and never shorter than at_least (the height you
    gave it by hand). Where the window can be moved (not Wayland), it moves up for room when it
    would otherwise run off the bottom. Returns the height asked for."""
    lay = win.layout()

    def relayout():
        # a child's new minimum reaches the layouts it sits in only later, on their own: now,
        # from the tree's card up to the window, or the window's old minimum clamps the resize
        w = tree.parentWidget()
        while w is not None:
            if w.layout() is not None:
                w.layout().invalidate()
                w.layout().activate()
            if w is win:
                break
            w = w.parentWidget()
    tree.setMinimumHeight(0)
    relayout()
    need = tree_content_height(tree)
    tree.setMinimumHeight(min(120, need))
    relayout()
    target = max(win.height() + need - tree.height(), lay.minimumSize().height())
    below, above = window_room(win, placed_h)
    if target > below and above and not QApplication.platformName().startswith("wayland"):
        up = min(target - below, above)
        win.move(win.x(), win.y() - up)
        below += up
    h = max(lay.minimumSize().height(), min(target, below), at_least or 0)
    win.resize(win.width(), h)
    return h


class ListFit:
    """The Install and Edit windows' file list (a card that folds). Folded, the window is as
    tall as its cards. Open, as tall as the list's rows need, as far as the screen has room
    (then the list scrolls), and never shorter than you last made it by hand with the list
    open: it only grows past that. That height is kept for next time."""
    FIT_QUIET = 0.4                     # s after a change of ours in which a resize isn't yours

    def _fit_setup(self, card, key):
        self._fit_card, self._fit_key = card, key
        self._placed_h = None
        self._asked_h = None
        self._quiet_until = 0.0
        blob = load_window_state(key)
        try:
            self._hand_h = int(bytes(blob).decode()) if blob else None
        except (TypeError, ValueError):
            self._hand_h = None
        self.tree.itemExpanded.connect(lambda _it: self._refit())       # opening a folder: room for it
        self.tree.itemCollapsed.connect(lambda _it: self._refit())

    def _hush(self):
        self._quiet_until = time.monotonic() + self.FIT_QUIET

    def showEvent(self, e):
        super().showEvent(e)
        if self._placed_h is None:
            self._placed_h = self.height()               # the height the desktop placed it with
        self._hush()
        QTimer.singleShot(0, self._fit_now)

    def _fit_now(self):
        self._hush()
        if self._fit_card.folded:
            self.layout().activate()
            self._asked_h = self.minimumSizeHint().height()
            self.resize(self.width(), self._asked_h)
        else:
            self._asked_h = fit_window_to_tree(self, self.tree, self._placed_h, self._hand_h)

    def _refit(self):
        if self.isVisible() and not self._fit_card.folded:
            self._hush()
            QTimer.singleShot(0, self._fit_now)

    def resizeEvent(self, e):
        super().resizeEvent(e)
        # yours: the list is open, it isn't the height we asked for, and not right after a change of ours
        if (self.isVisible() and not self._fit_card.folded and self._asked_h is not None
                and time.monotonic() > self._quiet_until and abs(e.size().height() - self._asked_h) > 3):
            self._hand_h = e.size().height()

    def store_size(self):
        super().store_size()
        if self._hand_h:
            save_window_state(self._fit_key, QByteArray(str(int(self._hand_h)).encode()))


class InstallCard(QFrame):
    """A card in the Install window: a title row with an arrow that folds it to that row (a
    short summary then shows on the right), and its content underneath."""
    toggled = pyqtSignal(bool)                            # True: folded

    def __init__(self, title, body, summary="", folded=False):
        super().__init__(objectName="InstCard")
        v = QVBoxLayout(self)
        v.setContentsMargins(12, 8, 12, 8)
        v.setSpacing(6)
        head = QHBoxLayout()
        head.setSpacing(6)
        self.chevron = ChevronButton()
        self.chevron.clicked.connect(self.toggle)
        head.addWidget(self.chevron)
        self.title = QLabel(title)
        self.title.setStyleSheet(f"font-weight: 600; color: {C['silver']};")
        self.title.setCursor(Qt.CursorShape.PointingHandCursor)
        self.title.mousePressEvent = lambda e: self.toggle() if e.button() == Qt.MouseButton.LeftButton else None
        head.addWidget(self.title)
        head.addStretch(1)
        self.summary = QLabel(summary)
        self.summary.setStyleSheet(f"color: {C['ash']};")
        head.addWidget(self.summary)
        v.addLayout(head)
        self.body = body
        v.addWidget(body, 1)
        self.folded = None
        self.set_folded(folded)

    def set_summary(self, text):
        self.summary.setText(text)

    def set_folded(self, folded):
        if folded == self.folded:
            return
        self.folded = folded
        self.body.setVisible(not folded)
        self.summary.setVisible(folded)
        self.chevron.set_open(not folded)
        self.chevron.setToolTip("Expand" if folded else "Collapse")
        pol = self.sizePolicy()
        pol.setVerticalPolicy(QSizePolicy.Policy.Maximum if folded else QSizePolicy.Policy.Preferred)
        self.setSizePolicy(pol)

    def toggle(self):
        self.set_folded(not self.folded)
        self.toggled.emit(self.folded)


class TipRows(QObject):
    """Tooltips for rows of plain widgets, in the list's own tooltip style (ScrollTip): shown
    over a row, kept while the pointer is on the row or on the tip."""

    def __init__(self, owner):
        super().__init__(owner)
        self.tip = ScrollTip(owner)
        self.rows = {}

    def add(self, row, make_html):
        self.rows[row] = make_html
        row.installEventFilter(self)

    def eventFilter(self, row, e):
        t = e.type()
        if t == QEvent.Type.ToolTip and row in self.rows:
            QToolTip.hideText()
            anchor = QRect(row.mapToGlobal(QPoint(0, 0)), row.size())
            if not (self.tip.isVisible() and self.tip.anchor == anchor):
                self.tip.show_tip(self.rows[row](), e.globalPos(), anchor)
            return True
        if t == QEvent.Type.Enter:
            self.tip._in_view = True
        elif t == QEvent.Type.Leave:
            self.tip.pointer_left()
        return False


SNIPPET_KINDS = (("menu", "Mod menu"), ("user", "user.settings · dx12user.settings"),
                 ("user_own", "user.settings · dx12user.settings"), ("input", "input.settings"),
                 ("input_xml", "input.xml"))
KIND_NAME = dict(SNIPPET_KINDS)


def snippet_rows(found, remastered=False, menus=()):
    """The parts of a mod you may leave out, as the Install and Edit windows list them: its own
    menus (menus: their file names), and what its instructions ask to paste.
    [(kind, target, what, tooltip html)] — kind None for the filelist line (done by itself)."""
    esc, steel, ash, silver = html.escape, C["steel"], C["ash"], C["silver"]
    optional = set(found.get("snippet_optional") or ())
    rows = []
    if menus:
        blocks = [f"<p style='margin:8px 0 0 0'>{file_html(f)}</p>" for f in menus]
        note = ("The mod's options page in the game. Without it, the mod uses its defaults, and some "
                "mods don't work. Your values come back when you switch it on again.")
        rows.append(("menu", KIND_NAME["menu"], ", ".join(menus), tip_section(KIND_NAME["menu"], "silver", blocks, note)))
    user = found.get("user_settings") or {}
    if user:
        n = sum(len(v) for v in user.values())
        blocks = [f"<p style='margin:10px 0 0 0'><span style='color:{steel}'>[{esc(sec)}]</span>"
                  f"&nbsp;&nbsp;<span style='color:{ash}'>{len(v)} value{'s' if len(v) != 1 else ''}</span></p>"
                  for sec, v in user.items()]
        note = ("Added to both files. Values you have stay. Taken out when the mod is off or removed.")
        rows.append(("user", KIND_NAME["user"],
                     f"{len(user)} section{'s' if len(user) != 1 else ''}, {n} value{'s' if n != 1 else ''}",
                     tip_section(KIND_NAME["user"], "silver", blocks, note)))
    own = found.get("user_settings_own") or {}
    if own:
        n = sum(len(v) for v in own.values())
        names = ", ".join(dict.fromkeys(Path(x).name for x in found.get("own_source") or ()))
        blocks = [f"<p style='margin:10px 0 0 0'><span style='color:{steel}'>[{esc(sec)}]</span>"
                  f"&nbsp;&nbsp;<span style='color:{ash}'>{len(v)} value{'s' if len(v) != 1 else ''}</span></p>"
                  for sec, v in own.items()]
        note = ("Looks like the mod's own file, not instructions. Off by default.")
        rows.append(("user_own", KIND_NAME["user_own"],
                     f"{n} value{'s' if n != 1 else ''}, from {names}" if names else f"{n} value{'s' if n != 1 else ''}",
                     tip_section(KIND_NAME["user_own"], "silver", blocks, note)))
    keys = found.get("keybind_lines") or {}
    if keys:
        n = sum(len(v) for v in keys.values())
        groups = {}
        for ctx, lines in keys.items():
            groups.setdefault(tuple(lines), []).append(ctx)
        blocks = []
        for lines, ctxs in groups.items():
            binds = []
            for l in lines:
                key, _, act = l.partition("=")
                m = re.search(r"Action=([^,)]+)", act)
                binds.append(f"<span style='color:{steel}'>{esc(key[3:] if key.upper().startswith('IK_') else key)}</span>"
                             f"&nbsp;&nbsp;<span style='color:{ash}'>→ {esc(m.group(1) if m else act)}</span>")
            blocks.append(f"<p style='margin:12px 0 0 0; color:{silver}'>{'<br>'.join(map(esc, ctxs))}</p>"
                          f"<p style='margin:4px 0 0 0'>{'<br>'.join(binds)}</p>")
        note = ("A key two mods want goes to the higher priority. Taken out when the mod is off or removed.")
        rows.append(("input", KIND_NAME["input"],
                     f"{n} keybind{'s' if n != 1 else ''} in {len(keys)} context{'s' if len(keys) != 1 else ''}",
                     tip_section(KIND_NAME["input"], "silver", blocks, note)))
    xml = found.get("input_xml") or []
    if xml:
        ids = [(re.search(r'\bid\s*=\s*"([^"]+)"', l) or [None, l])[1] for l in xml]
        blocks = [f"<p style='margin:8px 0 0 0'><span style='color:{steel}'>{esc(i)}</span></p>" for i in ids]
        note = ("Added to the game's key bindings list, merged with other mods' changes. "
                "Taken out when the mod is off or removed.")
        rows.append(("input_xml", KIND_NAME["input_xml"],
                     f"{len(xml)} entr{'ies' if len(xml) != 1 else 'y'}, merged",
                     tip_section(KIND_NAME["input_xml"], "silver", blocks, note)))
    files = found.get("snippet_filelist") or []
    if files and rows and not remastered:          # 5.00 has no filelists: nothing to show
        blocks = [f"<p style='margin:8px 0 0 0'>{file_html(f)}</p>" for f in files]
        rows.append((None, "dx11 · dx12 filelist", ", ".join(files),
                     tip_section("dx11 · dx12 filelist", "silver", blocks,
                                 "The app lists a mod's menu files itself, so its menu shows in game. "
                                 "Nothing to choose.")))
    return [(k, t, w, h, k in optional) for k, t, w, h in rows]


class ModFieldsMixin:
    """What the Install and Edit windows share: the name / version / Nexus ID / section grid (with
    the New and Remove section buttons) and the "From the mod's instructions" card."""

    def _build_fields(self, v, name, version, nexus_id, sections, section, mgr, section_tip):
        # the name row and the section row share one grid, so every field and button lines up:
        # [label][name / section dropdown][ ][Version][field][ ][Nexus ID][field]
        grid = QGridLayout()
        grid.setHorizontalSpacing(12)
        grid.setVerticalSpacing(12)
        grid.setColumnStretch(1, 1)
        for gap in (2, 5):
            grid.setColumnMinimumWidth(gap, 8)
        self.fields_grid = grid
        name_lab = QLabel("Name in list")
        grid.addWidget(name_lab, 0, 0)
        self.name = QLineEdit(name)
        self._first_name = name
        grid.addWidget(self.name, 0, 1)
        grid.addWidget(QLabel("Version"), 0, 3)
        self.version = QLineEdit(version, placeholderText="unknown")
        self.version.setFixedWidth(110)
        grid.addWidget(self.version, 0, 4)
        grid.addWidget(QLabel("Nexus ID"), 0, 6)
        self.nexus = QLineEdit(nexus_id, placeholderText="none")
        self.nexus.setFixedWidth(90)
        self.nexus.setToolTip("The mod's number on Nexus, or paste its page link. Taken from the file "
                              "name when it has one.")
        grid.addWidget(self.nexus, 0, 7)
        v.addLayout(grid)
        section_lab = QLabel("Section")
        grid.addWidget(section_lab, 1, 0)
        self.section = QComboBox()
        self.section.addItem("No section", "")
        for sid, sname in sections:
            self.section.addItem(sname, sid)
        self.section.setCurrentIndex(max(0, self.section.findData(section or "")))
        self._section_start = self.section.currentIndex()
        self.section.setToolTip(section_tip)
        grid.addWidget(self.section, 1, 1)
        self.new_section = QPushButton("New section…")
        self.new_section.setToolTip("Add a section at the bottom of the list, with this mod in it")
        self.new_section.clicked.connect(self._add_section)
        self.del_section = QPushButton("Remove section")
        self.del_section.setToolTip("Remove the chosen section. Its mods stay, with the same priority.")
        self.del_section.clicked.connect(self._remove_section)
        # the buttons exactly as tall as the dropdown, so the row lines up
        h = self.section.sizeHint().height()
        for b, col in ((self.new_section, 3), (self.del_section, 6)):
            b.setFixedHeight(h)
            b.setVisible(mgr is not None)
            grid.addWidget(b, 1, col, 1, 2)             # under "Version" + its field, "Nexus ID" + its field
        self.section.currentIndexChanged.connect(self._section_buttons)
        self._section_buttons()
        # one label column, so the name field and the Section dropdown start at the same x
        label_w = max(name_lab.sizeHint().width(), section_lab.sizeHint().width())
        for lab in (name_lab, section_lab):
            lab.setFixedWidth(label_w)

    def _section_buttons(self, *_):
        self.del_section.setEnabled(bool(self.section.currentData()))

    def _add_section(self):
        name, ok = QInputDialog.getText(self, "New section", "Name:")
        name = name.strip()
        if not ok or not name:
            return
        row = self.mgr.add_separator(len(self.mgr.rows), name)
        self.sections_changed = True
        self.section.addItem(name, row["id"])
        self.section.setCurrentIndex(self.section.count() - 1)

    def _remove_section(self):
        sid = self.section.currentData()
        if not sid:
            return
        name = self.section.currentText()
        n = sum(1 for r in self.mgr.rows if not r.get("sep") and self.mgr.section_of(r["id"]) == sid)
        if n:
            r = QMessageBox.question(self, "Remove section",
                                     f"Remove the section “{name}”?\n\nIts {n} mod{'s' if n != 1 else ''} stay "
                                     "installed and move out of it.")
            if r != QMessageBox.StandardButton.Yes:
                return
        self.mgr.remove_section(sid)
        self.sections_changed = True
        self.section.removeItem(self.section.currentIndex())
        self.section.setCurrentIndex(0)

    @staticmethod
    def _menus_in(plan, mgr):
        """The menus of its own an archive brings (see ModManager.menu_files): XML files in its
        bin/config/r4game/user_config_matrix/pc that aren't the game's own files there."""
        out = []
        for row in plan or ():
            if row.get("kind") != "bin":
                continue
            pc = ci_path(Path(row["src"]), FILELIST_DIR.split("/", 1)[1])
            if not pc.is_dir():
                continue
            for f in sorted(pc.iterdir(), key=lambda x: x.name.lower()):
                if f.is_file() and f.suffix.lower() == ".xml" and (mgr is None or mgr.is_own_menu(f"{FILELIST_DIR}/{f.name}")):
                    out.append(f.name)
        return out

    def _snippet_body(self, rows, found, off):
        body = QWidget(objectName="CardBody")
        lay = QVBoxLayout(body)
        lay.setContentsMargins(26, 0, 0, 2)                # lined up under the card's title
        lay.setSpacing(4)
        self.tips = TipRows(self)
        name_w = max(self.fontMetrics().horizontalAdvance(t) for _k, t, _w, _h, _o in rows) + 24
        for kind, target, what, tip, optional in rows:
            row = QWidget(objectName="CardBody")
            h = QHBoxLayout(row)
            h.setContentsMargins(0, 1, 0, 1)
            h.setSpacing(10)
            if kind is None:
                box = QLabel("✓")
                box.setAlignment(Qt.AlignmentFlag.AlignCenter)
                box.setStyleSheet(f"color: {C['moss']}; font-weight: 700;")
            else:
                box = QCheckBox()
                box.setChecked(kind not in off)
                box.toggled.connect(self._snip_summary)
                self.snip_boxes[kind] = box
            box.setFixedWidth(22)
            name = QLabel(target)
            # the menu stands out: leaving it out can stop a mod from working, unlike the rest
            # the mod's own config files: in grey, they're offered but not meant as instructions
            name.setStyleSheet(f"color: {C['ash'] if kind == 'user_own' else C['steel']};"
                               + (" font-weight: 700;" if kind == "menu" else ""))
            name.setFixedWidth(name_w)
            info = QLabel(what)
            info.setStyleSheet(f"color: {C['silver'] if kind and kind != 'user_own' else C['ash']};")
            h.addWidget(box)
            h.addWidget(name)
            h.addWidget(info)
            if optional:
                h.addWidget(QLabel("Optional", objectName="Tag"))
            h.addStretch(1)
            if kind is not None:
                # a click anywhere on the row's text ticks it too
                for lab in (name, info):
                    lab.mousePressEvent = lambda e, b=box: b.toggle() if e.button() == Qt.MouseButton.LeftButton else None
            self.tips.add(row, lambda t=tip: t)
            lay.addWidget(row)
        src = list(dict.fromkeys((found.get("snippet_source") or []) + (found.get("keybind_source") or [])))
        if src:
            lab = QLabel("from " + ", ".join(src), objectName="Muted")
            lab.setWordWrap(True)
            lay.addWidget(lab)
        return body

    def _snip_summary(self, *_):
        if self.snip_card is None:
            return
        on = [t for k, t in SNIPPET_KINDS if k in self.snip_boxes and self.snip_boxes[k].isChecked()]
        short = {"user.settings · dx12user.settings": "user.settings"}
        on = list(dict.fromkeys(short.get(t, t) for t in on))
        self.snip_card.set_summary(" · ".join(on) if on else "nothing added")

    def done(self, result):
        if getattr(self, "tips", None) is not None:
            self.tips.tip.hide_tip()
        super().done(result)

    def snippets_off(self):
        """The kinds you unticked: [user / input / input_xml]."""
        return sorted(k for k, b in self.snip_boxes.items() if not b.isChecked())



class InstallDialog(ModFieldsMixin, ListFit, RememberingDialog):
    window_key = "install"
    CARD_GAP = 10                                          # space between the cards
    TABLE_ROWS = 8                                         # more folders than this scroll

    def __init__(self, parent, archive, tmpdir, plan, note, defaults=None, sections=(), section=None, game=None,
                 snippets=None, snippets_off=(), mgr=None, page_section=None, verb="Install"):
        super().__init__(parent)
        self.mgr = mgr
        self.verb = verb                             # Install, or Update / Reinstall / Downgrade / Replace
        self.sections_changed = False                # the main list redraws when this window closes
        self.folds = dict(load_config().get("install_folds") or {})
        self.setWindowTitle(f"{verb} {clean_stem(Path(archive).name)}")
        self.resize(800, 640)
        self.archive, self.plan = Path(archive), plan
        v = QVBoxLayout(self)
        v.setContentsMargins(22, 20, 22, 18)
        v.setSpacing(12)
        v.addWidget(QLabel(f"{verb} mod", objectName="DialogTitle"))
        src_lab = QLabel(Path(archive).name, objectName="Muted")
        src_lab.setToolTip(str(archive))
        v.addWidget(src_lab)
        guessed_name, guessed_version, guessed_id = parse_archive_name(self.archive.name)
        info = self.mod_info = (snippets or {}).get("mod_info") or {}
        if info.get("version") and not guessed_version:
            guessed_version = info["version"]           # from the mod's own info file
        if info.get("name") and not guessed_id and not defaults:
            guessed_name = info["name"]                 # not a Nexus download: its own name is better
        if defaults:                                  # a reinstall keeps what you had set
            guessed_name = defaults.get("name") or guessed_name
            guessed_version = clean_version(defaults.get("version")) or guessed_version
            guessed_id = defaults.get("nexus") or guessed_id
        self._build_fields(v, guessed_name, guessed_version, guessed_id, sections, section, mgr,
                           "Where to list the mod: at the bottom of this section.")
        # a file from the Nexus page of a mod you have: that mod's section, as it goes right under it
        self._section_tip = self.section.toolTip()
        self._page_section = page_section
        self.auto_section = False
        self._follow_page()
        self.nexus.textChanged.connect(self._follow_page)
        # versions of one mod that install to the same place: exactly one can go in, and the
        # one made for this game (next-gen or classic) is picked when the folder names say so
        self.exclusive = exclusive_sets(plan)
        gen = game_generation(game)
        gen_name = generation_name(gen)
        self.matched = set()
        for root in set(self.exclusive.values()):
            members = [i for i, r in self.exclusive.items() if r == root]
            fits = [i for i in members
                    if gen and variant_generation(plan[i]["src"].relative_to(tmpdir).as_posix()) == gen]
            pick = fits[0] if len(fits) == 1 else next((i for i in members if plan[i].get("include", True)), members[0])
            for i in members:
                plan[i] = dict(plan[i], include=(i == pick))
            if len(fits) == 1:
                self.matched.add(pick)
        msg = {
            "variants": "This archive has several versions or options. Tick only the ones you want.",
            "guess": "Couldn't recognise this archive. Check the preview below before installing.",
        }.get(note)
        if self.exclusive:
            msg = "Separate versions of the same mod. Pick one."
            if self.matched:
                msg += f" The one for your game ({gen_name}) is selected."
        if msg:
            lab = QLabel(msg, objectName="Warn")
            lab.setWordWrap(True)
            v.addWidget(lab)
        # made for another game version: said before it goes in (details in the tooltip)
        self.gv_note = QLabel()
        self.gv_note.setWordWrap(True)
        self.gv_note.setTextFormat(Qt.TextFormat.RichText)
        self.gv_note.hide()
        self._gv_cache = {}
        v.addWidget(self.gv_note)
        self.nexus.textChanged.connect(lambda *_: self._game_version_note() if hasattr(self, "rows") else None)

        # --- top: what's in the archive
        self.table = QTableWidget(len(plan), 4)
        self.table.setHorizontalHeaderLabels(["", "From archive", "Type", "Folder name"])
        self.table.verticalHeader().setVisible(False)
        self.table.setWordWrap(False)
        self.table.setTextElideMode(Qt.TextElideMode.ElideLeft)   # keep the end of long paths
        self.table.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
        self.table.setShowGrid(False)
        self.table.verticalHeader().setDefaultSectionSize(40)
        hh = self.table.horizontalHeader()
        hh.setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)
        hh.setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
        hh.setSectionResizeMode(2, QHeaderView.ResizeMode.Fixed)   # sized to the dropdown below
        hh.setSectionResizeMode(3, QHeaderView.ResizeMode.Stretch)
        self.rows = []
        for r, e in enumerate(plan):
            use = QTableWidgetItem()
            use.setFlags(Qt.ItemFlag.ItemIsUserCheckable | Qt.ItemFlag.ItemIsEnabled)
            use.setCheckState(Qt.CheckState.Checked if e.get("include", True) else Qt.CheckState.Unchecked)
            self.table.setItem(r, 0, use)
            rel = e["src"].relative_to(tmpdir).as_posix()
            src_item = self._ro(r, 1, "(archive root)" if rel == "." else rel + "/")
            src_item.setToolTip(src_item.text())
            if r in self.matched:
                src_item.setText(src_item.text() + f"   ✓ your game ({gen_name})")
                src_item.setForeground(QBrush(QColor(C["moss"])))
            row = {"use": use, "combo": None, "edit": None, "src": e["src"], "files": list_files(e["src"])}
            if e["kind"] == "bin":
                self._ro(r, 2, "Game files")
                self._ro(r, 3, "bin")
            else:
                combo = QComboBox()
                for key, label in TYPE_CHOICES:
                    combo.addItem(label, key)
                choice = {"mods": "mod", "wrap": "mod", "dlc": "dlc", "dlcwrap": "dlc"}.get(e["kind"], e["kind"])
                combo.setCurrentIndex([k for k, _ in TYPE_CHOICES].index(choice))
                edit = QLineEdit(e["name"])
                edit.setFrame(False)
                combo.currentIndexChanged.connect(self._schedule)
                edit.textChanged.connect(self._schedule)
                self.table.setCellWidget(r, 2, combo)
                self.table.setCellWidget(r, 3, edit)
                row["combo"], row["edit"] = combo, edit
            self.rows.append(row)
        self.table.itemChanged.connect(self._schedule)
        self.table.itemChanged.connect(self._one_version)
        no_hover_focus(self.table)
        # header auto-sizing ignores embedded widgets, so size the Type column to the widest dropdown
        combos = [r["combo"] for r in self.rows if r["combo"] is not None]
        if combos:
            # measured on a throwaway copy: changing a real one's size policy would leave just
            # that one narrower than its cell
            probe = QComboBox()
            for key, label in TYPE_CHOICES:
                probe.addItem(label, key)
            probe.setSizeAdjustPolicy(QComboBox.SizeAdjustPolicy.AdjustToContents)
            widest = max(probe.fontMetrics().horizontalAdvance(label) for _, label in TYPE_CHOICES)
            type_w = max(probe.sizeHint().width(), widest + 70)
            probe.deleteLater()
        else:
            type_w = self.table.fontMetrics().horizontalAdvance("Game files") + 40
        self.table.setColumnWidth(2, type_w)
        table_h = (self.table.horizontalHeader().sizeHint().height()
                   + sum(self.table.rowHeight(i) for i in range(len(plan)))
                   + 2 * self.table.frameWidth() + 2)
        self.table.setMaximumHeight(table_h)
        self._table_h = table_h

        # --- what the game folder gets
        self.tree = QTreeWidget()
        self.tree.setHeaderLabels(["Path", "Files"])
        self.tree.setUniformRowHeights(True)
        self.tree.setFrameShape(QFrame.Shape.NoFrame)
        self.tree.header().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        self.tree.header().setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        self.tree.header().setStretchLastSection(False)
        self.tree.setMinimumHeight(120)

        # --- the cards: what the instructions ask for, the archive, the game folder
        self.snip_boxes = {}
        rows = snippet_rows(snippets or {}, remastered=game_generation(game) == "rem",
                            menus=self._menus_in(plan, mgr))
        self.snip_card = None
        if rows:
            self.snip_card = InstallCard("Optional parts", self._snippet_body(rows, snippets, snippets_off),
                                         folded=self.folds.get("snippets", False))
            self._snip_summary()
            v.addWidget(self.snip_card)
        self.table.setFixedHeight(min(table_h, self.table.horizontalHeader().sizeHint().height()
                                      + 40 * self.TABLE_ROWS + 2 * self.table.frameWidth() + 2))
        n = len(plan)
        self.table_card = InstallCard("Archive contents", self.table, f"{n} folder{'s' if n != 1 else ''}",
                                      folded=self.folds.get("archive", False))
        v.addWidget(self.table_card)
        # the file preview always starts folded: open it when you want to check where files go
        self.tree_card = InstallCard("Added to the game folder", self.tree, folded=True)
        v.addWidget(self.tree_card, 1)
        self._spacer = QWidget()                           # takes the room when the preview is folded
        v.addWidget(self._spacer, 1)
        self._spacer.setVisible(self.tree_card.folded)
        for key, card in (("snippets", self.snip_card), ("archive", self.table_card), ("preview", self.tree_card)):
            if card is not None:
                card.toggled.connect(lambda folded, k=key: self._card_toggled(k, folded))
        self._fit_setup(self.tree_card, "install_open_h")

        bb = QDialogButtonBox()
        bb.addButton(verb, QDialogButtonBox.ButtonRole.AcceptRole).setObjectName("Primary")
        bb.addButton(QDialogButtonBox.StandardButton.Cancel)
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        v.addWidget(bb)

        self._timer = QTimer(self)
        self._timer.setSingleShot(True)
        self._timer.setInterval(200)
        self._timer.timeout.connect(self._rebuild)
        self.restore_size()
        self._rebuild()

    def _card_toggled(self, key, folded):
        self._hush()
        if key != "preview":                           # the preview isn't remembered: it always starts folded
            self.folds[key] = folded
        self.folds.pop("preview", None)
        cfg = load_config()
        if (cfg.get("install_folds") or {}) != self.folds:
            cfg["install_folds"] = dict(self.folds)
            save_config(cfg)
        # the filler takes the spare height only while the preview is folded; open, the preview
        # gets all of it, so it follows the window as it's resized
        self._spacer.setVisible(self.tree_card.folded)
        QTimer.singleShot(0, self._fit_now)

    # --- the instructions card
    def _ro(self, r, c, text):
        it = QTableWidgetItem(text)
        it.setFlags(Qt.ItemFlag.ItemIsEnabled)
        self.table.setItem(r, c, it)
        return it

    def _schedule(self, *_):
        self._timer.start()

    def _one_version(self, item):
        """Ticking one version of a mod unticks the others — they'd overwrite each other."""
        if item.column() != 0 or item.checkState() != Qt.CheckState.Checked:
            return
        group = self.exclusive.get(item.row())
        if group is None:
            return
        for r, g in self.exclusive.items():
            if g == group and r != item.row():
                other = self.rows[r]["use"]
                if other.checkState() == Qt.CheckState.Checked:
                    other.setCheckState(Qt.CheckState.Unchecked)

    @staticmethod
    def _row_kind_name(row):
        if row["combo"] is None:
            return "bin", "bin"
        kind = effective_kind(row["combo"].currentData(), row["src"])
        name = row["edit"].text().strip().replace("/", "_").replace("\\", "_").strip(". ")
        if kind in ("mods", "wrap") and name:
            name = ensure_mod_prefix(name)
        return kind, name

    def _rebuild(self):
        canon, paths = {}, []

        def canon_dir(path):
            # the game folder is case-insensitive under Wine, so Config/ and config/ are one folder
            parts, out = path.split("/"), []
            for i, part in enumerate(parts):
                out.append(canon.setdefault("/".join(parts[: i + 1]).lower(), part))
            return "/".join(out)

        for row in self.rows:
            if row["use"].checkState() != Qt.CheckState.Checked:
                continue
            kind, name = self._row_kind_name(row)
            rem = self.mgr is not None and self.mgr.remastered()
            skip = {f"{FILELIST_DIR}/{fl}".lower() for fl in FILELISTS}
            for rel in row["files"]:
                full = dest_path(kind, name or "?", rel)
                if rem and (full.lower().startswith("bin/x64/") or full.lower() in skip):
                    continue                             # not placed on 5.x (no DX11 build, no filelists)
                d, _, f = full.rpartition("/")
                paths.append(f"{canon_dir(d)}/{f}" if d else f)
        fill_path_tree(self.tree, paths)
        n = len(paths)
        self.tree_card.set_summary(f"{n} file{'s' if n != 1 else ''}")
        self._refit()                                     # other files: the preview's height follows
        self._game_version_note()

    def _game_version_note(self):
        """Its copies of game files, against your game: a line when they're from another version.
        On 5.x also what in it was made for 4.x (formats, encodings, UI files 5.00 changed)."""
        if not self.mgr:
            return
        gen = game_generation(self.mgr.game)
        files, ui, ui_date = [], [], None
        rem = {"utf16": [], "packed16": [], "srt": [], "strings16": [], "cache16": [], "rebuild": [], "ui": [],
               "date": None}
        for e, row in zip(self.plan, self.rows):
            if row["use"].checkState() != Qt.CheckState.Checked:
                continue
            src = Path(e["src"])
            if src not in self._gv_cache:
                folder = src if ci_child(src, "content") else src.parent if src.name.lower() == "content" else src
                try:
                    copies = ModManager.folder_game_copies(folder) if self._row_kind_name(row)[0] == "mods" else []
                    self._gv_cache[src] = (copies, *ModManager.folder_ui_files(folder),
                                           ModManager.remaster_scan(src) if gen == "rem" else None)
                except Exception:
                    self._gv_cache[src] = ([], [], None, None)
            got, paths, date, scan = self._gv_cache[src]
            files += got
            ui += paths
            if date and (ui_date is None or date < ui_date):
                ui_date = date
            for k in ("utf16", "packed16", "srt", "strings16", "cache16", "rebuild", "ui"):
                rem[k] += (scan or {}).get(k, [])
            rem.setdefault("cache16_from", {}).update((scan or {}).get("cache16_from") or {})
            if gen == "rem" and self._row_kind_name(row)[0] == "bin":
                x64 = ci_child(src, "x64")
                rem["dx11"] = rem.get("dx11", []) + (list_files(x64) if x64 and x64.is_dir() else [])
            if scan and scan.get("date") and (rem["date"] is None or scan["date"] < rem["date"]):
                rem["date"] = scan["date"]
        next_gen = gen in ("ng", "rem")
        made = compare_made_for(files, self.mgr.game_file_versions) if files else None
        # UI files from before next-gen: the files' own dates can't tell (see made_for), so here,
        # before there's a Nexus upload date to go by, they aren't flagged
        old_ui = False
        declared = (getattr(self, "mod_info", {}) or {}).get("game") or []
        gens = {version_generation(v) for v in declared} - {0}
        game_gen = {"rem": 5, "ng": 4, "og": 1}.get(gen)
        for_rem = 5 in gens or any(g >= 5 for g in gens)
        rem_old = False          # caches and UI files: only a Nexus upload date says old (see made_for)
        if not rem_old:
            rem["rebuild"], rem["ui"] = [], []
        rem_bad = bool(rem["packed16"] or rem["srt"] or rem["strings16"] or rem["cache16"] or rem["rebuild"] or rem["ui"])
        rem_any = gen == "rem" and rem_bad
        dx11 = rem.get("dx11", []) if gen == "rem" else []
        other_gen = bool(gens and game_gen and game_gen not in gens)
        nid = self.nexus_id()
        page = (self.mgr.state.get("nexus_cache", {}).get(nid) or {}).get("name", "") if nid else ""
        built = built_in_mod({"nexus": nid, "name": self.name.text()}, page, remastered=gen == "rem") \
            if next_gen and nid else None
        if not (made and made["status"]) and not old_ui and not built and not rem_any and not dx11 and not other_gen:
            self.gv_note.hide()
            return
        yours = version_range(self.mgr.game_version()) or "?"
        lines, tips = [], []
        classic = bool(old_ui) or bool(made and made["status"] == "classic") or rem_bad
        if made and made["status"]:
            off = [f for f in made["files"] if f[4] in ("older", "newer")]
            what = {"classic": "from before the next-gen update" if gen != "rem" else "made for 4.x",
                    "older": "from an older patch", "newer": "from a newer patch"}[made["status"]]
            lines.append(f"<b>Made for {html.escape(made['label'])}</b>, your game is "
                         f"{html.escape(yours)}. {len(off)} game file{'s' if len(off) != 1 else ''} in it "
                         f"{'are' if len(off) != 1 else 'is'} {what}.")
            if made["status"] == "classic" and gen == "rem":
                why = ("\nThey undo what 5.00 changed in these files. Look for a Remastered version.")
            elif made["status"] == "classic":
                why = ("\nThey undo what next-gen changed, and can stop scripts from compiling. Look for "
                       "a next-gen version.")
            else:
                why = "\nThey undo CDPR's later changes to these files (or need a newer game)."
            tips.append("\n".join(f"{rel}: made for {version_range(mine)}" for _k, rel, mine, _g, _v in off) + why)
        only_collision = rem_bad and rem["cache16"] and not any(rem[k] for k in ("packed16", "srt", "strings16",
                                                                                    "rebuild", "ui"))
        if only_collision and not (made and made["status"] == "classic") and not old_ui:
            classic = False         # amber: the rest of the mod works and nothing breaks
        if only_collision:
            note = collision_note(rem)
            lines.append("<b>Old collision.cache</b>: " + note.split(": ", 1)[0][len("Its "):] + ".")
            tips.append("\n".join(rem["cache16"]) + "\n" + note.split(": ", 1)[1].capitalize() + " " + COLLISION_FIX)
        elif rem_bad:
            n = sum(len(rem[k]) for k in ("packed16", "srt", "strings16", "cache16", "rebuild", "ui"))
            lines.append(f"<b>Made for 4.x</b>: {n} file{'s' if n != 1 else ''} in it won't work on 5.00.")
            for key, head in (("packed16", "Packed XML/CSV (UTF-16):"),
                              ("strings16", "Strings (.w3strings):"),
                              ("srt", "SpeedTree (.srt):"),
                              ("cache16", "Collision cache:"),
                              ("rebuild", "Caches and other files:"),
                              ("ui", "UI files:")):
                if rem[key]:
                    tips.append("\n".join([head] + rem[key]))
            tips.append("They need remaking for 5.00 with REDkit. Look for a Remastered version.")
        if other_gen and not (made and made["status"]):
            lines.append(f"<b>Made for game version {html.escape(', '.join(declared))}</b>, by its info file. "
                         f"Your game is {html.escape(yours)}.")
            tips.append(f"From {self.mod_info.get('file', 'its info file')}.")
        if dx11:
            lines.append(f"<b>{len(dx11)} file{'s' if len(dx11) != 1 else ''} for the DX11 build</b> (bin/x64) won't be "
                         "placed. 5.00 runs on DX12 only.")
            tips.append("\n".join(dx11))
        if old_ui:
            when = time.strftime("%d %b %Y", time.localtime(ui_date))
            lines.append(f"<b>Made before next-gen</b> ({when}): it replaces {len(ui)} UI "
                         f"file{'s' if len(ui) != 1 else ''} next-gen changed.")
            tips.append("\n".join(ui) + "\nOld UI files don't fit next-gen: menus can break. Look for a "
                        "next-gen version.")
        if built:
            name, since, instead = built
            if isinstance(instead, str):
                lines.append(f"<b>Part of the game since {html.escape(since)}</b>. {html.escape(instead)}")
                tips.append(f"{name}: not needed since {since}, by CDPR's list for the Remastered.")
            else:
                lines.append(f"<b>Part of the game since {html.escape(since)}</b>. Installing it can undo later "
                             "improvements." + (f" Use {html.escape(instead[0][1])} instead." if instead else ""))
                tips.append(f"{name}: in the game since {since}, by the next-gen changelog."
                            + ("\nNext-gen version: " + ", ".join(f"{n} (Nexus {i})" for i, n in instead)
                               if instead else ""))
        colour, fill, edge = ((C["blood"], "rgba(227,115,95,0.10)", "rgba(227,115,95,0.45)") if classic else
                              (C["bronze_hi"], "rgba(201,164,92,0.10)", "rgba(201,164,92,0.40)"))
        self.gv_note.setStyleSheet(f"QLabel {{ color: {colour}; background: {fill}; border: 1px solid {edge}; "
                                   "border-radius: 6px; padding: 6px 10px; }")
        self.gv_note.setText("⚠&nbsp; " + "<br>⚠&nbsp; ".join(lines))
        self.gv_note.setToolTip("\n\n".join(tips))
        self.gv_note.show()

    def result_plan(self):
        out = []
        for e, row in zip(self.plan, self.rows):
            e = dict(e)
            e["include"] = row["use"].checkState() == Qt.CheckState.Checked
            e["kind"], e["name"] = self._row_kind_name(row)
            out.append(e)
        return (self.name.text().strip() or clean_stem(self.archive.name)), out

    def version_text(self):
        return clean_version(self.version.text())

    def nexus_id(self):
        return extract_nexus_id(self.nexus.text())

    def section_id(self):
        """The chosen separator's id, or None for the top of the list."""
        return self.section.currentData() or None

    def name_touched(self):
        return self.name.text().strip() != (self._first_name or "").strip()

    def _follow_page(self, *_):
        """Show the section of the page's main mod while you haven't picked one yourself."""
        if not hasattr(self, "_section_first"):
            self._section_first = self.section.currentIndex()     # what it showed before (your last pick)
        if self._page_section is None or self.section.currentIndex() != self._section_start:
            return
        hit = self._page_section(self.nexus_id())
        if hit:
            sid, main = hit
            self.section.setCurrentIndex(max(0, self.section.findData(sid or "")))
            self.section.setToolTip(f"{main}'s section, the same Nexus page.\n"
                                    "Pick another to put it at the bottom of that one.")
        elif self.auto_section:
            self.section.setCurrentIndex(self._section_first)
            self.section.setToolTip(self._section_tip)
        self.auto_section = bool(hit)
        self._section_start = self.section.currentIndex()

    def section_touched(self):
        return self.section.currentIndex() != self._section_start

    def accept(self):
        _, plan = self.result_plan()
        used = [e for e in plan if e["include"]]
        if not used:
            QMessageBox.warning(self, "Nothing selected", "Tick at least one row.")
            return
        if any(e["kind"] != "bin" and not e["name"] for e in used):
            QMessageBox.warning(self, "Missing name", "Every ticked row needs a folder name.")
            return
        super().accept()


class EditModDialog(ModFieldsMixin, ListFit, RememberingDialog):
    """An installed mod's details to change: the same fields as the Install window, what its
    instructions add to the game's settings files, and the files it put in the game."""
    window_key = "edit_mod"

    def __init__(self, parent, mgr, mod, is_main=None):
        super().__init__(parent)
        self.mgr, self.mod = mgr, mod
        self.sections_changed = False
        self.snip_boxes, self.snip_card, self.tips = {}, None, None
        self.setWindowTitle(f"Edit {mod['name']}")
        self.resize(800, 520)
        v = QVBoxLayout(self)
        v.setContentsMargins(22, 20, 22, 18)
        v.setSpacing(12)
        v.addWidget(QLabel("Edit mod", objectName="DialogTitle"))
        src = Path(mod["archive"]).name if mod.get("archive") else "Taken over from the game folder"
        when = time.strftime("%d %b %Y", time.localtime(mod.get("installed", 0)))
        src_lab = QLabel(f"{src}  ·  installed {when}", objectName="Muted")
        src_lab.setToolTip(mod.get("archive") or "")
        v.addWidget(src_lab)
        self._build_fields(v, mod["name"], mod.get("version", ""), str(mod.get("nexus") or ""),
                           mgr.sections(), mgr.section_of(mod["id"]), mgr,
                           "Its section. Moving it doesn't change its priority.")
        # a mod in a group: is it the group's main mod
        self.main_box = None
        if is_main is not None:
            self.main_box = QCheckBox("Main mod of its group")
            self.main_box.setChecked(is_main)
            self.main_box.setToolTip("Sits on top of its group. Switching it off switches the group off.")
            self.fields_grid.addWidget(self.main_box, 2, 1, 1, 7)
        rows = snippet_rows(mod, remastered=mgr.remastered(), menus=mgr.menu_files(mod))
        if rows:
            self.snip_card = InstallCard("Optional parts",
                                         self._snippet_body(rows, mod, set(mod.get("snippets_off") or ())))
            self._snip_summary()
            v.addWidget(self.snip_card)
        self.tree = QTreeWidget()
        self.tree.setHeaderLabels(["Path", "Files"])
        self.tree.setUniformRowHeights(True)
        self.tree.setFrameShape(QFrame.Shape.NoFrame)
        self.tree.header().setSectionResizeMode(0, QHeaderView.ResizeMode.Stretch)
        self.tree.header().setSectionResizeMode(1, QHeaderView.ResizeMode.ResizeToContents)
        self.tree.header().setStretchLastSection(False)
        self.tree.setMinimumHeight(120)
        files = mgr.mod_files(mod)
        fill_path_tree(self.tree, files)
        self.files_card = InstallCard("Installed files", self.tree, f"{len(files)} file{'s' if len(files) != 1 else ''}",
                                      folded=True)
        self.files_card.toggled.connect(self._files_toggled)
        self._fit_setup(self.files_card, "edit_open_h")
        v.addWidget(self.files_card, 1)
        self._spacer = QWidget()                           # takes the room while the files are folded
        v.addWidget(self._spacer, 1)
        bb = QDialogButtonBox()
        bb.addButton("Save", QDialogButtonBox.ButtonRole.AcceptRole).setObjectName("Primary")
        bb.addButton(QDialogButtonBox.StandardButton.Cancel)
        bb.accepted.connect(self.accept)
        bb.rejected.connect(self.reject)
        v.addWidget(bb)
        self.restore_size()

    def _files_toggled(self, folded):
        self._hush()
        self._spacer.setVisible(folded)
        QTimer.singleShot(0, self._fit_now)

    def section_id(self):
        return self.section.currentData() or None

    def done(self, result):
        if self.tips is not None:
            self.tips.tip.hide_tip()
        super().done(result)


# --- Nexus "Mod Manager Download" (nxm:// links) ----------------------------------
# While the app is open and has an API key, it's the system's handler for nxm:// links: the
# browser hands the link to a second copy of the app, which passes it to the open window over
# a local socket and quits. On close, whatever handled nxm:// before gets it back. Links for
# other games go to that previous handler, so nothing else stops working meanwhile.
NXM_MIME = "x-scheme-handler/nxm"
NXM_DESKTOP_ID = "w3modmanager-nxm.desktop"
NEXUS_DOMAIN = "witcher3"


def _xdg_config_home():
    return Path(os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config")


def _xdg_data_home():
    return Path(os.environ.get("XDG_DATA_HOME") or Path.home() / ".local" / "share")


def _app_socket_path():
    base = os.environ.get("XDG_RUNTIME_DIR") or tempfile.gettempdir()
    return str(Path(base) / f"w3modmanager-{os.getuid()}.sock")


def parse_nxm(url):
    """{'game', 'mod', 'file', 'key', 'expires', 'user'} from an nxm:// link, or None."""
    try:
        u = urllib.parse.urlsplit(url.strip())
    except ValueError:
        return None
    if u.scheme.lower() != "nxm":
        return None
    m = re.match(r"^/mods/(\d+)/files/(\d+)/?$", u.path or "")
    if not m:
        return None
    q = dict(urllib.parse.parse_qsl(u.query))
    return {"game": (u.netloc or "").lower(), "mod": m.group(1), "file": m.group(2),
            "key": q.get("key", ""), "expires": q.get("expires", ""), "user": q.get("user_id", ""),
            "url": url.strip()}


def send_to_running_app(message):
    """Hand a message to the open window. False when no copy of the app is running."""
    try:
        with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as s:
            s.settimeout(3)
            s.connect(_app_socket_path())
            s.sendall(message.encode("utf-8") + b"\n")
        return True
    except OSError:
        return False


def _mimeapps_files():
    """The files that decide the default handler, most important first: the desktop's own
    (kde-mimeapps.list) counts only when it exists."""
    home = _xdg_config_home()
    files = []
    for desk in os.environ.get("XDG_CURRENT_DESKTOP", "").lower().split(":"):
        f = home / f"{desk}-mimeapps.list"
        if desk and f.is_file():
            files.append(f)
    files.append(home / "mimeapps.list")
    return files


def _mimeapps_get(path, key=NXM_MIME):
    """The [Default Applications] value for key in one mimeapps.list, or None."""
    try:
        lines = Path(path).read_text(errors="ignore").splitlines()
    except OSError:
        return None
    section = None
    for line in lines:
        s = line.strip()
        if s.startswith("[") and s.endswith("]"):
            section = s[1:-1]
        elif section == "Default Applications" and "=" in s and s.split("=", 1)[0].strip() == key:
            return s.split("=", 1)[1].strip()
    return None


def _mimeapps_set(path, value, key=NXM_MIME):
    """Set (or with None, remove) key in [Default Applications]; every other line is kept."""
    path = Path(path)
    try:
        raw = path.read_text(errors="ignore")
    except FileNotFoundError:
        if value is None:
            return
        raw = ""
    lines = raw.splitlines()
    out, section, done, sec_at = [], None, False, None
    for line in lines:
        s = line.strip()
        if s.startswith("[") and s.endswith("]"):
            if section == "Default Applications" and not done and value is not None:
                out.append(f"{key}={value}")
                done = True
            section = s[1:-1]
            out.append(line)
            if section == "Default Applications":
                sec_at = len(out)
            continue
        if section == "Default Applications" and "=" in s and s.split("=", 1)[0].strip() == key:
            if value is not None and not done:
                out.append(f"{key}={value}")
                done = True
            continue
        out.append(line)
    if value is not None and not done:
        if section == "Default Applications":
            out.append(f"{key}={value}")
        elif sec_at is None:
            if out and out[-1].strip():
                out.append("")
            out += ["[Default Applications]", f"{key}={value}"]
    new = "\n".join(out) + ("\n" if out else "")
    if new != raw:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(path.name + ".w3mm-tmp")
        tmp.write_text(new)
        os.replace(tmp, path)


def _desktop_file(desktop_id):
    """Where a desktop id lives: yours first, then the system's."""
    dirs = [_xdg_data_home()] + [Path(d) for d in (os.environ.get("XDG_DATA_DIRS")
                                                    or "/usr/local/share:/usr/share").split(":") if d]
    for d in dirs:
        for rel in (desktop_id, desktop_id.replace("-", "/", 1)):
            f = d / "applications" / rel
            if f.is_file():
                return f
    return None


def _launch_desktop(desktop_id, url):
    """Open a link with a given handler, by its desktop file's Exec line."""
    f = _desktop_file(desktop_id) if desktop_id else None
    if not f:
        return False
    exec_line = None
    section = None
    for line in f.read_text(errors="ignore").splitlines():
        s = line.strip()
        if s.startswith("["):
            section = s
        elif section == "[Desktop Entry]" and s.startswith("Exec="):
            exec_line = s[5:]
            break
    if not exec_line:
        return False
    try:
        parts = shlex.split(exec_line)
    except ValueError:
        return False
    args, used = [], False
    for p in parts:
        if p in ("%u", "%U", "%f", "%F"):
            args.append(url)
            used = True
        elif re.fullmatch(r"%[a-zA-Z]", p):
            continue
        else:
            args.append(p.replace("%%", "%"))
    if not used:
        args.append(url)
    try:
        subprocess.Popen(args, start_new_session=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return True
    except OSError:
        return False


def _refresh_app_database():
    """KDE reads handlers from its own cache: ask it to notice the change (quietly, in the
    background). Other desktops read the files directly."""
    for tool in ("kbuildsycoca6", "kbuildsycoca5", "update-desktop-database"):
        exe = shutil.which(tool)
        if exe:
            args = [exe] + ([str(_xdg_data_home() / "applications")] if tool == "update-desktop-database" else [])
            try:
                subprocess.Popen(args, start_new_session=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except OSError:
                pass
            if tool.startswith("kbuild"):
                break


class NxmHandler:
    """Registers the app for nxm:// links and gives them back afterwards. What was there
    before is kept in the app's config, so a crash is undone on the next start."""

    def __init__(self, cfg):
        self.cfg = cfg

    @property
    def desktop_path(self):
        return _xdg_data_home() / "applications" / NXM_DESKTOP_ID

    def registered(self):
        return "nxm_restore" in self.cfg

    def previous(self):
        """The handler nxm:// links had before this app took them, or None."""
        restore = self.cfg.get("nxm_restore") or {}
        main = str(_xdg_config_home() / "mimeapps.list")
        order = [str(f) for f in _mimeapps_files()]
        for f in order:
            v = restore.get(f)
            if v and NXM_DESKTOP_ID not in v:
                return v.split(";")[0].strip() or None
        v = _mimeapps_get(main)
        return None if not v or NXM_DESKTOP_ID in v else v.split(";")[0].strip()

    def register(self):
        script = Path(__file__).resolve()
        entry = "\n".join([
            "[Desktop Entry]", "Type=Application", f"Name={APP_NAME} (Nexus downloads)",
            "Comment=Hands Nexus “Mod Manager Download” links to the open mod manager",
            f"Exec={shlex.quote(sys.executable)} {shlex.quote(str(script))} %u",
            f"MimeType={NXM_MIME};", "NoDisplay=true", "Terminal=false", ""])
        self.desktop_path.parent.mkdir(parents=True, exist_ok=True)
        if not self.desktop_path.is_file() or self.desktop_path.read_text(errors="ignore") != entry:
            self.desktop_path.write_text(entry)
        if not self.registered():
            # what's there now is what goes back when the app closes
            self.cfg["nxm_restore"] = {str(f): _mimeapps_get(f) for f in _mimeapps_files()}
            save_config(self.cfg)
        for f in _mimeapps_files():
            _mimeapps_set(f, f"{NXM_DESKTOP_ID};")
        _refresh_app_database()

    def unregister(self):
        restore = self.cfg.pop("nxm_restore", None)
        if restore is not None:
            for f, value in restore.items():
                current = _mimeapps_get(f)
                if current is not None and NXM_DESKTOP_ID not in current:
                    continue                      # you picked another handler since: yours stays
                _mimeapps_set(f, value)
            save_config(self.cfg)
        try:
            self.desktop_path.unlink()
        except FileNotFoundError:
            pass
        _refresh_app_database()


class DownloadCancelled(Exception):
    pass


def safe_url(uri):
    """A download address as a browser would send it: spaces and other characters a URL
    can't hold raw are percent-encoded, while anything already encoded stays as it is."""
    u = urllib.parse.urlsplit(uri.strip())
    path = urllib.parse.quote(u.path, safe="/%:@!$&'()*+,;=-._~")
    query = urllib.parse.quote(u.query, safe="=&%/:@!$'()*+,;?-._~")
    return urllib.parse.urlunsplit((u.scheme, u.netloc, path, query, u.fragment))


def _nexus_request(path, api_key, what):
    """nexus_get with messages that say what actually failed for downloads."""
    try:
        return nexus_get(path, api_key)
    except RuntimeError as e:
        text = str(e)
        if isinstance(e, (NexusKeyRejected, NexusForbidden)) and what == "link":
            raise RuntimeError("Nexus refused the download link. Links from the website expire "
                               "after a while. Click “Mod Manager Download” again.") from e
        if "HTTP 404" in text:
            raise RuntimeError(f"Nexus doesn't have that {what} (it may have been removed).") from e
        raise


class NexusDownload(QThread):
    """Fetch one file from an nxm:// link into the downloads folder."""
    info = pyqtSignal(dict)
    progress = pyqtSignal(object, object, float)     # bytes done, bytes total (or None), bytes/s
    done = pyqtSignal(str)
    failed = pyqtSignal(str)
    cancelled = pyqtSignal()

    CHUNK = 256 * 1024

    def __init__(self, link, api_key, dest_dir):
        super().__init__()
        self.link, self.api_key, self.dest_dir = link, api_key, Path(dest_dir)
        self.meta = {}
        self.reused = False                               # the file was already in the downloads folder
        self._stop = False

    def cancel(self):
        self._stop = True

    def run(self):
        try:
            path = self._fetch()
        except DownloadCancelled:
            self.cancelled.emit()
        except Exception as e:                            # shown on the row, the app carries on
            msg = str(e) or e.__class__.__name__
            self.failed.emit(msg if len(msg) <= 160 else msg[:157] + "…")
        else:
            self.done.emit(str(path))

    def _fetch(self):
        mod, fid = self.link["mod"], self.link["file"]
        base = f"{NEXUS_GAME}/mods/{mod}"
        if not self.meta:
            f = _nexus_request(f"{base}/files/{fid}.json", self.api_key, "file")
            try:
                m = _nexus_request(f"{base}.json", self.api_key, "mod")
            except RuntimeError:
                m = {}
            size = f.get("size_in_bytes") or (f.get("size_kb") or f.get("size") or 0) * 1024 or None
            self.meta = {"file_name": Path(f.get("file_name") or f"{mod}-{fid}.zip").name,
                         "file_title": f.get("name") or "", "version": clean_version(f.get("version") or f.get("mod_version")),
                         "category": (f.get("category_name") or "").upper(), "size": size,
                         "mod_name": m.get("name") or "", "mod": mod, "file": fid}
            self.info.emit(dict(self.meta))
        dest = self.dest_dir / self.meta["file_name"]
        size = self.meta["size"]
        if dest.is_file() and (not size or dest.stat().st_size == size):
            self.reused = True
            return dest                                   # already downloaded earlier
        self._check()
        q = {k: self.link[k] for k in ("key", "expires") if self.link.get(k)}
        links = _nexus_request(f"{base}/files/{fid}/download_link.json"
                               + ("?" + urllib.parse.urlencode(q) if q else ""), self.api_key, "link")
        uri = next((l.get("URI") for l in links if l.get("URI")), None) if isinstance(links, list) else None
        if not uri:
            raise RuntimeError("Nexus didn't give a download address for this file.")
        self.dest_dir.mkdir(parents=True, exist_ok=True)
        part = dest.with_name(dest.name + ".part")
        have = part.stat().st_size if part.is_file() else 0
        headers = {"User-Agent": USER_AGENT}
        if have:
            headers["Range"] = f"bytes={have}-"
        req = urllib.request.Request(safe_url(uri), headers=headers)
        try:
            r = urllib.request.urlopen(req, timeout=30)
        except urllib.error.HTTPError as e:
            if e.code == 416 and have:                    # the partial file is already complete
                part.replace(dest)
                return dest
            raise RuntimeError(f"The download server returned HTTP {e.code}.") from e
        except urllib.error.URLError as e:
            raise RuntimeError(f"Couldn't reach the download server: {e.reason}") from e
        except (ValueError, OSError) as e:
            raise RuntimeError(f"Couldn't start the download: {str(e).split('.')[0]}.") from e
        with r:
            if have and r.status != 206:
                have = 0                                  # the server started over
            length = r.headers.get("Content-Length")
            total = (have + int(length)) if length and length.isdigit() else size
            done, last, window = have, 0.0, []
            with open(part, "ab" if have else "wb") as out:
                while True:
                    self._check()
                    try:
                        chunk = r.read(self.CHUNK)
                    except OSError as e:
                        raise RuntimeError(f"The download stopped: {e}") from e
                    if not chunk:
                        break
                    out.write(chunk)
                    done += len(chunk)
                    now = time.monotonic()
                    window.append((now, done))
                    window = [w for w in window if now - w[0] <= 3] or window[-1:]
                    if now - last >= 0.2:
                        span = window[-1][0] - window[0][0]
                        speed = (window[-1][1] - window[0][1]) / span if span > 0 else 0.0
                        self.progress.emit(done, total, speed)
                        last = now
            if total and done < total:
                raise RuntimeError("The download ended early. Retry picks up where it stopped.")
        part.replace(dest)
        self.progress.emit(done, total or done, 0.0)
        return dest

    def _check(self):
        if self._stop:
            raise DownloadCancelled()


_SHA1_CACHE = {}


def _file_sha1(path):
    """A file's hash, worked out once per version of the file (path, size, time)."""
    st = os.stat(path)
    key = (str(path), st.st_size, st.st_mtime_ns)
    if key not in _SHA1_CACHE:
        h = hashlib.sha1()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1 << 20), b""):
                h.update(chunk)
        _SHA1_CACHE[key] = h.hexdigest()
    return _SHA1_CACHE[key]


def human_size(n):
    if n is None:
        return "?"
    for unit in ("B", "KB", "MB", "GB"):
        if n < 1024 or unit == "GB":
            return f"{n:.0f} {unit}" if unit in ("B", "KB") else f"{n:.1f} {unit}"
        n /= 1024


class DownloadsButton(QPushButton):
    """The footer's Downloads toggle: which way the panel goes, and a bronze count of the
    downloads running right now."""

    def __init__(self):
        super().__init__(objectName="DlToggle")
        self.setCheckable(True)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(12, 0, 10, 0)
        lay.setSpacing(8)
        self.label = QLabel()
        self.label.setStyleSheet("background: transparent; border: 0;")
        self.badge = QLabel()
        self.badge.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.badge.setFixedSize(20, 20)
        self.badge.setStyleSheet(f"background: {C['bronze']}; color: {C['stone']}; border-radius: 10px; "
                                 "font-weight: 700; border: 0;")
        self.arrow = QLabel()
        self.arrow.setStyleSheet("background: transparent; border: 0;")
        for wdg in (self.label, self.badge, self.arrow):           # the arrow sits at the far right
            wdg.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
            lay.addWidget(wdg)
        self.set_state(False, 0)

    def set_state(self, open_, running):
        self.setChecked(open_)
        self.label.setText("Downloads")
        self.arrow.setText("‹" if open_ else "›")
        self.badge.setText(str(running))
        self.badge.setVisible(running > 0)
        self.setToolTip("Hide downloads" if open_ else "Show downloads")
        self.setFixedWidth(self.label.sizeHint().width() + self.arrow.sizeHint().width() + 30
                           + (28 if running else 0))
        self.setFixedHeight(30)


def breakable(text, run=14):
    """Text that can wrap anywhere it needs to: long unbroken words (file names, addresses)
    get invisible break points after - _ . / and, failing those, every few characters."""
    def split(word):
        if len(word) <= run:
            return word
        out, since = [], 0
        for ch in word:
            out.append(ch)
            since += 1
            if ch in "-_./\\?&=" or since >= run:
                out.append("\u200b")
                since = 0
        return "".join(out)
    return re.sub(r"\S{%d,}" % (run + 1), lambda m: split(m.group()), text or "")


class WrapLabel(QLabel):
    """A label that never asks for more width than it's given: whatever doesn't fit wraps
    onto the next line, long words included."""

    def __init__(self, text="", objectName=None):
        super().__init__()
        if objectName:
            self.setObjectName(objectName)
        self.setWordWrap(True)
        self.setSizePolicy(QSizePolicy.Policy.Ignored, QSizePolicy.Policy.Preferred)
        self.setMinimumWidth(10)
        self.setText(text)

    def setText(self, text):
        super().setText(breakable(text))


class TrashButton(QAbstractButton):
    """A small, quiet trash can: grey until you point at it, then red — it deletes files."""

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setFixedSize(24, 24)
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def sizeHint(self):
        return QSize(24, 24)

    def paintEvent(self, e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        hot = self.underMouse()
        if hot:
            bg = QColor(C["blood"])
            bg.setAlphaF(0.16)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(bg)
            p.drawRoundedRect(QRectF(0, 0, 24, 24), 6, 6)
        pen = QPen(QColor(C["blood"] if hot else C["ash"]), 1.5)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        p.setPen(pen)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawLine(QPointF(6.5, 7.5), QPointF(17.5, 7.5))            # lid
        p.drawLine(QPointF(10, 7.5), QPointF(10.5, 5.5))             # handle
        p.drawLine(QPointF(10.5, 5.5), QPointF(13.5, 5.5))
        p.drawLine(QPointF(13.5, 5.5), QPointF(14, 7.5))
        body = QPainterPath()                                        # can
        body.moveTo(7.8, 7.5)
        body.lineTo(8.6, 18.2)
        body.quadTo(8.7, 19, 9.5, 19)
        body.lineTo(14.5, 19)
        body.quadTo(15.3, 19, 15.4, 18.2)
        body.lineTo(16.2, 7.5)
        p.drawPath(body)
        p.drawLine(QPointF(10.8, 10.2), QPointF(11, 16.3))            # ridges
        p.drawLine(QPointF(13.2, 10.2), QPointF(13, 16.3))

    def enterEvent(self, e):
        self.update()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self.update()
        super().leaveEvent(e)


class StatusLabel(WrapLabel):
    """The main window's status line: a short message on screen; any longer explanation goes
    in its tooltip (cleared with every new message, so it never outlives its message)."""

    def setText(self, text):
        super().setText(text)
        self.setToolTip("")

    def say(self, text, detail=""):
        self.setText(text)
        self.setToolTip(detail)


TICK_LEFT = False                     # the installed tick: after the name, so every name lines up
CHEVRON_LEFT = True  # the card's arrow before its name; the bin keeps the corner


class ChevronButton(QAbstractButton):
    """A card's collapse arrow: down when it's open, right when it's collapsed (at the end of
    the name row: down to open, up to collapse)."""

    def __init__(self):
        super().__init__()
        self.setFixedSize(20, 20)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._open = True

    def set_open(self, on):
        if self._open != on:
            self._open = on
            self.update()

    def paintEvent(self, _e):
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        pen = QPen(QColor(C["bronze_hi"] if self.underMouse() else C["ash"]), 1.6)
        pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
        p.setPen(pen)
        cx, cy = self.width() / 2, self.height() / 2
        if not CHEVRON_LEFT:
            d = -1 if self._open else 1
            pts = [QPointF(cx - 4, cy - 2 * d), QPointF(cx, cy + 2 * d), QPointF(cx + 4, cy - 2 * d)]
        elif self._open:
            pts = [QPointF(cx - 4, cy - 2), QPointF(cx, cy + 2), QPointF(cx + 4, cy - 2)]
        else:
            pts = [QPointF(cx - 2, cy - 4), QPointF(cx + 2, cy), QPointF(cx - 2, cy + 4)]
        p.drawPolyline(pts)

    def enterEvent(self, e):
        self.update()
        super().enterEvent(e)

    def leaveEvent(self, e):
        self.update()
        super().leaveEvent(e)


def move_to_trash(path):
    """Put a file in your desktop's Trash, the way your file manager would, so it shows there and
    can be restored. On KDE through KIO (kioclient), elsewhere through GIO (gio trash), which
    both know where a file on another drive goes. Qt's own way is the last resort: on a second
    drive it makes a .Trash-<your id> folder there that KDE's Trash may not show, so a file would
    seem deleted for good. True when the file is in the Trash."""
    path = Path(path)
    if not path.exists():
        return False
    tools = []
    if "kde" in os.environ.get("XDG_CURRENT_DESKTOP", "").lower():
        tools += [(t, ["move", str(path), "trash:/"]) for t in ("kioclient6", "kioclient5", "kioclient")]
    tools += [("gio", ["trash", str(path)])]
    for tool, args in tools:
        exe = shutil.which(tool)
        if not exe:
            continue
        try:
            r = subprocess.run([exe, *args], capture_output=True, text=True, timeout=60)
        except (OSError, subprocess.TimeoutExpired):
            continue
        if r.returncode == 0 and not path.exists():
            return True
    ok, _where = QFile.moveToTrash(str(path))
    return bool(ok)


def reveal_in_file_manager(paths):
    """Open the folder these files are in with them selected, in whichever file manager you use
    (Dolphin, Files, Nemo, Thunar…): the freedesktop "show these items" request every one of them
    answers. False when nothing answered it (then the caller just opens the folder)."""
    uris = [QUrl.fromLocalFile(str(p)).toString(QUrl.ComponentFormattingOption.FullyEncoded)   # "%20" for spaces
            for p in paths if Path(p).exists()]
    if not uris:
        return False
    try:
        from PyQt6.QtDBus import QDBusConnection, QDBusInterface, QDBusMessage  # noqa: F401
    except ImportError:
        return False
    bus = QDBusConnection.sessionBus()
    if not bus.isConnected():
        return False
    iface = QDBusInterface("org.freedesktop.FileManager1", "/org/freedesktop/FileManager1",
                           "org.freedesktop.FileManager1", bus)
    if not iface.isValid():
        return False
    from PyQt6.QtCore import QMetaType
    from PyQt6.QtDBus import QDBusArgument
    items = QDBusArgument()
    items.add(uris, QMetaType.Type.QStringList.value)         # sent as a list of strings ("as")
    reply = iface.call("ShowItems", items, "")
    return reply.type() != QDBusMessage.MessageType.ErrorMessage


def download_menu(panel, pos, url, rows, total):
    """The downloads panel's right-click menu. rows: the finished (or stopped) files it acts on;
    total: how many files the card holds."""
    menu = QMenu(panel)
    if url:                                        # a card from your own files may have none
        page = menu.addAction("Open Nexus page", lambda: QDesktopServices.openUrl(QUrl(url)))
        font = QFont(page.font())
        font.setBold(True)
        page.setFont(font)
    files = [f for r in rows for f in r.files_on_disk()]
    menu.addAction("Open in Downloads folder", lambda: panel.show_files(files))
    if rows:
        many = len(rows) > 1
        menu.addSeparator()
        menu.addAction(f"Remove all {len(rows)} from list" if many else "Remove from list",
                       lambda: [panel.remove_row(r) for r in list(rows)])
        on_disk = [r for r in rows if r.files_on_disk()]
        if on_disk:
            n = len(on_disk)
            menu.addAction(f"Move {n} files to Trash" if n > 1 else "Move file to Trash",
                           lambda: [r.delete_file() for r in list(on_disk)])
    menu.exec(pos)


def restyle(widget, name, value):
    """Set a property the theme styles by (QFrame#DlRow[nested="true"], say), and let the widget
    take on its new look: only when it changed, since that's what costs."""
    if widget.property(name) == value:
        return
    widget.setProperty(name, value)
    widget.style().unpolish(widget)
    widget.style().polish(widget)
    # a frame works out its border's width when told its style changed (a border that comes or
    # goes moves what's inside it)
    QApplication.sendEvent(widget, QEvent(QEvent.Type.StyleChange))
    widget.updateGeometry()


class ModGroup(QFrame):
    """A mod's card in the downloads panel. Each file downloaded from its Nexus page sits in
    it as a sub-card; a mod with a single file shows it without the inner frame.
    Its arrow collapses it to its name. Until you use the arrow, a mod you have installed in this
    exact version starts collapsed (with a green tick)."""

    def __init__(self, panel, mod_id):
        super().__init__(objectName="DlGroup")        # its looks are in the theme (QFrame#DlGroup): a
        self.panel, self.mod_id, self.rows = panel, str(mod_id), []   # style of its own per card was slow
        v = QVBoxLayout(self)
        v.setContentsMargins(14, 14, 14, 14)
        v.setSpacing(12)
        self.header = WrapLabel(f"Nexus mod {mod_id}", objectName="DlName")
        head = QHBoxLayout()
        head.setSpacing(6)
        self.chevron = ChevronButton()
        self.chevron.clicked.connect(self.toggle)
        if CHEVRON_LEFT:
            head.addWidget(self.chevron, 0, Qt.AlignmentFlag.AlignTop)
        self.header.setCursor(Qt.CursorShape.PointingHandCursor)
        self.header.mousePressEvent = lambda e: self.toggle() if e.button() == Qt.MouseButton.LeftButton else None
        self.tick = QLabel("✓", objectName="DlTick")
        self.tick.setToolTip("Installed: this exact version")
        self.tick.hide()
        if TICK_LEFT:
            head.addWidget(self.tick, 0, Qt.AlignmentFlag.AlignTop)
        head.addWidget(self.header, 1)
        if not TICK_LEFT:
            head.addWidget(self.tick, 0, Qt.AlignmentFlag.AlignVCenter)
        self.trash = TrashButton()                         # for a mod with a single file
        self.trash.setToolTip("Move the downloaded file to the Trash")
        self.trash.clicked.connect(lambda: self.rows and self.rows[0].delete_file())
        head.addWidget(self.trash, 0, Qt.AlignmentFlag.AlignTop)
        if not CHEVRON_LEFT:
            head.addSpacing(18)                            # well apart from the bin
            head.addWidget(self.chevron, 0, Qt.AlignmentFlag.AlignTop)
        v.addLayout(head)
        self.box = QVBoxLayout()
        if CHEVRON_LEFT:
            self.box.setContentsMargins(20 + 6, 0, 0, 0)   # the files line up under the name
        self.box.setSpacing(8)
        v.addLayout(self.box)

    def add_row(self, row, top=True):
        if row in self.rows:
            self.rows.remove(row)
        self.rows.insert(0 if top else len(self.rows), row)
        self.box.insertWidget(0 if top else self.box.count(), row)
        row.group = self
        self.refresh()

    def take_row(self, row):
        if row in self.rows:
            self.rows.remove(row)
        self.box.removeWidget(row)
        self.refresh()

    def refresh(self):
        # a Nexus download knows its page's name; a card from your files only guesses it
        name = next((r.meta.get("mod_name") for r in sorted(self.rows, key=lambda r: bool(r.meta.get("local")))
                     if r.meta.get("mod_name")), None)
        self.header.setText(name or (f"Nexus mod {self.mod_id}" if self.mod_id.isdigit() else "Mod"))
        nested = len(self.rows) > 1
        for r in self.rows:
            r.set_nested(nested)
        self.refresh_fold()

    # --- collapsing
    def installed(self):
        """Every file in it is the exact version you have installed: nothing to do here."""
        return bool(self.rows) and all(r.state == "done" and getattr(r, "action", "") == "Reinstall"
                                       for r in self.rows)

    def folded(self):
        """Collapsed to its name: your choice for this mod, or — until you make one — collapsed
        when it's installed. While the filter is on, cards open to show what matched (the arrow
        still folds one, just for the time the filter's on)."""
        if self.panel.query:
            return getattr(self, "_filter_fold", False)
        choice = self.panel.fold_choice(self.mod_id)
        if choice is not None:
            return choice
        return self.installed()

    def toggle(self):
        if self.panel.query:
            self._filter_fold = not self.folded()
        else:
            self.panel.set_fold_choice(self.mod_id, not self.folded())
        self.refresh_fold()
        # settle every layout now and paint the list straight away: left to the event loop, the
        # hidden files' old pixels could stay on screen for a moment after the card shrank
        self.layout().activate()                  # the card first, then the list around it
        inner = self.panel.scroll.widget()
        if inner.layout():
            inner.layout().invalidate()
            inner.layout().activate()
        QApplication.sendPostedEvents(None, QEvent.Type.LayoutRequest)
        self.panel.scroll.viewport().repaint()

    def pending_update(self):
        """The downloaded files in it that are a newer version of what you have installed."""
        return [r for r in self.rows if r.state == "done" and getattr(r, "action", "") == "Update"]

    def refresh_fold(self):
        fold = self.folded()
        # folded, its name says what's in it: ✓ installed, ↑ a newer version downloaded, not
        # installed yet (the same ↑ as in the mod list). Open, its file rows say so already
        upd = self.pending_update()
        if upd:
            r = upd[0]
            installed = self.panel.match(r)[0] or {}
            self.tick.setText("↑")
            self.tick.setToolTip(f"Update downloaded, not installed yet: {version_label(r.meta.get('version'))}"
                                 + (f" (you have {version_label(installed.get('version'))})" if installed.get("version") else ""))
        else:
            self.tick.setText("✓")
            self.tick.setToolTip("Installed: this exact version")
        restyle(self.tick, "kind", "update" if upd else "")
        self.tick.setVisible(fold and (bool(upd) or self.installed()))
        self.chevron.set_open(not fold)
        self.chevron.setToolTip("Expand" if fold else "Collapse")
        shown = getattr(self, "filter_rows", None)
        for r in self.rows:
            r.setVisible(not fold and (shown is None or r in shown))
        one = self.rows[0] if len(self.rows) == 1 else None
        self.trash.setVisible(bool(one) and not fold and not one.running() and bool(one.files_on_disk()))

    def contextMenuEvent(self, e):
        """Right-click the mod's card: its Nexus page, the folder, and the card's own actions."""
        idle = [r for r in self.rows if not r.running()]
        download_menu(self.panel, e.globalPos(), NEXUS_URL.format(self.mod_id) if self.mod_id.isdigit() else None,
                      idle, len(self.rows))
        e.accept()

    def full_min_width(self):
        """How narrow this card can get with its files showing — even while folded, so opening
        one never has to widen the panel."""
        lay, own = self.layout().contentsMargins(), self.contentsMargins()
        pad = lay.left() + lay.right() + own.left() + own.right()
        return max([self.minimumSizeHint().width()] + [r.minimumSizeHint().width() + pad for r in self.rows])


class FadeLabel(QWidget):
    """One line of grey text that never holds its row wider: when there isn't room, it's cut and
    fades out toward the buttons next to it. The full text is in the tooltip."""
    FADE = 28

    def __init__(self, text=""):
        super().__init__()
        self._text = text
        self.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Preferred)

    def setText(self, text):
        self._text = text or ""
        self.updateGeometry()
        self.update()

    def text(self):
        return self._text

    def sizeHint(self):
        return QSize(self.fontMetrics().horizontalAdvance(self._text) + 2, self.fontMetrics().height())

    def minimumSizeHint(self):
        # always room for the start of it ("v3.1…"), so it's never cut away completely
        return QSize(min(self.sizeHint().width(), self.fontMetrics().averageCharWidth() * 6), self.fontMetrics().height())

    def paintEvent(self, _e):
        if not self._text:
            return
        p = QPainter(self)
        colour = QColor(C["ash"])
        w = self.width()
        if self.fontMetrics().horizontalAdvance(self._text) > w:
            fade = QLinearGradient(max(0, w - self.FADE), 0, w, 0)
            clear = QColor(colour)
            clear.setAlpha(0)
            fade.setColorAt(0, colour)
            fade.setColorAt(1, clear)
            p.setPen(QPen(QBrush(fade), 1))
        else:
            p.setPen(colour)
        p.drawText(self.rect(), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), self._text)


class DownloadRow(QFrame):
    """One downloaded file: which file, how far along, and what you can do with it. It lives
    in its mod's card in the downloads panel."""

    def __init__(self, panel, link):
        super().__init__()
        self.panel, self.link = panel, link
        self.meta, self.path, self.thread, self.group = {}, None, None, None
        self.state = "starting"
        self.setObjectName("DlRow")
        v = QVBoxLayout(self)
        v.setSpacing(10)
        self.title = WrapLabel("Downloading…", objectName="DlTitle")
        top = QHBoxLayout()
        top.setSpacing(6)
        top.addWidget(self.title, 1)
        self.btn_trash = TrashButton()
        self.btn_trash.setToolTip("Move the downloaded file to the Trash")
        self.btn_trash.clicked.connect(self.delete_file)
        top.addWidget(self.btn_trash, 0, Qt.AlignmentFlag.AlignTop)
        v.addLayout(top)
        self.sub = WrapLabel(objectName="Muted")
        v.addWidget(self.sub)
        self.bar = QProgressBar()
        self.bar.setTextVisible(False)
        self.bar.setFixedHeight(6)
        self.bar.setRange(0, 0)
        v.addWidget(self.bar)
        self.status = WrapLabel(objectName="Muted")
        v.addWidget(self.status)
        row = QHBoxLayout()
        row.setSpacing(6)
        self.meta_lab = FadeLabel()                        # version (· category), beside the buttons
        row.addWidget(self.meta_lab, 1)
        self.btn_main = QPushButton()
        self.btn_main.clicked.connect(self._main_clicked)
        self.btn_remove = QPushButton("Remove")
        self.btn_remove.setToolTip("Take it off this list. The file stays in the downloads folder.")
        self.btn_remove.clicked.connect(lambda: self.panel.remove_row(self))
        row.addWidget(self.btn_remove)
        row.addWidget(self.btn_main)
        v.addLayout(row)
        self.set_nested(False)
        self._show()

    def _apply_titles(self):
        """The mod's name is its card's heading. With several files, each is named so they
        can be told apart; with one, its title would only repeat the mod's name, so the
        version takes that line and the file's full title goes in the tooltip."""
        m = self.meta
        bits = []
        if m.get("version"):
            v = m["version"]
            bits.append(f"v{v}" if v[:1].isdigit() else v)   # shown with a v; kept bare
        if m.get("category") and m["category"] not in ("MAIN",):
            bits.append(m["category"].title())
        meta_line = "  ·  ".join(bits)
        file_title = m.get("file_title") or m.get("file_name") or ""
        tip = "\n".join(x for x in (m.get("file_title"), m.get("file_name")) if x)
        self.meta_lab.setText(meta_line)
        self.meta_lab.setToolTip("\n".join(x for x in (meta_line, tip) if x))
        self.sub.hide()
        if getattr(self, "_nested", False):
            # several files: each names itself
            self.title.setText(file_title or ("Downloading…" if self.running() else "Nexus file"))
            self.title.show()
            self.btn_trash.setVisible(not self.running() and bool(self.files_on_disk()))
        else:
            # the only file: the mod's name says it all, and its bin sits in the card's corner
            self.title.hide()
            self.btn_trash.hide()
        self.title.setToolTip(tip)

    def set_nested(self, nested):
        """A sub-card of its own when the mod has several files; part of the mod's card
        itself when it's the only one."""
        self._nested = nested
        restyle(self, "nested", nested)             # the frame of a sub-card: QFrame#DlRow in the theme
        self.layout().setContentsMargins(*((12, 10, 12, 10) if nested else (0, 0, 0, 0)))
        self._apply_titles()

    # --- running
    def start(self):
        dest = self.panel.downloads_dir()
        if dest is None:
            self._fail("Set the game folder first.")
            return
        self.state = "starting"
        t = NexusDownload(self.link, self.panel.api_key(), dest)
        t.meta = dict(self.meta)
        t.info.connect(self._got_info)
        t.progress.connect(self._got_progress)
        t.done.connect(self._finished)
        t.failed.connect(self._fail)
        t.cancelled.connect(self._cancelled)
        self.thread = t
        t.start()
        self._show()

    def cancel(self):
        if self.thread and self.thread.isRunning():
            self.thread.cancel()

    def running(self):
        return self.state in ("starting", "downloading")

    def _got_info(self, meta):
        self.meta = meta
        self._show()

    def _got_progress(self, done, total, speed):
        self.state = "downloading"
        if total:
            self.bar.setRange(0, 1000)
            self.bar.setValue(int(done * 1000 / total))
        text = f"{human_size(done)} of {human_size(total)}" if total else human_size(done)
        if speed:
            text += f"  ·  {human_size(speed)}/s"
        self.status.setText(text)
        self._show(keep_status=True)

    def _finished(self, path):
        self.state, self.path = "done", path
        self.reused = bool(getattr(self.thread, "reused", False))
        self._show()
        self.panel.row_finished(self)

    def _fail(self, msg):
        self.state = "failed"
        self.error = msg
        self.status.setText(msg)
        self._show(keep_status=True)
        self.panel.changed()

    def _cancelled(self):
        if self.panel.quitting:
            # stopped because the app is closing, not by you: keep what's downloaded so far
            self.thread = None
            self._fail("Stopped when the app closed. Retry continues where it left off.")
            return
        # a cancelled download leaves nothing behind
        name = self.meta.get("file_name")
        dest = self.panel.downloads_dir()
        if name and dest:
            try:
                (dest / (name + ".part")).unlink()
            except OSError:
                pass
        self.panel.remove_row(self)

    def _main_clicked(self):
        if self.running():
            self.cancel()
        elif self.state == "failed":
            self.start()
        elif self.state == "done":
            self.panel.install(self)

    # --- how it looks
    def _show(self, keep_status=False):
        m = self.meta
        if self.group is not None:
            self.group.refresh()                   # also names the file, the way the card needs
        else:
            self._apply_titles()
        self.bar.setVisible(self.running())
        if not keep_status:
            self.status.setText({"starting": "Asking Nexus…",
                                 "done": f"{'From your files' if m.get('local') else 'Downloaded'}  ·  "
                                         f"{human_size(m.get('size') or self._file_size())}"}
                                .get(self.state, self.status.text()))
        self.status.show()
        restyle(self.status, "dlstate", self.state)   # green when done, red when failed (the theme)
        action, tip = ("", "")
        if self.state == "done":
            installed, action = self.panel.match(self)
            tip = ("Not installed yet." if not installed else
                   f"Installed: {installed['name']} {installed.get('version') or '(version unknown)'}\n"
                   f"This download: {m.get('version') or '(version unknown)'}")
        self.btn_main.setText({"starting": "Cancel", "downloading": "Cancel", "failed": "Retry",
                               "done": action}.get(self.state, ""))
        # going back to an older version is a choice, so it doesn't get the inviting colour; the
        # same file again is harmless but rarely the point, so it's toned down
        self.btn_main.setObjectName("" if self.state != "done" or action == "Downgrade"
                                    else "Muted" if action == "Reinstall" else "Primary")
        self.btn_main.style().unpolish(self.btn_main)
        self.btn_main.style().polish(self.btn_main)
        self.btn_main.setToolTip(tip)
        self.action = action if self.state == "done" else ""
        self.btn_remove.setVisible(not self.running())
        self.btn_trash.setVisible(getattr(self, "_nested", False) and not self.running()
                                  and bool(self.files_on_disk()))
        if self.group is not None:
            self.group.refresh_fold()

    def record(self):
        """What the downloads history keeps for this card. The one-time key from the Nexus
        link isn't kept: it expires within hours, and a Premium account doesn't need it."""
        state = self.state if self.state in ("done", "failed") else "failed"
        error = getattr(self, "error", "") if self.state == "failed" else \
            ("" if self.state == "done" else "Stopped when the app closed. Retry continues where it left off.")
        return {"link": {k: self.link.get(k, "") for k in ("game", "mod", "file")},
                "meta": dict(self.meta), "state": state, "path": self.path or "", "error": error,
                "added": getattr(self, "added", int(time.time()))}

    @classmethod
    def from_record(cls, panel, rec):
        link = dict(rec.get("link") or {})
        link.update(key="", expires="", user="", url="")
        row = cls(panel, link)
        row.meta, row.path, row.added = dict(rec.get("meta") or {}), rec.get("path") or None, rec.get("added")
        if row.meta.get("version"):
            row.meta["version"] = clean_version(row.meta["version"])   # 'v1.0' saved by older versions
        row.state = rec.get("state") if rec.get("state") in ("done", "failed") else "failed"
        if row.state == "failed":
            row._fail(rec.get("error") or "Stopped. Retry continues where it left off.")
        else:
            row._show()
        return row

    def files_on_disk(self):
        """This download's files in the downloads folder: the finished archive and/or what a
        stopped download left behind."""
        out = []
        dest = self.panel.downloads_dir()
        name = self.meta.get("file_name")
        for f in ([Path(self.path)] if self.path else []) + \
                 ([dest / name, dest / (name + ".part")] if dest and name else []):
            if f.is_file() and f not in out:
                out.append(f)
        return out

    def contextMenuEvent(self, e):
        """Right-click one file: the same menu, its Nexus page opened on that file."""
        nid, fid = str(self.link.get("mod") or ""), str(self.link.get("file") or "")
        url = (NEXUS_URL.format(nid) + (f"?tab=files&file_id={fid}" if fid.isdigit() else "?tab=files")
               if nid.isdigit() else None)
        download_menu(self.panel, e.globalPos(), url, [] if self.running() else [self], 1)
        e.accept()

    def delete_file(self):
        """Move this download's files to the Trash straight away — no question asked, since
        they can be restored from there. Only when the Trash can't take them (a drive without
        one) is permanent deletion offered instead."""
        files = self.files_on_disk()
        if not files:
            return
        stuck = []
        for f in files:
            if not f.exists():
                continue
            if not move_to_trash(f):
                stuck.append(f)
        if stuck:
            r = QMessageBox.question(
                self.panel.main, "Trash not available",
                "These couldn't be moved to the Trash:\n\n" + "\n".join(f.name for f in stuck)
                + "\n\nDelete them permanently instead?")
            if r != QMessageBox.StandardButton.Yes:
                self._show()
                return
            failed = []
            for f in stuck:
                try:
                    f.unlink()
                except FileNotFoundError:
                    pass
                except OSError as e:
                    failed.append(f"{f.name}: {e.strerror or e}")
            if failed:
                QMessageBox.warning(self.panel.main, "Couldn't delete", "\n".join(failed))
                self._show()
                return
        self.panel.remove_row(self)

    def _file_size(self):
        try:
            return Path(self.path).stat().st_size if self.path else None
        except OSError:
            return None


class EdgeHandle(QSplitterHandle):
    """The divider before the downloads panel: wide enough to grab without aiming, but it
    looks like nothing more than the panel's 1px edge — window colour to its left, the
    panel's colour to its right."""

    def paintEvent(self, e):
        p = QPainter(self)
        mid = self.width() // 2
        p.fillRect(0, 0, mid, self.height(), QColor(C["stone"]))
        p.fillRect(mid, 0, self.width() - mid, self.height(), QColor(C["slate"]))
        p.fillRect(mid, 0, 1, self.height(), QColor(C["ridge"]))


class PanelSplitter(QSplitter):
    GRAB = 12                                        # how wide the grab zone is, in pixels

    def __init__(self):
        super().__init__(Qt.Orientation.Horizontal)
        self.setObjectName("PanelSplit")
        self.setHandleWidth(self.GRAB)

    def createHandle(self):
        return EdgeHandle(self.orientation(), self)


class DownloadsPanel(QWidget):
    """Right side of the main window: Nexus downloads. Shown and hidden from the footer's
    Downloads button; its width is yours to drag, and is remembered."""
    DEFAULT_W, MIN_W, MAX_W = 330, 240, 900
    BAR_EDGE = 4          # between the scrollbar and the panel's right edge
    BAR_GAP = 10          # between the cards and the scrollbar
    SLACK = 6             # kept spare beyond what the cards need, so nothing ever touches the edge
    EMPTY_TEXT = ("Click “Mod Manager Download” on a mod's Nexus page. It downloads here, then the "
                  "Install window opens.")

    def __init__(self, main):
        super().__init__()
        self.main = main
        self.rows = []                             # every file, newest first (the history's order)
        self.groups = {}                           # Nexus mod id -> its card
        h = QHBoxLayout(self)
        h.setContentsMargins(0, 0, 0, 0)
        h.setSpacing(0)
        # shown and hidden from the footer; the main window places this button
        self.button = DownloadsButton()
        self.button.clicked.connect(lambda: self.set_open(not self._open))

        self.body = QFrame(objectName="DlPanel")
        self.setMinimumWidth(self.MIN_W)
        self.setMaximumWidth(self.MAX_W)
        self.body.setStyleSheet(f"QFrame#DlPanel {{ background: {C['slate']}; }}")   # its edge is drawn by the divider
        self._open = False
        self.query = ""                              # the main window's filter, shared with the list
        v = QVBoxLayout(self.body)
        # the right margin is small: the scrollbar sits near the panel's edge, and the cards
        # keep their distance from it instead (the list's own right margin, below)
        v.setContentsMargins(16, 18, self.BAR_EDGE, 12)
        v.setSpacing(12)
        head = QHBoxLayout()
        head.setSpacing(6)
        head.setContentsMargins(0, 0, 16 - self.BAR_EDGE, 0)     # the header lines up with the cards
        title = QLabel("Downloads")
        title.setStyleSheet("font-size: 13pt; font-weight: 600; background: transparent;")
        titles = QVBoxLayout()
        titles.setSpacing(1)
        titles.addWidget(title)
        self.summary = QLabel(objectName="Muted")          # "5 mods · 1.2 GB"
        self.summary.setStyleSheet("background: transparent;")
        self.summary.hide()
        titles.addWidget(self.summary)
        head.addLayout(titles, 1)
        self.btn_folder = QPushButton("Open folder", objectName="PanelBtn")
        self.btn_folder.setToolTip("Open the downloads folder")
        self.btn_folder.clicked.connect(self.open_folder)
        head.addWidget(self.btn_folder)
        v.addLayout(head)

        self.scroll = QScrollArea()
        self.scroll.setWidgetResizable(True)
        self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)   # text wraps instead
        # the scrollbar's room is always kept: one appearing or going (a card opened or collapsed)
        # would change every card's width and reflow the whole list. It only shows when needed.
        self.scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOn)
        vbar = self.scroll.verticalScrollBar()

        def idle(_lo, hi, bar=vbar):
            if bar.property("idle") != (hi == 0):
                bar.setProperty("idle", hi == 0)
                bar.style().unpolish(bar)
                bar.style().polish(bar)
        vbar.rangeChanged.connect(idle)
        idle(0, 0)
        self.scroll.setStyleSheet("QScrollArea { background: transparent; } QScrollArea > QWidget > QWidget { background: transparent; }")
        inner = QWidget()
        self.list = QVBoxLayout(inner)
        self.list.setContentsMargins(0, 0, self.BAR_GAP, 0)
        # whenever the cards' layout changes (a button's text, a card opened, fonts settling), the
        # panel's minimum width is worked out again — so dragging it narrow never cuts a card
        inner.installEventFilter(self)
        self.list.setSpacing(12)
        self.empty = WrapLabel(self.EMPTY_TEXT, objectName="Muted")
        self.empty.setStyleSheet("background: transparent;")
        self.list.addWidget(self.empty)
        self.list.addStretch(1)
        self.scroll.setWidget(inner)
        v.addWidget(self.scroll, 1)
        h.addWidget(self.body)
        self.quitting = False
        self._save_width = QTimer(self, singleShot=True, interval=400)
        self._save_width.timeout.connect(self._store_width)
        # the system says when files appear or go in the downloads folder (no polling), so the
        # total stays right even when a file is deleted by hand
        self._watch = QFileSystemWatcher(self)
        self._watch_timer = QTimer(self, singleShot=True, interval=300)
        self._watch_timer.timeout.connect(self._folder_changed)
        self._watch.directoryChanged.connect(lambda _p: self._watch_timer.start())
        self.hide()                                  # the main window opens it once it's placed

    # --- helpers the rows use
    def api_key(self):
        return self.main.cfg.get("nexus_key", "")

    def downloads_dir(self):
        return self.main.mgr.root / "downloads" if self.main.mgr else None

    # --- history: downloads.json next to the downloads folder, apart from the settings
    def history_path(self):
        return self.main.mgr.root / "downloads.json" if self.main.mgr else None

    def load_history(self):
        """Bring back the cards from last time. A finished download whose file is gone
        (deleted outside the app) is left out; everything else comes back as it was."""
        for r in list(self.rows):
            if not r.running():
                self.remove_row(r, save=False)
        self._loading = True                       # no saving a half-built list while it fills
        path = self.history_path()
        try:
            records = json.loads(path.read_text()) if path and path.is_file() else []
        except (OSError, ValueError):
            records = []
        seen = set()
        for rec in records if isinstance(records, list) else []:
            if rec.get("state") == "done" and not (rec.get("path") and Path(rec["path"]).is_file()):
                continue
            key = (str((rec.get("link") or {}).get("mod")), str((rec.get("link") or {}).get("file")))
            if key in seen:
                continue                             # a duplicate from before: the newest one stays
            seen.add(key)
            row = DownloadRow.from_record(self, rec)
            self.rows.append(row)
            self._group(row.link.get("mod"), top=False).add_row(row, top=False)
        self._loading = False
        self.changed()

    def save_history(self):
        path = self.history_path()
        if not path or getattr(self, "_loading", False):
            return
        data = json.dumps([r.record() for r in self.rows], indent=1)
        try:
            if path.is_file() and path.read_text() == data:
                return
            path.parent.mkdir(parents=True, exist_ok=True)
            tmp = path.with_name(path.name + ".tmp")
            tmp.write_text(data)
            os.replace(tmp, path)
        except OSError:
            pass                                   # the list still works; it just isn't kept

    def open_folder(self):
        d = self.downloads_dir()
        if d:
            d.mkdir(parents=True, exist_ok=True)
            self.main.open_path(d)

    def show_files(self, files):
        """The downloads folder in your file manager, with these files selected (or just the
        folder, when they're gone or the file manager can't be asked)."""
        if not (files and reveal_in_file_manager(files)):
            self.open_folder()

    # --- open / folded
    # --- width
    def stored_width(self):
        w = _int(load_config().get("downloads_width"), self.DEFAULT_W)
        return max(self.MIN_W, min(self.MAX_W, w))

    def width_changed(self):
        """The divider was dragged: remember the new width (once you've let go of it)."""
        if self.isVisible():
            self._save_width.start()

    def _store_width(self):
        if not self.isVisible():
            return
        cfg = load_config()
        # the main window keeps its own copy of the settings and saves it too — keep both in step
        self.main.cfg["downloads_width"] = self.width()
        if cfg.get("downloads_width") != self.width():
            cfg["downloads_width"] = self.width()
            save_config(cfg)

    def refresh_visible(self):
        self.setVisible(self._open and bool(self.main.cfg.get("nexus_key")))
        if hasattr(self.main, "search"):         # the filter box says what it filters
            self.main.search.setPlaceholderText("Filter mods and downloads" if self.isVisibleTo(self.main)
                                                else "Filter mods")

    def set_open(self, on, remember=True):
        was = self._open
        resize = remember and on != was and bool(self.main.cfg.get("nexus_key"))
        if was and not on and self.isVisible():
            self._save_width.stop()
            self._store_width()                                        # as it was when you closed it
        room = max(self.stored_width(), self.minimumWidth()) + self.main.split.handleWidth()
        self._open = on
        if resize and on:
            self.main.panel_resizing(True, room)                       # room first, then the panel
        self.refresh_visible()
        if on:
            self.main.fit_panel(max(self.stored_width(), self.minimumWidth()))
        if resize and not on:
            self.main.panel_resizing(False, room)                      # panel gone, then shrink
        self.button.set_state(on, len(self.running()))
        if remember:
            cfg = load_config()
            if cfg.get("downloads_open") != on:
                cfg["downloads_open"] = on
                save_config(cfg)
                self.main.cfg["downloads_open"] = on

    # --- the list
    def _group(self, mod_id, top=True):
        """The card for a Nexus mod, made if needed, moved to the top (or kept last)."""
        key = str(mod_id)
        grp = self.groups.get(key)
        if grp is None:
            grp = self.groups[key] = ModGroup(self, key)
        self.list.removeWidget(grp)                  # out first, so the count below is right
        self.list.insertWidget(0 if top else self.list.count() - 1, grp)   # (the stretch stays last)
        return grp

    def find(self, mod, file):
        return next((r for r in self.rows if str(r.link.get("mod")) == str(mod)
                     and str(r.link.get("file")) == str(file)), None)

    def add(self, link):
        self.set_fold_choice(link["mod"], None)      # something new in it: show it
        # the same file again (same Nexus mod, same file on its page): one card, reused
        same = self.find(link["mod"], link["file"])
        if same is not None:
            self.set_open(True)
            if same.running():
                self.point_at(same, "Already downloading")
                return same
            self.rows.remove(same)
            self.rows.insert(0, same)
            self._group(link["mod"]).add_row(same)   # up to the top, where a new one would go
            same.link.update({k: link.get(k, "") for k in ("key", "expires", "url")})
            same.added = int(time.time())
            if same.state == "done" and same.path and Path(same.path).is_file():
                self.changed()
                self.point_at(same, "Already downloaded")
                self.offer_install(same)             # already here: nothing to download again
            else:
                same.start()                         # stopped or its file is gone: fetch it
                self.changed()
            return same
        row = DownloadRow(self, link)
        row.added = int(time.time())
        self.rows.insert(0, row)
        self._group(link["mod"]).add_row(row)
        self.set_open(True)
        row.start()
        self.changed()
        return row

    def add_local(self, mod, path):
        """A card for an archive you installed from your own files, so it can be installed again
        from here. It joins its Nexus mod's card when the mod has a Nexus ID; otherwise it gets
        a card of its own."""
        path = Path(path)
        if not path.is_file() or any(r.path and Path(r.path) == path for r in self.rows):
            return None
        mgr = self.main.mgr
        nid = str(mod.get("nexus") or "")
        page = (mgr.state.get("nexus_cache", {}).get(nid) or {}).get("name") if nid else ""
        main = mgr.group_main(nid) if nid else None
        key = nid if nid.isdigit() else f"local-{mod['id']}"
        link = {"game": "witcher3", "mod": key, "file": f"local:{path.name}"}
        # an older version of the same file from your files: this one takes its place
        for r in list(self.rows):
            if r.meta.get("local") and str(r.link.get("mod")) == key and \
                    file_family(r.meta.get("file_name")) == file_family(path.name) and file_family(path.name):
                self.remove_row(r, save=False)
        row = DownloadRow.from_record(self, {
            "link": link, "state": "done", "path": str(path), "added": int(time.time()),
            "meta": {"file_name": path.name, "file_title": mod["name"], "version": mod.get("version", ""),
                     "category": mod.get("nexus_cat", ""), "size": path.stat().st_size, "local": True,
                     "mod_name": page or (main["name"] if main else mod["name"]), "mod": nid}})
        self.rows.insert(0, row)
        self._group(key).add_row(row)
        self.changed()
        return row

    def remove_row(self, row, save=True):
        if row.running():
            return
        # the button you clicked (its trash, say) has the keyboard focus. When its card goes, Qt
        # hands the focus to the next widget in the order the cards were made, which can be
        # anywhere in the list, and scrolls there: the list jumped. The focus goes to the list
        # itself first, and the scroll position is kept.
        bar = self.scroll.verticalScrollBar()
        at = bar.value()
        fw = QApplication.focusWidget()
        gone = row.group if row.group is not None and len(row.group.rows) <= 1 else row
        if fw is not None and (fw is gone or gone.isAncestorOf(fw)):
            self.scroll.setFocus(Qt.FocusReason.OtherFocusReason)
        if row in self.rows:
            self.rows.remove(row)
        grp = row.group
        if grp is not None:
            grp.take_row(row)
            if not grp.rows:                       # its last file gone: the mod's card goes too
                self.groups.pop(grp.mod_id, None)
                self.set_fold_choice(grp.mod_id, None)
                grp.setParent(None)
                grp.deleteLater()
        row.setParent(None)
        row.deleteLater()
        if save:
            self.changed()
        bar.setValue(min(at, bar.maximum()))

    def row_finished(self, row):
        # the same archive already had a card from your own files: the Nexus one, which knows
        # more about it, takes its place
        for r in list(self.rows):
            if r is not row and r.meta.get("local") and r.path and row.path and Path(r.path) == Path(row.path):
                self.remove_row(r, save=False)
        self.changed()
        self.main.show_limits()                  # the allowance Nexus reported with this download
        if getattr(row, "reused", False):
            self.point_at(row, "Already downloaded")
        self.offer_install(row)

    def point_at(self, row, what):
        """A file you asked for again: its card is scrolled into view and flashes, and the status
        line says why nothing new appeared."""
        name = self._list_name(row) or row.meta.get("file_name") or "this file"
        version = version_label(row.meta.get("version")) if row.meta.get("version") else ""
        done = row.state == "done"
        installed = done and self.already_installed(row)
        text = f"{what}: {name}" + (f" {version}" if version else "") + (" (installed)" if installed else "")
        tip = "\n".join(x for x in (row.meta.get("file_title"), row.meta.get("file_name")) if x)
        why = ("It's still downloading." if not done else "It's already in your downloads.")
        self.main.status.say(text, "\n\n".join(x for x in (tip, why) if x))
        self.set_open(True)
        target = row if getattr(row, "_nested", False) and row.isVisibleTo(row.group) else row.group
        if target is None:
            return
        QTimer.singleShot(0, lambda: self._scroll_to(target))
        self.flash(target)

    def _scroll_to(self, widget):
        try:
            self.scroll.ensureWidgetVisible(widget, 0, 12)
        except RuntimeError:                     # the card went in the meantime
            pass

    def flash(self, widget, times=3):
        """Light a card's border up a few times, then put it back."""
        gen = (widget.property("flash_gen") or 0) + 1
        widget.setProperty("flash_gen", gen)

        def step(on):
            try:
                if widget.property("flash_gen") == gen:
                    restyle(widget, "flash", on)
            except RuntimeError:                 # the card was removed while it flashed
                pass
        for k in range(times):
            QTimer.singleShot(k * 440, lambda: step(True))
            QTimer.singleShot(k * 440 + 260, lambda: step(False))

    def offer_install(self, row):
        """Open the Install window for a finished download — unless it's exactly the file
        you already have installed: then there's nothing to decide, and the card says so."""
        if not self.already_installed(row):
            self.install(row)

    def already_installed(self, row):
        """Is this download the very file an installed mod came from? Same version isn't
        enough — Nexus re-uploads sometimes keep the number — so it's the same upload (Nexus
        names each one), or the same contents."""
        if row.state != "done" or not row.path:
            return False
        installed, action = self.match(row)
        if not installed or action != "Reinstall" or not installed.get("archive"):
            return False
        mine, theirs = Path(row.path), Path(installed["archive"])
        if mine.name.lower() == theirs.name.lower():
            return True
        try:
            if mine.stat().st_size != theirs.stat().st_size:
                return False
            return _file_sha1(mine) == _file_sha1(theirs)
        except OSError:
            return False

    @staticmethod
    def _list_name(row):
        """The name a download gets in the list. The page's main file: the mod's name. Any other
        file (optional file, patch, add-on…), or one Nexus doesn't say: that file's own title, with
        the mod's name in front when the title doesn't already have it — "Brothers In Arms - LOD
        Fixes", not a bare "LOD Fixes", and never the main mod's name."""
        m = row.meta
        mod_name = (m.get("mod_name") or "").strip()
        if m.get("local") and m.get("file_title"):
            return m["file_title"]
        if (m.get("category") or "").upper() == "MAIN" and mod_name:
            return mod_name
        title = (m.get("file_title") or "").strip()
        if not title and m.get("file_name"):
            title = parse_archive_name(Path(m["file_name"]).name)[0]
        if not title:
            return mod_name
        key = lambda s: re.sub(r"[^a-z0-9]+", "", s.lower())
        base = name_base(mod_name)
        # the title already names the mod ("Brothers In Arms - LOD Fixes" on the page "Brothers
        # In Arms - Ultimate Edition"): as it is. Otherwise the mod's name, without its edition
        # or subtitle, goes in front
        if not mod_name or names_mod(mod_name, title):
            return title
        return f"{base} - {title}"

    def match(self, row):
        """(the installed mod this download is a version of, or None; what the button says).
        Found by the mod itself, not the downloads folder — so a mod downloaded again long
        after its file was deleted is still recognised."""
        mgr = self.main.mgr
        mods = mgr.mods if mgr else []
        m = row.meta
        nid = str(m.get("mod") or row.link.get("mod") or "")
        fname = (m.get("file_name") or "").lower()
        same_file = [x for x in mods if x.get("archive") and os.path.basename(x["archive"]).lower() == fname]
        hit = same_file[0] if same_file else None
        if hit is None and nid:
            # one Nexus page can hold several files (a main file, optional files, patches): only
            # an installed mod that came from the same file — another version of it — counts
            fam = file_family(m.get("file_name"))
            same_page = [x for x in mods if str(x.get("nexus") or "") == nid]
            fid = m.get("file") or row.link.get("file")
            # the same file by its name without the version, or by Nexus's record of which file
            # replaced which (an author who renamed "Main files (5.0)" to "Main files (5.01)")
            kin = [x for x in same_page if (fam and file_family(x.get("archive")) == fam)
                   or mgr.same_file_line(x, nid, fid, m.get("file_name"))]
            if not kin:                      # installed without an archive name: go by the name
                want = self._list_name(row).lower()
                kin = [x for x in same_page if not file_family(x.get("archive")) and x["name"].lower() == want]
            hit = kin[0] if len(kin) == 1 else None
        if hit is None:
            return None, "Install"
        verdict = mgr.compare_to(hit, m.get("version"), nid, m.get("file") or row.link.get("file"), m.get("file_name"))
        return hit, {"newer": "Update", "same": "Reinstall", "older": "Downgrade"}.get(
            verdict, "Reinstall" if same_file else "Replace")

    def refresh_actions(self):
        """Installing or removing a mod changes what each finished download would do."""
        for r in self.rows:
            if r.state == "done":
                r._show()
        self.fit_width()                           # "Downgrade" is wider than "Install"

    def install(self, row):
        m = row.meta
        installed, _action = self.match(row)
        defaults = {"name": self._list_name(row), "version": m.get("version", ""),
                    "nexus": "".join(c for c in str(m.get("mod") or row.link["mod"]) if c.isdigit()),
                    "category": m.get("category", ""),
                    # a Nexus file id, never digits picked out of a card for your own archive
                    # ("local:Name-905-1-0-4-1700000000.zip" made a file id up)
                    "file": next((str(x) for x in (m.get("file"), row.link.get("file")) if str(x or "").isdigit()), "")}
        # a version of a mod you have goes straight in its place — even if the new version
        # renamed its folder, it's never installed as a second copy beside the old one
        self.main.install_archives([row.path], replace=installed["id"] if installed else None,
                                   defaults=defaults)

    def running(self):
        return [r for r in self.rows if r.running()]

    # --- which folded card is open: the one under the mouse, worked out so nothing jumps
    # --- collapsed cards: your choice per mod, kept between sessions
    def fold_choice(self, mod_id):
        return (self.main.cfg.get("download_folds") or {}).get(str(mod_id))

    def set_fold_choice(self, mod_id, collapsed):
        cfg = load_config()
        folds = dict(cfg.get("download_folds") or {})
        if collapsed is None:
            folds.pop(str(mod_id), None)
        else:
            folds[str(mod_id)] = bool(collapsed)
        if folds != (cfg.get("download_folds") or {}):
            cfg["download_folds"] = folds
            save_config(cfg)
        self.main.cfg["download_folds"] = folds

    def fit_width(self):
        """Never narrower than the cards need: the widest one's button row (version, Remove,
        Install/Update/…) plus the card's padding — so nothing is ever cut off."""
        if not hasattr(self, "_fit_timer"):
            self._fit_timer = QTimer(self, singleShot=True, interval=0)
            self._fit_timer.timeout.connect(self._fit_now)
        self._fit_timer.start()

    def eventFilter(self, obj, e):
        if e.type() == QEvent.Type.LayoutRequest and obj is self.scroll.widget():
            self.fit_width()
        return super().eventFilter(obj, e)

    def _fit_now(self):
        inner = self.scroll.widget()
        if inner.layout():
            inner.layout().activate()
        body = self.body.layout().contentsMargins()
        bar = self.scroll.verticalScrollBar().sizeHint().width()
        cards = max([inner.minimumSizeHint().width()] + [g.full_min_width() + self.BAR_GAP for g in self.groups.values()])
        need = cards + body.left() + body.right() + bar + self.SLACK
        need = max(self.MIN_W, min(self.MAX_W, need))
        if need != self.minimumWidth():
            self.setMinimumWidth(need)
            if self.isVisible() and self.width() < need:
                self.main.fit_panel(need)

    def _watch_folder(self):
        d = self.downloads_dir()
        want = [str(d)] if d is not None and d.is_dir() else []
        have = self._watch.directories()
        if have != want:
            if have:
                self._watch.removePaths(have)
            if want:
                self._watch.addPaths(want)

    def _folder_changed(self):
        """Something appeared or went in the downloads folder. A finished download whose file is
        gone (deleted by hand) leaves the list — as it would at the next start."""
        gone = [r for r in self.rows if r.state == "done" and not r.running()
                and not (r.path and Path(r.path).is_file())]
        for r in gone:
            self.remove_row(r, save=False)
        self.changed()

    def set_filter(self, text):
        """The filter box above the mod list narrows this list too."""
        q = (text or "").strip().lower()
        if q == self.query:
            return
        self.query = q
        for g in self.groups.values():
            g._filter_fold = False                   # each new filter opens what it finds
        self.apply_filter()
        self.update_summary()

    @staticmethod
    def _row_text(row):
        m = row.meta
        return " ".join(str(x) for x in (m.get("mod_name"), m.get("file_title"), m.get("file_name"),
                                         DownloadsPanel._list_name(row) if m else "", row.title.text())
                        if x).lower()

    def apply_filter(self):
        """Show the cards and files that match the filter: a card whose mod name matches shows
        all its files; otherwise only the files that match. Cards with nothing matching hide."""
        q = self.query
        hits = 0
        for g in self.groups.values():
            if not q:
                g.filter_rows = None
                g.setVisible(True)
            elif q in g.header.text().lower():
                g.filter_rows = None
                g.setVisible(True)
            else:
                g.filter_rows = {r for r in g.rows if q in self._row_text(r)}
                g.setVisible(bool(g.filter_rows))
            hits += g.isVisibleTo(self.body) if q else 0
            g.refresh_fold()
        if q and not hits and self.rows:
            self.empty.setText(f"No downloads match “{self.query}”.")
            self.empty.show()
        else:
            self.empty.setText(self.EMPTY_TEXT)
            self.empty.setVisible(not self.rows)
        self._hits = hits

    def update_summary(self):
        """How many mods the list holds and what their downloaded files take on disk."""
        if not self.rows:
            self.summary.hide()
            return
        files = [f for r in self.rows if not r.running() for f in r.files_on_disk()]
        size = 0
        for f in files:
            try:
                size += f.stat().st_size
            except OSError:
                pass
        n = len(self.groups)
        if self.query:
            shown = sum(1 for g in self.groups.values() if not g.isHidden())
            self.summary.setText(f"{shown} of {n} mod{'s' if n != 1 else ''}")
        else:
            self.summary.setText(f"{n} mod{'s' if n != 1 else ''}  ·  {human_size(size)}")
        k = len(self.rows)
        self.summary.setToolTip(f"{k} file{'s' if k != 1 else ''} downloaded, {human_size(size)} on disk\n"
                                f"{self.downloads_dir()}")
        self.summary.show()

    def changed(self):
        self._watch_folder()
        self.update_summary()
        self.save_history()
        self.fit_width()
        self.apply_filter()                          # new cards follow the filter that's on
        self.update_summary()
        self.button.set_state(self._open, len(self.running()))

    def cancel_all(self):
        for r in self.running():
            r.cancel()
        for r in list(self.rows):
            if r.thread:
                r.thread.wait(5000)

    def stop_for_quit(self):
        """The app is closing: stop running downloads but keep what they've fetched, so
        Retry picks up where they left off next time."""
        self.quitting = True
        self.cancel_all()
        QApplication.processEvents()                 # let each stopped download report back
        self.save_history()


class MainWindow(RememberSize, QMainWindow):
    window_key = "main"

    def __init__(self):
        super().__init__()
        self.setWindowTitle(f"{APP_NAME} {APP_VERSION}")
        self.resize(1100, 700)
        self.cfg = load_config()
        if NEXUS_CLIENT_ID and self.cfg.get("nexus_key") and (self.cfg.get("nexus_login") != "oauth" or not oauth_tokens()):
            # a personal key pasted before the app had its Nexus login: Nexus wants the login now
            self.cfg["nexus_key"] = ""
            save_config(self.cfg)
        self.mgr = None
        self._workers, self._queue = [], []
        self._busy = self._populating = False

        root = QWidget()
        outer = QVBoxLayout(root)
        outer.setContentsMargins(22, 18, 22, 12)
        outer.setSpacing(14)
        # the mod list and, to its right, the downloads panel — with a divider you can drag
        self.split = PanelSplitter()
        self.split.setChildrenCollapsible(False)
