_APP_ICON = None


def app_icon():
    """The app's icon (window, taskbar, Alt+Tab, the Settings window), every size in one QIcon."""
    global _APP_ICON
    if _APP_ICON is None:
        icon = QIcon()
        for size, data in _APP_ICON_PNG.items():
            pm = QPixmap()
            if pm.loadFromData(base64.b64decode(data), "PNG"):
                icon.addPixmap(pm)
        _APP_ICON = icon
    return _APP_ICON


def main():
    if _hand_off_or_clean_up():
        return
    move_problem = ""
    home = app_home_needed()
    if home is not None and not os.environ.get("W3MM_MOVED"):
        ok, move_problem = move_app_into(home)
        if ok:
            relaunch(home, moved_from=APP_DIR)
    refresh_launchers()
    sys.excepthook = report_error
    # KDE's file dialog runs inside the app and chats on the terminal (job trackers, trash
    # probes on read-only drives). Harmless, so it's kept quiet; the app's own errors aren't.
    QLoggingCategory.setFilterRules("kf.*.warning=false\nkf.*.info=false\nkf.*.debug=false")
    app = QApplication(sys.argv)
    app.setApplicationName(APP_NAME)
    app.setWindowIcon(app_icon())                      # every window of the app: title bar, taskbar, Alt+Tab
    # only claim a desktop entry when there is one — otherwise KDE's portal logs a warning
    data_dirs = [os.environ.get("XDG_DATA_HOME") or str(Path.home() / ".local/share")] + \
        (os.environ.get("XDG_DATA_DIRS") or "/usr/local/share:/usr/share").split(":")
    if any(Path(d, "applications", "w3modmanager.desktop").is_file() for d in data_dirs if d):
        app.setDesktopFileName("w3modmanager")
    code = 1
    w = None
    # a logout or kill closes the app properly, so nxm:// links are handed back even then
    for sig in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
        signal.signal(sig, lambda *_: app.quit())
    tick = QTimer()
    tick.timeout.connect(lambda: None)                  # lets Python see those signals
    tick.start(500)
    try:
        apply_theme(app)
        if move_problem:
            QMessageBox.warning(None, APP_NAME, move_problem)
        w = MainWindow()
        w.show()
        code = app.exec()
    except Exception:
        report_error(*sys.exc_info())
    if w is not None:
        try:
            w.release_links()
        except Exception:
            pass
    # Leave without Python and Qt tearing each other down: freeing Qt's objects during
    # interpreter shutdown is where PyQt apps crash on exit. Everything is saved by now.
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.flush()
        except (OSError, AttributeError):
            pass
    if RELAUNCH.get("home"):
        # a game folder set (first start) or changed in Settings: the app moves there and restarts
        ok, why = move_app_into(RELAUNCH["home"])
        if ok:
            relaunch(RELAUNCH["home"], moved_from=APP_DIR)
        sys.__stderr__.write(why + "\n")
    os._exit(code)

